def _enabled_layer_ids_for_preset_v211(preset: str, counts: dict[str, int]) -> set[str]:
    preset_value = LAYER_PRESETS_V211.get(preset, LAYER_PRESETS_V211["Balanced institutional"])
    if preset_value == "__ALL_ACTIVE__":
        return {layer_id for layer_id, count in counts.items() if int(count or 0) > 0}
    if preset_value is None:
        return {layer_id for layer_id in DEFAULT_TRUE_LAYER_IDS if int(counts.get(layer_id, 0) or 0) > 0}
    return {layer_id for layer_id in preset_value if int(counts.get(layer_id, 0) or 0) > 0}



# Additional source-pack parity helpers — V2.11.6
# ------------------------------------------------------------
# The bridge cannot reproduce every WorldMonitor React panel inside Plotly, but
# it should not ignore extra geospatial config arrays that have direct lat/lon
# coordinates. These exact mappings bring more of the original source pack into
# the map without using fuzzy trace matching.

EXTRA_GEOSPATIAL_ARRAY_LAYER_MAP_V211: dict[str, str] = {
    "AI_RESEARCH_LABS": "aiResearchLabs",
    "TECH_COMPANIES": "techCompanies",
    "STARTUP_ECOSYSTEMS": "startupEcosystems",
    "GULF_INVESTMENTS": "gulfInvestments",
    "GEO_HUBS": "geoHubs",
}


def _infer_layer_from_array_v211(name: str, arr: list[Any]) -> str | None:
    exact = EXTRA_GEOSPATIAL_ARRAY_LAYER_MAP_V211.get(str(name))
    if exact:
        return exact
    # Strict conservative fallback: only accept unknown arrays when at least
    # several records carry explicit coordinates. This avoids rendering UI
    # arrays, keyword arrays or non-map data as fake points.
    geo = 0
    for rec in arr[:80]:
        if isinstance(rec, dict) and _valid_latlon(rec.get("lat"), rec.get("lon", rec.get("lng"))):
            geo += 1
    if geo >= 5 and str(name).upper() in {"GEO_HUBS"}:
        return "geoHubs"
    return None

# ============================================================
# Source discovery / tolerant TypeScript extraction
# ============================================================

def _module_dir() -> Path:
    try:
        return Path(__file__).resolve().parent
    except Exception:
        return Path.cwd()


def _candidate_source_roots(extra_roots: Iterable[str | Path] | None = None) -> list[Path]:
    """
    V2.11 speed fix.
    Do not recursively scan the whole Codespace unless useful. Prefer explicit
    WorldMonitor folders, local ZIPs and shallow project roots. This avoids
    node_modules/.git/.venv scans during the first Streamlit render.
    """
    roots: list[Path] = []
    env = os.getenv("WORLD_MONITOR_SOURCE_DIR", "").strip()
    for value in list(extra_roots or []) + ([env] if env else []):
        try:
            p = Path(value).expanduser().resolve()
            if p.exists():
                roots.append(p)
        except Exception:
            pass

    base = _module_dir().resolve()
    preferred = [
        base / "worldmonitor_original",
        base / "worldmonitor",
        base / "wm_original",
        base / "wm_all",
        base / "src" / "config",
        base / "src",
        base / "data",
        base,  # needed for ZIPs placed next to the app; walking is pruned below
        Path("/mnt/data"),
    ]
    for p in preferred:
        try:
            p = p.resolve()
            if p.exists():
                roots.append(p)
        except Exception:
            pass

    unique: list[Path] = []
    seen: set[str] = set()
    for p in roots:
        key = str(p)
        if key not in seen:
            seen.add(key)
            unique.append(p)
    return unique

def _iter_source_files(extra_roots: Iterable[str | Path] | None = None) -> Iterator[tuple[str, str, str]]:
    """Yield (filename, text, source_label) from TS/JSON files and ZIP archives.

    V2.11 speed fix:
    - prune heavy folders such as node_modules, .git, .venv, __pycache__;
    - scan project root shallowly for ZIPs but avoid expensive irrelevant trees;
    - ignore lock/cache/build outputs.
    """
    seen_payloads: set[str] = set()
    roots = _candidate_source_roots(extra_roots)
    allowed_ext = {".ts", ".tsx", ".json", ".geojson"}
    ignored_names = {"package-lock.json", "Cargo.lock", "api-cache.json", "pnpm-lock.yaml", "yarn.lock"}
    ignored_dirs = {
        ".git", ".venv", "venv", "env", "node_modules", "__pycache__", ".pytest_cache",
        ".mypy_cache", ".ruff_cache", ".streamlit", "dist", "build", ".next", ".vite",
        "target", ".cache", ".npm", ".pnpm-store",
    }

    for root in roots:
        root = Path(root)

        # ZIP archives at this root. This is cheap and important when iLoveZIP files
        # are placed next to app.py.
        try:
            zips = list(root.glob("*.zip"))
        except Exception:
            zips = []
        for zpath in zips:
            try:
                with zipfile.ZipFile(zpath) as zf:
                    for info in zf.infolist():
                        name = Path(info.filename).name
                        if not name or name.startswith("."):
                            continue
                        suffix = Path(name).suffix.lower()
                        if suffix not in allowed_ext or name in ignored_names:
                            continue
                        # Skip generated/cache folders inside ZIPs.
                        parts = set(Path(info.filename).parts)
                        if parts.intersection(ignored_dirs):
                            continue
                        try:
                            raw = zf.read(info.filename)
                            text = raw.decode("utf-8", errors="ignore")
                        except Exception:
                            continue
                        h = hashlib.sha1((name + "\0" + text[:200000]).encode("utf-8", "ignore")).hexdigest()
                        if h in seen_payloads:
                            continue
                        seen_payloads.add(h)
                        yield name, text, f"{zpath.name}:{info.filename}"
            except Exception:
                continue

        # Extracted source files with pruned walking.
        try:
            for dirpath, dirnames, filenames in os.walk(root):
                dirnames[:] = [d for d in dirnames if d not in ignored_dirs and not d.startswith(".")]
                # If this is the app root, do not descend into arbitrary heavy project
                # trees except known WorldMonitor/source/data folders.
                rel_parts = Path(dirpath).resolve().relative_to(root.resolve()).parts if Path(dirpath).resolve() != root.resolve() else ()
                if root.name in {"quant-terminal", "workspace", "workspaces"} and rel_parts:
                    first = rel_parts[0]
                    allowed_first = {"src", "data", "worldmonitor", "worldmonitor_original", "wm_all", "wm_original"}
                    if first not in allowed_first:
                        dirnames[:] = []
                        continue

                for fname in filenames:
                    if fname.startswith(".") or fname in ignored_names:
                        continue
                    path = Path(dirpath) / fname
                    if path.suffix.lower() not in allowed_ext:
                        continue
                    try:
                        text = path.read_text(encoding="utf-8", errors="ignore")
                    except Exception:
                        continue
                    h = hashlib.sha1((path.name + "\0" + text[:200000]).encode("utf-8", "ignore")).hexdigest()
                    if h in seen_payloads:
                        continue
                    seen_payloads.add(h)
                    yield path.name, text, str(path)
        except Exception:
            pass

def _strip_ts_comments(text: str) -> str:
    out: list[str] = []
    i = 0
    n = len(text)
    quote: str | None = None
    while i < n:
        c = text[i]
        nxt = text[i + 1] if i + 1 < n else ""
        if quote:
            out.append(c)
            if c == "\\" and i + 1 < n:
                i += 1
                out.append(text[i])
            elif c == quote:
                quote = None
            i += 1
            continue
        if c in {"'", '"', "`"}:
            quote = c
            out.append(c)
            i += 1
            continue
        if c == "/" and nxt == "/":
            while i < n and text[i] != "\n":
                i += 1
            out.append("\n")
            continue
        if c == "/" and nxt == "*":
            i += 2
            while i + 1 < n and not (text[i] == "*" and text[i + 1] == "/"):
                i += 1
            i += 2
            continue
        out.append(c)
        i += 1
    return "".join(out)


def _find_ts_arrays(text: str) -> Iterator[tuple[str, str]]:
    stripped = _strip_ts_comments(text)
    pattern = re.compile(r"(?:export\s+)?const\s+([A-Za-z_$][\w$]*)\s*(?::[^=]+)?=\s*\[", re.M)
    for match in pattern.finditer(stripped):
        name = match.group(1)
        start = match.end() - 1
        depth = 0
        i = start
        quote: str | None = None
        while i < len(stripped):
            c = stripped[i]
            if quote:
                if c == "\\":
                    i += 2
                    continue
                if c == quote:
                    quote = None
            else:
                if c in {"'", '"', "`"}:
                    quote = c
                elif c == "[":
                    depth += 1
                elif c == "]":
                    depth -= 1
                    if depth == 0:
                        yield name, stripped[start : i + 1]
                        break
            i += 1


def _parse_ts_array(array_text: str) -> list[Any] | None:
    if json5 is None:
        return None
    cleaned = re.sub(r"\bas\s+const\b", "", array_text)
    cleaned = re.sub(r"\bsatisfies\s+[A-Za-z0-9_<>,\[\]\s]+", "", cleaned)
    try:
        value = json5.loads(cleaned)
        return value if isinstance(value, list) else None
    except Exception:
        return None


def _safe_float(value: Any, default: float | None = None) -> float | None:
    try:
        if value is None:
            return default
        if isinstance(value, (list, tuple, dict)):
            return default
        if pd.isna(value):
            return default
        x = float(value)
        if not math.isfinite(x):
            return default
        return x
    except Exception:
        return default


def _valid_latlon(lat: Any, lon: Any) -> bool:
    la = _safe_float(lat)
    lo = _safe_float(lon)
    return la is not None and lo is not None and -90 <= la <= 90 and -180 <= lo <= 180


def _id_hash(*parts: Any) -> str:
    raw = "|".join(str(p) for p in parts)
    return hashlib.sha1(raw.encode("utf-8", "ignore")).hexdigest()[:16]


def _text(value: Any, default: str = "") -> str:
    if value is None:
        return default
    try:
        if pd.isna(value):
            return default
    except Exception:
        pass
    s = str(value).strip()
    return s if s else default


def _title_from_record(record: dict[str, Any]) -> str:
    for key in ["name", "title", "city", "facility", "airport", "exchange", "company", "id"]:
        value = _text(record.get(key), "")
        if value:
            return value
    return "Untitled object"


def _metadata_preview(record: dict[str, Any], max_len: int = 1200) -> str:
    keep = {}
    for k, v in record.items():
        if k in {"lat", "lon", "lng", "points", "coords", "coordinates"}:
            continue
        if isinstance(v, (str, int, float, bool)) or v is None:
            keep[k] = v
        elif isinstance(v, list):
            keep[k] = ", ".join(_text(x) for x in v[:8])
        elif isinstance(v, dict):
            keep[k] = {kk: vv for kk, vv in list(v.items())[:6] if isinstance(vv, (str, int, float, bool))}
    try:
        return json.dumps(keep, ensure_ascii=False, default=str)[:max_len]
    except Exception:
        return str(keep)[:max_len]


def _points_from_any(value: Any) -> list[tuple[float, float]]:
    """Return list of (lon, lat). Handles [[lon,lat], ...]."""
    out: list[tuple[float, float]] = []
    if not isinstance(value, list):
        return out
    for item in value:
        if isinstance(item, (list, tuple)) and len(item) >= 2:
            lon = _safe_float(item[0])
            lat = _safe_float(item[1])
            if _valid_latlon(lat, lon):
                out.append((float(lon), float(lat)))
        elif isinstance(item, dict):
            lat = _safe_float(item.get("lat"))
            lon = _safe_float(item.get("lon", item.get("lng")))
            if _valid_latlon(lat, lon):
                out.append((float(lon), float(lat)))
    return out


