def _summary_metrics(objects: pd.DataFrame, registry: pd.DataFrame, static_status: pd.DataFrame, live_status: pd.DataFrame) -> dict[str, Any]:
    total = len(objects) if isinstance(objects, pd.DataFrame) else 0
    active_layers = int((registry["count"] > 0).sum()) if isinstance(registry, pd.DataFrame) and not registry.empty else 0
    enabled_layers = int(registry["enabled"].sum()) if isinstance(registry, pd.DataFrame) and not registry.empty else 0
    live_rows = int((objects["source_class"].astype(str) == "live").sum()) if total and "source_class" in objects.columns else 0
    static_rows = total - live_rows
    source_files = int(static_status["file"].nunique()) if isinstance(static_status, pd.DataFrame) and not static_status.empty and "file" in static_status.columns else 0
    ok_live = int(((live_status.get("status", pd.Series(dtype=str)).astype(str).str.upper() == "OK") & (pd.to_numeric(live_status.get("rows", pd.Series(dtype=float)), errors="coerce").fillna(0) > 0)).sum()) if isinstance(live_status, pd.DataFrame) and not live_status.empty else 0
    return {"total": total, "static": static_rows, "live": live_rows, "active_layers": active_layers, "enabled_layers": enabled_layers, "source_files": source_files, "ok_live": ok_live}



def _zip_source_health_v211(extra_roots: str = "") -> pd.DataFrame:
    """Fast diagnostic for local ZIP source discovery.

    Does not parse TypeScript arrays; it only checks whether readable ZIP files
    are present in the roots that V2.11 scans. This makes the Diagnostics tab
    immediately actionable when the bridge falls back to a weak static set.
    """
    rows: list[dict[str, Any]] = []
    roots = _candidate_source_roots([x.strip() for x in str(extra_roots or "").split(";") if x.strip()])
    seen: set[str] = set()
    for root in roots:
        try:
            for zpath in Path(root).glob("*.zip"):
                key = str(zpath.resolve())
                if key in seen:
                    continue
                seen.add(key)
                row = {"zip": zpath.name, "path": str(zpath), "readable": False, "files": 0, "ts_tsx": 0, "detail": ""}
                try:
                    with zipfile.ZipFile(zpath) as zf:
                        names = zf.namelist()
                        row["readable"] = True
                        row["files"] = len(names)
                        row["ts_tsx"] = len([n for n in names if n.endswith((".ts", ".tsx"))])
                        row["detail"] = "ZIP OK"
                except Exception as exc:
                    row["detail"] = f"{type(exc).__name__}: {str(exc)[:160]}"
                rows.append(row)
        except Exception:
            continue
    if not rows:
        rows.append({"zip": "NONE", "path": "", "readable": False, "files": 0, "ts_tsx": 0, "detail": "No ZIP detected in scanned source roots"})
    return pd.DataFrame(rows)

def _source_diagnostic_summary_v211(static_status: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(static_status, pd.DataFrame) or static_status.empty:
        return pd.DataFrame([{"metric": "static_status", "value": "empty"}])
    rows: list[dict[str, Any]] = []
    try:
        discovery = static_status[static_status["file"].astype(str).eq("SOURCE_DISCOVERY")]
        if not discovery.empty:
            rows.append({"metric": "source_discovery", "value": str(discovery.iloc[0].get("detail", ""))})
        ok = static_status[static_status.get("status", pd.Series(dtype=str)).astype(str).str.upper().eq("OK")]
        rows.append({"metric": "ok_collections", "value": int(len(ok))})
        rows.append({"metric": "source_files", "value": int(static_status.get("file", pd.Series(dtype=str)).nunique())})
        if "rows" in static_status.columns:
            rows.append({"metric": "loaded_rows", "value": int(pd.to_numeric(static_status["rows"], errors="coerce").fillna(0).sum())})
        if "detail" in static_status.columns:
            zip_hits = static_status[static_status["detail"].astype(str).str.contains(".zip", case=False, na=False)]
            rows.append({"metric": "zip_backed_collections", "value": int(len(zip_hits))})
            rows.append({"metric": "fallback_used", "value": bool(static_status["file"].astype(str).str.contains("FALLBACK", case=False, na=False).any())})
    except Exception as exc:
        rows.append({"metric": "diagnostic_error", "value": str(exc)[:160]})
    return pd.DataFrame(rows)



def _live_mode_status_v211(data_mode: str, live_status: pd.DataFrame, live_objects: pd.DataFrame) -> pd.DataFrame:
    gem = _load_global_event_module()
    rows = [
        {"item": "data_mode", "status": str(data_mode), "rows": "", "detail": "Static only is the fast default; Static + Live calls global_event_map providers."},
        {"item": "global_event_map", "status": "OK" if gem is not None else "SKIP", "rows": "", "detail": "Live adapter source module."},
        {"item": "live_objects", "status": "OK" if isinstance(live_objects, pd.DataFrame) and not live_objects.empty else ("OFF" if data_mode == "Static only" else "EMPTY"), "rows": len(live_objects) if isinstance(live_objects, pd.DataFrame) else 0, "detail": "Normalized live objects appended to the registry."},
    ]
    if isinstance(live_status, pd.DataFrame) and not live_status.empty:
        for _, r in live_status.iterrows():
            rows.append({
                "item": _text(r.get("provider"), "provider"),
                "status": _text(r.get("status"), ""),
                "rows": r.get("rows", 0),
                "detail": _text(r.get("detail"), ""),
            })
    return pd.DataFrame(rows)



def _worldmonitor_source_coverage_v211(extra_roots: str = "") -> pd.DataFrame:
    rows: list[dict[str, Any]] = []
    roots = _candidate_source_roots([x.strip() for x in str(extra_roots or "").split(";") if x.strip()])
    seen: set[str] = set()
    buckets = {
        "map/config geospatial": 0,
        "panels/ui": 0,
        "services/analytics": 0,
        "feeds/runtime": 0,
        "types/api/proto/docs": 0,
        "other": 0,
    }
    total_ts = 0
    total_files = 0
    for root in roots:
        try:
            for zpath in Path(root).glob("*.zip"):
                key = str(zpath.resolve())
                if key in seen:
                    continue
                seen.add(key)
                try:
                    with zipfile.ZipFile(zpath) as zf:
                        for name in zf.namelist():
                            if name.endswith("/"):
                                continue
                            total_files += 1
                            low = name.lower()
                            if name.endswith((".ts", ".tsx")):
                                total_ts += 1
                            if any(x in low for x in ["geo.ts", "ports.ts", "pipelines.ts", "trade-routes.ts", "bases", "airports", "datacenters", "finance-geo", "tech-geo", "irradiators"]):
                                buckets["map/config geospatial"] += 1
                            elif any(x in low for x in ["panel", "modal", "widget", "map.ts", "deckgl", "app.ts", "settings", "webcam"]):
                                buckets["panels/ui"] += 1
                            elif any(x in low for x in ["analysis", "clustering", "convergence", "freshness", "military", "cascade", "classifier", "worker"]):
                                buckets["services/analytics"] += 1
                            elif any(x in low for x in ["feed", "rss", "gdelt", "runtime", "relay", "api-cache"]):
                                buckets["feeds/runtime"] += 1
                            elif any(x in low for x in ["proto", "api", "types", "docs", "readme", "reference"]):
                                buckets["types/api/proto/docs"] += 1
                            else:
                                buckets["other"] += 1
                except Exception:
                    continue
        except Exception:
            continue
    for k, v in buckets.items():
        rows.append({"bucket": k, "files": int(v)})
    rows.insert(0, {"bucket": "TOTAL files in readable ZIPs", "files": int(total_files)})
    rows.insert(1, {"bucket": "TS/TSX files in readable ZIPs", "files": int(total_ts)})
    rows.append({"bucket": "note", "files": "UI/panel/service files are detected but not rendered in Plotly; full parity requires a Vite/deck.gl micro-frontend."})
    return pd.DataFrame(rows)

