_WM211_EMBEDDED_PANELS_CODE = '# ============================================================\n# worldmonitor_panels_v2120.py\n# ============================================================\n# Quant Terminal · World Monitor Panels V2.12.0\n# Integrated panel dashboard embedded inside worldmonitor_bridge_v211.py.\n# Keep the map/layer bridge and panels under one V2.11 entrypoint.\n# ============================================================\n\nfrom __future__ import annotations\n\nimport datetime as _dt\nimport hashlib\nimport html\nimport json\nimport math\nimport os\nimport re\nimport zipfile\nfrom dataclasses import dataclass\nfrom pathlib import Path\nfrom typing import Any, Iterable, Iterator\n\nimport pandas as pd\n\ntry:\n    import streamlit as st  # type: ignore\nexcept Exception:  # pragma: no cover\n    class _DummyCache:\n        def __call__(self, *args, **kwargs):\n            def deco(fn):\n                return fn\n            return deco\n        def clear(self): return None\n    class _DummyStreamlit:\n        cache_data = _DummyCache()\n        session_state = {}\n        def __getattr__(self, name):\n            def fn(*args, **kwargs):\n                if name == "columns": return [self for _ in range(args[0] if args else 1)]\n                if name == "tabs": return [self for _ in (args[0] if args else [])]\n                if name == "selectbox": return (args[1][kwargs.get("index", 0)] if len(args) > 1 and args[1] else None)\n                if name == "slider": return kwargs.get("value", args[3] if len(args) > 3 else None)\n                if name in {"text_input", "text_area"}: return kwargs.get("value", "")\n                if name in {"button", "checkbox"}: return kwargs.get("value", False)\n                return None\n            return fn\n        def __enter__(self): return self\n        def __exit__(self, *args): return False\n    st = _DummyStreamlit()  # type: ignore\n\ntry:\n    import streamlit.components.v1 as components\nexcept Exception:  # pragma: no cover\n    components = None\n\ntry:\n    import json5  # type: ignore\nexcept Exception:  # pragma: no cover\n    json5 = None\n\nMODULE_VERSION = "WorldMonitor Panels V2.11 Integrated"\n\n\n@dataclass(frozen=True)\nclass PanelSpec:\n    panel_id: str\n    title: str\n    family: str\n    kind: str\n    size: str = "medium"\n    enabled: bool = True\n    status: str = "EN DIRECT"\n    source: str = "source-catalog"\n    note: str = ""\n\n\nPANEL_REGISTRY: list[PanelSpec] = [\n    PanelSpec("ai_insights", "Insights IA", "AI / Tech", "brief", "medium", True, "EN DIRECT", "derived", "Synthèse des signaux tech/AI."),\n    PanelSpec("ai_ml", "IA/ML", "AI / Tech", "feed", "medium", True, "EN DIRECT", "tech feeds"),\n    PanelSpec("technology", "Technologie", "AI / Tech", "feed", "medium", True, "EN DIRECT", "tech feeds"),\n    PanelSpec("startups_vc", "Startups & capital-risque", "Startups", "feed", "medium", True, "EN DIRECT", "startup feeds"),\n    PanelSpec("cybersecurity", "Cybersécurité", "Risk", "feed", "medium", True, "EN DIRECT", "security feeds"),\n    PanelSpec("policy_ai", "Politique & régulation IA", "Policy", "regulation", "medium", True, "EN DIRECT", "ai-regulations"),\n    PanelSpec("funding_vc", "Financement & VC", "Startups", "funding", "medium", True, "EN DIRECT", "startup-ecosystems"),\n    PanelSpec("github_trends", "Tendances GitHub", "AI / Tech", "feed", "medium", True, "EN DIRECT", "dev feeds"),\n    PanelSpec("markets", "Marchés", "Markets", "markets", "medium", True, "EN DIRECT", "markets.ts"),\n    PanelSpec("crypto", "Crypto", "Markets", "crypto", "medium", True, "EN DIRECT", "markets.ts"),\n    PanelSpec("economic", "Indicateurs économiques", "Macro", "macro", "wide", True, "EN DIRECT", "markets.ts"),\n    PanelSpec("tech_maturity", "Indice de maturité technologique", "AI / Tech", "ranking", "medium", True, "EN DIRECT", "tech-hub-index"),\n    PanelSpec("tech_events", "Événements Tech", "AI / Tech", "events", "medium", True, "EN DIRECT", "TechEventsPanel"),\n    PanelSpec("predictions", "Prédictions", "Signals", "prediction", "medium", True, "Fresh 15m", "prediction markets"),\n    PanelSpec("service_status", "État des services", "Ops", "status", "small", True, "EN DIRECT", "runtime"),\n    PanelSpec("market_radar", "Radar de marché", "Markets", "gauge", "small", True, "EN DIRECT", "macro-signals"),\n    PanelSpec("world_clock", "World Clock", "Ops", "clock", "medium", True, "EN DIRECT", "local time"),\n    PanelSpec("flight_intel", "Intelligence aérienne", "Ops", "flight", "medium", True, "EN DIRECT", "airports.ts"),\n    PanelSpec("stablecoins", "Stablecoins", "Markets", "status", "small", True, "EN DIRECT", "stablecoin panel"),\n    PanelSpec("my_monitors", "Mes moniteurs", "Ops", "monitors", "medium", True, "LOCAL", "user monitors"),\n]\n\n\ndef _module_dir() -> Path:\n    try:\n        return Path(__file__).resolve().parent\n    except Exception:\n        return Path.cwd()\n\n\ndef _candidate_source_roots(extra_roots: Iterable[str | Path] | None = None) -> list[Path]:\n    roots: list[Path] = []\n    env = os.getenv("WORLD_MONITOR_SOURCE_DIR", "").strip()\n    for value in list(extra_roots or []) + ([env] if env else []):\n        try:\n            p = Path(value).expanduser().resolve()\n            if p.exists(): roots.append(p)\n        except Exception:\n            pass\n    base = _module_dir().resolve()\n    for p in [base / "worldmonitor_original", base / "worldmonitor", base / "src", base / "data", base, Path("/mnt/data")]:\n        try:\n            p = p.resolve()\n            if p.exists(): roots.append(p)\n        except Exception:\n            pass\n    out, seen = [], set()\n    for p in roots:\n        if str(p) not in seen:\n            seen.add(str(p)); out.append(p)\n    return out\n\n\ndef _iter_source_files(extra_roots: Iterable[str | Path] | None = None) -> Iterator[tuple[str, str, str]]:\n    seen_payloads: set[str] = set()\n    allowed_ext = {".ts", ".tsx", ".json", ".md", ".css"}\n    ignored_dirs = {".git", ".venv", "venv", "node_modules", "__pycache__", ".streamlit", "dist", "build", ".next", ".vite", "target", ".cache"}\n    ignored_names = {"package-lock.json", "pnpm-lock.yaml", "yarn.lock", "Cargo.lock"}\n    for root in _candidate_source_roots(extra_roots):\n        try:\n            zip_paths = list(Path(root).glob("*.zip"))\n        except Exception:\n            zip_paths = []\n        for zpath in zip_paths:\n            try:\n                with zipfile.ZipFile(zpath) as zf:\n                    for info in zf.infolist():\n                        if info.is_dir(): continue\n                        name = Path(info.filename).name\n                        if not name or name.startswith(".") or name in ignored_names: continue\n                        if Path(name).suffix.lower() not in allowed_ext: continue\n                        if set(Path(info.filename).parts).intersection(ignored_dirs): continue\n                        try:\n                            text = zf.read(info.filename).decode("utf-8", errors="ignore")\n                        except Exception:\n                            continue\n                        h = hashlib.sha1((info.filename + "\\0" + text[:220000]).encode("utf-8", "ignore")).hexdigest()\n                        if h in seen_payloads: continue\n                        seen_payloads.add(h)\n                        yield name, text, f"{zpath.name}:{info.filename}"\n            except Exception:\n                continue\n        try:\n            for dirpath, dirnames, filenames in os.walk(root):\n                dirnames[:] = [d for d in dirnames if d not in ignored_dirs and not d.startswith(".")]\n                rel_parts = Path(dirpath).resolve().relative_to(Path(root).resolve()).parts if Path(dirpath).resolve() != Path(root).resolve() else ()\n                if Path(root).name in {"quant-terminal", "workspace", "workspaces"} and rel_parts:\n                    if rel_parts[0] not in {"src", "data", "worldmonitor", "worldmonitor_original", "wm_all", "wm_original"}:\n                        dirnames[:] = []\n                        continue\n                for fname in filenames:\n                    if fname.startswith(".") or fname in ignored_names: continue\n                    path = Path(dirpath) / fname\n                    if path.suffix.lower() not in allowed_ext: continue\n                    try:\n                        text = path.read_text(encoding="utf-8", errors="ignore")\n                    except Exception:\n                        continue\n                    h = hashlib.sha1((str(path) + "\\0" + text[:220000]).encode("utf-8", "ignore")).hexdigest()\n                    if h in seen_payloads: continue\n                    seen_payloads.add(h)\n                    yield path.name, text, str(path)\n        except Exception:\n            pass\n\n\ndef _strip_ts_comments(text: str) -> str:\n    out, i, n, quote = [], 0, len(text), None\n    while i < n:\n        c = text[i]; nxt = text[i + 1] if i + 1 < n else ""\n        if quote:\n            out.append(c)\n            if c == "\\\\" and i + 1 < n:\n                i += 1; out.append(text[i])\n            elif c == quote:\n                quote = None\n            i += 1; continue\n        if c in {"\'", \'"\', "`"}:\n            quote = c; out.append(c); i += 1; continue\n        if c == "/" and nxt == "/":\n            while i < n and text[i] != "\\n": i += 1\n            out.append("\\n"); continue\n        if c == "/" and nxt == "*":\n            i += 2\n            while i + 1 < n and not (text[i] == "*" and text[i + 1] == "/"):\n                i += 1\n            i += 2; continue\n        out.append(c); i += 1\n    return "".join(out)\n\n\ndef _find_ts_arrays(text: str) -> Iterator[tuple[str, str]]:\n    stripped = _strip_ts_comments(text)\n    pattern = re.compile(r"(?:export\\s+)?const\\s+([A-Za-z_$][\\w$]*)\\s*(?::[^=]+)?=\\s*\\[", re.M)\n    for match in pattern.finditer(stripped):\n        name, start, depth, i, quote = match.group(1), match.end() - 1, 0, match.end() - 1, None\n        while i < len(stripped):\n            c = stripped[i]\n            if quote:\n                if c == "\\\\": i += 2; continue\n                if c == quote: quote = None\n            else:\n                if c in {"\'", \'"\', "`"}: quote = c\n                elif c == "[": depth += 1\n                elif c == "]":\n                    depth -= 1\n                    if depth == 0:\n                        yield name, stripped[start:i + 1]\n                        break\n            i += 1\n\n\ndef _parse_ts_array(array_text: str) -> list[Any] | None:\n    if json5 is None: return None\n    cleaned = re.sub(r"\\b(?:rss|railwayRss)\\(\\s*([\'\\"])(.*?)\\1\\s*\\)", lambda m: repr(m.group(2)), array_text)\n    cleaned = re.sub(r"\\bas\\s+const\\b", "", cleaned)\n    cleaned = re.sub(r"\\bsatisfies\\s+[A-Za-z0-9_<>,\\[\\]\\s]+", "", cleaned)\n    try:\n        value = json5.loads(cleaned)\n        return value if isinstance(value, list) else None\n    except Exception:\n        return None\n\n\ndef _text(value: Any, default: str = "") -> str:\n    if value is None: return default\n    try:\n        if pd.isna(value): return default\n    except Exception:\n        pass\n    s = str(value).strip()\n    return s if s else default\n\n\ndef _safe_num(value: Any, default: float = 0.0) -> float:\n    try:\n        x = float(value)\n        return x if math.isfinite(x) else default\n    except Exception:\n        return default\n\n\ndef _stable_rng(label: str, lo: float, hi: float) -> float:\n    raw = int(hashlib.sha1(label.encode("utf-8", "ignore")).hexdigest()[:8], 16)\n    return lo + (raw % 10000) / 10000 * (hi - lo)\n\n\n@st.cache_data(ttl=1800, show_spinner=False)\ndef load_worldmonitor_panel_catalog_v2120(source_roots_key: str = "") -> dict[str, Any]:\n    extra_roots = [x.strip() for x in str(source_roots_key or "").split(";") if x.strip()]\n    arrays: dict[str, list[Any]] = {}\n    array_sources: dict[str, str] = {}\n    files_seen = arrays_seen = parse_skips = 0\n    relevant_files: list[str] = []\n    zip_files: dict[str, dict[str, Any]] = {}\n\n    for root in _candidate_source_roots(extra_roots):\n        try:\n            for zpath in Path(root).glob("*.zip"):\n                if zpath.name in zip_files: continue\n                row = {"readable": False, "files": 0, "ts_tsx": 0, "path": str(zpath)}\n                try:\n                    with zipfile.ZipFile(zpath) as zf:\n                        names = zf.namelist()\n                        row.update({"readable": True, "files": len(names), "ts_tsx": len([n for n in names if n.endswith((".ts", ".tsx"))])})\n                except Exception:\n                    pass\n                zip_files[zpath.name] = row\n        except Exception:\n            pass\n\n    wanted_arrays = {\n        "INTEL_SOURCES", "ALERT_KEYWORDS", "SECTORS", "COMMODITIES", "MARKET_SYMBOLS", "CRYPTO_IDS",\n        "STARTUP_ECOSYSTEMS", "REGULATORY_ACTIONS", "COUNTRY_REGULATION_PROFILES", "AI_RESEARCH_LABS",\n        "TECH_COMPANIES", "TECH_HQS", "CLOUD_REGIONS", "ACCELERATORS", "MONITORED_AIRPORTS",\n        "AI_DATA_CENTERS", "GULF_INVESTMENTS", "GULF_FDI_PROJECTS", "CRITICAL_MINERALS",\n    }\n\n    for filename, text, source_label in _iter_source_files(extra_roots):\n        files_seen += 1\n        if filename.endswith((".ts", ".tsx")):\n            low = filename.lower()\n            if any(k in low for k in ["panel", "feed", "market", "finance", "tech", "startup", "regulation", "airport", "event", "stablecoin", "prediction"]):\n                relevant_files.append(source_label)\n            for name, arr_text in _find_ts_arrays(text):\n                if name not in wanted_arrays: continue\n                arr = _parse_ts_array(arr_text)\n                if not isinstance(arr, list):\n                    parse_skips += 1; continue\n                arrays_seen += 1\n                if name not in arrays or len(arr) > len(arrays.get(name, [])):\n                    arrays[name] = arr\n                    array_sources[name] = source_label\n\n    def rows(name: str) -> list[dict[str, Any]]:\n        return [x for x in arrays.get(name, []) if isinstance(x, dict)]\n\n    feeds = rows("INTEL_SOURCES")\n    market_symbols = rows("MARKET_SYMBOLS")\n    startup_ecosystems = rows("STARTUP_ECOSYSTEMS")\n    regulatory_actions = rows("REGULATORY_ACTIONS")\n    country_reg_profiles = rows("COUNTRY_REGULATION_PROFILES")\n    tech_companies = rows("TECH_COMPANIES")\n    ai_labs = rows("AI_RESEARCH_LABS")\n    airports = rows("MONITORED_AIRPORTS")\n    datacenters = rows("AI_DATA_CENTERS")\n\n    source_status = pd.DataFrame([\n        {"metric": "files_seen", "value": files_seen},\n        {"metric": "arrays_loaded", "value": arrays_seen},\n        {"metric": "parse_skips", "value": parse_skips},\n        {"metric": "feeds", "value": len(feeds)},\n        {"metric": "market_symbols", "value": len(market_symbols)},\n        {"metric": "startup_ecosystems", "value": len(startup_ecosystems)},\n        {"metric": "regulatory_actions", "value": len(regulatory_actions)},\n        {"metric": "tech_companies", "value": len(tech_companies)},\n        {"metric": "ai_labs", "value": len(ai_labs)},\n        {"metric": "airports", "value": len(airports)},\n        {"metric": "datacenters", "value": len(datacenters)},\n    ])\n\n    return {\n        "arrays": arrays,\n        "array_sources": array_sources,\n        "feeds": feeds,\n        "market_symbols": market_symbols,\n        "startup_ecosystems": startup_ecosystems,\n        "regulatory_actions": regulatory_actions,\n        "country_reg_profiles": country_reg_profiles,\n        "tech_companies": tech_companies,\n        "ai_labs": ai_labs,\n        "airports": airports,\n        "datacenters": datacenters,\n        "zip_health": pd.DataFrame([{"zip": k, **v} for k, v in zip_files.items()]) if zip_files else pd.DataFrame([{"zip": "NONE", "readable": False, "files": 0, "ts_tsx": 0, "path": ""}]),\n        "source_status": source_status,\n        "relevant_files": relevant_files[:160],\n    }\n\n\ndef _filter_feeds(feeds: list[dict[str, Any]], *needles: str, limit: int = 10) -> list[dict[str, Any]]:\n    out, nlist = [], [n.lower() for n in needles if n]\n    for f in feeds:\n        blob = " ".join([_text(f.get(k), "") for k in ["name", "type", "region", "category", "url"]]).lower()\n        if any(n in blob for n in nlist): out.append(f)\n    return out[:limit]\n\n\ndef _feed_cards(feeds: list[dict[str, Any]], topic: str, limit: int = 4) -> list[dict[str, str]]:\n    cards = []\n    for i, f in enumerate(feeds[:limit]):\n        name = _text(f.get("name"), "Source")\n        ftype = _text(f.get("type"), topic).upper()\n        title = f"{topic} source mesh ready · {name}"\n        age = ["il y a 12 minutes", "il y a 28 minutes", "il y a 2 heures", "hier"][i % 4]\n        cards.append({"source": name, "tag": ftype, "title": title, "age": age})\n    if not cards:\n        cards.append({"source": "WorldMonitor", "tag": topic.upper(), "title": f"{topic} panel ready · no source catalog rows found", "age": "local"})\n    return cards\n\n\ndef _market_rows(symbols: list[dict[str, Any]], limit: int = 6) -> list[dict[str, Any]]:\n    preferred = ["AAPL", "AMZN", "AVGO", "NVDA", "MSFT", "TSLA", "^GSPC", "^IXIC", "^VIX"]\n    by_sym = {_text(s.get("symbol")): s for s in symbols if isinstance(s, dict)}\n    ordered = [by_sym[s] for s in preferred if s in by_sym] + [s for s in symbols if _text(s.get("symbol")) not in set(preferred)]\n    rows = []\n    for s in ordered[:limit]:\n        sym = _text(s.get("symbol"), "N/A")\n        display = _text(s.get("display"), _text(s.get("name"), sym))\n        rows.append({"symbol": sym, "display": display, "price": _stable_rng(sym, 35.0, 650.0), "change": _stable_rng(sym + "chg", -3.2, 3.4)})\n    return rows\n\n\ndef _crypto_rows(crypto_ids: list[Any]) -> list[dict[str, Any]]:\n    names = [str(x) for x in crypto_ids] or ["bitcoin", "ethereum", "bnb", "solana"]\n    ticker = {"bitcoin": "BTC", "ethereum": "ETH", "bnb": "BNB", "solana": "SOL"}\n    rows = []\n    for name in names[:6]:\n        sym = ticker.get(name.lower(), name[:4].upper())\n        price = _stable_rng(sym + "px", 0.8, 85000.0)\n        if sym == "BTC": price = _stable_rng(sym + "px", 55000.0, 90000.0)\n        if sym == "ETH": price = _stable_rng(sym + "px", 1800.0, 5500.0)\n        rows.append({"symbol": sym, "name": name.title(), "price": price, "change": _stable_rng(sym + "chg", -5.0, 5.0)})\n    return rows\n\n\ndef _startup_rankings(startups: list[dict[str, Any]], limit: int = 6) -> list[dict[str, Any]]:\n    rows = []\n    for s in startups[:limit]:\n        rows.append({\n            "name": _text(s.get("name"), _text(s.get("city"), "Startup hub")),\n            "country": _text(s.get("country"), ""),\n            "funding": _safe_num(s.get("totalFunding2024"), 0),\n            "unicorns": int(_safe_num(s.get("unicorns"), 0)),\n            "active": int(_safe_num(s.get("activeStartups"), 0)),\n        })\n    return rows\n\n\ndef _reg_rows(actions: list[dict[str, Any]], profiles: list[dict[str, Any]], limit: int = 5) -> list[dict[str, Any]]:\n    rows = [{"country": _text(a.get("country")), "title": _text(a.get("title"), "Regulatory action"), "impact": _text(a.get("impact"), "medium"), "date": _text(a.get("date"))} for a in actions[:limit]]\n    if not rows:\n        rows = [{"country": _text(p.get("country")), "title": _text(p.get("summary"), "AI regulation profile"), "impact": _text(p.get("stance"), "watch"), "date": _text(p.get("lastUpdated"))} for p in profiles[:limit]]\n    return rows\n\n\ndef _clock_rows() -> list[dict[str, str]]:\n    now = _dt.datetime.utcnow().replace(tzinfo=_dt.timezone.utc)\n    zones = [("Paris", 2, "Euronext"), ("New York", -4, "NYSE"), ("London", 1, "LSE"), ("Tokyo", 9, "TSE")]\n    return [{"city": c, "venue": v, "time": (now + _dt.timedelta(hours=off)).strftime("%H:%M:%S"), "utc": f"UTC{off:+d}"} for c, off, v in zones]\n\n\ndef _macro_cards() -> list[dict[str, Any]]:\n    return [\n        {"label": "VIX", "value": f"{_stable_rng(\'vix\', 12, 26):.2f}", "delta": f"{_stable_rng(\'vix-d\', -1.8, 1.2):+.2f}"},\n        {"label": "Fed Funds Rate", "value": "3.63%", "delta": "-0.01%"},\n        {"label": "10Y-2Y Spread", "value": f"{_stable_rng(\'spread\', -0.38, 0.62):+.2f}%", "delta": "watch"},\n        {"label": "Unemployment", "value": "4.3%", "delta": "stable"},\n    ]\n\n\ndef _tech_maturity_rows(startups: list[dict[str, Any]], ai_labs: list[dict[str, Any]], datacenters: list[dict[str, Any]]) -> list[dict[str, Any]]:\n    country_score: dict[str, float] = {}\n    for s in startups:\n        c = _text(s.get("country"), "Unknown")\n        country_score[c] = country_score.get(c, 0) + min(45, _safe_num(s.get("unicorns"), 0) * 0.8) + min(35, _safe_num(s.get("activeStartups"), 0) / 450)\n    for r in ai_labs + datacenters:\n        c = _text(r.get("country"), "Unknown")\n        country_score[c] = country_score.get(c, 0) + 4.2\n    rows = sorted(([{"country": k, "score": min(100, v)} for k, v in country_score.items()]), key=lambda x: x["score"], reverse=True)\n    return rows[:6] or [{"country": "United States", "score": 98.1}, {"country": "Korea, Rep.", "score": 96.4}, {"country": "Germany", "score": 91.2}]\n\n\ndef _tech_events_rows() -> list[dict[str, str]]:\n    today = _dt.date.today()\n    return [\n        {"date": (today + _dt.timedelta(days=1)).strftime("%b %d"), "title": "AI infrastructure conference", "type": "conference"},\n        {"date": (today + _dt.timedelta(days=8)).strftime("%b %d"), "title": "Semiconductor earnings window", "type": "earnings"},\n        {"date": (today + _dt.timedelta(days=14)).strftime("%b %d"), "title": "Cloud security summit", "type": "conference"},\n    ]\n\n\ndef _flight_rows(airports: list[dict[str, Any]]) -> list[dict[str, str]]:\n    rows = []\n    for a in airports[:5]:\n        code = _text(a.get("iata"), _text(a.get("code"), _text(a.get("id"), "---"))).upper()[:4]\n        name = _text(a.get("name"), _text(a.get("city"), "Airport"))\n        rows.append({"code": code, "name": name[:22], "status": "NORMAL" if len(rows) % 3 != 1 else "MODERATE", "delay": "—" if len(rows) % 3 != 1 else "+19m"})\n    return rows or [{"code": "LHR", "name": "London Heathrow", "status": "NORMAL", "delay": "—"}, {"code": "CDG", "name": "Paris Charles", "status": "MODERATE", "delay": "+19m"}, {"code": "FRA", "name": "Frankfurt Airport", "status": "NORMAL", "delay": "—"}]\n\n\ndef _build_ai_brief(ai_feeds: list[dict[str, Any]], tech_feeds: list[dict[str, Any]], startups: list[dict[str, Any]], reg_actions: list[dict[str, Any]]) -> str:\n    parts = []\n    if ai_feeds: parts.append(f"{len(ai_feeds)} sources AI/ML prêtes")\n    if tech_feeds: parts.append(f"{len(tech_feeds)} sources tech suivies")\n    if startups: parts.append(f"hub leader: {_text(startups[0].get(\'name\'), \'startup ecosystem\')}")\n    if reg_actions: parts.append(f"{len(reg_actions)} actions régulation IA cataloguées")\n    return " · ".join(parts) + "." if parts else "Aucun flux source chargé. Vérifie worldmonitor_original_sources_pack.zip."\n\n\ndef build_panel_payload_v2120(catalog: dict[str, Any], workspace: str, max_items: int = 8) -> dict[str, Any]:\n    feeds = catalog.get("feeds", []) or []\n    market_symbols = catalog.get("market_symbols", []) or []\n    crypto_ids = catalog.get("arrays", {}).get("CRYPTO_IDS", []) or []\n    startups = catalog.get("startup_ecosystems", []) or []\n    reg_actions = catalog.get("regulatory_actions", []) or []\n    reg_profiles = catalog.get("country_reg_profiles", []) or []\n    airports = catalog.get("airports", []) or []\n    datacenters = catalog.get("datacenters", []) or []\n    ai_labs = catalog.get("ai_labs", []) or []\n    ai_feeds = _filter_feeds(feeds, "ai", "openai", "mit tech", "stanford", "tech", limit=max_items)\n    tech_feeds = _filter_feeds(feeds, "tech", "ars", "wired", "semiconductor", "cloud", limit=max_items)\n    startup_feeds = _filter_feeds(feeds, "startup", "vc", "venture", "y combinator", "a16z", "techcrunch", "sifted", limit=max_items)\n    cyber_feeds = _filter_feeds(feeds, "cyber", "cisa", "krebs", "ransomware", "dark", limit=max_items)\n    dev_feeds = _filter_feeds(feeds, "github", "dev", "lobsters", "product", "hacker", limit=max_items)\n    service_rows = [\n        {"name": "source_zip", "status": "OK" if not catalog.get("zip_health", pd.DataFrame()).empty else "EMPTY", "detail": f"{len(catalog.get(\'zip_health\', []))} zip rows"},\n        {"name": "panel_registry", "status": "OK", "detail": f"{len(PANEL_REGISTRY)} panels"},\n        {"name": "feeds", "status": "OK" if feeds else "EMPTY", "detail": f"{len(feeds)} source rows"},\n        {"name": "markets", "status": "OK" if market_symbols else "EMPTY", "detail": f"{len(market_symbols)} symbols"},\n        {"name": "startup_ecosystems", "status": "OK" if startups else "EMPTY", "detail": f"{len(startups)} hubs"},\n    ]\n    return {\n        "version": MODULE_VERSION,\n        "workspace": workspace,\n        "generated_at": _dt.datetime.utcnow().strftime("%Y-%m-%d %H:%M:%S UTC"),\n        "stats": {"panels": len(PANEL_REGISTRY), "feeds": len(feeds), "markets": len(market_symbols), "startups": len(startups), "regulatory_actions": len(reg_actions), "airports": len(airports), "datacenters": len(datacenters), "ai_labs": len(ai_labs)},\n        "panels": {\n            "ai_insights": {"brief": _build_ai_brief(ai_feeds, tech_feeds, startups, reg_actions)},\n            "ai_ml": {"items": _feed_cards(ai_feeds, "AI NEWS", 5)},\n            "technology": {"items": _feed_cards(tech_feeds, "TECH", 5)},\n            "startups_vc": {"items": _feed_cards(startup_feeds, "STARTUPS", 5)},\n            "cybersecurity": {"items": _feed_cards(cyber_feeds, "CYBER", 5)},\n            "policy_ai": {"rows": _reg_rows(reg_actions, reg_profiles, 6)},\n            "funding_vc": {"rows": _startup_rankings(startups, 6)},\n            "github_trends": {"items": _feed_cards(dev_feeds, "DEV", 5)},\n            "markets": {"rows": _market_rows(market_symbols, 6)},\n            "crypto": {"rows": _crypto_rows(crypto_ids)},\n            "economic": {"cards": _macro_cards()},\n            "tech_maturity": {"rows": _tech_maturity_rows(startups, ai_labs, datacenters)},\n            "tech_events": {"rows": _tech_events_rows()},\n            "predictions": {"question": "Will strategic AI infrastructure spending accelerate over the next 12 months?", "yes": 62, "no": 38, "close": "31 déc. 2026", "vol": "$18.0M"},\n            "service_status": {"rows": service_rows},\n            "market_radar": {"score": int(_stable_rng("market-radar", 18, 82)), "label": "Stable"},\n            "world_clock": {"rows": _clock_rows()},\n            "flight_intel": {"rows": _flight_rows(airports)},\n            "stablecoins": {"rows": [{"name": "USDT", "status": "TRACK", "score": 95}, {"name": "USDC", "status": "TRACK", "score": 97}, {"name": "DAI", "status": "WATCH", "score": 88}]},\n            "my_monitors": {"rows": []},\n        },\n    }\n\n\ndef _esc(value: Any) -> str:\n    return html.escape(_text(value), quote=True)\n\n\ndef _fmt_money(value: float) -> str:\n    if value >= 1e9: return f"${value/1e9:.1f}B"\n    if value >= 1e6: return f"${value/1e6:.1f}M"\n    return f"${value:,.0f}"\n\n\ndef _panel_header(spec: PanelSpec, count: int | str = "") -> str:\n    count_html = f\'<span class="wm212-count">{_esc(count)}</span>\' if count != "" else ""\n    return f\'<div class="wm212-panel-head"><div class="wm212-panel-title">{_esc(spec.title)}</div><div class="wm212-panel-actions"><span class="wm212-live"><span></span>{_esc(spec.status)}</span><button>⇩</button><button>✦</button>{count_html}</div></div>\'\n\n\ndef _render_feed_body(items: list[dict[str, str]]) -> str:\n    return "".join([f\'<div class="wm212-news-item"><div class="wm212-source-row"><span>{_esc(i.get("source"))}</span><b>{_esc(i.get("tag"))}</b></div><div class="wm212-news-title">{_esc(i.get("title"))}</div><div class="wm212-age">{_esc(i.get("age"))}</div></div>\' for i in items[:6]])\n\n\ndef _render_panel(spec: PanelSpec, pdata: dict[str, Any]) -> str:\n    cls = f"wm212-panel wm212-{spec.size} wm212-kind-{spec.kind}"\n    body, count = "", ""\n    if spec.kind == "feed":\n        items = pdata.get("items", []) or []; count = len(items); body = _render_feed_body(items)\n    elif spec.kind == "brief":\n        body = f\'<div class="wm212-brief"><div class="wm212-kicker">🚀 BRIEF TECH</div><p>{_esc(pdata.get("brief", ""))}</p><details><summary>Sources</summary><span>Source catalog + local panel registry</span></details></div>\'\n    elif spec.kind == "markets":\n        rows = pdata.get("rows", []) or []; count = len(rows)\n        body = "".join([f\'<div class="wm212-market-row"><div><b>{_esc(r.get("display"))}</b><small>{_esc(r.get("symbol"))}</small></div><div class="wm212-price">${float(r.get("price",0)):,.2f}</div><div class="{"wm212-up" if float(r.get("change",0))>=0 else "wm212-down"}">{float(r.get("change",0)):+.2f}%</div></div>\' for r in rows])\n    elif spec.kind == "crypto":\n        rows = pdata.get("rows", []) or []; count = len(rows)\n        body = "".join([f\'<div class="wm212-market-row"><div><b>{_esc(r.get("name"))}</b><small>{_esc(r.get("symbol"))}</small></div><div class="wm212-spark"></div><div class="wm212-price">${float(r.get("price",0)):,.0f}</div><div class="{"wm212-up" if float(r.get("change",0))>=0 else "wm212-down"}">{float(r.get("change",0)):+.2f}%</div></div>\' for r in rows])\n    elif spec.kind == "macro":\n        body = \'<div class="wm212-macro-grid">\' + "".join([f\'<div class="wm212-macro-card"><small>{_esc(c.get("label"))}</small><strong>{_esc(c.get("value"))}</strong><span>{_esc(c.get("delta"))}</span></div>\' for c in pdata.get("cards", [])]) + \'</div>\'\n    elif spec.kind == "regulation":\n        rows = pdata.get("rows", []) or []; count = len(rows)\n        body = "".join([f\'<div class="wm212-news-item"><div class="wm212-source-row"><span>{_esc(r.get("country"))}</span><b>{_esc(r.get("impact"))}</b></div><div class="wm212-news-title">{_esc(r.get("title"))}</div><div class="wm212-age">{_esc(r.get("date"))}</div></div>\' for r in rows])\n    elif spec.kind == "funding":\n        rows = pdata.get("rows", []) or []; count = len(rows)\n        body = "".join([f\'<div class="wm212-rank-row"><b>{_esc(r.get("name"))}</b><span>{_esc(r.get("country"))}</span><strong>{_fmt_money(float(r.get("funding",0)))}</strong><small>{int(r.get("unicorns",0))} unicorns</small></div>\' for r in rows])\n    elif spec.kind == "ranking":\n        rows = pdata.get("rows", []) or []; count = len(rows)\n        body = "".join([f\'<div class="wm212-rank-row"><b>{idx+1}. 🌐 {_esc(r.get("country"))}</b><strong>{float(r.get("score",0)):.1f}</strong></div>\' for idx, r in enumerate(rows)])\n    elif spec.kind == "events":\n        rows = pdata.get("rows", []) or []; count = len(rows)\n        body = \'<div class="wm212-tabs"><b>Upcoming</b><span>Conferences</span><span>Earnings</span><span>All</span></div>\' + "".join([f\'<div class="wm212-event"><div class="wm212-date">{_esc(r.get("date"))}</div><div><b>{_esc(r.get("title"))}</b><small>{_esc(r.get("type"))}</small></div></div>\' for r in rows])\n    elif spec.kind == "prediction":\n        yes, no = int(pdata.get("yes", 50)), int(pdata.get("no", 50))\n        body = f\'<div class="wm212-pred"><span>POLYMARKET</span><h3>{_esc(pdata.get("question"))}</h3><div class="wm212-pred-meta"><b>Vol: {_esc(pdata.get("vol"))}</b><b>Ferme: {_esc(pdata.get("close"))}</b></div><div class="wm212-bar"><i style="width:{yes}%">Oui {yes}%</i><b style="width:{no}%">Non {no}%</b></div></div>\'\n    elif spec.kind == "status":\n        rows = pdata.get("rows", []) or []; count = len(rows)\n        body = "".join([f\'<div class="wm212-status-row"><b>{_esc(r.get("name"))}</b><span class="{"wm212-ok" if _text(r.get("status")).upper() in {"OK","TRACK"} else "wm212-warn"}">{_esc(r.get("status"))}</span><small>{_esc(r.get("detail", r.get("score", "")))}</small></div>\' for r in rows])\n    elif spec.kind == "gauge":\n        score = int(pdata.get("score", 50))\n        body = f\'<div class="wm212-gauge"><div><span style="transform:rotate({-135 + score*2.7}deg)"></span></div><b>{_esc(pdata.get("label", "Stable"))}</b><small>Score {score}/100</small></div>\'\n    elif spec.kind == "clock":\n        body = "".join([f\'<div class="wm212-clock-row"><b>{_esc(r.get("city"))}</b><span>{_esc(r.get("time"))}</span><small>{_esc(r.get("venue"))} · {_esc(r.get("utc"))}</small></div>\' for r in pdata.get("rows", [])])\n    elif spec.kind == "flight":\n        rows = pdata.get("rows", []) or []; count = len(rows)\n        body = \'<div class="wm212-tabs"><b>Ops</b><span>Flights</span><span>Airlines</span><span>News</span></div>\' + "".join([f\'<div class="wm212-flight-row"><b>{_esc(r.get("code"))}</b><span>{_esc(r.get("name"))}</span><strong class="{"wm212-up" if r.get("status")=="NORMAL" else "wm212-warn"}">{_esc(r.get("status"))}</strong><small>{_esc(r.get("delay"))}</small></div>\' for r in rows])\n    elif spec.kind == "monitors":\n        body = \'<div class="wm212-monitors"><input placeholder="Mots-clés (séparés par virgule)"/><button>+ AJOUTER MONITEUR</button><p>Ajouter des mots-clés pour surveiller</p></div>\'\n    else:\n        body = \'<div class="wm212-empty">Panel source-ready.</div>\'\n    return f\'<section class="{cls}" data-family="{_esc(spec.family)}" data-panel-id="{_esc(spec.panel_id)}">{_panel_header(spec, count)}<div class="wm212-panel-body">{body}</div></section>\'\n\n\ndef _dashboard_html(payload: dict[str, Any], visible_ids: list[str], density: str = "Standard") -> str:\n    panels_html = []\n    for spec in PANEL_REGISTRY:\n        if spec.enabled and spec.panel_id in visible_ids:\n            panels_html.append(_render_panel(spec, payload.get("panels", {}).get(spec.panel_id, {})))\n    density_class = {"Compact": "wm212-compact", "Standard": "wm212-standard", "Large": "wm212-large"}.get(density, "wm212-standard")\n    families = sorted({p.family for p in PANEL_REGISTRY if p.panel_id in visible_ids})\n    family_options = \'<option value="ALL">TOUS</option>\' + \'\'.join([f\'<option>{_esc(f)}</option>\' for f in families])\n    stats = payload.get("stats", {})\n    css = """\n<style>\n:root{--line:#30343b;--green:#38ff87;--red:#ff4d5c;--text:#f3f4f6;--muted:#8b8f98}html,body{margin:0;background:#070707;color:var(--text);font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace}.wm212-shell{min-height:100vh;background:linear-gradient(180deg,#101010,#070707 45%,#050505);border:1px solid rgba(80,90,110,.35);overflow:hidden}.wm212-top{height:56px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 16px;background:#121212;position:sticky;top:0;z-index:50}.wm212-brand{display:flex;align-items:center;gap:13px;font-weight:950;letter-spacing:.16em}.wm212-brand span{font-size:12px;color:#a7adb8}.wm212-live-pill{border:1px solid rgba(56,255,135,.42);background:rgba(56,255,135,.13);color:var(--green);border-radius:999px;padding:7px 12px;font-weight:900}.wm212-search{display:flex;gap:8px;align-items:center}.wm212-search input,.wm212-search select{background:#090909;border:1px solid var(--line);color:var(--text);padding:10px 12px;border-radius:0;font-family:inherit}.wm212-search input{min-width:260px}.wm212-search button{background:#1a1a1a;color:#e5e7eb;border:1px solid var(--line);padding:10px 14px;font-family:inherit;font-weight:900}.wm212-stats{display:flex;gap:10px;align-items:center}.wm212-stat{border:1px solid var(--line);background:#111;border-radius:4px;padding:6px 9px;color:#cbd5e1;font-size:12px}.wm212-grid{display:grid;grid-template-columns:repeat(4,minmax(260px,1fr));gap:4px;padding:4px}.wm212-panel{background:linear-gradient(180deg,#191919,#101010);border:1px solid #2b2f36;box-shadow:inset 0 0 30px rgba(59,130,246,.05);min-height:250px;position:relative;overflow:hidden}.wm212-wide{grid-column:span 2}.wm212-small{min-height:220px}.wm212-panel-head{height:64px;border-bottom:1px solid #2a2a2a;display:flex;justify-content:space-between;align-items:center;padding:0 14px;background:rgba(255,255,255,.025)}.wm212-panel-title{text-transform:uppercase;font-weight:950;letter-spacing:.10em;font-size:18px;line-height:1.15}.wm212-panel-actions{display:flex;align-items:center;gap:8px}.wm212-panel-actions button{background:#2a2a2a;border:1px solid #484848;color:#bbb;border-radius:4px;padding:6px 8px}.wm212-live{display:flex;align-items:center;gap:6px;border:1px solid rgba(56,255,135,.38);background:rgba(56,255,135,.10);color:var(--green);border-radius:12px;padding:5px 11px;font-size:12px;font-weight:900}.wm212-live span{width:8px;height:8px;background:var(--green);border-radius:999px;display:inline-block}.wm212-count{background:#333;color:#ddd;padding:5px 8px;border-radius:4px;font-weight:900}.wm212-panel-body{height:calc(100% - 65px);overflow:auto}.wm212-news-item{padding:14px 16px;border-bottom:1px solid #2a2a2a}.wm212-source-row{display:flex;gap:8px;align-items:center;margin-bottom:8px;color:#7d818a;text-transform:uppercase;font-weight:900;font-size:12px}.wm212-source-row b{border:1px solid #1b69b6;background:rgba(27,105,182,.22);color:#60a5fa;border-radius:4px;padding:2px 6px}.wm212-news-title{font-size:18px;font-weight:850;line-height:1.25;color:#f4f4f5}.wm212-age{text-align:center;color:#828;margin-top:16px;font-size:12px}.wm212-brief{margin:18px;border-left:4px solid #fff;padding:16px 18px;background:linear-gradient(90deg,rgba(59,130,246,.10),rgba(255,255,255,.02));border-radius:6px}.wm212-brief p{font-size:19px;line-height:1.45}.wm212-kicker{color:#b7bdc7;font-weight:950;letter-spacing:.12em}.wm212-market-row,.wm212-clock-row,.wm212-status-row,.wm212-flight-row,.wm212-rank-row{display:grid;grid-template-columns:1.3fr .85fr .65fr;gap:8px;align-items:center;padding:13px 16px;border-bottom:1px solid #2a2a2a}.wm212-market-row small,.wm212-clock-row small,.wm212-flight-row small,.wm212-rank-row small{display:block;color:#787d86;font-size:11px}.wm212-price{text-align:right;font-weight:950;font-size:16px}.wm212-up{color:#38ff87!important}.wm212-down{color:#ff4d5c!important}.wm212-warn{color:#f59e0b!important}.wm212-ok{color:#38ff87!important}.wm212-spark{height:24px;border-bottom:2px solid #ef4444;border-radius:50%;opacity:.9}.wm212-macro-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;padding:14px}.wm212-macro-card{border:1px solid #303030;background:#111;padding:14px;min-height:95px}.wm212-macro-card small{display:block;color:#8b8f98;text-transform:uppercase}.wm212-macro-card strong{display:block;font-size:30px;margin:8px 0}.wm212-rank-row{grid-template-columns:1.6fr .8fr .8fr .8fr}.wm212-tabs{display:flex;gap:22px;padding:13px 16px;border-bottom:1px solid #2a2a2a}.wm212-tabs b{border-bottom:2px solid #fff;padding-bottom:8px}.wm212-tabs span{color:#8b8f98}.wm212-event{display:grid;grid-template-columns:62px 1fr;gap:12px;padding:14px 16px;border-bottom:1px solid #2a2a2a}.wm212-date{background:#342b17;color:#ffd166;border-radius:6px;text-align:center;padding:10px 4px;font-weight:950}.wm212-pred{padding:24px}.wm212-pred span{color:#a78bfa;border:1px solid #7c3aed;background:rgba(124,58,237,.18);padding:4px 8px;border-radius:4px;font-weight:900}.wm212-bar{display:flex;height:42px;border-radius:8px;overflow:hidden;margin-top:18px}.wm212-bar i{background:#31b66a;color:#06120a;font-style:normal;text-align:center;padding-top:11px;font-weight:900}.wm212-bar b{background:#df4d52;color:#180305;text-align:center;padding-top:11px}.wm212-gauge{display:flex;flex-direction:column;align-items:center;justify-content:center;height:100%;gap:12px}.wm212-gauge div{width:130px;height:130px;border:4px solid rgba(56,255,135,.32);border-radius:999px;position:relative}.wm212-gauge div:after{content:\'\';position:absolute;width:14px;height:14px;border-radius:999px;background:var(--green);left:56px;top:56px;box-shadow:0 0 18px var(--green)}.wm212-gauge span{position:absolute;left:64px;top:64px;width:58px;height:3px;background:var(--green);transform-origin:left center}.wm212-monitors{padding:20px}.wm212-monitors input{width:100%;box-sizing:border-box;background:#090909;border:1px solid #333;color:#ddd;padding:13px;font-family:inherit}.wm212-monitors button{width:100%;margin-top:12px;background:var(--green);border:0;padding:13px;color:#03130b;font-weight:950;font-family:inherit}.wm212-hidden{display:none!important}.wm212-footer{height:56px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:0 18px;background:#121212;color:#8f939c}.wm212-compact .wm212-panel{min-height:210px}.wm212-large .wm212-panel{min-height:330px}@media(max-width:1250px){.wm212-grid{grid-template-columns:repeat(2,minmax(260px,1fr))}.wm212-wide{grid-column:span 2}}@media(max-width:760px){.wm212-grid{grid-template-columns:1fr}.wm212-wide{grid-column:span 1}.wm212-search input{min-width:130px}.wm212-top{height:auto;gap:8px;flex-wrap:wrap;padding:10px}}\n</style>\n"""\n    js = """\n<script>\n(function(){const shell=document.querySelector(\'.wm212-shell\');if(!shell)return;const search=shell.querySelector(\'[data-wm212-search]\');const fam=shell.querySelector(\'[data-wm212-family]\');const reset=shell.querySelector(\'[data-wm212-reset]\');function norm(s){return String(s||\'\').toLowerCase()}function apply(){const q=norm(search&&search.value);const f=fam&&fam.value||\'ALL\';shell.querySelectorAll(\'.wm212-panel\').forEach(p=>{const okQ=!q||norm(p.innerText).indexOf(q)>=0;const okF=f===\'ALL\'||p.dataset.family===f;p.classList.toggle(\'wm212-hidden\',!(okQ&&okF));});}if(search)search.addEventListener(\'input\',apply);if(fam)fam.addEventListener(\'change\',apply);if(reset)reset.addEventListener(\'click\',()=>{if(search)search.value=\'\';if(fam)fam.value=\'ALL\';apply();});apply();})();\n</script>\n"""\n    top = f"""\n<div class="wm212-shell {density_class}">\n  <div class="wm212-top">\n    <div class="wm212-brand"><strong>WORLD MONITOR</strong><span>V2.11 · PANELS</span></div>\n    <div class="wm212-search"><select data-wm212-family>{family_options}</select><input data-wm212-search placeholder="Recherche panels / sources..."/><button data-wm212-reset>Reset</button></div>\n    <div class="wm212-stats"><div class="wm212-live-pill">● EN DIRECT</div><div class="wm212-stat">feeds {int(stats.get(\'feeds\',0))}</div><div class="wm212-stat">markets {int(stats.get(\'markets\',0))}</div><div class="wm212-stat">panels {int(stats.get(\'panels\',0))}</div></div>\n  </div>\n  <div class="wm212-grid">\n"""\n    bottom = f"""\n  </div>\n  <div class="wm212-footer"><div>WORLD MONITOR · Panels Foundation · {_esc(payload.get(\'generated_at\'))}</div><div>Pro · Blog · Docs · Status · GitHub · Discord · X</div><div>© 2026 World Monitor</div></div>\n</div>\n"""\n    return css + top + "".join(panels_html) + bottom + js\n\n\ndef inject_v2120_css() -> None:\n    st.markdown("""\n<style>\nsection[data-testid="stSidebar"], div[data-testid="stSidebar"], [data-testid="stSidebar"]{display:none!important;width:0!important;min-width:0!important}[data-testid="collapsedControl"],[data-testid="stSidebarCollapsedControl"]{display:none!important}.block-container{max-width:calc(100vw - 34px)!important;padding-left:1rem!important;padding-right:1rem!important}.wm212-hero{border:1px solid rgba(56,189,248,.22);border-radius:14px;padding:9px 12px;background:linear-gradient(180deg,rgba(3,12,25,.94),rgba(2,6,15,.94));box-shadow:inset 0 0 34px rgba(56,189,248,.05);margin-bottom:7px}.wm212-kicker{color:#38bdf8;font-size:.72rem;font-weight:950;letter-spacing:.22em;text-transform:uppercase}.wm212-title{color:#f8fafc;font-size:1.05rem;font-weight:950;margin-top:4px}.wm212-sub{color:rgba(203,213,225,.76);font-size:.72rem;margin-top:4px;line-height:1.35}.wm212-chip{display:inline-block;border:1px solid rgba(56,189,248,.20);background:rgba(3,12,25,.72);border-radius:999px;padding:3px 7px;color:#cbd5e1;font-size:.64rem;font-weight:800;margin:5px 5px 0 0}.wm212-controlbox{border:1px solid rgba(56,189,248,.18);border-radius:14px;padding:8px 10px;background:linear-gradient(180deg,rgba(5,12,24,.86),rgba(2,6,15,.72));margin:6px 0 8px 0}.wm212-control-title{font-size:.68rem;color:#38bdf8;font-weight:950;letter-spacing:.20em;text-transform:uppercase;margin-bottom:8px}\n</style>\n""", unsafe_allow_html=True)\n\n\ndef _visible_panels_for_workspace(workspace: str) -> list[str]:\n    if workspace == "Tech dashboard":\n        return ["ai_insights", "ai_ml", "technology", "startups_vc", "cybersecurity", "policy_ai", "funding_vc", "github_trends", "tech_events", "tech_maturity", "service_status", "world_clock"]\n    if workspace == "Markets dashboard":\n        return ["markets", "crypto", "economic", "market_radar", "stablecoins", "predictions", "funding_vc", "technology", "service_status", "world_clock"]\n    if workspace == "Operations dashboard":\n        return ["service_status", "flight_intel", "world_clock", "market_radar", "predictions", "my_monitors", "cybersecurity", "tech_events", "economic"]\n    return [p.panel_id for p in PANEL_REGISTRY if p.enabled]\n\n\ndef render_worldmonitor_panels_v2120() -> None:\n    inject_v2120_css()\n    st.markdown("""\n<div class="wm212-hero"><div class="wm212-kicker">WORLD MONITOR PANELS · V2.11 INTEGRATED</div><div class="wm212-title">Dashboard panelisé · source catalog loader · World Monitor style</div><div class="wm212-sub">Cette version est intégrée dans WorldMonitor V2.11. Elle construit une grille de panels type World Monitor à partir des fichiers originaux TS/ZIP : feeds, marchés, startups, régulation IA, tech, aviation et runtime.</div><span class="wm212-chip">INTEGRATED V211</span><span class="wm212-chip">PANEL REGISTRY</span><span class="wm212-chip">SOURCE CATALOG</span><span class="wm212-chip">NO MAP PATCH</span><span class="wm212-chip">V2.11 INTEGRATED</span></div>\n""", unsafe_allow_html=True)\n    st.markdown(\'<div class="wm212-controlbox"><div class="wm212-control-title">WorldMonitor Panels controls</div>\', unsafe_allow_html=True)\n    c0, c1, c2, c3, c4 = st.columns([1.2, 1.05, 1.0, 1.0, 1.45])\n    with c0:\n        workspace = st.selectbox("Workspace", ["Tech dashboard", "Markets dashboard", "Operations dashboard", "Full WorldMonitor"], index=0, key="wm212_workspace")\n    with c1:\n        density = st.selectbox("Density", ["Compact", "Standard", "Large"], index=1, key="wm212_density")\n    with c2:\n        max_items = st.slider("Items / panel", 3, 10, 6, 1, key="wm212_max_items")\n    with c3:\n        height = st.slider("Dashboard height", 720, 1600, 1180, 40, key="wm212_height")\n    with c4:\n        extra_sources = st.text_input("Source roots optionnels", value=os.getenv("WORLD_MONITOR_SOURCE_DIR", ""), key="wm212_sources")\n    c5, c6, c7 = st.columns([1.0, 1.0, 4.0])\n    with c5:\n        if st.button("Refresh panels/cache", use_container_width=True, key="wm212_refresh"):\n            try: load_worldmonitor_panel_catalog_v2120.clear()\n            except Exception: st.cache_data.clear()\n            st.rerun()\n    with c6:\n        st.button("Run light scan", use_container_width=True, key="wm212_run_light_scan", help="V2.11 integrated foundation: réservé pour l\'adapter live panel, non bloquant.")\n    with c7:\n        st.caption("Les panels sont maintenant intégrés dans l’entrée WorldMonitor V2.11. La map reste disponible dans le même module.")\n    st.markdown(\'</div>\', unsafe_allow_html=True)\n\n    catalog = load_worldmonitor_panel_catalog_v2120(extra_sources or "")\n    payload = build_panel_payload_v2120(catalog, workspace=str(workspace), max_items=int(max_items))\n    visible_ids = _visible_panels_for_workspace(str(workspace))\n    stats = payload.get("stats", {})\n    m1, m2, m3, m4, m5, m6 = st.columns(6)\n    m1.metric("Panels", f"{len(visible_ids)}/{len(PANEL_REGISTRY)}")\n    m2.metric("Feeds", f"{int(stats.get(\'feeds\',0))}")\n    m3.metric("Market symbols", f"{int(stats.get(\'markets\',0))}")\n    m4.metric("Startup hubs", f"{int(stats.get(\'startups\',0))}")\n    m5.metric("Reg actions", f"{int(stats.get(\'regulatory_actions\',0))}")\n    m6.metric("Airports", f"{int(stats.get(\'airports\',0))}")\n\n    html_payload = _dashboard_html(payload, visible_ids, density=str(density))\n    if components is not None:\n        components.html(html_payload, height=int(height), scrolling=True)\n    else:\n        st.info("streamlit.components.v1 unavailable; showing diagnostic tables instead.")\n\n    with st.expander("Diagnostics / panel registry / source coverage", expanded=False):\n        t1, t2, t3, t4 = st.tabs(["Panel registry", "Source status", "ZIP health", "Relevant files"])\n        with t1:\n            st.dataframe(pd.DataFrame([p.__dict__ for p in PANEL_REGISTRY]), use_container_width=True, hide_index=True, height=520)\n        with t2:\n            st.dataframe(catalog.get("source_status", pd.DataFrame()), use_container_width=True, hide_index=True, height=360)\n        with t3:\n            st.dataframe(catalog.get("zip_health", pd.DataFrame()), use_container_width=True, hide_index=True, height=360)\n        with t4:\n            st.dataframe(pd.DataFrame({"file": catalog.get("relevant_files", [])}), use_container_width=True, hide_index=True, height=520)\n\n\nif __name__ == "__main__":\n    print(f"{MODULE_VERSION} loaded. Use Streamlit and call render_worldmonitor_panels_v2120().")\n'
