_WM211_PANELS_NS: dict[str, Any] = _WM211_PANELS_MODULE.__dict__
try:
    exec(_WM211_EMBEDDED_PANELS_CODE, _WM211_PANELS_NS)
except Exception as _wm211_panels_exc:  # defer visible error to UI
    _WM211_PANELS_NS["_EMBEDDED_IMPORT_ERROR"] = _wm211_panels_exc


def _render_worldmonitor_panels_integrated_v211() -> None:
    err = _WM211_PANELS_NS.get("_EMBEDDED_IMPORT_ERROR")
    fn = _WM211_PANELS_NS.get("render_worldmonitor_panels_v2120")
    if err is not None or not callable(fn):
        st.error(f"WorldMonitor integrated panels error: {err}")
        st.info("The map bridge remains available. Check json5/pandas/streamlit components and source ZIP availability.")
        return
    fn()


def render_worldmonitor_bridge_v211() -> None:
    """Unified WorldMonitor V2.11 entrypoint.

    One import, one route, one file:
    - Map / Layers uses the validated V2.11.9 bridge.
    - Panels dashboard is embedded under the same function and file.
    - No separate app route or extra button is required.
    """
    try:
        st.markdown(
            """
            <style>
            .wm211-unified-shell{border:1px solid rgba(56,189,248,.18);border-radius:14px;padding:8px 10px;background:linear-gradient(180deg,rgba(3,12,25,.88),rgba(2,6,15,.74));margin:2px 0 8px 0;}
            .wm211-unified-title{color:#38bdf8;font-size:.70rem;font-weight:950;letter-spacing:.20em;text-transform:uppercase;margin-bottom:6px;}
            .wm211-unified-note{color:rgba(203,213,225,.70);font-size:.74rem;line-height:1.35;}
            </style>
            <div class="wm211-unified-shell">
              <div class="wm211-unified-title">WORLD MONITOR V2.11 · UNIFIED WORKSPACE</div>
              <div class="wm211-unified-note">Une seule entrée : carte/layers V2.11 validée + dashboard panels intégré. Aucun bouton séparé V2.12 requis.</div>
            </div>
            """,
            unsafe_allow_html=True,
        )
        mode = st.selectbox(
            "WorldMonitor workspace",
            ["Map / layers", "Panels dashboard", "Map + panels"],
            index=0,
            key="wm211_unified_workspace_mode",
            help="Map / layers garde la V2.11.9 stable. Panels dashboard affiche la partie WorldMonitor panelisée dans le même module.",
        )
    except Exception:
        mode = "Map / layers"

    if mode == "Panels dashboard":
        _render_worldmonitor_panels_integrated_v211()
    elif mode == "Map + panels":
        render_worldmonitor_map_v211()
        st.divider()
        _render_worldmonitor_panels_integrated_v211()
    else:
        render_worldmonitor_map_v211()


# Keep the direct test print coherent after the unified wrapper is defined.
if __name__ == "__main__":
    print(f"{MODULE_VERSION} loaded. Use Streamlit and call render_worldmonitor_bridge_v211().")


# ============================================================
# CLEAN UNIFIED WORLD MONITOR — user-facing override
# ============================================================
# Purpose:
# - Keep one file and one WorldMonitor V2.11 route.
# - Remove diagnostic tables and excessive control panels from the user UI.
# - Keep the V2.11.9 map/layer engine intact.
# - Add a compact live/static checkbox instead of multiple live controls.
# - Feed panels from live RSS/quote adapters when possible, with local catalog fallback.
# - Make map 2D/3D buttons interactive inside the map itself.

MODULE_VERSION = "WorldMonitor V2.11 Unified Clean"

