def _wm_clean_escape(value: Any) -> str:
    return html.escape(_text(value, ""), quote=True)


@st.cache_data(ttl=600, show_spinner=False)
def _wm_fetch_rss_items_v211(style: str = "Global", country: str = "Global", max_items: int = 40) -> list[dict[str, Any]]:
    """Light RSS adapter for panels. Returns best-effort linked items, never blocks hard."""
    style = str(style or "Global")
    country = str(country or "Global")
    country_q = "" if country == "Global" else f" {country}"

    queries = {
        "Global": ["artificial intelligence geopolitics", "technology markets", "cybersecurity", "startup venture capital"],
        "Tech": ["artificial intelligence", "semiconductors", "cloud infrastructure", "AI regulation"],
        "Finance": ["markets", "crypto", "venture capital", "central banks technology"],
        "Risk": ["cybersecurity", "AI regulation", "internet outage", "geopolitical risk technology"],
        "Ops": ["airport delays", "cloud outage", "cybersecurity alert", "technology events"],
    }.get(style, ["technology"])

    rss_urls: list[tuple[str, str, str]] = []
    for q in queries[:4]:
        enc = _wm_urlparse.quote_plus(q + country_q)
        rss_urls.append(("GOOGLE NEWS", "NEWS", f"https://news.google.com/rss/search?q={enc}&hl=en-US&gl=US&ceid=US:en"))

    rss_urls.extend([
        ("Ars Technica", "TECH", "https://feeds.arstechnica.com/arstechnica/index"),
        ("The Verge", "TECH", "https://www.theverge.com/rss/index.xml"),
        ("Krebs Security", "CYBER", "https://krebsonsecurity.com/feed/"),
        ("TechCrunch Startups", "STARTUP", "https://techcrunch.com/category/startups/feed/"),
        ("CNBC", "MARKETS", "https://www.cnbc.com/id/100003114/device/rss/rss.html"),
    ])

    items: list[dict[str, Any]] = []
    seen: set[str] = set()
    headers = {"User-Agent": "Mozilla/5.0 QuantTerminal WorldMonitor/2.11"}
    for source, tag, url in rss_urls:
        if len(items) >= max_items:
            break
        try:
            req = _wm_urlrequest.Request(url, headers=headers)
            with _wm_urlrequest.urlopen(req, timeout=4) as resp:
                raw = resp.read(500_000)
            root = _wm_et.fromstring(raw)
            for node in root.findall(".//item")[:8]:
                title = _text(node.findtext("title"), "")
                link = _text(node.findtext("link"), "")
                pub = _text(node.findtext("pubDate"), "")
                if not title:
                    continue
                key = title.lower().strip()
                if key in seen:
                    continue
                seen.add(key)
                items.append({"source": source, "tag": tag, "title": title, "url": link, "age": pub[:22] if pub else "live"})
                if len(items) >= max_items:
                    break
        except Exception:
            continue
    return items


@st.cache_data(ttl=90, show_spinner=False)
def _wm_fetch_quote_rows_v211() -> list[dict[str, Any]]:
    symbols = "AAPL,MSFT,NVDA,AMZN,AVGO,TSLA,BTC-USD,ETH-USD,SOL-USD,BNB-USD"
    url = "https://query1.finance.yahoo.com/v7/finance/quote?symbols=" + _wm_urlparse.quote(symbols)
    try:
        req = _wm_urlrequest.Request(url, headers={"User-Agent": "Mozilla/5.0 QuantTerminal"})
        with _wm_urlrequest.urlopen(req, timeout=4) as resp:
            payload = json.loads(resp.read(700_000).decode("utf-8", "ignore"))
        rows = []
        for r in payload.get("quoteResponse", {}).get("result", []):
            sym = _text(r.get("symbol"), "")
            price = r.get("regularMarketPrice")
            chg = r.get("regularMarketChangePercent")
            if sym and price is not None:
                rows.append({"symbol": sym.replace("-USD", ""), "display": sym.replace("-USD", ""), "price": float(price), "change": float(chg or 0)})
        return rows
    except Exception:
        return []


def _wm_filter_country_rows(rows: list[dict[str, Any]], country: str) -> list[dict[str, Any]]:
    if not rows or not country or country == "Global":
        return rows
    out = []
    needle = country.lower()
    for r in rows:
        blob = json.dumps(r, ensure_ascii=False, default=str).lower()
        if needle in blob:
            out.append(r)
    return out or rows


def _wm_panel_header(title: str, count: int | str = "", status: str = "EN DIRECT") -> str:
    return f'<div class="wmc-panel-head"><div>{_wm_clean_escape(title)}</div><div class="wmc-live"><span></span>{_wm_clean_escape(status)}</div><button>⇩</button><button>✦</button><small>{_wm_clean_escape(count)}</small></div>'


def _wm_news_list_html(items: list[dict[str, Any]], max_items: int = 4) -> str:
    if not items:
        return '<div class="wmc-empty">Aucune donnée live disponible · fallback local actif.</div>'
    body = []
    for item in items[:max_items]:
        url = _text(item.get("url"), "")
        title = _wm_clean_escape(item.get("title"))
        source = _wm_clean_escape(item.get("source"))
        tag = _wm_clean_escape(item.get("tag"))
        age = _wm_clean_escape(item.get("age"))
        link = f'<a class="wmc-open" target="_blank" href="{_wm_clean_escape(url)}">↗</a>' if url else '<span class="wmc-open off">·</span>'
        body.append(f'<div class="wmc-item"><div class="wmc-source">{source} <b>{tag}</b></div><div class="wmc-title">{title}</div><div class="wmc-age">{age}</div>{link}</div>')
    return "".join(body)


def _wm_table_rows_html(rows: list[dict[str, Any]], keys: list[str], max_rows: int = 5) -> str:
    if not rows:
        return '<div class="wmc-empty">Pas de lignes disponibles.</div>'
    out = []
    for r in rows[:max_rows]:
        cells = ''.join(f'<td>{_wm_clean_escape(r.get(k, ""))}</td>' for k in keys)
        out.append(f'<tr>{cells}</tr>')
    return '<table class="wmc-table">' + ''.join(out) + '</table>'


def _wm_clean_panel_html(panel_id: str, payload: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], country: str, max_items: int = 5) -> str:
    title = _WM_PANEL_TITLES.get(panel_id, panel_id)
    p = payload.get("panels", {}).get(panel_id, {}) if isinstance(payload, dict) else {}
    count = ""
    body = ""

    if panel_id in {"ai_ml", "technology", "startups_vc", "cybersecurity", "github_trends"}:
        news_key = {
            "ai_ml": "AI",
            "technology": "TECH",
            "startups_vc": "STARTUP",
            "cybersecurity": "CYBER",
            "github_trends": "DEV",
        }.get(panel_id, "TECH")
        items = live_news.get(news_key, []) or p.get("items", [])
        count = len(items)
        body = _wm_news_list_html(items, max_items=max_items)
    elif panel_id == "ai_insights":
        brief = _text(p.get("brief"), "Signaux IA/tech consolidés depuis sources live et catalogue local.")
        top = (live_news.get("AI", []) + live_news.get("TECH", []))[:2]
        body = f'<div class="wmc-brief">🚀 {_wm_clean_escape(brief)}</div>' + _wm_news_list_html(top, max_items=2)
        count = len(top)
    elif panel_id == "markets":
        rows = quote_rows[:6] or p.get("rows", [])
        body = "".join(f'<div class="wmc-market"><span>{_wm_clean_escape(r.get("display", r.get("symbol")))}</span><b>${float(r.get("price",0)):,.2f}</b><em class="{ "up" if float(r.get("change",0))>=0 else "down"}">{float(r.get("change",0)):+.2f}%</em></div>' for r in rows[:6])
        count = len(rows)
    elif panel_id == "crypto":
        rows = [r for r in quote_rows if str(r.get("symbol", "")).upper() in {"BTC", "ETH", "SOL", "BNB"}] or p.get("rows", [])
        body = "".join(f'<div class="wmc-market"><span>{_wm_clean_escape(r.get("symbol", r.get("name")))}</span><b>${float(r.get("price",0)):,.2f}</b><em class="{ "up" if float(r.get("change",0))>=0 else "down"}">{float(r.get("change",0)):+.2f}%</em></div>' for r in rows[:5])
        count = len(rows)
    elif panel_id == "economic":
        cards = p.get("cards", [])
        body = '<div class="wmc-macro">' + ''.join(f'<div><small>{_wm_clean_escape(c.get("label"))}</small><b>{_wm_clean_escape(c.get("value"))}</b><em>{_wm_clean_escape(c.get("delta"))}</em></div>' for c in cards[:4]) + '</div>'
        count = len(cards)
    elif panel_id == "policy_ai":
        rows = _wm_filter_country_rows(p.get("rows", []), country)
        body = _wm_table_rows_html(rows, ["country", "impact", "title", "date"], max_rows=max_items)
        count = len(rows)
    elif panel_id == "funding_vc":
        rows = _wm_filter_country_rows(p.get("rows", []), country)
        body = _wm_table_rows_html(rows, ["name", "country", "funding", "unicorns"], max_rows=max_items)
        count = len(rows)
    elif panel_id == "tech_maturity":
        rows = _wm_filter_country_rows(p.get("rows", []), country)
        body = ''.join(f'<div class="wmc-rank"><span>#{i+1} 🌐 {_wm_clean_escape(r.get("country"))}</span><b>{float(r.get("score",0)):.1f}</b></div>' for i, r in enumerate(rows[:max_items]))
        count = len(rows)
    elif panel_id == "tech_events":
        rows = p.get("rows", [])
        body = ''.join(f'<div class="wmc-event"><b>{_wm_clean_escape(r.get("date"))}</b><span>{_wm_clean_escape(r.get("title"))}</span><em>{_wm_clean_escape(r.get("type"))}</em></div>' for r in rows[:max_items])
        count = len(rows)
    elif panel_id == "predictions":
        yes = int(p.get("yes", 62)); no = int(p.get("no", 38))
        body = f'<div class="wmc-pred"><b>{_wm_clean_escape(p.get("question", "Prediction market"))}</b><div><span style="width:{yes}%">Oui {yes}%</span><em style="width:{no}%">Non {no}%</em></div><small>Vol { _wm_clean_escape(p.get("vol", "")) } · Ferme { _wm_clean_escape(p.get("close", "")) }</small></div>'
        count = "Fresh"
    elif panel_id == "service_status":
        rows = p.get("rows", [])
        body = _wm_table_rows_html(rows, ["name", "status", "detail"], max_rows=max_items)
        count = len(rows)
    elif panel_id == "market_radar":
        score = int(p.get("score", 50)); label = _wm_clean_escape(p.get("label", "Stable"))
        body = f'<div class="wmc-gauge"><div><span style="transform:rotate({score*1.8-90:.0f}deg)"></span></div><b>{label}</b></div>'
        count = score
    elif panel_id == "world_clock":
        rows = p.get("rows", [])
        body = ''.join(f'<div class="wmc-clock"><span>{_wm_clean_escape(r.get("city"))}<small>{_wm_clean_escape(r.get("venue"))}</small></span><b>{_wm_clean_escape(r.get("time"))}</b><em>{_wm_clean_escape(r.get("utc"))}</em></div>' for r in rows[:5])
        count = len(rows)
    elif panel_id == "flight_intel":
        rows = p.get("rows", [])
        body = _wm_table_rows_html(rows, ["code", "name", "status", "delay"], max_rows=max_items)
        count = len(rows)
    elif panel_id == "stablecoins":
        rows = p.get("rows", [])
        body = _wm_table_rows_html(rows, ["name", "status", "score"], max_rows=max_items)
        count = len(rows)
    elif panel_id == "my_monitors":
        body = '<div class="wmc-monitors"><input placeholder="Mots-clés séparés par virgule"/><button>+ AJOUTER MONITEUR</button><small>Surveillance locale à connecter en V2.11 live feeds.</small></div>'
        count = ""
    else:
        items = p.get("items", [])
        body = _wm_news_list_html(items, max_items=max_items)
        count = len(items)

    wide = " wide" if panel_id in {"economic", "tech_events"} else ""
    return f'<section class="wmc-panel{wide}" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, count)}<div class="wmc-body">{body}</div></section>'


