def _render_worldmonitor_map_clean_v211(live_enabled: bool = False) -> None:
    # Fixed operating model: 24h lookback, all earthquakes, all objects, Security Core default.
    static_objects, _static_status = load_worldmonitor_static_objects_v211("")
    live_objects = pd.DataFrame()
    if live_enabled:
        live_objects, _live_status = load_live_event_objects_v211(hours_back=24, min_magnitude=0.0, cache_nonce=0, provider_profile="Fast natural")
    frames = [df for df in [static_objects, live_objects] if isinstance(df, pd.DataFrame) and not df.empty]
    objects = pd.concat(frames, ignore_index=True) if frames else pd.DataFrame(columns=static_objects.columns if isinstance(static_objects, pd.DataFrame) else [])
    if not objects.empty:
        objects = objects.drop_duplicates(subset=["object_id", "kind", "points_json"], keep="first").reset_index(drop=True)
    registry = build_layer_registry_v211(objects, preset="Security Core")
    render_map_v211(objects, registry, region="Global", projection="Flat world", height=700, projection_scale=1.0)


def _render_worldmonitor_panels_clean_v211(style: str = "Global", country: str = "Global", live_enabled: bool = True) -> None:
    err = _WM211_PANELS_NS.get("_EMBEDDED_IMPORT_ERROR") if isinstance(_WM211_PANELS_NS, dict) else None
    if err is not None:
        st.error(f"WorldMonitor panels source loader error: {err}")
        return
    load_fn = _WM211_PANELS_NS.get("load_worldmonitor_panel_catalog_v2120")
    build_fn = _WM211_PANELS_NS.get("build_panel_payload_v2120")
    if not callable(load_fn) or not callable(build_fn):
        st.error("WorldMonitor panels loader unavailable in integrated module.")
        return
    catalog = load_fn("")
    workspace = _WM_STYLE_TO_WORKSPACE.get(style, "Full WorldMonitor")
    payload = build_fn(catalog, workspace=workspace, max_items=5)
    visible_ids = _WM_STYLE_TO_PANELS.get(style, _WM_STYLE_TO_PANELS["Global"])
    live_items = _wm_fetch_rss_items_v211(style, country, max_items=44) if live_enabled else []
    live_news = _wm_bucket_live_news(live_items)
    quote_rows = _wm_fetch_quote_rows_v211() if live_enabled else []
    html_payload = _wm_clean_dashboard_html(payload, visible_ids, style, country, live_news, quote_rows)
    if components is not None:
        components.html(html_payload, height=900, scrolling=True)
    else:
        st.info("streamlit.components.v1 unavailable; panels HTML cannot be rendered.")


def render_worldmonitor_bridge_v211() -> None:
    """Single clean WorldMonitor V2.11 entrypoint: map + live-linked panels, minimal controls."""
    _wm_inject_clean_css_v211()
    st.markdown("""
<div class="wmclean-top"><div class="wmclean-title">WORLD MONITOR V2.11 · UNIFIED CLEAN WORKSPACE</div><div class="wmclean-sub">Carte V2.11 validée + panels intégrés. Commandes réduites : style général, pays/zone et live. Diagnostics masqués.</div></div>
""", unsafe_allow_html=True)

    st.markdown('<div class="wmclean-control">', unsafe_allow_html=True)
    c1, c2, c3, c4 = st.columns([1.2, 1.1, .7, 4])
    with c1:
        style = st.selectbox("Style", ["Global", "Tech", "Finance", "Risk", "Ops"], index=1, key="wm_clean_style")
    with c2:
        country = st.selectbox("Pays / zone", _WM_COUNTRIES, index=0, key="wm_clean_country")
    with c3:
        live_enabled = st.checkbox("Live", value=True, key="wm_clean_live")
    with c4:
        st.markdown('<div class="wmclean-caption">24h par défaut · séismes sans seuil · objets complets par couche · 2D/3D directement dans la carte · panels alimentés par RSS/quotes live avec fallback catalogue local.</div>', unsafe_allow_html=True)
    st.markdown('</div>', unsafe_allow_html=True)

    _render_worldmonitor_map_clean_v211(live_enabled=bool(live_enabled))
    _render_worldmonitor_panels_clean_v211(style=str(style), country=str(country), live_enabled=bool(live_enabled))



# ============================================================
# CLEAN UNIFIED WORLD MONITOR — V2.11.10 UX sizing pass
# ============================================================
# Purpose:
# - Keep one WorldMonitor V2.11 entry and one file.
# - Keep the clean UI, but add the original-style time window row.
# - Keep 2D/3D controls inside the map and make them robustly interactive.
# - Resize panel dashboard cards to WorldMonitor-like tile proportions.
# - Keep diagnostics hidden and live lightweight.

MODULE_VERSION = "WorldMonitor V2.11 Unified Clean UX"

_WM_TIME_OPTIONS = ["1h", "6h", "24h", "48h", "7d", "Tout"]
_WM_TIME_TO_HOURS = {"1h": 1, "6h": 6, "24h": 24, "48h": 48, "7d": 168, "Tout": 168}


