# ============================================================
# FINAL LOCK — V2.11 CLEAN UNIFIED PRODUCTION PASS
# ============================================================
# Fixes requested after V2.11 clean unified v3:
# - remove duplicated top time-window control;
# - keep only the WorldMonitor in-map timebar;
# - make in-map 1h/6h/24h/48h/7d/Tout buttons functional via URL query state;
# - make in-map 2D/3D buttons functional via URL query state;
# - keep external UI minimal: Style, Pays / zone, Live;
# - preserve complete static objects, min earthquake magnitude = 0.0, Fast natural live;
# - keep diagnostics hidden;
# - improve panel feed deduplication and value formatting.

MODULE_VERSION = "WorldMonitor V2.11 Unified Clean Final"
_WM_FINAL_TIME_PARAM = "wm_time"
_WM_FINAL_PROJ_PARAM = "wm_projection"
_WM_FINAL_VALID_PROJ = {"2D", "3D"}


def _wm_final_get_query_param(name: str, default: str) -> str:
    try:
        value = st.query_params.get(name, default)  # type: ignore[attr-defined]
        if isinstance(value, list):
            value = value[0] if value else default
        value = str(value or default)
    except Exception:
        value = default
    return value


def _wm_final_get_time_window() -> str:
    value = _wm_final_get_query_param(_WM_FINAL_TIME_PARAM, "24h")
    return value if value in _WM_TIME_OPTIONS else "24h"


def _wm_final_get_projection_mode() -> str:
    value = _wm_final_get_query_param(_WM_FINAL_PROJ_PARAM, "2D").upper()
    return value if value in _WM_FINAL_VALID_PROJ else "2D"


def _wm_final_hours_from_window(time_window: str) -> int:
    return int(_WM_TIME_TO_HOURS.get(str(time_window), 24))


def _wm_final_projection_name(projection_mode: str) -> str:
    return "3D globe" if str(projection_mode).upper() == "3D" else "Flat world"


def _wm_final_money(value: Any) -> str:
    try:
        x = float(value)
        if not math.isfinite(x):
            return _text(value, "")
        if abs(x) >= 1_000_000_000_000:
            return f"${x/1_000_000_000_000:.2f}T"
        if abs(x) >= 1_000_000_000:
            return f"${x/1_000_000_000:.1f}B"
        if abs(x) >= 1_000_000:
            return f"${x/1_000_000:.1f}M"
        if abs(x) >= 1_000:
            return f"${x/1_000:.1f}K"
        return f"${x:,.0f}"
    except Exception:
        return _text(value, "")


def _wm_news_list_html(items: list[dict[str, Any]], max_items: int = 4) -> str:
    """Final feed renderer: no duplicated source/tag labels and safer item clipping."""
    if not items:
        return '<div class="wmc-empty">Aucune donnée live disponible · fallback local actif.</div>'
    body: list[str] = []
    seen: set[str] = set()
    for item in items:
        title_raw = _text(item.get("title"), "")
        key = re.sub(r"\s+", " ", title_raw.lower()).strip()
        if not title_raw or key in seen:
            continue
        seen.add(key)
        url = _text(item.get("url"), "")
        tag = _text(item.get("tag"), "NEWS").upper().strip()
        source = _text(item.get("source"), "SOURCE").upper().strip()
        # Avoid labels like "GOOGLE NEWS AI AI".
        source = re.sub(rf"\s+{re.escape(tag)}$", "", source).strip() if tag else source
        if source == tag:
            source = "SOURCE"
        title = _wm_clean_escape(title_raw)
        age = _wm_clean_escape(item.get("age"))
        link = f'<a class="wmc-open" target="_blank" href="{_wm_clean_escape(url)}">↗</a>' if url else '<span class="wmc-open off">·</span>'
        body.append(f'<div class="wmc-item"><div class="wmc-source">{_wm_clean_escape(source)} <b>{_wm_clean_escape(tag)}</b></div><div class="wmc-title">{title}</div><div class="wmc-age">{age}</div>{link}</div>')
        if len(body) >= int(max_items):
            break
    return "".join(body) if body else '<div class="wmc-empty">Aucune donnée filtrée.</div>'


def _wm_bucket_live_news(items: list[dict[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    """Final strict topic routing: one article belongs to one panel bucket only."""
    out: dict[str, list[dict[str, Any]]] = {"AI": [], "TECH": [], "CYBER": [], "STARTUP": [], "MARKETS": [], "DEV": []}
    seen_titles: set[str] = set()
    for it in items or []:
        title = _text(it.get("title"), "")
        key = re.sub(r"\s+", " ", title.lower()).strip()
        if not key or key in seen_titles:
            continue
        seen_titles.add(key)
        explicit = _text(it.get("tag"), "").upper().strip()
        blob = (title + " " + _text(it.get("source"), "") + " " + explicit).lower()
        bucket = "TECH"
        if any(k in blob for k in ["cyber", "ransom", "malware", "cisa", "security", "breach", "vulnerability", "exploit", "botnet"]):
            bucket = "CYBER"
        elif any(k in blob for k in ["startup", "venture", "vc", "funding", "seed round", "series a", "techcrunch", "inc.com", "global venturing"]):
            bucket = "STARTUP"
        elif any(k in blob for k in ["github", "developer", "open-source", "open source", "repository", "nvidia developer", "dev.to"]):
            bucket = "DEV"
        elif any(k in blob for k in ["market", "stock", "fed", "crypto", "bitcoin", "ethereum", "etf", "cnbc", "yahoo finance", "nasdaq"]):
            bucket = "MARKETS"
        elif any(k in blob for k in ["artificial intelligence", " a.i.", " ai ", "anthropic", "openai", "deepmind", "model", "agent", "nvidia", "gpu", "semiconductor"]):
            bucket = "AI"
        elif explicit in out:
            bucket = explicit
        out[bucket].append({**it, "tag": bucket})

    # Backfill only with items not already used in a category. This avoids the old
    # AI/Tech/Startup duplication while still keeping panels populated.
    for bucket in out:
        if out[bucket]:
            continue
        used = {re.sub(r"\s+", " ", _text(x.get("title"), "").lower()).strip() for vals in out.values() for x in vals}
        fallback = []
        for it in items or []:
            k = re.sub(r"\s+", " ", _text(it.get("title"), "").lower()).strip()
            if k and k not in used:
                fallback.append({**it, "tag": bucket})
            if len(fallback) >= 3:
                break
        out[bucket] = fallback
    return out


try:
    _WM_PREV_CLEAN_PANEL_HTML_FINAL = _wm_clean_panel_html
except Exception:
    _WM_PREV_CLEAN_PANEL_HTML_FINAL = None


def _wm_clean_panel_html(panel_id: str, payload: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], country: str, max_items: int = 4) -> str:
    """Final panel corrections for AI insights and funding value formatting."""
    title = _WM_PANEL_TITLES.get(panel_id, panel_id)
    p = payload.get("panels", {}).get(panel_id, {}) if isinstance(payload, dict) else {}

    if panel_id == "ai_insights":
        ai_items = (live_news.get("AI", []) or [])[:2]
        tech_items = (live_news.get("TECH", []) or [])[:1]
        brief = _text(p.get("brief"), "Signaux IA/tech consolidés depuis sources live et catalogue local.")
        signals = []
        if ai_items:
            signals.append(f"AI live: {len(live_news.get('AI', []))} items")
        if tech_items:
            signals.append(f"Tech mesh: {len(live_news.get('TECH', []))} items")
        body = f'<div class="wmc-brief">🚀 {_wm_clean_escape(brief)}</div>'
        if signals:
            body += '<div class="wmc-signal-strip">' + ''.join(f'<span>{_wm_clean_escape(s)}</span>' for s in signals) + '</div>'
        # Do not repeat the same articles shown in IA/ML; show one compact lead only.
        if ai_items:
            body += _wm_news_list_html(ai_items[:1], max_items=1)
        return f'<section class="wmc-panel" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, len(ai_items))}<div class="wmc-body">{body}</div></section>'

    if panel_id == "funding_vc":
        rows = _wm_filter_country_rows(p.get("rows", []), country)
        formatted = []
        for r in rows:
            rr = dict(r)
            rr["funding"] = _wm_final_money(rr.get("funding", 0))
            formatted.append(rr)
        body = _wm_table_rows_html(formatted, ["name", "country", "funding", "unicorns"], max_rows=max_items)
        return f'<section class="wmc-panel" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, len(formatted))}<div class="wmc-body">{body}</div></section>'

    if callable(_WM_PREV_CLEAN_PANEL_HTML_FINAL):
        return _WM_PREV_CLEAN_PANEL_HTML_FINAL(panel_id, payload, live_news, quote_rows, country, max_items=max_items)
    return f'<section class="wmc-panel"><div class="wmc-body"><div class="wmc-empty">Panel unavailable.</div></div></section>'


def _map_component_html(
    fig: go.Figure,
    registry: pd.DataFrame,
    stage_height: int = 860,
    active_time: str = "24h",
    projection_mode: str = "2D",
) -> str:
    """Final map chrome: only in-map time controls, and 2D/3D/time write query state."""
    if callable(_WM_OLD_MAP_COMPONENT_HTML_V211):
        html_payload = _WM_OLD_MAP_COMPONENT_HTML_V211(fig, registry, stage_height)
    else:
        html_payload = ""
    if not html_payload:
        return ""

    projection_mode = "3D" if str(projection_mode).upper() == "3D" else "2D"
    active_time = active_time if active_time in _WM_TIME_OPTIONS else "24h"

    tools_html = (
        '<div class="wm-tools">'
        f'<button class="wm-chip {"on" if projection_mode == "2D" else ""}" data-wm-proj="2D" title="Carte 2D">2D</button>'
        f'<button class="wm-chip {"on" if projection_mode == "3D" else ""}" data-wm-proj="3D" title="Globe 3D">3D</button>'
        '<button class="wm-chip" data-wm-fullscreen title="Fullscreen map">□</button>'
        '<div class="wm-chip">⌖</div>'
        '</div>'
    )
    old_tools = '<div class="wm-tools"><div class="wm-chip on">2D</div><div class="wm-chip">3D</div><button class="wm-chip" data-wm-fullscreen title="Fullscreen map">□</button><div class="wm-chip">⌖</div></div>'
    old_tools_2 = '<div class="wm-tools"><button class="wm-chip on" data-wm-proj="2d">2D</button><button class="wm-chip" data-wm-proj="3d">3D</button><button class="wm-chip" data-wm-fullscreen title="Fullscreen map">□</button><div class="wm-chip">⌖</div></div>'
    if old_tools in html_payload:
        html_payload = html_payload.replace(old_tools, tools_html, 1)
    elif old_tools_2 in html_payload:
        html_payload = html_payload.replace(old_tools_2, tools_html, 1)
    else:
        html_payload = html_payload.replace('<div class="wm-plot">', tools_html + '<div class="wm-plot">', 1)

    time_buttons = ''.join(
        f'<button class="wm-time-btn {"on" if t == active_time else ""}" data-wm-time="{t}">{t}</button>'
        for t in _WM_TIME_OPTIONS
    )
    timebar = f'<div class="wm-timebar" title="Fenêtre active: {active_time}">{time_buttons}</div>'
    html_payload = html_payload.replace('<div class="wm-plot">', timebar + '<div class="wm-plot">', 1)

    final_css = """
      .wm-timebar{position:absolute;top:72px;left:18px;z-index:6;display:flex;gap:0;background:rgba(5,5,6,.94);border:1px solid rgba(148,163,184,.26);box-shadow:0 14px 36px rgba(0,0,0,.44)}
      .wm-time-btn{appearance:none;border:0;border-right:1px solid rgba(148,163,184,.26);background:#08080a;color:#9ca3af;font-family:inherit;font-size:12px;font-weight:950;letter-spacing:.02em;padding:12px 18px;min-width:54px;cursor:pointer}.wm-time-btn:last-child{border-right:0}.wm-time-btn.on{background:#33ff88;color:#031308}.wm-time-btn:hover:not(.on){background:#171719;color:#e5e7eb}.wm-tools .wm-chip{cursor:pointer}.wm-tools .wm-chip.on{background:#33ff88!important;color:#00140a!important;border-color:#33ff88!important}
      .wmc-signal-strip{display:flex;gap:6px;flex-wrap:wrap;margin:0 12px 8px}.wmc-signal-strip span{border:1px solid rgba(56,255,135,.28);background:rgba(56,255,135,.08);color:#40ff88;border-radius:999px;padding:4px 7px;font-size:11px;font-weight:900}
    """
    html_payload = html_payload.replace("</style>", final_css + "\n</style>", 1)

    final_js = f"""
<script>
(function(){{
  const stage=document.currentScript.closest('.wm-stage') || document.querySelector('.wm-stage');
  if(!stage) return;
  function gd(){{return stage.querySelector('.plotly-graph-div');}}
  function navParam(name,value){{
    try{{
      const loc=window.parent && window.parent.location ? window.parent.location : window.location;
      const url=new URL(loc.href);
      if(url.searchParams.get(name)===value) return;
      url.searchParams.set(name,value);
      loc.href=url.toString();
    }}catch(e){{
      try{{localStorage.setItem('wm211_'+name,value);}}catch(_){{}}
    }}
  }}
  function relayoutProjection(kind){{
    const g=gd();
    if(!g || !window.Plotly) return;
    try{{
      if(kind==='3D'){{
        window.Plotly.relayout(g, {{'geo.projection.type':'orthographic','geo.projection.scale':1.18,'geo.projection.rotation.lon':15,'geo.projection.rotation.lat':0}});
      }}else{{
        window.Plotly.relayout(g, {{'geo.projection.type':'equirectangular','geo.projection.scale':1.0,'geo.lonaxis.range':[-180,180],'geo.lataxis.range':[-62,84]}});
      }}
    }}catch(e){{}}
  }}
  stage.querySelectorAll('[data-wm-time]').forEach(btn=>btn.addEventListener('click',function(){{
    stage.querySelectorAll('[data-wm-time]').forEach(b=>b.classList.toggle('on', b===btn));
    navParam('{_WM_FINAL_TIME_PARAM}', btn.dataset.wmTime || '24h');
  }}));
  stage.querySelectorAll('[data-wm-proj]').forEach(btn=>btn.addEventListener('click',function(){{
    const kind=(btn.dataset.wmProj || '2D').toUpperCase();
    stage.querySelectorAll('[data-wm-proj]').forEach(b=>b.classList.toggle('on', b===btn));
    relayoutProjection(kind);
    navParam('{_WM_FINAL_PROJ_PARAM}', kind);
  }}));
}})();
</script>
"""
    # Place the final interaction script at the very end of the wm-stage.
    # Critical: the previous version inserted this script into the top header,
    # before the timebar/projection buttons existed in the DOM. The click
    # listeners therefore bound to zero elements. rpartition inserts the script
    # before the final closing stage </div>, after all map controls/drawer nodes.
    marker = "</div>"
    head, sep, tail = html_payload.rpartition(marker)
    if sep:
        return head + final_js + sep + tail
    return html_payload + final_js


def render_map_v211(
    objects: pd.DataFrame,
    registry: pd.DataFrame,
    region: str,
    projection: str,
    height: int = 860,
    projection_scale: float | None = None,
    active_time: str = "24h",
    projection_mode: str | None = None,
) -> None:
    fig = build_plotly_figure_v211(
        objects,
        registry,
        projection=projection,
        region=region,
        fig_height=max(520, int(height) - 54),
        projection_scale=projection_scale,
    )
    mode = projection_mode or ("3D" if projection == "3D globe" else "2D")
    html_payload = _map_component_html(
        fig,
        registry,
        stage_height=int(height),
        active_time=str(active_time or "24h"),
        projection_mode=str(mode),
    )
    if components is None:
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": True, "responsive": True})
    else:
        components.html(html_payload, height=int(height), scrolling=False)


def _render_worldmonitor_map_clean_v211(
    live_enabled: bool = False,
    time_window: str = "24h",
    style: str = "Global",
    projection_mode: str = "2D",
) -> None:
    static_objects, _static_status = load_worldmonitor_static_objects_v211("")
    live_objects = pd.DataFrame()
    if live_enabled:
        hours_back = _wm_final_hours_from_window(str(time_window))
        # "Tout" keeps static complete and caps live to the safe 7d provider window.
        live_objects, _live_status = load_live_event_objects_v211(
            hours_back=hours_back,
            min_magnitude=0.0,
            cache_nonce=hours_back,
            provider_profile="Fast natural",
        )
    frames = [df for df in [static_objects, live_objects] if isinstance(df, pd.DataFrame) and not df.empty]
    objects = pd.concat(frames, ignore_index=True) if frames else pd.DataFrame(columns=static_objects.columns if isinstance(static_objects, pd.DataFrame) else [])
    if not objects.empty:
        objects = objects.drop_duplicates(subset=["object_id", "kind", "points_json"], keep="first").reset_index(drop=True)
    preset = _WM_STYLE_TO_MAP_PRESET.get(str(style), "Balanced institutional")
    registry = build_layer_registry_v211(objects, preset=preset)
    projection = _wm_final_projection_name(str(projection_mode))
    projection_scale = 1.18 if projection == "3D globe" else 1.0
    render_map_v211(
        objects,
        registry,
        region="Global",
        projection=projection,
        height=660,
        projection_scale=projection_scale,
        active_time=str(time_window or "24h"),
        projection_mode=str(projection_mode),
    )


def _render_worldmonitor_panels_clean_v211(style: str = "Global", country: str = "Global", live_enabled: bool = True) -> None:
    err = _WM211_PANELS_NS.get("_EMBEDDED_IMPORT_ERROR") if isinstance(_WM211_PANELS_NS, dict) else None
    if err is not None:
        st.error(f"WorldMonitor panels source loader error: {err}")
        return
    load_fn = _WM211_PANELS_NS.get("load_worldmonitor_panel_catalog_v2120")
    build_fn = _WM211_PANELS_NS.get("build_panel_payload_v2120")
    if not callable(load_fn) or not callable(build_fn):
        st.error("WorldMonitor panels loader unavailable in integrated module.")
        return
    catalog = load_fn("")
    workspace = _WM_STYLE_TO_WORKSPACE.get(style, "Full WorldMonitor")
    payload = build_fn(catalog, workspace=workspace, max_items=3)
    visible_ids = _WM_STYLE_TO_PANELS.get(style, _WM_STYLE_TO_PANELS["Global"])
    live_items = _wm_fetch_rss_items_v211(style, country, max_items=64) if live_enabled else []
    live_news = _wm_bucket_live_news(live_items)
    quote_rows = _wm_fetch_quote_rows_v211() if live_enabled else []
    html_payload = _wm_clean_dashboard_html(payload, visible_ids, style, country, live_news, quote_rows)
    panel_units = sum(2 if pid in {"economic", "tech_events"} else 1 for pid in visible_ids)
    rows = max(2, math.ceil(panel_units / 4))
    component_height = int(min(1780, max(860, 54 + rows * 382 + 56)))
    if components is not None:
        components.html(html_payload, height=component_height, scrolling=True)
    else:
        st.info("streamlit.components.v1 unavailable; panels HTML cannot be rendered.")


