def _wm_country_cfg_v211(country: str) -> dict[str, Any]:
    return dict(_WM_COUNTRY_CONTEXT_V211.get(str(country or "Global"), _WM_COUNTRY_CONTEXT_V211["Global"]))


def _wm_normalize_news_key_v211(item: dict[str, Any]) -> str:
    raw = re.sub(r"\s+[-–—]\s+[^-–—]{2,80}$", "", _text(item.get("title"), "").lower()).strip()
    raw = re.sub(r"[^a-z0-9]+", " ", raw).strip()
    return raw[:180]


def _wm_article_score_for_bucket_v211(blob: str, bucket: str) -> int:
    rules = {
        "CYBER": ["cyber", "ransom", "malware", "cisa", "breach", "vulnerability", "exploit", "security", "hacker", "zero day", "apt"],
        "STARTUP": ["startup", "venture", "vc", "funding", "raised", "seed", "series a", "series b", "techcrunch", "a16z", "y combinator", "unicorn"],
        "MARKETS": ["market", "stock", "fed", "rates", "crypto", "bitcoin", "cnbc", "earnings", "inflation", "treasury", "nasdaq"],
        "DEV": ["github", "developer", "open source", "product hunt", "dev", "repository", "coding", "software supply chain"],
        "AI": ["ai", "artificial intelligence", "anthropic", "openai", "model", "llm", "agent", "nvidia", "semiconductor", "datacenter", "data center", "gpu"],
        "TECH": ["technology", "cloud", "chips", "semiconductor", "software", "hardware", "infrastructure", "telecom", "satellite"],
    }
    return sum(1 for k in rules.get(bucket, []) if k in blob)


def _wm_bucket_live_news(items: list[dict[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    """Strict one-bucket routing to stop repeated articles across panels."""
    buckets = {"AI": [], "TECH": [], "CYBER": [], "STARTUP": [], "MARKETS": [], "DEV": []}
    seen: set[str] = set()
    priority = ["CYBER", "STARTUP", "MARKETS", "DEV", "AI", "TECH"]
    for it in items or []:
        key = _wm_normalize_news_key_v211(it)
        if not key or key in seen:
            continue
        seen.add(key)
        blob = (_text(it.get("title"), "") + " " + _text(it.get("source"), "") + " " + _text(it.get("tag"), "")).lower()
        scored = [(bucket, _wm_article_score_for_bucket_v211(blob, bucket)) for bucket in priority]
        bucket, score = max(scored, key=lambda x: (x[1], -priority.index(x[0])))
        if score <= 0:
            bucket = "TECH"
        enriched = {**it, "tag": bucket if bucket != "MARKETS" else "MARKET"}
        buckets[bucket].append(enriched)
    # Conservative backfill: do not backfill with AI into all panels. Only TECH
    # gets general items; others may be compact, which is better than noise.
    if not buckets["TECH"]:
        buckets["TECH"] = list((items or [])[:3])
    return buckets


@st.cache_data(ttl=120, show_spinner=False)
def _wm_fetch_quote_rows_v211() -> list[dict[str, Any]]:
    """Live Yahoo quotes with sane deterministic fallback values."""
    symbols = "AAPL,MSFT,NVDA,AMZN,AVGO,TSLA,BTC-USD,ETH-USD,SOL-USD,BNB-USD,^VIX,^GSPC,^IXIC"
    url = "https://query1.finance.yahoo.com/v7/finance/quote?symbols=" + _wm_urlparse.quote(symbols)
    try:
        req = _wm_urlrequest.Request(url, headers={"User-Agent": "Mozilla/5.0 QuantTerminal WorldMonitor/2.11"})
        with _wm_urlrequest.urlopen(req, timeout=4) as resp:
            payload = json.loads(resp.read(900_000).decode("utf-8", "ignore"))
        rows = []
        for r in payload.get("quoteResponse", {}).get("result", []):
            sym = _text(r.get("symbol"), "")
            price = r.get("regularMarketPrice")
            chg = r.get("regularMarketChangePercent")
            if not sym or price is None:
                continue
            display = sym.replace("-USD", "").replace("^GSPC", "S&P 500").replace("^IXIC", "Nasdaq").replace("^VIX", "VIX")
            rows.append({"symbol": sym.replace("-USD", ""), "display": display, "price": float(price), "change": float(chg or 0)})
        if rows:
            return rows
    except Exception:
        pass
    fallback = [
        ("AAPL", "Apple", 212.40), ("MSFT", "Microsoft", 497.20), ("NVDA", "NVIDIA", 158.30),
        ("AMZN", "Amazon", 221.10), ("AVGO", "Broadcom", 276.50), ("TSLA", "Tesla", 318.20),
        ("BTC", "Bitcoin", 58500.0), ("ETH", "Ethereum", 3850.0), ("SOL", "Solana", 145.0), ("BNB", "BNB", 620.0),
        ("^VIX", "VIX", 18.7), ("^GSPC", "S&P 500", 6250.0), ("^IXIC", "Nasdaq", 20250.0),
    ]
    return [
        {"symbol": sym, "display": name, "price": price * (1 + _stable_rng(sym + "pxv2", -0.018, 0.018)), "change": _stable_rng(sym + "chgv2", -2.4, 2.6)}
        for sym, name, price in fallback
    ]


def _wm_country_keyword_score_v211(item: dict[str, Any], country: str) -> int:
    if not country or country == "Global":
        return 0
    cfg = _wm_country_cfg_v211(country)
    blob = json.dumps(item, ensure_ascii=False, default=str).lower()
    return sum(1 for k in cfg.get("keywords", []) if str(k).lower() in blob)


def _wm_prioritize_country_items_v211(items: list[dict[str, Any]], country: str, limit: int | None = None) -> list[dict[str, Any]]:
    if not items:
        return []
    if not country or country == "Global":
        return items[:limit] if limit else items
    ranked = sorted(enumerate(items), key=lambda pair: (_wm_country_keyword_score_v211(pair[1], country), -pair[0]), reverse=True)
    out = [it for _, it in ranked]
    return out[:limit] if limit else out


def _wm_signal_context_v211(style: str, country: str, live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], live_enabled: bool) -> dict[str, Any]:
    news_count = sum(len(v) for v in (live_news or {}).values())
    cyber_count = len((live_news or {}).get("CYBER", []))
    ai_count = len((live_news or {}).get("AI", [])) + len((live_news or {}).get("TECH", []))
    startup_count = len((live_news or {}).get("STARTUP", []))
    market_changes = [float(r.get("change", 0)) for r in (quote_rows or []) if str(r.get("symbol", "")).upper() not in {"BTC", "ETH", "SOL", "BNB"}]
    avg_change = sum(market_changes) / len(market_changes) if market_changes else 0.0
    vix_rows = [r for r in (quote_rows or []) if str(r.get("symbol", "")).upper() in {"^VIX", "VIX"}]
    vix_level = float(vix_rows[0].get("price", 18.0)) if vix_rows else 18.0
    market_stress = int(max(0, min(100, 38 + max(0, -avg_change) * 12 + max(0, vix_level - 18) * 1.9)))
    cyber_stress = int(max(0, min(100, 22 + cyber_count * 9 + (8 if style in {"Risk", "Ops"} else 0))))
    tech_momentum = int(max(0, min(100, 35 + ai_count * 5 + startup_count * 3 + (8 if style == "Tech" else 0))))
    geo_heat = int(max(0, min(100, 28 + news_count * 1.5 + (10 if country != "Global" else 0))))
    global_risk = int(round(0.30 * market_stress + 0.30 * cyber_stress + 0.25 * geo_heat + 0.15 * (100 - tech_momentum)))
    if global_risk >= 68:
        regime = "Elevated"
    elif global_risk >= 45:
        regime = "Watch"
    else:
        regime = "Stable"
    lead = "Live signal mesh active" if live_enabled else "Static/local signal mesh"
    if country != "Global":
        lead += f" · country focus: {country}"
    return {
        "regime": regime,
        "global_risk": global_risk,
        "cyber_stress": cyber_stress,
        "market_stress": market_stress,
        "tech_momentum": tech_momentum,
        "geo_heat": geo_heat,
        "lead": lead,
        "avg_market_change": avg_change,
        "news_count": news_count,
    }


def _wm_context_strip_html_v211(ctx: dict[str, Any]) -> str:
    def chip(label: str, value: Any, cls: str = "") -> str:
        return f'<div class="wmc-sig {cls}"><small>{_wm_clean_escape(label)}</small><b>{_wm_clean_escape(value)}</b></div>'
    risk_cls = "hot" if int(ctx.get("global_risk", 0)) >= 68 else ("watch" if int(ctx.get("global_risk", 0)) >= 45 else "ok")
    return (
        '<div class="wmc-signalbar">'
        f'<div class="wmc-signal-lead"><b>{_wm_clean_escape(ctx.get("regime", "Stable"))}</b><span>{_wm_clean_escape(ctx.get("lead", ""))}</span></div>'
        + chip("Global Risk", f'{int(ctx.get("global_risk", 0))}/100', risk_cls)
        + chip("Cyber", f'{int(ctx.get("cyber_stress", 0))}/100')
        + chip("Market", f'{int(ctx.get("market_stress", 0))}/100')
        + chip("Tech Momentum", f'{int(ctx.get("tech_momentum", 0))}/100', "ok")
        + chip("Geo Heat", f'{int(ctx.get("geo_heat", 0))}/100')
        + '</div>'
    )


def _wm_clean_panel_html(panel_id: str, payload: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], country: str, max_items: int = 4) -> str:
    """Override: strict news distribution + better market/crypto + country-aware tables."""
    title = _WM_PANEL_TITLES.get(panel_id, panel_id)
    p = payload.get("panels", {}).get(panel_id, {}) if isinstance(payload, dict) else {}

    if panel_id in {"ai_ml", "technology", "startups_vc", "cybersecurity", "github_trends"}:
        key = {"ai_ml": "AI", "technology": "TECH", "startups_vc": "STARTUP", "cybersecurity": "CYBER", "github_trends": "DEV"}.get(panel_id, "TECH")
        items = _wm_prioritize_country_items_v211(live_news.get(key, []) or p.get("items", []), country, limit=max_items)
        return f'<section class="wmc-panel" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, len(items))}<div class="wmc-body">{_wm_news_list_html(items, max_items=max_items)}</div></section>'

    if panel_id == "ai_insights":
        ai_items = _wm_prioritize_country_items_v211((live_news.get("AI", []) + live_news.get("TECH", [])), country, limit=2)
        brief = _text(p.get("brief"), "AI/tech signal mesh ready.")
        if country != "Global":
            brief = f"{country} focus · " + brief
        signals = [
            f"AI {len(live_news.get('AI', []))}", f"Tech {len(live_news.get('TECH', []))}", f"Cyber {len(live_news.get('CYBER', []))}", f"Startup {len(live_news.get('STARTUP', []))}"
        ]
        body = f'<div class="wmc-brief">🚀 {_wm_clean_escape(brief)}</div><div class="wmc-signal-strip">' + ''.join(f'<span>{_wm_clean_escape(s)}</span>' for s in signals) + '</div>'
        if ai_items:
            body += _wm_news_list_html(ai_items[:1], max_items=1)
        return f'<section class="wmc-panel" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, len(ai_items))}<div class="wmc-body">{body}</div></section>'

    if panel_id == "markets":
        rows = [r for r in quote_rows if str(r.get("symbol", "")).upper() not in {"BTC", "ETH", "SOL", "BNB", "BTC-USD", "ETH-USD", "SOL-USD", "BNB-USD"}]
        rows = rows[:6] or p.get("rows", [])[:6]
        body = "".join(f'<div class="wmc-market"><span>{_wm_clean_escape(r.get("display", r.get("symbol")))}</span><b>${float(r.get("price",0)):,.2f}</b><em class="{"up" if float(r.get("change",0))>=0 else "down"}">{float(r.get("change",0)):+.2f}%</em></div>' for r in rows)
        return f'<section class="wmc-panel" data-panel="markets">{_wm_panel_header(title, len(rows))}<div class="wmc-body">{body}</div></section>'

    if panel_id == "crypto":
        rows = [r for r in quote_rows if str(r.get("symbol", "")).upper().replace("-USD", "") in {"BTC", "ETH", "SOL", "BNB"}]
        rows = rows[:5]
        body = "".join(f'<div class="wmc-market"><span>{_wm_clean_escape(r.get("display", r.get("symbol")))}</span><b>${float(r.get("price",0)):,.2f}</b><em class="{"up" if float(r.get("change",0))>=0 else "down"}">{float(r.get("change",0)):+.2f}%</em></div>' for r in rows)
        if not body:
            body = '<div class="wmc-empty">Crypto quote adapter unavailable.</div>'
        return f'<section class="wmc-panel" data-panel="crypto">{_wm_panel_header(title, len(rows))}<div class="wmc-body">{body}</div></section>'

    if panel_id in {"policy_ai", "funding_vc", "tech_maturity"}:
        # Reuse previous specialized formatting where possible after country prioritization.
        if panel_id == "policy_ai":
            rows = _wm_prioritize_country_items_v211(_wm_filter_country_rows(p.get("rows", []), country), country, limit=max_items)
            body = _wm_table_rows_html(rows, ["country", "impact", "title", "date"], max_rows=max_items)
            return f'<section class="wmc-panel" data-panel="policy_ai">{_wm_panel_header(title, len(rows))}<div class="wmc-body">{body}</div></section>'
        if panel_id == "funding_vc":
            rows = _wm_prioritize_country_items_v211(_wm_filter_country_rows(p.get("rows", []), country), country, limit=max_items)
            formatted = []
            for r in rows:
                rr = dict(r)
                rr["funding"] = _wm_final_money(rr.get("funding", 0))
                formatted.append(rr)
            body = _wm_table_rows_html(formatted, ["name", "country", "funding", "unicorns"], max_rows=max_items)
            return f'<section class="wmc-panel" data-panel="funding_vc">{_wm_panel_header(title, len(formatted))}<div class="wmc-body">{body}</div></section>'
        rows = _wm_prioritize_country_items_v211(_wm_filter_country_rows(p.get("rows", []), country), country, limit=max_items)
        body = ''.join(f'<div class="wmc-rank"><span>#{i+1} 🌐 {_wm_clean_escape(r.get("country"))}</span><b>{float(r.get("score",0)):.1f}</b></div>' for i, r in enumerate(rows))
        return f'<section class="wmc-panel" data-panel="tech_maturity">{_wm_panel_header(title, len(rows))}<div class="wmc-body">{body}</div></section>'

    # Fall through to previously validated renderer for structural panels.
    if callable(globals().get("_WM_PREV_CLEAN_PANEL_HTML_FINAL")):
        return globals()["_WM_PREV_CLEAN_PANEL_HTML_FINAL"](panel_id, payload, live_news, quote_rows, country, max_items=max_items)
    return f'<section class="wmc-panel"><div class="wmc-body"><div class="wmc-empty">Panel unavailable.</div></div></section>'


