# --- V2.11.11 post-smoke fixes: no duplicate backfill + local deterministic quote RNG ---
def _wm_stable_rng_v211(label: str, lo: float, hi: float) -> float:
    raw = int(hashlib.sha1(str(label).encode("utf-8", "ignore")).hexdigest()[:8], 16)
    return lo + (raw % 10000) / 10000 * (hi - lo)


def _wm_bucket_live_news(items: list[dict[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    buckets = {"AI": [], "TECH": [], "CYBER": [], "STARTUP": [], "MARKETS": [], "DEV": []}
    seen: set[str] = set()
    priority = ["CYBER", "STARTUP", "MARKETS", "DEV", "AI", "TECH"]
    for it in items or []:
        key = _wm_normalize_news_key_v211(it)
        if not key or key in seen:
            continue
        seen.add(key)
        blob = (_text(it.get("title"), "") + " " + _text(it.get("source"), "") + " " + _text(it.get("tag"), "")).lower()
        scored = [(bucket, _wm_article_score_for_bucket_v211(blob, bucket)) for bucket in priority]
        bucket, score = max(scored, key=lambda x: (x[1], -priority.index(x[0])))
        if score <= 0:
            bucket = "TECH"
        buckets[bucket].append({**it, "tag": bucket if bucket != "MARKETS" else "MARKET"})
    return buckets


@st.cache_data(ttl=120, show_spinner=False)
def _wm_fetch_quote_rows_v211() -> list[dict[str, Any]]:
    symbols = "AAPL,MSFT,NVDA,AMZN,AVGO,TSLA,BTC-USD,ETH-USD,SOL-USD,BNB-USD,^VIX,^GSPC,^IXIC"
    url = "https://query1.finance.yahoo.com/v7/finance/quote?symbols=" + _wm_urlparse.quote(symbols)
    try:
        req = _wm_urlrequest.Request(url, headers={"User-Agent": "Mozilla/5.0 QuantTerminal WorldMonitor/2.11"})
        with _wm_urlrequest.urlopen(req, timeout=4) as resp:
            payload = json.loads(resp.read(900_000).decode("utf-8", "ignore"))
        rows: list[dict[str, Any]] = []
        for r in payload.get("quoteResponse", {}).get("result", []):
            sym = _text(r.get("symbol"), "")
            price = r.get("regularMarketPrice")
            chg = r.get("regularMarketChangePercent")
            if not sym or price is None:
                continue
            display = sym.replace("-USD", "").replace("^GSPC", "S&P 500").replace("^IXIC", "Nasdaq").replace("^VIX", "VIX")
            rows.append({"symbol": sym.replace("-USD", ""), "display": display, "price": float(price), "change": float(chg or 0)})
        if rows:
            return rows
    except Exception:
        pass
    fallback = [
        ("AAPL", "Apple", 212.40), ("MSFT", "Microsoft", 497.20), ("NVDA", "NVIDIA", 158.30),
        ("AMZN", "Amazon", 221.10), ("AVGO", "Broadcom", 276.50), ("TSLA", "Tesla", 318.20),
        ("BTC", "Bitcoin", 58500.0), ("ETH", "Ethereum", 3850.0), ("SOL", "Solana", 145.0), ("BNB", "BNB", 620.0),
        ("^VIX", "VIX", 18.7), ("^GSPC", "S&P 500", 6250.0), ("^IXIC", "Nasdaq", 20250.0),
    ]
    return [
        {"symbol": sym, "display": name, "price": price * (1 + _wm_stable_rng_v211(sym + "pxv2", -0.018, 0.018)), "change": _wm_stable_rng_v211(sym + "chgv2", -2.4, 2.6)}
        for sym, name, price in fallback
    ]


