def _wm_intel_cfg_v211(country: str) -> dict[str, Any]:
    if country in _WM_COUNTRY_INTEL_V211:
        return _WM_COUNTRY_INTEL_V211[country]
    base = _wm_country_cfg_v211(country) if callable(globals().get("_wm_country_cfg_v211")) else {}
    return {
        "region": base.get("region", "Global"),
        "sectors": ["technology", "markets", "infrastructure"],
        "assets": ["equity index", "FX", "rates"],
        "risks": ["policy risk", "cyber risk", "market stress"],
        "watch": list(base.get("keywords", []))[:5] or ["country-specific news", "market reaction", "policy signals"],
    }


def _wm_items_flat_v211(live_news: dict[str, list[dict[str, Any]]]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for bucket in ["CYBER", "AI", "TECH", "STARTUP", "MARKETS", "DEV"]:
        out.extend([{**x, "_bucket": bucket} for x in (live_news or {}).get(bucket, [])])
    return out


def _wm_quality_metrics_v211(country: str, live_news: dict[str, list[dict[str, Any]]]) -> dict[str, Any]:
    items = _wm_items_flat_v211(live_news)
    total = len(items)
    if total <= 0:
        return {"total": 0, "country_hits": 0, "country_score": 0, "source_diversity": 0, "quality": 38, "status": "LOCAL FALLBACK", "top_sources": []}
    sources = [_text(x.get("source"), "source") for x in items]
    unique_sources = len(set(sources))
    country_hits = sum(1 for x in items if _wm_country_keyword_score_v211(x, country) > 0)
    country_score = 0 if country == "Global" else int(min(100, round(100 * country_hits / max(1, total))))
    diversity_score = int(min(100, unique_sources * 12))
    quality = int(min(100, max(35, 25 + min(35, total * 2) + min(25, diversity_score * .25) + (15 if country == "Global" else country_score * .15))))
    top_sources = []
    for s in sorted(set(sources), key=lambda z: (-sources.count(z), z))[:4]:
        top_sources.append({"source": s, "items": sources.count(s)})
    status = "HIGH" if quality >= 74 else ("WATCH" if quality >= 52 else "THIN")
    return {"total": total, "country_hits": country_hits, "country_score": country_score, "source_diversity": unique_sources, "quality": quality, "status": status, "top_sources": top_sources}


def _wm_signal_drivers_v211(ctx: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], country: str, style: str) -> list[dict[str, Any]]:
    items = _wm_items_flat_v211(live_news)
    vix = next((r for r in quote_rows if str(r.get("symbol", "")).upper() in {"^VIX", "VIX"}), None)
    equity_moves = [float(r.get("change", 0.0)) for r in quote_rows if str(r.get("symbol", "")).upper() not in {"BTC", "ETH", "SOL", "BNB", "^VIX", "VIX"}]
    avg_move = sum(equity_moves) / len(equity_moves) if equity_moves else 0.0
    cyber_items = live_news.get("CYBER", [])
    ai_items = live_news.get("AI", []) + live_news.get("TECH", [])
    country_hits = [x for x in items if _wm_country_keyword_score_v211(x, country) > 0]
    drivers = [
        {
            "score": "Global Risk",
            "value": f"{int(ctx.get('global_risk', 0))}/100",
            "driver": f"Weighted blend of market stress {int(ctx.get('market_stress', 0))}, cyber {int(ctx.get('cyber_stress', 0))}, geo heat {int(ctx.get('geo_heat', 0))}, and tech momentum {int(ctx.get('tech_momentum', 0))}.",
            "evidence": f"{len(items)} live items · {len(country_hits)} country hits · style={style}.",
        },
        {
            "score": "Cyber",
            "value": f"{int(ctx.get('cyber_stress', 0))}/100",
            "driver": f"{len(cyber_items)} cyber-routed articles plus risk/ops style boost when active.",
            "evidence": _text(cyber_items[0].get("title"), "No high-confidence cyber headline") if cyber_items else "No high-confidence cyber headline.",
        },
        {
            "score": "Market",
            "value": f"{int(ctx.get('market_stress', 0))}/100",
            "driver": f"Average equity move {avg_move:+.2f}% and VIX level {float(vix.get('price', 18.0)) if vix else 18.0:.1f}.",
            "evidence": "Live Yahoo quotes when reachable; deterministic fallback otherwise.",
        },
        {
            "score": "Tech Momentum",
            "value": f"{int(ctx.get('tech_momentum', 0))}/100",
            "driver": f"{len(ai_items)} AI/tech items and startup/AI source density.",
            "evidence": _text(ai_items[0].get("title"), "No AI/tech headline") if ai_items else "No AI/tech headline.",
        },
        {
            "score": "Geo Heat",
            "value": f"{int(ctx.get('geo_heat', 0))}/100",
            "driver": f"{int(ctx.get('news_count', 0))} routed news items; country focus adds context weight.",
            "evidence": f"Country focus: {country}" if country != "Global" else "Global cross-region monitoring.",
        },
    ]
    return drivers


def _wm_alert_engine_v211(ctx: dict[str, Any], country: str, style: str, live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    cfg = _wm_intel_cfg_v211(country)
    alerts: list[dict[str, Any]] = []
    assets = ", ".join(cfg.get("assets", [])[:5])
    cyber_items = live_news.get("CYBER", [])
    ai_items = live_news.get("AI", []) + live_news.get("TECH", [])
    market_stress = int(ctx.get("market_stress", 0))
    cyber = int(ctx.get("cyber_stress", 0))
    tech = int(ctx.get("tech_momentum", 0))
    geo = int(ctx.get("geo_heat", 0))

    if cyber >= 65 or (style in {"Risk", "Ops"} and cyber_items):
        alerts.append({
            "level": "HIGH" if cyber >= 80 else "WATCH",
            "title": f"{country if country != 'Global' else 'Global'} cyber stress elevated",
            "confidence": min(94, 58 + cyber // 2),
            "impact": "Critical infrastructure, cloud, financial systems",
            "assets": assets,
            "driver": _text(cyber_items[0].get("title"), f"{len(cyber_items)} cyber items routed") if cyber_items else "Risk style cyber weighting",
        })
    if market_stress >= 62:
        down = sorted([r for r in quote_rows if float(r.get("change", 0.0)) < 0], key=lambda r: float(r.get("change", 0.0)))[:3]
        alerts.append({
            "level": "WATCH",
            "title": "Market stress above threshold",
            "confidence": min(90, 52 + market_stress // 2),
            "impact": "Risk appetite, rates sensitivity, beta exposure",
            "assets": ", ".join(_text(x.get("symbol"), "") for x in down) or assets,
            "driver": f"Market stress score {market_stress}/100 with negative movers: " + ", ".join(_text(x.get("symbol"), "") for x in down),
        })
    if tech >= 72:
        alerts.append({
            "level": "MOMENTUM",
            "title": f"{country if country != 'Global' else 'Global'} AI / infrastructure momentum cluster",
            "confidence": min(92, 55 + tech // 2),
            "impact": "AI capex, semiconductors, data centers, power demand",
            "assets": assets,
            "driver": _text(ai_items[0].get("title"), f"{len(ai_items)} AI/tech items routed") if ai_items else "Tech score from source density",
        })
    if geo >= 72:
        alerts.append({
            "level": "WATCH",
            "title": f"{country if country != 'Global' else 'Global'} geopolitical heat elevated",
            "confidence": min(88, 50 + geo // 2),
            "impact": "Policy, logistics, commodities, regional risk premia",
            "assets": assets,
            "driver": f"Geo heat score {geo}/100; country focus and news density.",
        })

    if not alerts:
        alerts.append({
            "level": "STABLE",
            "title": f"{country if country != 'Global' else 'Global'} monitoring stable",
            "confidence": 62,
            "impact": "No immediate high-conviction cross-panel signal",
            "assets": assets,
            "driver": "Scores remain below alert thresholds.",
        })
    return alerts[:4]


def _wm_country_intel_v211(style: str, country: str, ctx: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]]) -> dict[str, Any]:
    cfg = _wm_intel_cfg_v211(country)
    quality = _wm_quality_metrics_v211(country, live_news)
    return {
        "country": country,
        "region": cfg.get("region", "Global"),
        "regime": ctx.get("regime", "Stable"),
        "style": style,
        "sectors": cfg.get("sectors", [])[:6],
        "assets": cfg.get("assets", [])[:6],
        "risks": cfg.get("risks", [])[:5],
        "watch": cfg.get("watch", [])[:5],
        "quality": quality,
    }


_WM_PREV_CLEAN_PANEL_HTML_V211 = _wm_clean_panel_html


def _wm_valueplus_badge_v211(text: Any, cls: str = "") -> str:
    color = "#38ff87" if cls == "ok" else ("#f59e0b" if cls == "warn" else ("#ff4d57" if cls == "hot" else "#7dd3fc"))
    return f'<span style="display:inline-block;border:1px solid {color};color:{color};border-radius:999px;padding:2px 7px;margin:2px 4px 2px 0;font-size:11px;font-weight:900;">{_wm_clean_escape(text)}</span>'


def _wm_clean_panel_html(panel_id: str, payload: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], country: str, max_items: int = 4) -> str:
    vp = payload.get("value_plus", {}) if isinstance(payload, dict) else {}
    title = _WM_PANEL_TITLES.get(panel_id, panel_id)

    if panel_id == "country_intel":
        intel = vp.get("country_intel", {})
        sectors = ''.join(_wm_valueplus_badge_v211(x, "ok") for x in intel.get("sectors", []))
        assets = ''.join(_wm_valueplus_badge_v211(x) for x in intel.get("assets", []))
        risks = ''.join(_wm_valueplus_badge_v211(x, "warn") for x in intel.get("risks", []))
        watch = ''.join(f'<li>{_wm_clean_escape(x)}</li>' for x in intel.get("watch", []))
        q = intel.get("quality", {})
        body = (
            f'<div class="wmc-brief"><b>{_wm_clean_escape(intel.get("country", country))}</b> · '
            f'{_wm_clean_escape(intel.get("region", "Global"))} · regime <b>{_wm_clean_escape(intel.get("regime", "Stable"))}</b><br>'
            f'<small>Style actif: {_wm_clean_escape(intel.get("style", ""))} · source quality {int(q.get("quality", 0))}/100 · {int(q.get("total", 0))} items</small></div>'
            f'<div style="padding:0 13px 10px 13px;"><small>KEY SECTORS</small><br>{sectors}<br><small>MARKET LINKS</small><br>{assets}<br><small>MAIN RISKS</small><br>{risks}</div>'
            f'<ul style="margin:4px 22px 12px 28px;color:#cbd5e1;line-height:1.4;">{watch}</ul>'
        )
        return f'<section class="wmc-panel wide" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, "CTX")}<div class="wmc-body">{body}</div></section>'

    if panel_id == "signal_drivers":
        rows = vp.get("drivers", [])
        body = ''.join(
            f'<div class="wmc-item"><div class="wmc-source">{_wm_clean_escape(r.get("score"))} <b>{_wm_clean_escape(r.get("value"))}</b></div>'
            f'<div class="wmc-title" style="font-size:14px;">{_wm_clean_escape(r.get("driver"))}</div>'
            f'<div class="wmc-age" style="text-align:left;">{_wm_clean_escape(r.get("evidence"))}</div></div>'
            for r in rows[:5]
        ) or '<div class="wmc-empty">No driver data.</div>'
        return f'<section class="wmc-panel wide" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, len(rows))}<div class="wmc-body">{body}</div></section>'

    if panel_id == "alert_engine":
        rows = vp.get("alerts", [])
        def lvl_cls(level: str) -> str:
            return "hot" if level in {"HIGH", "CRITICAL"} else ("warn" if level in {"WATCH", "MOMENTUM"} else "ok")
        body = ''.join(
            f'<div class="wmc-item"><div class="wmc-source">{_wm_valueplus_badge_v211(r.get("level"), lvl_cls(_text(r.get("level"))))} CONF {int(r.get("confidence", 0))}%</div>'
            f'<div class="wmc-title">{_wm_clean_escape(r.get("title"))}</div>'
            f'<div style="color:#cbd5e1;font-size:12px;margin-top:7px;">Impact: {_wm_clean_escape(r.get("impact"))}<br>Affected: {_wm_clean_escape(r.get("assets"))}</div>'
            f'<div class="wmc-age" style="text-align:left;">Driver: {_wm_clean_escape(r.get("driver"))}</div></div>'
            for r in rows[:4]
        ) or '<div class="wmc-empty">No alerts.</div>'
        return f'<section class="wmc-panel wide" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, len(rows))}<div class="wmc-body">{body}</div></section>'

    if panel_id == "source_quality":
        q = vp.get("quality", {})
        src_rows = q.get("top_sources", [])
        body = (
            f'<div class="wmc-macro">'
            f'<div><small>QUALITY</small><b>{int(q.get("quality", 0))}/100</b><em>{_wm_clean_escape(q.get("status", ""))}</em></div>'
            f'<div><small>LIVE ITEMS</small><b>{int(q.get("total", 0))}</b><em>routed</em></div>'
            f'<div><small>COUNTRY HITS</small><b>{int(q.get("country_hits", 0))}</b><em>{int(q.get("country_score", 0))}%</em></div>'
            f'<div><small>SOURCES</small><b>{int(q.get("source_diversity", 0))}</b><em>diversity</em></div>'
            f'</div>'
            + ''.join(f'<div class="wmc-market"><span>{_wm_clean_escape(r.get("source"))}</span><b>{int(r.get("items",0))}</b><em class="up">items</em></div>' for r in src_rows[:4])
        )
        return f'<section class="wmc-panel" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, q.get("status", ""))}<div class="wmc-body">{body}</div></section>'

    return _WM_PREV_CLEAN_PANEL_HTML_V211(panel_id, payload, live_news, quote_rows, country, max_items=max_items)


def _render_worldmonitor_panels_clean_v211(style: str = "Global", country: str = "Global", live_enabled: bool = True) -> None:
    err = _WM211_PANELS_NS.get("_EMBEDDED_IMPORT_ERROR") if isinstance(_WM211_PANELS_NS, dict) else None
    if err is not None:
        st.error(f"WorldMonitor panels source loader error: {err}")
        return
    load_fn = _WM211_PANELS_NS.get("load_worldmonitor_panel_catalog_v2120")
    build_fn = _WM211_PANELS_NS.get("build_panel_payload_v2120")
    if not callable(load_fn) or not callable(build_fn):
        st.error("WorldMonitor panels loader unavailable in integrated module.")
        return

    catalog = load_fn("")
    workspace = _WM_STYLE_TO_WORKSPACE.get(style, "Full WorldMonitor")
    payload = build_fn(catalog, workspace=workspace, max_items=3)
    visible_ids = _WM_STYLE_TO_PANELS.get(style, _WM_STYLE_TO_PANELS["Global"])

    live_items = _wm_fetch_rss_items_v211(style, country, max_items=96) if live_enabled else []
    live_items = _wm_prioritize_country_items_v211(live_items, country, limit=None)
    live_news = _wm_bucket_live_news(live_items)
    quote_rows = _wm_fetch_quote_rows_v211()
    ctx = _wm_signal_context_v211(style, country, live_news, quote_rows, live_enabled)

    quality = _wm_quality_metrics_v211(country, live_news)
    drivers = _wm_signal_drivers_v211(ctx, live_news, quote_rows, country, style)
    alerts = _wm_alert_engine_v211(ctx, country, style, live_news, quote_rows)
    intel = _wm_country_intel_v211(style, country, ctx, live_news, quote_rows)
    payload["value_plus"] = {
        "ctx": ctx,
        "quality": quality,
        "drivers": drivers,
        "alerts": alerts,
        "country_intel": intel,
    }

    html_payload = _wm_clean_dashboard_html(payload, visible_ids, style, country, live_news, quote_rows, signal_context=ctx)
    panel_units = sum(2 if pid in {"economic", "tech_events", "country_intel", "signal_drivers", "alert_engine"} else 1 for pid in visible_ids)
    rows = max(2, math.ceil(panel_units / 4))
    component_height = int(min(2200, max(1040, 52 + 70 + rows * 382 + 52)))
    if components is not None:
        components.html(html_payload, height=component_height, scrolling=True)
    else:
        st.info("streamlit.components.v1 unavailable; panels HTML cannot be rendered.")


def render_worldmonitor_bridge_v211() -> None:
    """V2.11 Value+ Intelligence entrypoint: map + explainable country-aware signal engine."""
    _wm_inject_clean_css_v211()
    time_window = _wm_final_get_time_window()
    projection_mode = _wm_final_get_projection_mode()
    st.markdown("""
<div class="wmclean-top"><div class="wmclean-title">WORLD MONITOR V2.11 · VALUE+ INTELLIGENCE WORKSPACE</div><div class="wmclean-sub">Carte V2.11 validée + panels intégrés + Country Intelligence + score explanations + alert engine. Interface volontairement minimale.</div></div>
""", unsafe_allow_html=True)

    st.markdown('<div class="wmclean-control">', unsafe_allow_html=True)
    c1, c2, c3, c4 = st.columns([1.05, 1.05, .55, 4.4])
    with c1:
        style = st.selectbox("Style", ["Global", "Tech", "Finance", "Risk", "Ops"], index=0, key="wm_clean_style")
