def _wm_v2_blob(item: dict[str, Any]) -> str:
    return (_text(item.get("title"), "") + " " + _text(item.get("source"), "") + " " + _text(item.get("tag"), "")).lower()


def _wm_is_cyber_relevant_v211(item: dict[str, Any]) -> bool:
    blob = _wm_v2_blob(item)
    hard = any(k in blob for k in _WM_CYBER_HARD_TERMS_V211)
    if not hard:
        return False
    # Allow if a strong cyber term is explicit; otherwise suppress generic crisis/travel/noise.
    if any(k in blob for k in _WM_CYBER_FALSE_POSITIVE_V211) and not any(k in blob for k in ["cyberattack", "breach", "vulnerability", "ransomware", "malware", "cisa", "phishing", "idor"]):
        return False
    return True


def _wm_article_score_for_bucket_v211(blob: str, bucket: str) -> int:
    """V2 strict thematic scorer. Security is not enough to qualify as cyber."""
    rules = {
        "CYBER": ["cyberattack", "cyber attack", "cybersecurity", "ransomware", "malware", "breach", "data breach", "vulnerability", "exploit", "zero day", "zero-day", "cisa", "hacker", "phishing", "idor", "apt", "ddos"],
        "STARTUP": ["startup", "venture", "vc", "funding", "raised", "seed", "series a", "series b", "techcrunch", "a16z", "y combinator", "unicorn"],
        "MARKETS": ["market", "stock", "fed", "rates", "crypto", "bitcoin", "cnbc", "earnings", "inflation", "treasury", "nasdaq", "ecb", "bond", "yield"],
        "DEV": ["github", "developer", "open source", "product hunt", "repository", "coding", "software supply chain"],
        "AI": ["ai", "artificial intelligence", "anthropic", "openai", "model", "llm", "agent", "nvidia", "gpu", "datacenter", "data center"],
        "TECH": ["technology", "cloud", "chips", "semiconductor", "software", "hardware", "infrastructure", "telecom", "satellite", "network outage"],
    }
    score = sum(1 for k in rules.get(bucket, []) if k in blob)
    if bucket == "CYBER" and any(k in blob for k in _WM_CYBER_FALSE_POSITIVE_V211) and score < 2:
        score = 0
    return score


def _wm_bucket_live_news(items: list[dict[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    buckets = {"AI": [], "TECH": [], "CYBER": [], "STARTUP": [], "MARKETS": [], "DEV": []}
    seen: set[str] = set()
    priority = ["CYBER", "STARTUP", "MARKETS", "DEV", "AI", "TECH"]
    for it in items or []:
        key = _wm_normalize_news_key_v211(it)
        if not key or key in seen:
            continue
        seen.add(key)
        blob = _wm_v2_blob(it)
        if _wm_is_cyber_relevant_v211(it):
            bucket = "CYBER"
        else:
            scored = [(bucket, _wm_article_score_for_bucket_v211(blob, bucket)) for bucket in priority if bucket != "CYBER"]
            bucket, score = max(scored, key=lambda x: (x[1], -priority.index(x[0])))
            if score <= 0:
                bucket = "TECH"
        enriched = {**it, "tag": bucket if bucket != "MARKETS" else "MARKET"}
        buckets[bucket].append(enriched)
    if not buckets["TECH"]:
        buckets["TECH"] = list((items or [])[:3])
    return buckets


def _wm_country_market_rows_v211(country: str, quote_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    if country == "Global" or country == "United States":
        rows = [r for r in (quote_rows or []) if str(r.get("symbol", "")).upper() not in {"BTC", "ETH", "SOL", "BNB", "BTC-USD", "ETH-USD", "SOL-USD", "BNB-USD", "^VIX", "VIX", "^GSPC", "^IXIC"}]
        return rows[:6] if rows else [{"symbol": s, "display": d, "price": p, "change": _wm_stable_rng_v211(s + "chg-v2", -1.8, 1.8)} for s, d, p in _WM_COUNTRY_MARKETS_V211["United States"]]
    base = _WM_COUNTRY_MARKETS_V211.get(country)
    if not base:
        return _wm_country_market_rows_v211("United States", quote_rows)
    return [{"symbol": s, "display": d, "price": p * (1 + _wm_stable_rng_v211(s + country + "px", -0.012, 0.012)), "change": _wm_stable_rng_v211(s + country + "chg", -1.6, 1.8)} for s, d, p in base]


def _wm_country_macro_cards_v211(country: str, payload: dict[str, Any]) -> list[dict[str, Any]]:
    rows = _WM_COUNTRY_MACRO_V211.get(country)
    if rows:
        return [{"label": a, "value": b, "delta": c} for a, b, c in rows]
    return (payload.get("panels", {}).get("economic", {}).get("cards", []) if isinstance(payload, dict) else []) or [
        {"label": "VIX", "value": "20.39", "delta": "+0.69"},
        {"label": "Rates", "value": "watch", "delta": "macro"},
        {"label": "FX", "value": "watch", "delta": "country"},
        {"label": "Growth", "value": "stable", "delta": "nowcast"},
    ]


def _wm_signal_context_v211(style: str, country: str, live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], live_enabled: bool) -> dict[str, Any]:
    news_count = sum(len(v) for v in (live_news or {}).values())
    cyber_count = len((live_news or {}).get("CYBER", []))
    ai_count = len((live_news or {}).get("AI", [])) + len((live_news or {}).get("TECH", []))
    startup_count = len((live_news or {}).get("STARTUP", []))
    country_hits = sum(1 for x in _wm_items_flat_v211(live_news) if _wm_country_keyword_score_v211(x, country) > 0)
    market_rows = _wm_country_market_rows_v211(country, quote_rows)
    market_changes = [float(r.get("change", 0)) for r in market_rows]
    avg_change = sum(market_changes) / len(market_changes) if market_changes else 0.0
    vix_rows = [r for r in (quote_rows or []) if str(r.get("symbol", "")).upper() in {"^VIX", "VIX"}]
    vix_level = float(vix_rows[0].get("price", 18.0)) if vix_rows else 18.0
    market_stress = int(max(0, min(100, 34 + max(0, -avg_change) * 13 + max(0, vix_level - 18) * 1.6)))
    cyber_stress = int(max(0, min(96, 18 + cyber_count * 6 + min(16, country_hits * 2) + (8 if style in {"Risk", "Ops"} else 0))))
    tech_momentum = int(max(0, min(96, 32 + ai_count * 4 + startup_count * 2 + (9 if style == "Tech" else 0))))
    geo_heat = int(max(0, min(94, 26 + min(38, news_count * 0.8) + min(18, country_hits * 1.8) + (6 if country != "Global" else 0))))
    global_risk = int(round(0.33 * market_stress + 0.32 * cyber_stress + 0.25 * geo_heat + 0.10 * max(0, 100 - tech_momentum)))
    regime = "Elevated" if global_risk >= 68 else ("Watch" if global_risk >= 45 else "Stable")
    return {
        "global_risk": global_risk,
        "cyber_stress": cyber_stress,
        "market_stress": market_stress,
        "tech_momentum": tech_momentum,
        "geo_heat": geo_heat,
        "regime": regime,
        "news_count": news_count,
        "avg_market_change": avg_change,
        "vix_level": vix_level,
        "style": style,
        "country": country,
        "live": bool(live_enabled),
        "country_hits": country_hits,
    }


def _wm_first_relevant_item_v211(items: list[dict[str, Any]], country: str = "Global", predicate=None) -> dict[str, Any] | None:
    candidates = items or []
    if predicate:
        candidates = [x for x in candidates if predicate(x)]
    if country != "Global":
        ranked = sorted(enumerate(candidates), key=lambda p: (_wm_country_keyword_score_v211(p[1], country), -p[0]), reverse=True)
        candidates = [x for _, x in ranked]
    return candidates[0] if candidates else None


def _wm_signal_drivers_v211(ctx: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], country: str, style: str) -> list[dict[str, Any]]:
    cyber_item = _wm_first_relevant_item_v211((live_news or {}).get("CYBER", []), country, _wm_is_cyber_relevant_v211)
    ai_item = _wm_first_relevant_item_v211(((live_news or {}).get("AI", []) + (live_news or {}).get("TECH", [])), country, lambda x: any(k in _wm_v2_blob(x) for k in ["ai", "nvidia", "datacenter", "data center", "semiconductor", "cloud", "infrastructure"]))
    return [
        {"score": "GLOBAL RISK", "value": f"{int(ctx.get('global_risk',0))}/100", "driver": f"Blend pondéré de market stress {int(ctx.get('market_stress',0))}, cyber {int(ctx.get('cyber_stress',0))}, geo heat {int(ctx.get('geo_heat',0))}, tech momentum {int(ctx.get('tech_momentum',0))}.", "evidence": f"{int(ctx.get('news_count',0))} live items · {int(ctx.get('country_hits',0))} country hits · style={style}."},
        {"score": "CYBER", "value": f"{int(ctx.get('cyber_stress',0))}/100", "driver": f"{len((live_news or {}).get('CYBER', []))} articles cyber strictement routés; mots-clés forts requis.", "evidence": _text((cyber_item or {}).get("title"), "No hard cyber driver detected.")},
        {"score": "MARKET", "value": f"{int(ctx.get('market_stress',0))}/100", "driver": f"Mouvement moyen actions pays {float(ctx.get('avg_market_change',0)):+.2f}% et VIX {float(ctx.get('vix_level',0)):.1f}.", "evidence": "Panel marché country-aware; fallback déterministe seulement si Yahoo est indisponible."},
        {"score": "TECH MOMENTUM", "value": f"{int(ctx.get('tech_momentum',0))}/100", "driver": f"{len((live_news or {}).get('AI', [])) + len((live_news or {}).get('TECH', []))} articles AI/tech + {len((live_news or {}).get('STARTUP', []))} startup/VC.", "evidence": _text((ai_item or {}).get("title"), "No AI infrastructure driver detected.")},
        {"score": "GEO HEAT", "value": f"{int(ctx.get('geo_heat',0))}/100", "driver": "Pays/zone + densité d’items live pertinents.", "evidence": f"Country hits: {int(ctx.get('country_hits',0))}."},
    ]


def _wm_alert_engine_v211(ctx: dict[str, Any], country: str, style: str, live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]]) -> list[dict[str, Any]]:
    cfg = _wm_intel_cfg_v211(country)
    assets = ", ".join(cfg.get("assets", [])[:6]) or "country assets"
    alerts: list[dict[str, Any]] = []
    cyber_item = _wm_first_relevant_item_v211((live_news or {}).get("CYBER", []), country, _wm_is_cyber_relevant_v211)
    if int(ctx.get("cyber_stress", 0)) >= 58 and cyber_item:
        alerts.append({"level": "HIGH" if int(ctx.get("cyber_stress",0)) >= 78 else "WATCH", "confidence": min(94, 58 + int(ctx.get("cyber_stress",0)) // 2), "title": f"{country} cyber stress elevated" if country != "Global" else "Global cyber stress elevated", "impact": "Critical infrastructure, cloud, financial systems", "assets": assets, "driver": _text(cyber_item.get("title"), "Hard cyber cluster detected.")})
    ai_item = _wm_first_relevant_item_v211(((live_news or {}).get("AI", []) + (live_news or {}).get("TECH", [])), country, lambda x: any(k in _wm_v2_blob(x) for k in ["ai", "nvidia", "datacenter", "data center", "semiconductor", "cloud", "infrastructure"]))
    if int(ctx.get("tech_momentum", 0)) >= 68 and ai_item:
        alerts.append({"level": "MOMENTUM", "confidence": min(92, 54 + int(ctx.get("tech_momentum",0)) // 2), "title": f"{country} AI / infrastructure momentum cluster" if country != "Global" else "AI infrastructure momentum cluster", "impact": "AI capex, semiconductors, data centers, power demand", "assets": assets, "driver": _text(ai_item.get("title"), "AI infrastructure cluster detected.")})
    if int(ctx.get("market_stress", 0)) >= 56:
        alerts.append({"level": "WATCH", "confidence": min(88, 50 + int(ctx.get("market_stress",0)) // 2), "title": "Market stress above watch threshold", "impact": "Risk appetite, liquidity, index beta", "assets": assets, "driver": f"Avg country equity move {float(ctx.get('avg_market_change',0)):+.2f}%, VIX {float(ctx.get('vix_level',0)):.1f}."})
    if int(ctx.get("geo_heat", 0)) >= 64:
        geo_item = _wm_first_relevant_item_v211(_wm_items_flat_v211(live_news), country, lambda x: not _wm_is_cyber_relevant_v211(x))
        alerts.append({"level": "WATCH", "confidence": min(86, 48 + int(ctx.get("geo_heat",0)) // 2), "title": f"{country} geopolitical heat elevated" if country != "Global" else "Global geopolitical heat elevated", "impact": "Policy risk, supply chains, sentiment", "assets": assets, "driver": _text((geo_item or {}).get("title"), f"{int(ctx.get('country_hits',0))} country-relevant items.")})
    if not alerts:
        alerts.append({"level": "INFO", "confidence": 64, "title": f"{country} signal mesh stable" if country != "Global" else "Global signal mesh stable", "impact": "No immediate stress cluster", "assets": assets, "driver": "Scores below alert thresholds."})
    return alerts[:4]


_WM_V2_PREV_PANEL_HTML = _wm_clean_panel_html

def _wm_clean_panel_html(panel_id: str, payload: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], country: str, max_items: int = 4) -> str:
    title = _WM_PANEL_TITLES.get(panel_id, panel_id)
    if panel_id == "markets":
        rows = _wm_country_market_rows_v211(country, quote_rows)
        body = "".join(f'<div class="wmc-market"><span>{_wm_clean_escape(r.get("display", r.get("symbol")))}</span><b>${float(r.get("price",0)):,.2f}</b><em class="{ "up" if float(r.get("change",0))>=0 else "down"}">{float(r.get("change",0)):+.2f}%</em></div>' for r in rows[:6])
        return f'<section class="wmc-panel" data-panel="markets">{_wm_panel_header(title, len(rows))}<div class="wmc-body">{body}</div></section>'
    if panel_id == "economic":
        cards = _wm_country_macro_cards_v211(country, payload)
        body = '<div class="wmc-macro">' + ''.join(f'<div><small>{_wm_clean_escape(c.get("label"))}</small><b>{_wm_clean_escape(c.get("value"))}</b><em>{_wm_clean_escape(c.get("delta"))}</em></div>' for c in cards[:4]) + '</div>'
        return f'<section class="wmc-panel wide" data-panel="economic">{_wm_panel_header(title, len(cards))}<div class="wmc-body">{body}</div></section>'
    return _WM_V2_PREV_PANEL_HTML(panel_id, payload, live_news, quote_rows, country, max_items=max_items)


_WM_V2_PREV_DASHBOARD_HTML = _wm_clean_dashboard_html

def _wm_clean_dashboard_html(payload: dict[str, Any], visible_ids: list[str], style: str, country: str, live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], signal_context: dict[str, Any] | None = None) -> str:
    html_payload = _WM_V2_PREV_DASHBOARD_HTML(payload, visible_ids, style, country, live_news, quote_rows, signal_context=signal_context)
    extra_css = """
<style>
html,body,.wmc-shell,.wmc-grid,.wmc-panel,.wmc-top,.wmc-foot{ -webkit-print-color-adjust:exact!important; print-color-adjust:exact!important; color-adjust:exact!important; }
html,body{background:#050608!important;color:#f4f4f5!important;}
.wmc-shell{background:#0b0d10!important;border-color:#30343b!important;}
.wmc-grid{background:#050608!important;}
.wmc-panel{background:linear-gradient(180deg,#17191d,#0f1115)!important;border-color:#313640!important;min-height:285px!important;max-height:390px!important;}
.wmc-panel.wide{min-height:285px!important;}
.wmc-top,.wmc-foot{background:#121417!important;}
.wmc-item{min-height:82px!important;}
.wmc-title{font-size:15px!important;line-height:1.22!important;}
.wmc-body{scrollbar-color:#334155 #0b0d10;}
.wmc-live{background:rgba(56,255,135,.10)!important;}
.wmc-sig,.wmc-signal-lead{background:#17191d!important;}
.wmc-brief{background:#1b1f2a!important;}
</style>
"""
    html_payload = html_payload.replace("<style>", extra_css + "\n<style>", 1)
    html_payload = html_payload.replace("WORLD MONITOR · Value+ Signals", "WORLD MONITOR · Value+ Intelligence V2")
    return html_payload


_WM_PREV_FOCUS_FIGURE_V2 = _wm_focus_figure_on_country_v211

def _wm_focus_figure_on_country_v211(fig: go.Figure, country: str, projection_mode: str) -> None:
    _WM_PREV_FOCUS_FIGURE_V2(fig, country, projection_mode)
    # Slightly cleaner Europe/France viewport after PDF validation.
    try:
        if country == "France" and str(projection_mode).upper() != "3D":
            fig.update_geos(center=dict(lon=2.5, lat=46.2), lonaxis_range=[-7.5, 12.5], lataxis_range=[40.5, 53.5])
    except Exception:
        pass


def _render_worldmonitor_panels_clean_v211(style: str = "Global", country: str = "Global", live_enabled: bool = True) -> None:
    err = _WM211_PANELS_NS.get("_EMBEDDED_IMPORT_ERROR") if isinstance(_WM211_PANELS_NS, dict) else None
    if err is not None:
        st.error(f"WorldMonitor panels source loader error: {err}")
        return
    load_fn = _WM211_PANELS_NS.get("load_worldmonitor_panel_catalog_v2120")
    build_fn = _WM211_PANELS_NS.get("build_panel_payload_v2120")
    if not callable(load_fn) or not callable(build_fn):
        st.error("WorldMonitor panels loader unavailable in integrated module.")
        return
    catalog = load_fn("")
    workspace = _WM_STYLE_TO_WORKSPACE.get(style, "Full WorldMonitor")
    payload = build_fn(catalog, workspace=workspace, max_items=3)
    visible_ids = _WM_STYLE_TO_PANELS.get(style, _WM_STYLE_TO_PANELS["Global"])
    live_items = _wm_fetch_rss_items_v211(style, country, max_items=96) if live_enabled else []
    live_items = _wm_prioritize_country_items_v211(live_items, country, limit=None)
    live_news = _wm_bucket_live_news(live_items)
    quote_rows = _wm_fetch_quote_rows_v211()
    ctx = _wm_signal_context_v211(style, country, live_news, quote_rows, live_enabled)
    quality = _wm_quality_metrics_v211(country, live_news)
    drivers = _wm_signal_drivers_v211(ctx, live_news, quote_rows, country, style)
    alerts = _wm_alert_engine_v211(ctx, country, style, live_news, quote_rows)
    intel = _wm_country_intel_v211(style, country, ctx, live_news, quote_rows)
    payload["value_plus"] = {"ctx": ctx, "quality": quality, "drivers": drivers, "alerts": alerts, "country_intel": intel}
    html_payload = _wm_clean_dashboard_html(payload, visible_ids, style, country, live_news, quote_rows, signal_context=ctx)
    panel_units = sum(2 if pid in {"economic", "tech_events", "country_intel", "signal_drivers", "alert_engine"} else 1 for pid in visible_ids)
    rows = max(2, math.ceil(panel_units / 4))
    component_height = int(min(2400, max(1120, 52 + 70 + rows * 430 + 58)))
    if components is not None:
        components.html(html_payload, height=component_height, scrolling=True)
    else:
        st.info("streamlit.components.v1 unavailable; panels HTML cannot be rendered.")


if __name__ == "__main__":
    print(f"{MODULE_VERSION} loaded. Use Streamlit and call render_worldmonitor_bridge_v211().")

