def _wm_v3_timeout_urlopen(url: str, timeout: int = 5, headers: dict[str, str] | None = None) -> bytes:
    req = _wm_v3_urlrequest.Request(url, headers=headers or {"User-Agent": "Mozilla/5.0 QuantTerminal WorldMonitor/2.11"})
    with _wm_v3_urlrequest.urlopen(req, timeout=timeout) as resp:
        return resp.read(900_000)


def _wm_v3_layer_object(
    layer_id: str,
    title: str,
    lat: float,
    lon: float,
    source: str,
    collection: str,
    severity: float = 55,
    confidence: float = 62,
    metadata: dict[str, Any] | None = None,
) -> dict[str, Any]:
    spec = LAYER_BY_ID.get(layer_id, LAYER_BY_ID.get("newsLocations"))
    if spec is None:
        spec = LayerSpec(layer_id, layer_id, "Other")
    oid = _id_hash(layer_id, title, lat, lon, source, collection)
    return {
        "object_id": f"direct:{layer_id}:{oid}",
        "layer_id": layer_id,
        "layer_label": spec.label,
        "group": spec.group,
        "title": _text(title, "Live object"),
        "source_file": source,
        "collection": collection,
        "source_class": "live" if layer_id not in {"renewableInstallations"} else "static",
        "color": spec.color,
        "icon": spec.icon,
        "metadata": json.dumps(metadata or {}, ensure_ascii=False, default=str)[:1400],
        "severity": max(0, min(100, float(severity or 55))),
        "confidence": max(0, min(100, float(confidence or 62))),
        "kind": "point",
        "lat": float(lat),
        "lon": float(lon),
        "points_json": "",
    }


def _wm_v3_infer_geo_from_text(text: str, default_country: str = "Global") -> tuple[float, float, str] | None:
    blob = str(text or "").lower()
    # Prefer explicit title/location hints.
    best: tuple[float, float, str] | None = None
    for key, value in _WM_V3_GEO_HINTS.items():
        if key in blob:
            best = value
            break
    if best:
        return best
    # Fall back to currently supported country configuration when the query is country-specific.
    if default_country and default_country != "Global":
        try:
            cfg = _wm_country_cfg_v211(default_country)
            if cfg:
                return (float(cfg.get("lat", 0.0)), float(cfg.get("lon", 0.0)), str(default_country))
        except Exception:
            pass
    return None


def _wm_v3_rss_items_for_query(query: str, limit: int = 10) -> list[dict[str, str]]:
    enc = _wm_v3_urlparse.quote_plus(query)
    url = f"https://news.google.com/rss/search?q={enc}&hl=en-US&gl=US&ceid=US:en"
    out: list[dict[str, str]] = []
    try:
        raw = _wm_v3_timeout_urlopen(url, timeout=5)
        root = _wm_v3_et.fromstring(raw)
        for node in root.findall(".//item")[:limit]:
            title = _text(node.findtext("title"), "")
            if not title:
                continue
            out.append({
                "title": title,
                "url": _text(node.findtext("link"), ""),
                "pubDate": _text(node.findtext("pubDate"), ""),
                "source": "Google News RSS",
            })
    except Exception:
        pass
    return out


def _wm_v3_fetch_usgs(hours_back: int, min_magnitude: float) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    start = (_wm_v3_dt.datetime.utcnow() - _wm_v3_dt.timedelta(hours=max(1, int(hours_back or 24)))).strftime("%Y-%m-%dT%H:%M:%S")
    url = "https://earthquake.usgs.gov/fdsnws/event/1/query?" + _wm_v3_urlparse.urlencode({
        "format": "geojson", "starttime": start, "minmagnitude": float(min_magnitude or 0.0), "limit": 600, "orderby": "time",
    })
    try:
        data = json.loads(_wm_v3_timeout_urlopen(url, timeout=6).decode("utf-8", "ignore"))
        for f in data.get("features", [])[:600]:
            props = f.get("properties", {}) or {}
            coords = (((f.get("geometry") or {}).get("coordinates") or []) + [None, None])[:2]
            lon, lat = _safe_float(coords[0]), _safe_float(coords[1])
            if not _valid_latlon(lat, lon):
                continue
            mag = _safe_float(props.get("mag"), 0.0) or 0.0
            rows.append(_wm_v3_layer_object(
                "earthquakes", _text(props.get("title"), "USGS earthquake"), float(lat), float(lon),
                "USGS direct", "USGS_EARTHQUAKES", severity=min(100, 25 + mag * 10), confidence=94,
                metadata={"mag": mag, "place": props.get("place"), "time": props.get("time"), "url": props.get("url")},
            ))
        return rows, {"provider": "USGS direct", "status": "OK", "rows": len(rows), "detail": "direct public GeoJSON"}
    except Exception as exc:
        return rows, {"provider": "USGS direct", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:140]}"}


def _wm_v3_fetch_gdacs() -> tuple[list[dict[str, Any]], dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    url = "https://www.gdacs.org/xml/rss.xml"
    try:
        raw = _wm_v3_timeout_urlopen(url, timeout=6)
        root = _wm_v3_et.fromstring(raw)
        ns = {"geo": "http://www.w3.org/2003/01/geo/wgs84_pos#", "georss": "http://www.georss.org/georss"}
        for item in root.findall(".//item")[:220]:
            title = _text(item.findtext("title"), "GDACS alert")
            desc = _text(item.findtext("description"), "")
            lat = lon = None
            pt = item.findtext("georss:point", namespaces=ns)
            if pt and len(pt.split()) >= 2:
                a, b = pt.split()[:2]
                lat, lon = _safe_float(a), _safe_float(b)
            if lat is None:
                lat = _safe_float(item.findtext("geo:lat", namespaces=ns))
                lon = _safe_float(item.findtext("geo:long", namespaces=ns))
            if not _valid_latlon(lat, lon):
                continue
            layer = "natural"
            if any(k in (title + desc).lower() for k in ["earthquake", " eq "]):
                layer = "earthquakes"
            elif any(k in (title + desc).lower() for k in ["cyclone", "storm", "flood", "volcano", "tsunami", "drought"]):
                layer = "natural"
            rows.append(_wm_v3_layer_object(layer, title, float(lat), float(lon), "GDACS direct", "GDACS_RSS", severity=72, confidence=88, metadata={"description": desc[:500], "link": _text(item.findtext("link"), "")}))
        return rows, {"provider": "GDACS direct", "status": "OK", "rows": len(rows), "detail": "direct public RSS"}
    except Exception as exc:
        return rows, {"provider": "GDACS direct", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:140]}"}


def _wm_v3_fetch_eonet(hours_back: int) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    days = max(1, min(30, math.ceil(max(1, int(hours_back or 24)) / 24)))
    url = f"https://eonet.gsfc.nasa.gov/api/v3/events?status=open&days={days}"
    cat_to_layer = {
        "wildfires": "fires", "severeStorms": "natural", "volcanoes": "natural", "floods": "natural",
        "drought": "climate", "dustHaze": "climate", "tempExtremes": "climate", "seaLakeIce": "climate", "snow": "weather",
    }
    try:
        data = json.loads(_wm_v3_timeout_urlopen(url, timeout=6).decode("utf-8", "ignore"))
        for ev in data.get("events", [])[:300]:
            cats = ev.get("categories") or []
            cat = _text((cats[0] or {}).get("id") if cats else "", "natural")
            layer = cat_to_layer.get(cat, "natural")
            geoms = ev.get("geometry") or []
            latest = geoms[-1] if geoms else {}
            coords = latest.get("coordinates") or []
            if latest.get("type") != "Point" or len(coords) < 2:
                continue
            lon, lat = _safe_float(coords[0]), _safe_float(coords[1])
            if not _valid_latlon(lat, lon):
                continue
            rows.append(_wm_v3_layer_object(layer, _text(ev.get("title"), "NASA EONET event"), float(lat), float(lon), "NASA EONET direct", "EONET", severity=62, confidence=84, metadata={"category": cat, "date": latest.get("date"), "sources": ev.get("sources", [])[:3]}))
        return rows, {"provider": "NASA EONET direct", "status": "OK", "rows": len(rows), "detail": f"public API days={days}"}
    except Exception as exc:
        return rows, {"provider": "NASA EONET direct", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:140]}"}


def _wm_v3_fetch_nws_weather() -> tuple[list[dict[str, Any]], dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    try:
        data = json.loads(_wm_v3_timeout_urlopen("https://api.weather.gov/alerts/active", timeout=6, headers={"User-Agent": "QuantTerminal WorldMonitor/2.11 contact: local"}).decode("utf-8", "ignore"))
        for feat in data.get("features", [])[:120]:
            prop = feat.get("properties", {}) or {}
            geom = feat.get("geometry") or {}
            coords = geom.get("coordinates") or []
            pts: list[tuple[float, float]] = []
            try:
                if geom.get("type") == "Polygon":
                    pts = [(float(x[1]), float(x[0])) for x in coords[0][:80] if len(x) >= 2]
                elif geom.get("type") == "MultiPolygon":
                    pts = [(float(x[1]), float(x[0])) for x in coords[0][0][:80] if len(x) >= 2]
            except Exception:
                pts = []
            if not pts:
                continue
            lat = sum(p[0] for p in pts) / len(pts)
            lon = sum(p[1] for p in pts) / len(pts)
            if not _valid_latlon(lat, lon):
                continue
            sev = {"Extreme": 90, "Severe": 76, "Moderate": 58, "Minor": 42}.get(_text(prop.get("severity")), 48)
            rows.append(_wm_v3_layer_object("weather", _text(prop.get("headline"), prop.get("event", "NWS alert")), lat, lon, "NWS direct", "NWS_ALERTS", severity=sev, confidence=82, metadata={"event": prop.get("event"), "severity": prop.get("severity"), "area": prop.get("areaDesc"), "expires": prop.get("expires")}))
        return rows, {"provider": "NWS weather direct", "status": "OK", "rows": len(rows), "detail": "US weather.gov active alerts"}
    except Exception as exc:
        return rows, {"provider": "NWS weather direct", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:140]}"}


def _wm_v3_fetch_news_derived_layers(hours_back: int) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    rows: list[dict[str, Any]] = []
    statuses: list[dict[str, Any]] = []
    for layer, queries in _WM_V3_NEWS_LAYER_QUERIES.items():
        before = len(rows)
        for query in queries[:2]:
            for item in _wm_v3_rss_items_for_query(query, limit=6):
                title = _text(item.get("title"), "")
                blob = title.lower()
                if not any(k in blob for k in _WM_V3_LAYER_KEYWORDS.get(layer, [])):
                    continue
                geo = _wm_v3_infer_geo_from_text(title, "Global")
                if geo is None:
                    continue
                lat, lon, loc = geo
                rows.append(_wm_v3_layer_object(layer, title, lat, lon, "Google News RSS geo-inferred", f"NEWS_DERIVED_{layer.upper()}", severity=58 if layer != "outages" else 66, confidence=58, metadata={"location_inferred": loc, "url": item.get("url"), "pubDate": item.get("pubDate"), "query": query, "method": "headline geocoding"}))
        statuses.append({"provider": f"News-derived {layer}", "status": "OK" if len(rows) > before else "EMPTY", "rows": len(rows) - before, "detail": "real RSS item + conservative headline geocoding"})
    return rows, statuses


@st.cache_data(ttl=300, show_spinner=False)
def load_live_event_objects_v211(hours_back: int = 168, min_magnitude: float = 0.0, cache_nonce: int = 0, provider_profile: str = "Fast natural") -> tuple[pd.DataFrame, pd.DataFrame]:
    """V3 live loader: original adapter + direct public layer repair adapters."""
    frames: list[pd.DataFrame] = []
    statuses: list[dict[str, Any]] = []

    # 1) Keep existing/global_event_map adapter if available.
    try:
        prev_objects, prev_status = _WM_V3_PREV_LOAD_LIVE_EVENT_OBJECTS_V211(hours_back=hours_back, min_magnitude=min_magnitude, cache_nonce=cache_nonce, provider_profile=provider_profile)
        if isinstance(prev_objects, pd.DataFrame) and not prev_objects.empty:
            frames.append(prev_objects)
        if isinstance(prev_status, pd.DataFrame) and not prev_status.empty:
            statuses.extend(prev_status.to_dict("records"))
    except Exception as exc:
        statuses.append({"provider": "global_event_map previous", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:140]}"})

    # 2) Direct public adapters. These repair the commonly empty live layers.
    # Run them concurrently so a slow public endpoint does not block the whole map.
    direct_rows: list[dict[str, Any]] = []
    fetchers = [
        ("USGS direct", lambda: _wm_v3_fetch_usgs(hours_back, min_magnitude)),
        ("GDACS direct", _wm_v3_fetch_gdacs),
        ("NASA EONET direct", lambda: _wm_v3_fetch_eonet(hours_back)),
        ("NWS weather direct", _wm_v3_fetch_nws_weather),
        ("News-derived repair", lambda: _wm_v3_fetch_news_derived_layers(hours_back)),
    ]
    with _wm_v3_futures.ThreadPoolExecutor(max_workers=5) as ex:
        fut_map = {ex.submit(fn): label for label, fn in fetchers}
        done, not_done = _wm_v3_futures.wait(fut_map.keys(), timeout=18)
        for fut in done:
            label = fut_map.get(fut, "direct adapter")
            try:
                result = fut.result(timeout=0)
                # Normal fetchers return (rows, status); news repair returns (rows, [statuses]).
                rows, status = result
                direct_rows.extend(rows or [])
                if isinstance(status, list):
                    statuses.extend(status)
                else:
                    statuses.append(status)
            except Exception as exc:
                statuses.append({"provider": label, "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:140]}"})
        for fut in not_done:
            label = fut_map.get(fut, "direct adapter")
            try:
                fut.cancel()
            except Exception:
                pass
            statuses.append({"provider": label, "status": "TIMEOUT", "rows": 0, "detail": "direct layer repair endpoint exceeded 18s budget"})

    if direct_rows:
        frames.append(pd.DataFrame(direct_rows))
    objects = pd.concat(frames, ignore_index=True) if frames else pd.DataFrame()
    if not objects.empty:
        objects = objects.drop_duplicates(subset=["object_id", "kind", "points_json"], keep="first").reset_index(drop=True)
        objects["severity"] = pd.to_numeric(objects.get("severity"), errors="coerce").fillna(55).clip(0, 100)
        objects["confidence"] = pd.to_numeric(objects.get("confidence"), errors="coerce").fillna(60).clip(0, 100)
    return objects, pd.DataFrame(statuses)


def _wm_v3_registry_actionable(registry: pd.DataFrame) -> pd.DataFrame:
    """Keep real/actionable layer rows visible; hide empty provider-only placeholders from the drawer."""
    if not isinstance(registry, pd.DataFrame) or registry.empty:
        return registry
    work = registry.copy()
    work["count"] = pd.to_numeric(work.get("count"), errors="coerce").fillna(0).astype(int)
    # Keep non-empty layers and a few core layers only when they have rows. Provider-only zero layers are hidden.
    work = work[work["count"] > 0].copy()
    return work.reset_index(drop=True)


def _map_component_html(fig: go.Figure, registry: pd.DataFrame, stage_height: int = 860, active_time: str = "24h", projection_mode: str = "2D") -> str:
    registry_actionable = _wm_v3_registry_actionable(registry)
    html_payload = _WM_V3_PREV_MAP_COMPONENT_HTML(fig, registry_actionable, stage_height=stage_height, active_time=active_time, projection_mode=projection_mode)
    if not html_payload:
        return html_payload
    v3_css = """
      .wm-row.disabled{display:none!important;}
      .wm-section:empty{display:none!important;}
      .wm-actions:after{content:'READY LAYERS';margin-left:auto;color:#38bdf8;font-size:9px;font-weight:950;letter-spacing:.14em;align-self:center;}
      .wm-foot:before{content:'actionable only';color:#64748b;font-size:9px;margin-right:6px;}
    """
    html_payload = html_payload.replace("</style>", v3_css + "\n</style>", 1)
    html_payload = html_payload.replace("LIVE · V2.11.9", "LIVE · V2.11.9 · LAYER REPAIR", 1)
    return html_payload


