def _wm_v31_capability_state(row: dict[str, Any]) -> tuple[str, str, str, str]:
    """Return (state, provider, need, reason) for compact layer capability UI."""
    layer_id = _text(row.get("layer_id"), "")
    count = int(_safe_float(row.get("count"), 0) or 0)
    source_class = _text(row.get("source_class"), "").lower()
    note = _text(row.get("note"), "")
    hint = _WM_V31_PROVIDER_HINTS.get(layer_id, {})
    provider = hint.get("provider") or source_class or "source registry"
    need = hint.get("need") or "source/provider"
    reason = hint.get("reason") or note or "layer capability"

    if count > 0:
        return "READY", provider, "loaded", f"{count} real object(s) loaded"
    if layer_id in _WM_V31_LOCKED_LAYER_IDS or "real ais" in note.lower() or "provider-only" in source_class:
        return "LOCKED", provider, need, reason
    if "variant" in source_class:
        return "LOCKED", provider, need, reason
    return "PROVIDER", provider, need, reason


def _wm_v31_layer_capability_rows(registry: pd.DataFrame) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if not isinstance(registry, pd.DataFrame) or registry.empty:
        source_rows = [{"layer_id": spec.layer_id, "label": spec.label, "group": spec.group, "count": 0, "source_class": spec.source_class, "note": spec.note} for spec in LAYER_SPECS]
    else:
        source_rows = registry.to_dict("records")
    for row in source_rows:
        state, provider, need, reason = _wm_v31_capability_state(row)
        count = int(_safe_float(row.get("count"), 0) or 0)
        rows.append({
            "layer_id": _text(row.get("layer_id")),
            "label": _text(row.get("label"), _text(row.get("layer_id"))),
            "group": _text(row.get("group"), "Other"),
            "count": count,
            "state": state,
            "provider": provider,
            "need": need,
            "reason": reason,
            "source_class": _text(row.get("source_class"), ""),
            "note": _text(row.get("note"), ""),
        })
    order = {"LOCKED": 0, "PROVIDER": 1, "READY": 2}
    rows.sort(key=lambda r: (order.get(r.get("state"), 9), str(r.get("group", "")), str(r.get("label", ""))))
    return rows


