def _wm_clean_dashboard_html(payload: dict[str, Any], visible_ids: list[str], style: str, country: str, live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], signal_context: dict[str, Any] | None = None) -> str:
    source_registry = payload.get("source_registry_v32", []) if isinstance(payload, dict) else []
    return _wm_v32_dashboard_html(payload, visible_ids, style, country, live_news, quote_rows, signal_context=signal_context, source_registry=source_registry)


def _render_worldmonitor_panels_clean_v211(style: str = "Global", country: str = "Global", live_enabled: bool = True) -> None:
    err = _WM211_PANELS_NS.get("_EMBEDDED_IMPORT_ERROR") if isinstance(_WM211_PANELS_NS, dict) else None
    if err is not None:
        st.error(f"WorldMonitor panels source loader error: {err}")
        return
    load_fn = _WM211_PANELS_NS.get("load_worldmonitor_panel_catalog_v2120")
    build_fn = _WM211_PANELS_NS.get("build_panel_payload_v2120")
    if not callable(load_fn) or not callable(build_fn):
        st.error("WorldMonitor panels loader unavailable in integrated module.")
        return
    catalog = load_fn("")
    workspace = _WM_STYLE_TO_WORKSPACE.get(style, "Full WorldMonitor")
    payload = build_fn(catalog, workspace=workspace, max_items=5)
    live_items = _wm_fetch_rss_items_v211(style, country, max_items=128) if live_enabled else []
    live_items = _wm_prioritize_country_items_v211(live_items, country, limit=None)
    live_news = _wm_bucket_live_news(live_items)
    quote_rows = _wm_country_market_rows_v211(country, _wm_fetch_quote_rows_v211())
    ctx = _wm_signal_context_v211(style, country, live_news, quote_rows, live_enabled)
    payload["value_plus"] = {"ctx": ctx, "quality": _wm_quality_metrics_v211(country, live_news), "drivers": _wm_signal_drivers_v211(ctx, live_news, quote_rows, country, style), "alerts": _wm_alert_engine_v211(ctx, country, style, live_news, quote_rows), "country_intel": _wm_country_intel_v211(style, country, ctx, live_news, quote_rows)}
    payload["source_registry_v32"] = _wm_v32_build_source_registry(catalog, live_items)
    base_ids = ["country_intel", "alert_engine", "signal_drivers", "source_quality", "ai_insights", "live_news", "threat_timeline", "ai_posture", "ai_forecasts", "country_instability", "strategic_risk", "intel_flow", "live_intel", "cross_source", "infra_cascade", "world_news", "region_us", "region_europe", "region_mena", "region_africa", "region_latam", "region_apac", "energy_resources", "government", "think_tanks", "commodities", "energy_complex", "markets", "crypto", "economic", "supply_chain", "finance", "ai_ml", "technology", "cybersecurity", "climate_anomalies", "flight_intel"]
    style_add = {"Tech": ["policy_ai", "funding_vc", "github_trends", "tech_events", "tech_maturity", "vc_financing"], "Finance": ["central_bank_watch", "financial_stress", "fixed_income", "yield_curve", "stablecoins"], "Risk": ["service_status", "internet_disruptions", "central_bank_watch"], "Ops": ["service_status", "world_clock", "flight_intel", "supply_chain"], "Global": ["central_bank_watch", "financial_stress", "world_clock"]}.get(style, [])
    visible_ids: list[str] = []
    for pid in base_ids + style_add:
        if pid not in visible_ids: visible_ids.append(pid)
    html_payload = _wm_clean_dashboard_html(payload, visible_ids, style, country, live_news, quote_rows, signal_context=ctx)
    panel_units = sum(2 if pid in {"country_intel", "signal_drivers", "alert_engine", "live_news", "world_news", "economic"} else 1 for pid in visible_ids)
    rows = max(3, math.ceil(panel_units / 4))
    component_height = int(min(5200, max(1500, 78 + rows * 398 + 64)))
    if components is not None: components.html(html_payload, height=component_height, scrolling=True)
    else: st.info("streamlit.components.v1 unavailable; panels HTML cannot be rendered.")


def _map_component_html(fig: go.Figure, registry: pd.DataFrame, stage_height: int = 860, active_time: str = "24h", projection_mode: str = "2D") -> str:
    html_payload = _WM_V32_PREV_MAP_COMPONENT_HTML(fig, registry, stage_height=stage_height, active_time=active_time, projection_mode=projection_mode)
    if not html_payload: return html_payload
    html_payload = re.sub(r"(LAYER STATUS\s*·\s*)+LAYER STATUS", "LAYER STATUS", html_payload)
    html_payload = html_payload.replace("LAYER REPAIR · LAYER STATUS", "LAYER STATUS")
    return html_payload


def _wm_v32_snapshot_for_tests() -> dict[str, Any]:
    cats: dict[str, int] = {}
    for p in _WM_V32_PANEL_CATALOG:
        cats[p["category"]] = cats.get(p["category"], 0) + 1
    return {"module": MODULE_VERSION, "panel_count": len(_WM_V32_PANEL_CATALOG), "panel_categories": cats, "fallback_sources": len(_WM_V32_FALLBACK_SOURCE_NAMES), "source_registry_count": len(_wm_v32_build_source_registry({}, [])), "settings_tabs": ["Paramètres", "Panneaux", "Sources", "Notifications", "API Keys"]}


if __name__ == "__main__":
    print(f"{MODULE_VERSION} loaded. Use Streamlit and call render_worldmonitor_bridge_v211().")


