def _wm_v321_region_terms(region: str) -> list[str]:
    return {
        "United States": ["united states", "u.s.", "usa", "washington", "new york", "federal reserve", "trump", "white house", "cisa"],
        "Europe": ["europe", "european", "eu ", "france", "germany", "ukraine", "russia", "brussels", "ecb", "london", "paris"],
        "Middle East": ["middle east", "mena", "israel", "iran", "gaza", "gulf", "saudi", "uae", "qatar", "hormuz", "syria"],
        "Africa": ["africa", "sudan", "south africa", "nigeria", "kenya", "ethiopia", "egypt", "morocco"],
        "Latin America": ["latin america", "latam", "mexico", "brazil", "venezuela", "argentina", "chile", "colombia"],
        "Asia": ["asia", "china", "japan", "korea", "india", "taiwan", "singapore", "south china sea", "beijing", "tokyo"],
    }.get(region, [str(region or "").lower()])


def _wm_v321_tag_score(blob: str, tag: str) -> int:
    b = blob.lower()
    rules = {
        "GEO": ["geopolitic", "conflict", "war", "military", "diplomacy", "security", "risk", "sanction", "election", "government", "policy"],
        "NEWS": ["world", "breaking", "politics", "security", "government", "diplomacy", "protest", "crisis"],
        "ENERGY": ["oil", "gas", "lng", "opec", "energy", "power", "electricity", "pipeline", "hormuz", "suez", "brent", "crude"],
        "CYBER": _WM_CYBER_HARD_TERMS_V211,
        "AI": ["ai", "artificial intelligence", "openai", "anthropic", "model", "llm", "gpu", "datacenter", "data center"],
        "TECH": ["technology", "semiconductor", "chips", "cloud", "software", "hardware", "infrastructure", "satellite"],
        "STARTUP": ["startup", "venture", "vc", "funding", "seed", "series a", "unicorn", "techcrunch", "a16z"],
        "MARKETS": ["market", "stock", "earnings", "rates", "fed", "ecb", "bond", "yield", "inflation", "treasury", "cnbc", "reuters"],
        "DEV": ["github", "developer", "open source", "repository", "software supply chain"],
    }
    return sum(1 for k in rules.get(tag, []) if k in b)


def _wm_v321_fetch_google_rss(source: str, tag: str, region: str, query: str, per_feed: int, seen: set[str]) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    try:
        enc = _wm_urlparse.quote_plus(query)
        url = f"https://news.google.com/rss/search?q={enc}&hl=en-US&gl=US&ceid=US:en"
        req = _wm_urlrequest.Request(url, headers={"User-Agent": "Mozilla/5.0 QuantTerminal WorldMonitor/3.2.1"})
        with _wm_urlrequest.urlopen(req, timeout=3.5) as resp:
            raw = resp.read(500_000)
        root = _wm_et.fromstring(raw)
        for node in root.findall(".//item")[:per_feed]:
            title = _text(node.findtext("title"), "")
            link = _text(node.findtext("link"), "")
            pub = _text(node.findtext("pubDate"), "")
            if not title:
                continue
            key = re.sub(r"\s+", " ", title.lower()).strip()
            if key in seen:
                continue
            seen.add(key)
            out.append({"source": source, "tag": tag, "region": region, "title": title, "url": link, "age": pub[:22] if pub else "live"})
    except Exception:
        return []
    return out


@st.cache_data(ttl=600, show_spinner=False)
def _wm_fetch_rss_items_v211(style: str = "Global", country: str = "Global", max_items: int = 128) -> list[dict[str, Any]]:
    """V3.2.1 strict source-routing RSS adapter.

    Unlike the previous adapter, this creates explicit GEO/NEWS/ENERGY buckets
    and region metadata so regional panels do not all fall back to generic CNBC.
    """
    style = str(style or "Global")
    country = str(country or "Global")
    seen: set[str] = set()
    items: list[dict[str, Any]] = []
    per_feed = 4 if max_items <= 80 else 5

    queries = list(_WM_V321_TOPIC_QUERIES.get(style, _WM_V321_TOPIC_QUERIES["Global"]))
    if country and country != "Global":
        queries = [(tag, f"{q} {country}") for tag, q in queries]

    for tag, q in queries:
        items.extend(_wm_v321_fetch_google_rss(f"Google News {tag}", tag, country if country != "Global" else "Global", q, per_feed, seen))
        if len(items) >= max_items:
            return items[:max_items]

    # Always add a light regional mesh. This feeds region panels even when the
    # top-level style is Global.
    for region, rq in _WM_V321_REGION_QUERIES.items():
        for tag, q in rq[:2]:
            items.extend(_wm_v321_fetch_google_rss(f"Google News {region}", tag, region, q, 3, seen))
            if len(items) >= max_items:
                return items[:max_items]

    # Direct sources are used, but tagged and region-scoped. They no longer
    # become the universal fallback for every regional panel.
    for source, tag, region, url in _WM_V321_DIRECT_FEEDS:
        if len(items) >= max_items:
            break
        try:
            req = _wm_urlrequest.Request(url, headers={"User-Agent": "Mozilla/5.0 QuantTerminal WorldMonitor/3.2.1"})
            with _wm_urlrequest.urlopen(req, timeout=3.5) as resp:
                raw = resp.read(500_000)
            root = _wm_et.fromstring(raw)
            for node in root.findall(".//item")[:5]:
                title = _text(node.findtext("title"), "")
                link = _text(node.findtext("link"), "")
                pub = _text(node.findtext("pubDate"), "")
                if not title:
                    continue
                key = re.sub(r"\s+", " ", title.lower()).strip()
                if key in seen:
                    continue
                seen.add(key)
                items.append({"source": source, "tag": tag, "region": region, "title": title, "url": link, "age": pub[:22] if pub else "live"})
                if len(items) >= max_items:
                    break
        except Exception:
            continue
    return items[:max_items]


def _wm_bucket_live_news(items: list[dict[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    """V3.2.1 bucket router with dedicated region/topic families."""
    bucket_names = ["AI", "TECH", "CYBER", "STARTUP", "MARKETS", "DEV", "GEO", "NEWS", "ENERGY"]
    buckets: dict[str, list[dict[str, Any]]] = {k: [] for k in bucket_names}
    seen: set[str] = set()
    priority = ["CYBER", "ENERGY", "GEO", "STARTUP", "MARKETS", "DEV", "AI", "TECH", "NEWS"]
    for it in items or []:
        key = _wm_normalize_news_key_v211(it)
        if not key or key in seen:
            continue
        seen.add(key)
        blob = _wm_v2_blob(it)
        explicit_tag = str(it.get("tag") or "").upper()
        if _wm_is_cyber_relevant_v211(it):
            bucket = "CYBER"
        elif explicit_tag in buckets and _wm_v321_tag_score(blob, explicit_tag) > 0:
            bucket = explicit_tag
        else:
            scored = [(tag, _wm_v321_tag_score(blob, tag)) for tag in priority if tag != "CYBER"]
            bucket, score = max(scored, key=lambda x: (x[1], -priority.index(x[0])))
            if score <= 0:
                bucket = explicit_tag if explicit_tag in buckets else "NEWS"
        enriched = {**it, "tag": bucket if bucket != "MARKETS" else "MARKET", "topic_bucket": bucket, "region": it.get("region", _wm_v32_region_from_text(json.dumps(it, ensure_ascii=False, default=str)))}
        buckets.setdefault(bucket, []).append(enriched)
        # Strategic/news panels can use non-market geopolitical items too.
        if bucket in {"GEO", "ENERGY", "CYBER"}:
            buckets.setdefault("NEWS", []).append(enriched)
    if not buckets["TECH"]:
        buckets["TECH"] = list((items or [])[:3])
    return buckets


def _wm_v321_item_region_match(item: dict[str, Any], region: str) -> bool:
    if region in {"Global", "Tout", "All", ""}:
        return True
    item_region = _text(item.get("region"), "")
    if item_region == region:
        return True
    blob = json.dumps(item, ensure_ascii=False, default=str).lower()
    return any(term in blob for term in _wm_v321_region_terms(region))


def _wm_v32_item_matches_region(item: dict[str, Any], region: str) -> bool:
    return _wm_v321_item_region_match(item, region)


def _wm_v32_select_news(live_news: dict[str, list[dict[str, Any]]], families: list[str] | None = None, region: str = "Global", limit: int = 6) -> list[dict[str, Any]]:
    """V3.2.1 strict selector: no generic global fallback for regional panels."""
    families = families or list(live_news.keys())
    items, seen = [], set()
    for fam in families:
        for item in live_news.get(fam, []) or []:
            title_key = _text(item.get("title"), "").lower().strip()
            if not title_key or title_key in seen:
                continue
            if region != "Global" and not _wm_v321_item_region_match(item, region):
                continue
            seen.add(title_key)
            items.append(item)
            if len(items) >= limit:
                return items
    return items[:limit]


def _wm_v321_quote_crypto_rows() -> list[dict[str, Any]]:
    rows = _wm_fetch_quote_rows_v211() or []
    crypto = [r for r in rows if str(r.get("symbol", "")).upper().replace("-USD", "") in {"BTC", "ETH", "SOL", "BNB"}]
    if crypto:
        return crypto[:5]
    # deterministic fallback only after the quote adapter returned no crypto rows
    fallback = [("BTC", "Bitcoin", 60000.0), ("ETH", "Ethereum", 3200.0), ("SOL", "Solana", 150.0), ("BNB", "BNB", 560.0)]
    return [{"symbol": s, "display": name, "price": price * (1 + _wm_stable_rng_v211(s + "v321px", -0.015, 0.015)), "change": _wm_stable_rng_v211(s + "v321chg", -3.0, 3.0)} for s, name, price in fallback]


_WM_V321_PREV_CLEAN_PANEL_HTML = _wm_clean_panel_html


def _wm_clean_panel_html(panel_id: str, payload: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], country: str, max_items: int = 4) -> str:
    if panel_id == "crypto":
        title = _WM_PANEL_TITLES.get(panel_id, panel_id)
        rows = _wm_v321_quote_crypto_rows()
        body = "".join(f'<div class="wmc-market"><span>{_wm_clean_escape(r.get("display", r.get("symbol")))}</span><b>${float(r.get("price",0)):,.2f}</b><em class="{"up" if float(r.get("change",0))>=0 else "down"}">{float(r.get("change",0)):+.2f}%</em></div>' for r in rows[:5])
        return f'<section class="wmc-panel" data-panel="crypto">{_wm_panel_header(title, len(rows))}<div class="wmc-body">{body}</div></section>'
    return _WM_V321_PREV_CLEAN_PANEL_HTML(panel_id, payload, live_news, quote_rows, country, max_items=max_items)


_WM_V321_PREV_EXTRA_PANEL_HTML = _wm_v32_extra_panel_html


def _wm_v321_panel_from_items(panel_id: str, title: str, items: list[dict[str, Any]], max_items: int = 5, wide: bool = False, status: str = "EN DIRECT") -> str:
    css = " wide" if wide else ""
    body = _wm_v32_news_items_html(items, max_items=max_items)
    if not items:
        body = '<div class="wmc-empty">Aucun item régional strict. Le provider est prêt, mais aucun titre routé sans fallback générique.</div>'
    return f'<section class="wmc-panel{css}" data-panel="{_wm_clean_escape(panel_id)}">{_wm_panel_header(title, len(items), status)}<div class="wmc-body">{body}</div></section>'


def _wm_v32_extra_panel_html(panel_id: str, payload: dict[str, Any], live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], country: str, style: str, ctx: dict[str, Any], max_items: int = 5) -> str | None:
    title = _WM_PANEL_TITLES.get(panel_id, panel_id)
    region_map = {"region_us": "United States", "region_europe": "Europe", "region_mena": "Middle East", "region_africa": "Africa", "region_latam": "Latin America", "region_apac": "Asia"}
    if panel_id == "world_news":
        items = _wm_v32_select_news(live_news, ["GEO", "NEWS", "CYBER", "ENERGY"], "Global", max_items)
        return _wm_v321_panel_from_items(panel_id, title, items, max_items=max_items, wide=True)
    if panel_id in region_map:
        region = region_map[panel_id]
        items = _wm_v32_select_news(live_news, ["GEO", "NEWS", "ENERGY", "CYBER", "MARKETS", "TECH"], region, max_items)
        return _wm_v321_panel_from_items(panel_id, title, items, max_items=max_items)
    if panel_id == "energy_resources":
        items = _wm_v32_select_news(live_news, ["ENERGY", "GEO", "MARKETS"], "Global", max_items)
        return _wm_v321_panel_from_items(panel_id, title, items, max_items=max_items)
    if panel_id == "government":
        items = _wm_v32_select_news(live_news, ["GEO", "NEWS"], country if country != "Global" else "Global", max_items)
        return _wm_v321_panel_from_items(panel_id, title, items, max_items=max_items)
    if panel_id == "think_tanks":
        source_terms = ["aei", "atlantic", "brookings", "csis", "carnegie", "economist", "chatham", "iiss", "cfr"]
        items = []
        for fam in ["GEO", "AI", "NEWS"]:
            for it in live_news.get(fam, []) or []:
                blob = json.dumps(it, ensure_ascii=False, default=str).lower()
                if any(t in blob for t in source_terms):
                    items.append(it)
        if not items:
            items = _wm_v32_select_news(live_news, ["GEO", "AI"], "Global", max_items)
        return _wm_v321_panel_from_items(panel_id, title, items[:max_items], max_items=max_items)
    if panel_id == "finance":
        items = _wm_v32_select_news(live_news, ["MARKETS"], country if country != "Global" else "Global", max_items)
        return _wm_v321_panel_from_items(panel_id, title, items, max_items=max_items)
    return _WM_V321_PREV_EXTRA_PANEL_HTML(panel_id, payload, live_news, quote_rows, country, style, ctx, max_items=max_items)


