# ============================================================
# WORLD MONITOR V2.11 · VALUE+ INTELLIGENCE V3.2.3
# Source Relevance / Region Anchoring / Quality Calibration
# ============================================================
# Purpose:
# - Keep V3.2.2 source manager, modal, crypto repair and layer status.
# - Reduce residual topic leakage: AI != generic software supply chain, Cyber != source label.
# - Require regional anchors for regional panels so query artefacts do not leak across theatres.
# - Recalibrate source quality so it cannot stay at 100 when routing is still imperfect.
# - Normalize visible version labels; avoid V3.2.2.1 footer artefacts.

MODULE_VERSION = "WorldMonitor V2.11 Unified Value+ Intelligence V3.2.3 Source Relevance"

_WM_V323_STALE_DAYS = 10
_WM_V323_AI_TERMS = [
    "artificial intelligence", " a.i.", " ai ", " ai-", "-ai", "openai", "anthropic", "claude",
    "gemini", "llm", "large language model", "machine learning", "gpu", "nvidia", "datacenter",
    "data center", "ai infrastructure", "ai chip", "ai model", "foundation model", "neural",
]
_WM_V323_TECH_TERMS = [
    "semiconductor", "semiconductors", "chip", "chips", "cloud", "software", "hardware", "quantum",
    "satellite", "space", "infrastructure", "data center", "datacenter", "server", "compute",
]
_WM_V323_DEV_TERMS = ["github", "open source", "developer", "software supply chain", "repository", "dependency", "dependencies", "npm", "pypi"]
_WM_V323_GEO_TERMS = [
    "war", "conflict", "geopolitical", "geopolitics", "diplomacy", "sanction", "sanctions", "security",
    "military", "crisis", "trade", "policy", "election", "summit", "attack", "protest", "defense", "risk",
]
_WM_V323_MARKET_TERMS = ["market", "markets", "stocks", "stock", "rates", "fed", "ecb", "bond", "yield", "inflation", "treasury", "earnings", "dollar", "oil price"]
_WM_V323_ENERGY_TERMS = ["oil", "gas", "lng", "energy", "opec", "pipeline", "hormuz", "suez", "crude", "brent", "power", "electricity", "storage"]
_WM_V323_STARTUP_TERMS = ["startup", "venture", "funding", "vc", "seed", "series a", "unicorn", "a16z", "capital"]
_WM_V323_LOW_CONTEXT_TITLE_TERMS = [
    "encyclopedia", "britannica", "prueba", "definition", "explained:", "what is ", "course", "jobs",
    "webinar", "event calendar", "conference agenda", "images -", "photo gallery", "press release roundup",
]
_WM_V323_REGION_EXCLUDES = {
    "United States": ["middle east", "iran", "gaza", "israel", "hormuz", "sudan", "ukraine", "russia"],
    "Europe": ["latin america", "africa", "middle east", "indopacific", "indo-pacific"],
    "Middle East": ["latin america", "south america", "european union", "africa"],
    "Africa": ["middle east", "iran", "hormuz", "ukraine", "russia", "latin america"],
    "Latin America": ["middle east", "iran", "hormuz", "africa", "ukraine"],
    "Asia": ["latin america", "africa"],
}


def _wm_v323_blob_title_source(item: dict[str, Any]) -> str:
    return (_text(item.get("title"), "") + " " + _text(item.get("source"), "")).lower()


def _wm_v323_title(item: dict[str, Any]) -> str:
    return _wm_v322_clean_title(item.get("title")) if callable(globals().get("_wm_v322_clean_title")) else _text(item.get("title"), "")


def _wm_v323_has_any(text: str, terms: list[str]) -> bool:
    return any(t in text for t in terms)


def _wm_v323_region_anchor_score(item: dict[str, Any], region: str) -> int:
    region = _WM_V322_REGION_ALIASES.get(region, region)
    if region in {"Global", "Tout", "All", ""}:
        return 1
    # Deliberately do not include item['region']; this prevents the query label from self-validating.
    blob = _wm_v323_blob_title_source(item)
    terms = _wm_v321_region_terms(region) if callable(globals().get("_wm_v321_region_terms")) else [str(region).lower()]
    score = sum(1 for t in terms if t and t in blob)
    # Strong domain names can validate a region even when the headline is short.
    if region == "Europe" and any(x in blob for x in ["euvsdisinfo", "cepa", "consilium", "ecb", "brussels"]):
        score += 1
    if region == "Africa" and any(x in blob for x in ["african", "africa", "african union", "african arguments"]):
        score += 1
    if region == "Asia" and any(x in blob for x in ["the diplomat", "asia-pacific", "asian", "japan", "china", "india", "taiwan"]):
        score += 1
    if region == "Latin America" and any(x in blob for x in ["latin", "latam", "el país", "brazil", "mexico", "venezuela"]):
        score += 1
    if region == "Middle East" and any(x in blob for x in ["iran", "israel", "gaza", "gulf", "hormuz", "qatar", "oman"]):
        score += 1
    if region == "United States" and any(x in blob for x in ["u.s.", "us ", "united states", "washington", "federal reserve", "white house", "congress"]):
        score += 1
    return score


def _wm_v323_region_quality_ok(item: dict[str, Any], region: str) -> bool:
    region = _WM_V322_REGION_ALIASES.get(region, region)
    if region in {"Global", "Tout", "All", ""}:
        return True
    blob = _wm_v323_blob_title_source(item)
    score = _wm_v323_region_anchor_score(item, region)
    if score <= 0:
        return False
    # Prevent obvious off-theatre artefacts unless the correct theatre is also strongly anchored.
    for bad in _WM_V323_REGION_EXCLUDES.get(region, []):
        if bad in blob and score < 2:
            return False
    return True


def _wm_v323_topic_score(blob: str, tag: str) -> int:
    tag = str(tag or "NEWS").upper()
    if tag == "CYBER":
        return 3 if _wm_is_cyber_relevant_v211({"title": blob, "tag": tag}) else 0
    if tag == "AI":
        return sum(1 for t in _WM_V323_AI_TERMS if t in blob)
    if tag == "TECH":
        return sum(1 for t in _WM_V323_TECH_TERMS if t in blob)
    if tag == "DEV":
        return sum(1 for t in _WM_V323_DEV_TERMS if t in blob)
    if tag == "GEO":
        return sum(1 for t in _WM_V323_GEO_TERMS if t in blob)
    if tag == "NEWS":
        return sum(1 for t in (_WM_V323_GEO_TERMS + ["world", "breaking", "government"]) if t in blob)
    if tag == "ENERGY":
        return sum(1 for t in _WM_V323_ENERGY_TERMS if t in blob)
    if tag == "MARKETS":
        return sum(1 for t in _WM_V323_MARKET_TERMS if t in blob)
    if tag == "STARTUP":
        return sum(1 for t in _WM_V323_STARTUP_TERMS if t in blob)
    return 0


# Override V3.2.2 scoring with stricter topic terms.
def _wm_v321_tag_score(blob: str, tag: str) -> int:
    return _wm_v323_topic_score(str(blob or "").lower(), tag)


# Override V3.2.2 quality gate.
def _wm_v322_quality_ok(item: dict[str, Any], intended_tag: str | None = None, intended_region: str | None = None) -> bool:
    title = _wm_v323_title(item)
    if len(title) < 18:
        return False
    blob = _wm_v323_blob_title_source(item)
    if any(term in blob for term in _WM_V323_LOW_CONTEXT_TITLE_TERMS):
        return False
    if any(src in blob for src in _WM_V322_LOW_QUALITY_SOURCES):
        return False
    # Search operators can occasionally bleed into returned titles; reject these as artefacts.
    if "when:7d" in blob or "site:" in blob:
        return False
    if not _wm_v322_is_fresh(item.get("raw_pub") or item.get("age"), days=_WM_V323_STALE_DAYS):
        return False
    tag = str(intended_tag or item.get("topic_bucket") or item.get("tag") or "NEWS").upper()
    if tag == "MARKET":
        tag = "MARKETS"
    if tag == "CYBER" and not _wm_is_cyber_relevant_v211(item):
        return False
    if tag == "AI" and _wm_v323_topic_score(blob, "AI") <= 0:
        return False
    if tag == "TECH" and _wm_v323_topic_score(blob, "TECH") <= 0:
        return False
    if tag == "DEV" and _wm_v323_topic_score(blob, "DEV") <= 0:
        return False
    if tag == "ENERGY" and _wm_v323_topic_score(blob, "ENERGY") <= 0:
        return False
    if tag == "MARKETS" and _wm_v323_topic_score(blob, "MARKETS") <= 0:
        return False
    if tag == "STARTUP" and _wm_v323_topic_score(blob, "STARTUP") <= 0:
        return False
    if tag in {"GEO", "NEWS"} and _wm_v323_topic_score(blob, tag) <= 0:
        return False
    if intended_region and not _wm_v323_region_quality_ok(item, intended_region):
        return False
    return True


# Override region match: explicit query region is not enough; require title/source anchor.
def _wm_v321_item_region_match(item: dict[str, Any], region: str) -> bool:
    region = _WM_V322_REGION_ALIASES.get(region, region)
    if region in {"Global", "Tout", "All", ""}:
        return True
    return _wm_v323_region_quality_ok(item, region)


def _wm_v32_item_matches_region(item: dict[str, Any], region: str) -> bool:
    return _wm_v321_item_region_match(item, region)


# Override bucket router to avoid AI/Tech/Cyber cross-contamination.
def _wm_bucket_live_news(items: list[dict[str, Any]]) -> dict[str, list[dict[str, Any]]]:
    bucket_names = ["AI", "TECH", "CYBER", "STARTUP", "MARKETS", "DEV", "GEO", "NEWS", "ENERGY"]
    buckets: dict[str, list[dict[str, Any]]] = {k: [] for k in bucket_names}
    seen: set[str] = set()
    priority = ["CYBER", "ENERGY", "GEO", "STARTUP", "MARKETS", "DEV", "AI", "TECH", "NEWS"]
    for it in items or []:
        key = _wm_normalize_news_key_v211(it)
        if not key or key in seen:
            continue
        seen.add(key)
        blob = _wm_v323_blob_title_source(it)
        explicit = str(it.get("tag") or "NEWS").upper()
        if explicit == "MARKET":
            explicit = "MARKETS"
        bucket = "NEWS"
        if _wm_is_cyber_relevant_v211(it):
            bucket = "CYBER"
        elif _wm_v323_topic_score(blob, "AI") > 0 and explicit in {"AI", "TECH"}:
            bucket = "AI"
        elif _wm_v323_topic_score(blob, "DEV") > 0 and explicit in {"DEV", "AI", "TECH"}:
            bucket = "DEV"
        elif explicit in bucket_names and _wm_v323_topic_score(blob, explicit) > 0:
            bucket = explicit
        else:
            scored = [(tag, _wm_v323_topic_score(blob, tag)) for tag in bucket_names]
            bucket, score = max(scored, key=lambda x: (x[1], -priority.index(x[0])))
            if score <= 0:
                continue
        enriched = {**it, "tag": bucket if bucket != "MARKETS" else "MARKET", "topic_bucket": bucket, "region": it.get("region", _wm_v32_region_from_text(json.dumps(it, ensure_ascii=False, default=str)))}
        if not _wm_v322_quality_ok(enriched, bucket, str(enriched.get("region") or "Global")):
            continue
        buckets.setdefault(bucket, []).append(enriched)
        # NEWS is for strategic/news aggregation; do not copy cyber into it to reduce duplication.
        if bucket in {"GEO", "ENERGY"}:
            buckets.setdefault("NEWS", []).append(enriched)
    return buckets


# Override selector: strict region and quality; no cross-region fallback.
def _wm_v32_select_news(live_news: dict[str, list[dict[str, Any]]], families: list[str] | None = None, region: str = "Global", limit: int = 6) -> list[dict[str, Any]]:
    families = families or list(live_news.keys())
    region = _WM_V322_REGION_ALIASES.get(region, region)
    items: list[dict[str, Any]] = []
    seen: set[str] = set()
    for fam in families:
        fam_u = "MARKETS" if str(fam).upper() == "MARKET" else str(fam).upper()
        for item in live_news.get(fam, []) or []:
            if not _wm_v322_quality_ok(item, str(item.get("topic_bucket") or item.get("tag") or fam_u), str(item.get("region") or "Global")):
                continue
            if region != "Global" and not _wm_v321_item_region_match(item, region):
                continue
            k = _wm_normalize_news_key_v211(item)
            if not k or k in seen:
                continue
            seen.add(k)
            items.append(item)
            if len(items) >= limit:
                return items
    return items[:limit]


# Override source quality: no more automatic 100/100 when routing still has caveats.
def _wm_quality_metrics_v211(country: str, live_news: dict[str, list[dict[str, Any]]]) -> dict[str, Any]:
    flat: list[dict[str, Any]] = []
    seen: set[str] = set()
    for bucket, vals in (live_news or {}).items():
        for x in vals or []:
            k = _wm_normalize_news_key_v211(x)
            if k and k not in seen:
                seen.add(k)
                flat.append({**x, "_bucket": bucket})
    total = len(flat)
    if total <= 0:
        return {"total": 0, "country_hits": 0, "country_score": 0, "source_diversity": 0, "quality": 38, "status": "LOCAL FALLBACK", "top_sources": []}
    sources = [_text(x.get("source"), "source") for x in flat]
    unique_sources = len(set(sources))
    country_hits = sum(1 for x in flat if _wm_country_keyword_score_v211(x, country) > 0)
    country_score = 0 if country == "Global" else int(min(100, round(100 * country_hits / max(1, total))))
    google_ratio = sum(1 for s in sources if "google news" in s.lower()) / max(1, total)
    regional_items = [x for x in flat if _text(x.get("region"), "Global") not in {"Global", ""}]
    regional_anchor_ratio = sum(1 for x in regional_items if _wm_v323_region_anchor_score(x, _text(x.get("region"), "Global")) > 0) / max(1, len(regional_items))
    topic_ok = sum(1 for x in flat if _wm_v323_topic_score(_wm_v323_blob_title_source(x), str(x.get("topic_bucket") or x.get("tag") or "NEWS")) > 0) / max(1, total)
    freshness_ok = sum(1 for x in flat if _wm_v322_is_fresh(x.get("raw_pub") or x.get("age"), days=_WM_V323_STALE_DAYS)) / max(1, total)
    diversity_score = min(100, unique_sources * 8)
    quality = int(round(32 + min(22, total * 0.45) + diversity_score * 0.22 + 18 * topic_ok + 14 * freshness_ok + 10 * regional_anchor_ratio))
    if country == "Global" and country_hits == 0:
        quality = min(quality, 88)
    if google_ratio > 0.85:
        quality = min(quality, 86)
    if regional_anchor_ratio < 0.55 and regional_items:
        quality = min(quality, 78)
    quality = int(max(35, min(96, quality)))
    top_sources = []
    for s in sorted(set(sources), key=lambda z: (-sources.count(z), z))[:5]:
        top_sources.append({"source": s, "items": sources.count(s)})
    status = "HIGH" if quality >= 78 else ("WATCH" if quality >= 58 else "THIN")
    return {"total": total, "country_hits": country_hits, "country_score": country_score, "source_diversity": unique_sources, "quality": quality, "status": status, "top_sources": top_sources, "google_ratio": round(google_ratio, 2), "regional_anchor_ratio": round(regional_anchor_ratio, 2), "topic_ok": round(topic_ok, 2)}


_WM_V323_PREV_DASHBOARD_HTML = _wm_v32_dashboard_html

def _wm_v32_dashboard_html(payload: dict[str, Any], visible_ids: list[str], style: str, country: str, live_news: dict[str, list[dict[str, Any]]], quote_rows: list[dict[str, Any]], signal_context: dict[str, Any] | None = None, source_registry: list[dict[str, Any]] | None = None) -> str:
    html_payload = _WM_V323_PREV_DASHBOARD_HTML(payload, visible_ids, style, country, live_news, quote_rows, signal_context=signal_context, source_registry=source_registry)
    html_payload = re.sub(r"Value\+ Intelligence V3(?:\.\d+)+(?:\.1)?", "Value+ Intelligence V3.2.3", html_payload)
    html_payload = html_payload.replace("Source Quality", "Source Relevance")
    return html_payload


