    html_payload = re.sub(r"LIVE · V(?:2\.11\.9|3\.2\.1|3\.2\.2)(?:\.1)?", "LIVE · V3.2.3", html_payload)
    html_payload = re.sub(r"(LAYER STATUS\s*·\s*)+LAYER STATUS", "LAYER STATUS", html_payload)
    return html_payload


