def _wm38_panel_escape(value: Any) -> str:
    try:
        return html.escape(_text(value, ""), quote=True)
    except Exception:
        return html.escape(str(value or ""), quote=True)


def _wm38_panel_json(value: Any) -> str:
    return json.dumps(value, ensure_ascii=False, default=str).replace("</", "<\\/")


def _wm38_num(value: Any, default: float = 0.0) -> float:
    try:
        x = float(value)
        return x if math.isfinite(x) else default
    except Exception:
        return default


def _wm38_safe_int(value: Any, default: int = 0) -> int:
    try:
        return int(round(float(value)))
    except Exception:
        return int(default)


def _wm38_delta_class(value: Any) -> str:
    try:
        return "up" if float(value) >= 0 else "down"
    except Exception:
        s = str(value or "").lower()
        if any(x in s for x in ["crit", "alert", "war", "red", "severe", "high"]):
            return "down"
        if any(x in s for x in ["ok", "norm", "stable", "green", "low"]):
            return "up"
        return "flat"


def _wm38_family(panel_id: str, category: str = "") -> str:
    pid = str(panel_id or "")
    cat = str(category or "")
    if pid in {"country_intel", "strategic_risk", "country_instability", "threat_timeline", "ai_posture", "alert_engine", "signal_drivers", "cross_source", "intel_flow", "live_intel", "ai_forecasts", "force_posture", "escalation_monitor", "economic_warfare", "disaster_cascade", "webcams"}:
        return "Risk / Intelligence"
    if pid in {"markets", "crypto", "economic", "finance", "central_bank_watch", "financial_stress", "fixed_income", "yield_curve", "stablecoins", "commodities", "energy_complex", "daily_market_brief", "stock_analysis", "backtesting", "wm_analyst", "trade_policy"}:
        return "Markets / Macro"
    if pid in {"ai_insights", "ai_ml", "technology", "cybersecurity", "github_trends", "tech_events", "tech_maturity", "vc_financing", "funding_vc", "startups_vc", "policy_ai", "product_hunt", "ipo_spac", "internet_disruptions", "service_status"}:
        return "AI / Tech"
    if pid in {"infra_cascade", "energy_resources", "supply_chain", "flight_intel", "climate_anomalies", "world_clock", "market_radar", "oil_inventory", "pipeline_status", "strategic_storage", "global_fuel_shortage"}:
        return "Infrastructure / Ops"
    if pid.startswith("region_") or pid in {"world_news", "live_news", "government", "think_tanks", "good_news", "breakthroughs", "renewable_energy"}:
        return "News / Regions"
    if "Finance" in cat or "March" in cat:
        return "Markets / Macro"
    if "Tech" in cat or "Technologie" in cat:
        return "AI / Tech"
    if "Renseignement" in cat or "Principal" in cat:
        return "Risk / Intelligence"
    return "Workspace"


def _wm38_family_style(family: str) -> dict[str, str]:
    f = str(family or "")
    styles = {
        "Risk / Intelligence": {"accent": "#ff4d5c", "soft": "rgba(255,77,92,.16)", "mid": "#ff8a00", "icon": "◆"},
        "Markets / Macro": {"accent": "#35e986", "soft": "rgba(53,233,134,.13)", "mid": "#38bdf8", "icon": "$"},
        "AI / Tech": {"accent": "#7dd3fc", "soft": "rgba(125,211,252,.14)", "mid": "#a78bfa", "icon": "✦"},
        "Infrastructure / Ops": {"accent": "#fbbf24", "soft": "rgba(251,191,36,.14)", "mid": "#22d3ee", "icon": "⚙"},
        "News / Regions": {"accent": "#60a5fa", "soft": "rgba(96,165,250,.13)", "mid": "#f97316", "icon": "●"},
        "Workspace": {"accent": "#94a3b8", "soft": "rgba(148,163,184,.12)", "mid": "#38bdf8", "icon": "□"},
    }
    return styles.get(f, styles["Workspace"])




# === WM211 DIRECT LIVE FIRST V4.0.2 HELPERS START ===
# Minimal ordering only. This intentionally does NOT add focus navigation,
# global filtering, or V4.1 size overrides. It restores the V4.0.1 dashboard
# ergonomics while placing direct/live panels at the top.
_WM402_LIVE_FIRST_IDS = ["live_news", "webcams"]
_WM402_ALWAYS_OPEN_IDS = {"live_news", "webcams"}


def _wm402_order_panel_ids(ids: list[str]) -> list[str]:
    seen: set[str] = set()
    clean: list[str] = []
    for pid in list(ids or []):
        spid = str(pid)
        if spid and spid not in seen:
            seen.add(spid)
            clean.append(spid)
    priority = {pid: i for i, pid in enumerate(_WM402_LIVE_FIRST_IDS)}
    return sorted(clean, key=lambda x: (priority.get(x, 10000), clean.index(x)))
# === WM211 DIRECT LIVE FIRST V4.0.2 HELPERS END ===




