def _wm403_blob(item: dict[str, Any]) -> str:
    return " ".join(str(item.get(k, "")) for k in ["title", "source", "provider", "region", "country", "tag", "category", "topic_bucket"]).lower()


def _wm403_first_matching(items: list[dict[str, Any]], keys: list[str], limit: int = 8) -> list[dict[str, Any]]:
    scored: list[tuple[int, int, dict[str, Any]]] = []
    seen: set[str] = set()
    for idx, it in enumerate(items or []):
        if not isinstance(it, dict):
            continue
        blob = _wm403_blob(it)
        score = sum(1 for k in keys if str(k).lower() in blob)
        if score <= 0:
            continue
        title_key = str(it.get("url") or it.get("title") or it.get("name") or idx)
        if title_key in seen:
            continue
        seen.add(title_key)
        scored.append((score, -idx, it))
    return [x[2] for x in sorted(scored, key=lambda x: (x[0], x[1]), reverse=True)[:int(limit)]]


def _wm403_nonempty_or_fallback(pid: str, rows: list[dict[str, Any]], items: list[dict[str, Any]], soft_keys: list[str] | None = None, limit: int = 8) -> list[dict[str, Any]]:
    if rows:
        return rows[:int(limit)]
    if soft_keys:
        soft = _wm403_first_matching(items, soft_keys, limit)
        if soft:
            return soft
    fallback = _wm403_provider_ready_fallback(pid)
    if fallback:
        return fallback
    return (items or [])[:int(limit)]
