def _wm38_panel_title(panel_id: str) -> str:
    try:
        titles = globals().get("_WM_PANEL_TITLES", {})
        if isinstance(titles, dict) and panel_id in titles:
            return str(titles.get(panel_id) or panel_id)
    except Exception:
        pass
    return str(panel_id or "").replace("_", " ").title()


def _wm38_panel_catalog(visible_ids: list[str]) -> list[dict[str, Any]]:
    raw_catalog = globals().get("_WM_V32_PANEL_CATALOG", [])
    catalog_by_id = {}
    if isinstance(raw_catalog, list):
        for p in raw_catalog:
            if isinstance(p, dict) and p.get("id"):
                catalog_by_id[str(p["id"])] = dict(p)

    ids: list[str] = []
    for pid in list(visible_ids or []):
        if pid not in ids:
            ids.append(str(pid))
    for pid, meta in catalog_by_id.items():
        if bool(meta.get("default")) and pid not in ids:
            ids.append(pid)
    for pid, meta in catalog_by_id.items():
        if pid not in ids:
            ids.append(pid)

    ids = _wm402_order_panel_ids(ids) if '_wm402_order_panel_ids' in globals() else ids

    out: list[dict[str, Any]] = []
    for idx, pid in enumerate(ids):
        meta = dict(catalog_by_id.get(pid, {"id": pid, "title": _wm38_panel_title(pid), "status": "READY", "default": False, "size": "medium"}))
        family = _wm38_family(pid, str(meta.get("category", "")))
        style = _wm38_family_style(family)
        status = str(meta.get("status", "READY") or "READY").upper()
        locked = status in {"PRO", "LOCKED"} or bool(meta.get("locked"))
        size = str(meta.get("size", "medium") or "medium")
        meta.update({
            "id": pid,
            "title": str(meta.get("title") or _wm38_panel_title(pid)),
            "family": family,
            "accent": style["accent"],
            "soft": style["soft"],
            "mid": style["mid"],
            "icon": style["icon"],
            "locked": locked,
            "status": status,
            "size": size,
            "default_open": bool(pid in visible_ids or meta.get("default") or ("_WM402_ALWAYS_OPEN_IDS" in globals() and pid in _WM402_ALWAYS_OPEN_IDS)),
            "order": idx,
        })
        out.append(meta)
    return out


def _wm38_flat_news(live_news: Any) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    if isinstance(live_news, dict):
        for _, vals in live_news.items():
            if isinstance(vals, list):
                rows.extend([x for x in vals if isinstance(x, dict)])
    elif isinstance(live_news, list):
        rows = [x for x in live_news if isinstance(x, dict)]
    seen: set[str] = set()
    clean: list[dict[str, Any]] = []
    for item in rows:
        key = str(item.get("url") or item.get("title") or item.get("name") or len(clean))
        if key in seen:
            continue
        seen.add(key)
        clean.append(item)
    return clean



