def _wm38_source_label(item: Any) -> str:
    if isinstance(item, dict):
        src = _text(item.get("source"), _text(item.get("provider"), "SOURCE"))
        tag = _text(item.get("tag"), _text(item.get("topic_bucket"), _text(item.get("category"), "")))
        return (src + (" · " + tag if tag else "")).strip()
    if isinstance(item, str):
        return "WorldMonitor · TEXT"
    return "WorldMonitor · ITEM"


def _wm38_news_cards(items: Any, limit: int = 6, compact: bool = False) -> str:
    # V4.0 direct/live hotfix: some direct panels return a ready HTML fragment.
    # Do not iterate over a string as if it were a list of news dictionaries.
    if isinstance(items, str):
        return items
    if items is None:
        return '<div class="wm38-empty">Aucune donnée disponible pour ce panneau. Provider/live feed prêt.</div>'
    try:
        if isinstance(items, pd.DataFrame):
            raw_items = items.to_dict("records")
        elif isinstance(items, dict):
            raw_items = [items]
        elif isinstance(items, (list, tuple, set)):
            raw_items = list(items)
        else:
            raw_items = []
    except Exception:
        raw_items = []
    if not raw_items:
        return '<div class="wm38-empty">Aucune donnée disponible pour ce panneau. Provider/live feed prêt.</div>'

    out: list[str] = []
    for raw in raw_items[: int(limit)]:
        if isinstance(raw, dict):
            item = raw
        elif isinstance(raw, str):
            item = {"title": raw, "source": "WorldMonitor", "tag": "TEXT", "age": ""}
        else:
            item = {"title": _text(raw, "Untitled signal"), "source": "WorldMonitor", "tag": "ITEM", "age": ""}
        title = _text(item.get("title"), _text(item.get("name"), "Untitled signal"))
        src = _wm38_source_label(item)
        age = _text(item.get("published"), _text(item.get("published_at"), _text(item.get("date"), _text(item.get("time"), _text(item.get("age"), "")))))
        url = _text(item.get("url"), _text(item.get("link"), _text(item.get("source_url"), "")))
        tag = src.split("·")[-1].strip().upper() if "·" in src else ""
        href = f'<a class="wm38-open" target="_blank" href="{_wm38_panel_escape(url)}">↗</a>' if url.startswith(("http://", "https://")) else '<span class="wm38-open muted">·</span>'
        out.append(
            '<div class="wm38-item">'
            f'<div class="wm38-src"><span>{_wm38_panel_escape(src)}</span>{f"<b>{_wm38_panel_escape(tag)}</b>" if tag else ""}{href}</div>'
            f'<div class="wm38-title">{_wm38_panel_escape(title)}</div>'
            f'<div class="wm38-age">{_wm38_panel_escape(age)}</div>'
            '</div>'
        )
    return "".join(out)


def _wm38_metric_grid(metrics: list[dict[str, Any]]) -> str:
    if not metrics:
        return '<div class="wm38-empty">Aucune métrique.</div>'
    cards = []
    for m in metrics[:8]:
        delta = m.get("delta", m.get("status", ""))
        cards.append(
            '<div class="wm38-metric">'
            f'<small>{_wm38_panel_escape(m.get("label", m.get("name", "metric")))}</small>'
            f'<b>{_wm38_panel_escape(m.get("value", "-"))}</b>'
            f'<span class="{_wm38_delta_class(delta)}">{_wm38_panel_escape(delta)}</span>'
            '</div>'
        )
    return '<div class="wm38-metrics">' + "".join(cards) + '</div>'


def _wm38_bar_row(label: str, value: Any, delta: Any = "", detail: str = "", color_class: str = "") -> str:
    val = max(0.0, min(100.0, _wm38_num(value, 0.0)))
    cls = color_class or ("crit" if val >= 75 else ("warn" if val >= 50 else "ok"))
    return (
        '<div class="wm38-bar-row">'
        f'<div class="wm38-bar-head"><b>{_wm38_panel_escape(label)}</b><span>{val:.0f}/100 {_wm38_panel_escape(delta)}</span></div>'
        f'<div class="wm38-bar-track"><i class="{cls}" style="width:{val:.0f}%"></i></div>'
        f'<small>{_wm38_panel_escape(detail)}</small>'
        '</div>'
    )


