def _wm38_render_country_intel(payload: dict[str, Any], ctx: dict[str, Any], display_style: str, country: str) -> str:
    ci = ((payload.get("value_plus", {}) or {}).get("country_intel", {}) or {}) if isinstance(payload, dict) else {}
    sectors = ["AI infrastructure", "cyber", "markets", "energy", "supply chains"]
    risks = ["geopolitical escalation", "cyber disruption", "rates / liquidity", "critical infrastructure"]
    links = ["AAPL", "MSFT", "NVDA", "AVGO", "BTC"]
    quality = ((payload.get("value_plus", {}) or {}).get("quality", {}) or {})
    q = _wm38_safe_int(quality.get("quality", quality.get("score", 84)), 84)
    title_country = _text(ci.get("country"), country or "Global") if isinstance(ci, dict) else country
    regime = _text(ci.get("regime"), "Watch") if isinstance(ci, dict) else "Watch"
    return (
        '<div class="wm38-context-card">'
        f'<div class="wm38-context-main"><b>{_wm38_panel_escape(title_country)}</b><span>{_wm38_panel_escape(display_style)} · regime { _wm38_panel_escape(regime) }</span></div>'
        f'<div class="wm38-quality"><b>{q}/100</b><small>source quality</small></div>'
        '</div>'
        '<div class="wm38-chip-block"><label>KEY SECTORS</label>' + "".join(f'<span>{_wm38_panel_escape(x)}</span>' for x in sectors) + '</div>'
        '<div class="wm38-chip-block"><label>MARKET LINKS</label>' + "".join(f'<span>{_wm38_panel_escape(x)}</span>' for x in links) + '</div>'
        '<div class="wm38-risk-list"><label>MAIN RISKS</label>' + "".join(f'<p>• {_wm38_panel_escape(x)}</p>' for x in risks) + '</div>'
    )


def _wm38_render_alerts(payload: dict[str, Any]) -> str:
    alerts = ((payload.get("value_plus", {}) or {}).get("alerts", []) or []) if isinstance(payload, dict) else []
    if not isinstance(alerts, list) or not alerts:
        alerts = [
            {"label": "WATCH", "confidence": 94, "title": "Global cyber stress elevated", "impact": "Critical infrastructure, cloud, financial systems"},
            {"label": "MOMENTUM", "confidence": 92, "title": "AI infrastructure momentum cluster", "impact": "AI capex, semiconductors, data centers, power demand"},
        ]
    out = []
    for a in alerts[:5]:
        conf = _wm38_safe_int(a.get("confidence", a.get("score", 80)), 80)
        label = _text(a.get("label"), _text(a.get("type"), "WATCH")).upper()
        out.append(
            '<div class="wm38-alert-card">'
            f'<div><span class="wm38-tag danger">{_wm38_panel_escape(label)}</span><b>{conf}%</b></div>'
            f'<h4>{_wm38_panel_escape(a.get("title", "Signal"))}</h4>'
            f'<p>{_wm38_panel_escape(a.get("impact", a.get("driver", "")))}</p>'
            '</div>'
        )
    return "".join(out)


def _wm38_render_drivers(payload: dict[str, Any]) -> str:
    drivers = ((payload.get("value_plus", {}) or {}).get("drivers", []) or []) if isinstance(payload, dict) else []
    if not isinstance(drivers, list) or not drivers:
        drivers = [
            {"metric": "GLOBAL RISK", "score": 48, "driver": "Blend pondéré de market stress, cyber, geo heat, tech momentum."},
            {"metric": "CYBER", "score": 72, "driver": "Articles cyber strictement routés; mots-clés forts requis."},
            {"metric": "MARKET", "score": 34, "driver": "Mouvement moyen actions pays et VIX."},
            {"metric": "TECH MOMENTUM", "score": 92, "driver": "Articles AI/tech + startup/VC."},
        ]
    html_rows = []
    for d in drivers[:6]:
        name = _text(d.get("metric"), _text(d.get("label"), _text(d.get("name"), "Signal")))
        score = d.get("score", d.get("value", 50))
