def _wm38_render_source_quality(payload: dict[str, Any], live_news: Any, source_registry: list[dict[str, Any]]) -> str:
    quality = ((payload.get("value_plus", {}) or {}).get("quality", {}) or {}) if isinstance(payload, dict) else {}
    items = len(_wm38_flat_news(live_news))
    sources = len(source_registry or [])
    q = _wm38_safe_int(quality.get("quality", quality.get("score", 84)), 84)
    top_sources = quality.get("top_sources", []) if isinstance(quality, dict) else []
    metrics = [
        {"label": "QUALITY", "value": f"{q}/100", "delta": "HIGH" if q >= 75 else "WATCH"},
        {"label": "LIVE ITEMS", "value": items, "delta": "routed"},
        {"label": "SOURCES", "value": sources, "delta": "diversity"},
        {"label": "COUNTRY HITS", "value": quality.get("country_hits", 0) if isinstance(quality, dict) else 0, "delta": "hits"},
    ]
    out = _wm38_metric_grid(metrics)
    if isinstance(top_sources, list) and top_sources:
        out += '<div class="wm38-source-mini">' + "".join(f'<span>{_wm38_panel_escape(s.get("source", "source"))} · {_wm38_panel_escape(s.get("items", ""))}</span>' for s in top_sources[:5] if isinstance(s, dict)) + '</div>'
    return out


def _wm38_render_timeline(live_news: Any, ctx: dict[str, Any]) -> str:
    items = _wm38_flat_news(live_news)[:8]
    critical = max(1, min(9, len([x for x in items if any(k in str(x).lower() for k in ["war", "attack", "critical", "cyber", "ransom"])])))
    high = max(1, min(9, len(items) - critical + 1))
    bars = [
        ("Critical", 72, "crit"),
        ("High", 82, "warn"),
        ("Medium", 44, "med"),
        ("Low", 35, "ok"),
    ]
    top = (
        '<div class="wm38-timeline-top">'
        f'<div><b>{critical}</b><span>Critical/high</span></div>'
        f'<div><b>{max(1, len(items)//4)}</b><span>Active days</span></div>'
        f'<div><b>{"Worsening" if critical >= 2 else "Watch"}</b><span>{critical} recent vs 0 earlier</span></div>'
        '</div>'
    )
    return top + "".join(_wm38_bar_row(name, val, detail="", color_class=cls) for name, val, cls in bars) + _wm38_news_cards(items[:4], 4)


