def _wm38_render_markets(panel_id: str, quote_rows: list[dict[str, Any]], payload: dict[str, Any]) -> str:
    rows: list[dict[str, Any]] = []
    if panel_id in {"markets", "finance"} and quote_rows:
        rows = quote_rows[:8]
    else:
        pdata = (payload.get("panels", {}) or {}).get(panel_id, {}) if isinstance(payload, dict) else {}
        if isinstance(pdata, dict):
            rows = list(pdata.get("rows", []) or [])[:8]
    if not rows:
        defaults = [
            {"symbol": "AAPL", "display": "Apple", "price": 308.67, "change": 4.85},
            {"symbol": "AMZN", "display": "Amazon", "price": 242.71, "change": 0.42},
            {"symbol": "AVGO", "display": "Broadcom", "price": 360.49, "change": -2.40},
        ]
        rows = defaults if panel_id in {"markets", "finance"} else []
    if panel_id == "crypto" and not rows:
        rows = [
            {"symbol": "BTC", "display": "Bitcoin", "price": 62009, "change": 0.97},
            {"symbol": "ETH", "display": "Ethereum", "price": 1732.82, "change": 2.37},
            {"symbol": "BNB", "display": "BNB", "price": 565.42, "change": 0.78},
        ]
    if not rows:
        return '<div class="wm38-empty">Marchés prêts. Aucun quote/live row disponible.</div>'
    out = []
    for r in rows[:8]:
        sym = _text(r.get("symbol"), _text(r.get("ticker"), _text(r.get("name"), "N/A")))
        name = _text(r.get("display"), _text(r.get("name"), sym))
        px = r.get("price", r.get("last", r.get("value", "-")))
        chg = r.get("change", r.get("pct_change", r.get("delta", "")))
        cls = _wm38_delta_class(chg)
        try:
            chg_txt = f"{float(chg):+.2f}%"
        except Exception:
            chg_txt = str(chg or "")
        try:
            px_txt = f"{float(px):,.2f}" if abs(float(px)) < 10000 else f"{float(px):,.0f}"
        except Exception:
            px_txt = str(px)
        out.append(
            '<div class="wm38-market-row">'
            f'<div><b>{_wm38_panel_escape(name)}</b><small>{_wm38_panel_escape(sym)}</small></div>'
            '<div class="wm38-spark"><i></i></div>'
            f'<strong>${_wm38_panel_escape(px_txt)}</strong>'
            f'<span class="{cls}">{_wm38_panel_escape(chg_txt)}</span>'
            '</div>'
        )
    return "".join(out)


