def _wm40_render_direct_news(live_news: Any) -> str:
    channels = _wm40_direct_news_channels()
    first = channels[0]
    tabs = []
    for i, ch in enumerate(channels):
        src = _wm40_youtube_live_embed(ch["channel"])
        tabs.append(f'<button class="wm40-live-tab {"on" if i == 0 else ""}" data-src="{src}" data-provider="{_wm38_panel_escape(ch["id"])}">{_wm38_panel_escape(ch["label"])}</button>')
    fallback_items = _wm38_news_cards(_wm38_news_for_panel("world_news", live_news, "Global"), limit=4)
    return (
        '<div class="wm40-live wm40-news-direct">'
        '<div class="wm40-direct-top"><b>● DIRECT</b><span>Provider video stream · fallback articles below</span><button data-wm40-reload>LIVE now</button></div>'
        '<div class="wm40-live-tabs">' + ''.join(tabs) + '</div>'
        f'<div class="wm40-live-player"><iframe src="{_wm40_youtube_live_embed(first["channel"])}" loading="lazy" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div>'
        '<details class="wm40-live-fallback"><summary>Articles live / fallback source feed</summary>' + fallback_items + '</details>'
        '</div>'
    )


def _wm40_render_webcams() -> str:
    tiles = _wm40_webcam_tiles()
    out = []
    for tile in tiles:
        if tile.get("video"):
            src = _wm40_youtube_video_embed(tile["video"])
        elif tile.get("channel"):
            src = _wm40_youtube_live_embed(tile["channel"])
        else:
            src = ""
        frame = f'<iframe src="{src}" loading="lazy" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>' if src else '<div class="wm40-noembed">Embed unavailable</div>'
        href = _wm38_panel_escape(tile.get("href", ""))
        out.append(
            '<div class="wm40-webcam-tile">'
            f'<div class="wm40-tile-head"><span>● {_wm38_panel_escape(tile.get("label"))}</span><b>{_wm38_panel_escape(tile.get("region"))}</b></div>'
            + frame +
            f'<a target="_blank" href="{href}">ouvrir le direct ↗</a>'
            '</div>'
        )
    return '<div class="wm40-webcams"><div class="wm40-direct-top"><b>● WEBCAMS / LIVE</b><span>Embeds publics + fallback externe</span><button data-wm40-reload>refresh</button></div><div class="wm40-webcam-grid">' + ''.join(out) + '</div></div>'


