# === WM211 INSTITUTIONAL PANEL INTELLIGENCE V4.0.4 HELPERS START ===
# These helpers make the panels decision-oriented without pretending that
# provider-ready/fallback rows are real-time institutional data.
def _wm404_lower(value: Any) -> str:
    try:
        return str(value or "").lower()
    except Exception:
        return ""


def _wm404_item_blob(item: dict[str, Any]) -> str:
    if not isinstance(item, dict):
        return _wm404_lower(item)
    keys = ["title", "name", "source", "provider", "tag", "category", "topic_bucket", "region", "country", "summary", "description", "url"]
    return " ".join(_wm404_lower(item.get(k, "")) for k in keys)


def _wm404_classify_topic(item: dict[str, Any]) -> str:
    blob = _wm404_item_blob(item)
    rules = [
        ("cyber", ["cyber", "cisa", "ransom", "malware", "vulnerability", "exploit", "breach", "kev", "cve"]),
        ("geo", ["war", "conflict", "military", "missile", "drone", "iran", "taiwan", "ukraine", "gaza", "red sea"]),
        ("energy", ["oil", "gas", "lng", "energy", "hormuz", "brent", "natgas", "storage", "pipeline"]),
        ("market", ["market", "stock", "bond", "rate", "fed", "ecb", "inflation", "earnings", "treasury"]),
        ("ai", ["ai", "artificial intelligence", "semiconductor", "chip", "datacenter", "cloud", "llm", "model"]),
        ("supply", ["shipping", "supply", "port", "suez", "freight", "logistics", "convoy", "insurance"]),
        ("policy", ["government", "treasury", "state department", "white house", "sanction", "export control", "regulation", "law"]),
        ("disaster", ["earthquake", "flood", "storm", "heat", "wildfire", "reliefweb", "gdacs", "eonet"]),
    ]
    for topic, words in rules:
        if any(w in blob for w in words):
            return topic
    return "news"


def _wm404_topic_score(item: dict[str, Any]) -> int:
    topic = _wm404_classify_topic(item)
    blob = _wm404_item_blob(item)
    base = {"cyber": 72, "geo": 76, "energy": 68, "market": 58, "ai": 62, "supply": 65, "policy": 55, "disaster": 67}.get(topic, 45)
    if any(x in blob for x in ["critical", "crisis", "attack", "exploit", "war", "dead", "surge", "emergency"]):
        base += 12
    if any(x in blob for x in ["watch", "warning", "risk", "threat", "pressure", "disruption"]):
        base += 7
    if any(x in blob for x in ["provider-ready", "fallback", "ready"]):
        base = min(base, 35)
    return int(max(0, min(100, base)))


def _wm404_is_fallback_item(item: dict[str, Any]) -> bool:
    blob = _wm404_item_blob(item)
    return any(x in blob for x in ["provider-ready", "fallback", "route ready", "connect ", "no source", "aucune donnée"])


def _wm404_source_name(item: dict[str, Any]) -> str:
    if not isinstance(item, dict):
        return "WorldMonitor"
    return _text(item.get("source"), _text(item.get("provider"), "WorldMonitor"))


def _wm404_dedupe_diversify(items: list[dict[str, Any]], limit: int = 6, max_per_source: int = 2, max_per_topic: int = 3) -> list[dict[str, Any]]:
    if not isinstance(items, list):
        return []
    cleaned: list[dict[str, Any]] = []
    seen: set[str] = set()
    source_counts: dict[str, int] = {}
    topic_counts: dict[str, int] = {}
    scored: list[tuple[int, int, dict[str, Any]]] = []
    for idx, it in enumerate(items):
        if not isinstance(it, dict):
            continue
        key = str(it.get("url") or it.get("link") or it.get("title") or it.get("name") or idx).strip()
        if not key or key in seen:
            continue
        seen.add(key)
        scored.append((_wm404_topic_score(it), -idx, it))
    for _, _, it in sorted(scored, key=lambda x: (x[0], x[1]), reverse=True):
        src = _wm404_source_name(it).lower()[:60]
        topic = _wm404_classify_topic(it)
        if source_counts.get(src, 0) >= int(max_per_source):
            continue
        if topic_counts.get(topic, 0) >= int(max_per_topic):
            continue
        source_counts[src] = source_counts.get(src, 0) + 1
        topic_counts[topic] = topic_counts.get(topic, 0) + 1
        cleaned.append(it)
        if len(cleaned) >= int(limit):
            break
    if len(cleaned) < int(limit):
        for _, _, it in sorted(scored, key=lambda x: (x[0], x[1]), reverse=True):
            if it not in cleaned:
                cleaned.append(it)
            if len(cleaned) >= int(limit):
                break
    return cleaned[:int(limit)]


def _wm404_panel_state(panel_id: str, items: list[dict[str, Any]] | None = None, provider_ready: bool = False) -> dict[str, Any]:
    items = [x for x in (items or []) if isinstance(x, dict)]
    fallback_count = sum(1 for x in items if _wm404_is_fallback_item(x))
    real_count = max(0, len(items) - fallback_count)
    if provider_ready or (items and fallback_count == len(items)):
        status = "PROVIDER"
        conf = 42
    elif real_count > 0:
        status = "LIVE"
        conf = min(92, 58 + real_count * 5)
    else:
        status = "EMPTY"
        conf = 20
    return {"status": status, "real_count": real_count, "fallback_count": fallback_count, "confidence": conf, "freshness": "cache/live" if real_count else "provider-ready"}


def _wm404_state_strip(panel_id: str, items: list[dict[str, Any]] | None = None, provider_ready: bool = False, note: str = "") -> str:
    stt = _wm404_panel_state(panel_id, items, provider_ready)
    cls = "ok" if stt["status"] == "LIVE" else ("warn" if stt["status"] == "PROVIDER" else "crit")
    return (
        '<div class="wm404-state-strip">'
        f'<span class="{cls}">{_wm38_panel_escape(stt["status"])}</span>'
        f'<b>{int(stt["confidence"])}%</b><small>confidence</small>'
        f'<b>{int(stt["real_count"])} / {int(stt["fallback_count"])} </b><small>real/fallback</small>'
        f'<em>{_wm38_panel_escape(note or stt["freshness"])}</em>'
        '</div>'
    )


def _wm404_drilldown(items: list[dict[str, Any]], limit: int = 4) -> str:
    rows = []
    for it in (items or [])[:int(limit)]:
        if not isinstance(it, dict):
            continue
        title = _text(it.get("title"), _text(it.get("name"), "signal"))
        src = _wm404_source_name(it)
        topic = _wm404_classify_topic(it).upper()
        age = _text(it.get("published"), _text(it.get("published_at"), _text(it.get("date"), _text(it.get("age"), ""))))
        score = _wm404_topic_score(it)
        rows.append({"source": src[:34], "topic": topic, "score": score, "time": age[:24], "title": title[:86]})
    if not rows:
        return '<details class="wm404-drill"><summary>Source drilldown</summary><div class="wm38-empty">Aucune source détaillable.</div></details>'
    return '<details class="wm404-drill"><summary>Source drilldown</summary>' + _wm38_rows_table(rows, limit=limit) + '</details>'


def _wm404_news_panel(panel_id: str, live_news: Any, country: str = "Global", limit: int = 5, note: str = "") -> str:
    raw = _wm38_news_for_panel(panel_id, live_news, country)
    items = _wm404_dedupe_diversify(raw, limit=limit, max_per_source=2, max_per_topic=2)
    provider_ready = bool(items and all(_wm404_is_fallback_item(x) for x in items if isinstance(x, dict)))
    topics: dict[str, int] = {}
    for it in items:
        t = _wm404_classify_topic(it)
        topics[t] = topics.get(t, 0) + 1
    topic_line = " · ".join(f"{k}:{v}" for k, v in sorted(topics.items(), key=lambda x: x[0])) or "no classified topics"
    return _wm404_state_strip(panel_id, items, provider_ready, note or topic_line) + _wm38_news_cards(items, limit=limit) + _wm404_drilldown(items, limit=min(5, limit))


def _wm404_provider_note(name: str, provider: str, fields: str) -> str:
    return (
        '<div class="wm404-provider-note">'
        f'<b>{_wm38_panel_escape(name)}</b><span>Provider cible</span><em>{_wm38_panel_escape(provider)}</em>'
        f'<small>{_wm38_panel_escape(fields)}</small>'
        '</div>'
    )


def _wm404_waterfall(rows: list[tuple[str, int, str]], title: str = "Score decomposition") -> str:
    total = max(0, min(100, sum(max(0, min(100, int(v))) for _, v, _ in rows)))
    scale = total or 1
    parts = [f'<div class="wm404-waterfall"><h4>{_wm38_panel_escape(title)} <b>{min(100,total)}/100</b></h4>']
    for label, value, detail in rows:
        v = max(0, min(100, int(value)))
        cls = "crit" if v >= 25 else ("warn" if v >= 12 else "ok")
        parts.append(
            '<div class="wm404-wf-row">'
            f'<span>{_wm38_panel_escape(label)}</span><i><u class="{cls}" style="width:{min(100, round(v / scale * 100))}%"></u></i>'
            f'<b>{v}</b><small>{_wm38_panel_escape(detail)}</small>'
            '</div>'
        )
    parts.append('</div>')
    return ''.join(parts)


def _wm404_next_watch(rows: list[str]) -> str:
    if not rows:
        return ""
    return '<div class="wm404-next"><b>Next watch</b>' + ''.join(f'<span>{_wm38_panel_escape(x)}</span>' for x in rows[:5]) + '</div>'


def _wm404_render_country_intel(payload: dict[str, Any], ctx: dict[str, Any], display_style: str, country: str) -> str:
    base = _wm38_render_country_intel(payload, ctx, display_style, country)
    # This renderer is called without live_news in the original signature; keep stable baseline and add country-specific framework.
    selected = str(country or "Global")
    risk_bias = 8 if selected not in {"Global", "France", "Germany", "Japan"} else 0
    matrix = [
        {"axis": "Geo", "score": min(100, 58 + risk_bias), "delta": "watch", "driver": "conflict proximity / theatre pressure"},
        {"axis": "Cyber", "score": 72, "delta": "high", "driver": "critical infra / exploit news cluster"},
        {"axis": "Macro", "score": 46, "delta": "stable", "driver": "rates, FX, liquidity pressure"},
        {"axis": "Supply", "score": min(100, 63 + risk_bias), "delta": "watch", "driver": "shipping, chokepoints, energy exposure"},
        {"axis": "Source", "score": 84, "delta": "audit", "driver": "source quality and corroboration control"},
    ]
    providers = [("Country event store", "READY", "country keyword routing, entity mapping"), ("Risk axis model", "OK", "geo/cyber/macro/supply/source"), ("Map focus", "OK", "bbox, marker, country focus")]
    return base + '<div class="wm404-section-title">Country risk matrix</div>' + _wm38_rows_table(matrix, 6) + _wm405_provider_ladder("country_intel", providers) + _wm404_next_watch(["country selection now changes map focus", "next: country-specific event store", "next: 24h/7d axis delta"])

def _wm404_render_actionable_alerts(payload: dict[str, Any], live_news: Any) -> str:
    store = _wm405_event_store(live_news, "Global") if "_wm405_event_store" in globals() else []
    alerts = ((payload.get("value_plus", {}) or {}).get("alerts", []) or []) if isinstance(payload, dict) else []
    # Use existing value_plus alerts as fallback only when the event store is empty.
    if not store and alerts:
        converted = []
        for a in alerts[:6]:
            converted.append({"title": _text(a.get("title"), "Signal"), "topic": "risk", "source": "value_plus", "corroboration": 1, "confidence": _wm38_safe_int(a.get("confidence", 70), 70), "actionability": _wm38_safe_int(a.get("confidence", 70), 70), "raw": a})
        store = converted
    top = [r for r in store if int(r.get("actionability", 0)) >= 55][:6]
    if not top:
        top = store[:4]
    queue_rows = [{"rank": i + 1, "priority": ("P0" if int(r.get("actionability", 0)) >= 88 else "P1" if int(r.get("actionability", 0)) >= 74 else "P2"), "topic": str(r.get("topic", "news")).upper(), "confidence": int(r.get("confidence", 0)), "source": str(r.get("source", ""))[:22]} for i, r in enumerate(top[:6])]
    return _wm405_action_cards(top, 4) + '<div class="wm404-section-title">Triage queue</div>' + _wm38_rows_table(queue_rows, 6) + _wm404_drilldown([r.get("raw", {}) for r in top], 5)

