    store = _wm405_event_store(live_news, "Global") if "_wm405_event_store" in globals() else []
    evidence = _wm405_evidence_rows(store, 5) if "_wm405_evidence_rows" in globals() else []
    return _wm405_topic_waterfall(store, "Institutional signal waterfall") + '<div class="wm404-section-title">Evidence tape</div>' + _wm38_rows_table(evidence, 5) + _wm404_next_watch(["raise score only with independent corroboration", "separate provider-ready from confirmed live", "store previous snapshot for true 24h delta"])

