    gauge = '<div class="wm38-risk-gauge"><div class="wm38-donut" style="--score:' + str(total) + ';"><span>' + str(total) + '</span></div><div><small>TENDANCE</small><b>' + _wm38_panel_escape(label) + '</b><em>decomposed</em></div></div>'
