def _wm404_render_cyber(live_news: Any) -> str:
    store = _wm405_event_store(live_news, "Global") if "_wm405_event_store" in globals() else []
    cyber = [r for r in store if r.get("topic") == "cyber"]
    rows = []
    for r in cyber[:6]:
        title = str(r.get("title", "Cyber signal"))
        cve = re.search(r"CVE-\d{4}-\d{4,7}", title, flags=re.I)
        rows.append({"signal": cve.group(0).upper() if cve else "EXPLOIT", "severity": int(r.get("severity", 0)), "conf": int(r.get("confidence", 0)), "source": str(r.get("source", ""))[:22], "title": title[:68]})
    raw = [r.get("raw", {}) for r in cyber[:5] if isinstance(r.get("raw"), dict)]
    return _wm404_state_strip("cybersecurity", raw, False, "KEV/NVD-ready cyber routing") + _wm38_rows_table(rows, 6) + _wm405_provider_ladder("cyber", [("CISA KEV", "READY", "known exploited, due date"), ("NVD", "READY", "CVSS, CWE, vendor"), ("EPSS", "READY", "exploit probability"), ("Vendor advisories", "READY", "patch/remediation")]) + _wm404_drilldown(raw, 5)

