# === WM211 INSTITUTIONAL PANEL INTELLIGENCE V4.0.4 HELPERS END ===

# === WM211 INSTITUTIONAL PANEL UPGRADE V4.0.5 START ===
# Conservative institutional layer for existing panels.
# Scope:
# - no map change;
# - no navigation change;
# - no layout reset;
# - no fake live provider;
# - improve scoring, source quality, corroboration and actionability from already-loaded rows.

def _wm405_clamp(value: Any, lo: float = 0.0, hi: float = 100.0, default: float = 0.0) -> float:
    try:
        x = float(value)
        if not math.isfinite(x):
            return float(default)
        return max(float(lo), min(float(hi), x))
    except Exception:
        return float(default)


def _wm405_words(value: Any) -> set[str]:
    try:
        return set(re.findall(r"[a-z0-9]{3,}", str(value or "").lower()))
    except Exception:
        return set()


def _wm405_blob(item: Any) -> str:
    if isinstance(item, dict):
        keys = ["title", "name", "source", "provider", "tag", "category", "topic_bucket", "region", "country", "summary", "description", "url", "published", "date", "age"]
        return " ".join(str(item.get(k, "")) for k in keys).lower()
    return str(item or "").lower()


def _wm405_parse_time(value: Any):
    try:
        raw = str(value or "").strip()
        if not raw:
            return None
        if raw.endswith("Z"):
            raw = raw[:-1] + "+00:00"
        raw = raw.replace(" UTC", "+00:00")
        # Handle common RFC-like formats without adding a hard dependency.
        for fmt in ("%a, %d %b %Y %H:%M:%S %Z", "%a, %d %b %Y %H:%M:%S %z", "%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S%z", "%Y-%m-%dT%H:%M:%S.%f%z"):
            try:
                dt = _dt.datetime.strptime(raw, fmt)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=_dt.timezone.utc)
                return dt.astimezone(_dt.timezone.utc)
            except Exception:
                pass
        try:
            dt = _dt.datetime.fromisoformat(raw)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=_dt.timezone.utc)
            return dt.astimezone(_dt.timezone.utc)
        except Exception:
            return None
    except Exception:
        return None


def _wm405_item_time(item: dict[str, Any]):
    if not isinstance(item, dict):
        return None
    for k in ["timestamp_utc", "published_at", "published", "pubDate", "updated_at", "date", "time", "created_at"]:
        dt = _wm405_parse_time(item.get(k))
        if dt is not None:
            return dt
    return None


def _wm405_age_hours(item: dict[str, Any]) -> float | None:
    dt = _wm405_item_time(item)
    if dt is None:
        return None
    try:
        return max(0.0, (_dt.datetime.now(_dt.timezone.utc) - dt).total_seconds() / 3600.0)
    except Exception:
        return None


def _wm405_freshness_score(item: dict[str, Any]) -> int:
    age = _wm405_age_hours(item)
    if age is None:
        # Unknown age is not fatal, but should not receive a live-grade score.
        return 48
    if age <= 1:
        return 96
    if age <= 6:
        return 88
    if age <= 24:
        return 76
    if age <= 48:
        return 64
    if age <= 168:
        return 46
    return 22


def _wm405_source_tier(source: Any) -> tuple[str, int]:
    s = str(source or "").lower()
    official = ["cisa", "nvd", "eia", "fred", "ecb", "usgs", "gdacs", "nasa", "reliefweb", "un ", "state dept", "treasury", "pentagon", "white house", "gov", ".gov", "europa"]
    wires = ["reuters", "ap news", "associated press", "bloomberg", "financial times", "ft ", "bbc", "dw", "france 24", "al jazeera", "cnbc", "cnn"]
    specialist = ["oilprice", "securityweek", "krebs", "industrial cyber", "techcrunch", "semivision", "crunchbase", "atlantic council", "carnegie", "csis", "rand"]
    if any(x in s for x in official):
        return "PRIMARY", 92
    if any(x in s for x in wires):
        return "WIRE", 82
    if any(x in s for x in specialist):
        return "SPECIALIST", 73
    if any(x in s for x in ["google news", "provider", "fallback", "ready"]):
        return "AGGREGATED", 54
    return "OPEN", 62


def _wm405_country_terms(country: str) -> list[str]:
    c = str(country or "Global")
    mapping = {
        "Global": [],
        "France": ["france", "french", "paris", "europe", "european", "ecb"],
        "United States": ["united states", "u.s.", "us ", "america", "american", "washington", "federal", "cisa", "treasury", "pentagon", "white house"],
        "China": ["china", "chinese", "beijing", "shanghai", "taiwan", "semiconductor"],
        "Taiwan": ["taiwan", "taipei", "strait", "tsmc", "china", "semiconductor"],
        "Israel": ["israel", "gaza", "jerusalem", "hamas", "iran", "middle east"],
        "Ukraine": ["ukraine", "kyiv", "russia", "moscow", "nato", "europe"],
        "Germany": ["germany", "german", "berlin", "europe", "energy", "ecb"],
        "Japan": ["japan", "tokyo", "boj", "yen", "asia", "semiconductor"],
    }
    return mapping.get(c, [c.lower()])


def _wm405_country_match(item: dict[str, Any], country: str) -> bool:
    terms = _wm405_country_terms(country)
    if not terms:
        return True
    blob = _wm405_blob(item)
    return any(t in blob for t in terms)


def _wm405_canonical_key(item: dict[str, Any]) -> str:
    title = _text(item.get("title"), _text(item.get("name"), "signal")) if isinstance(item, dict) else str(item or "signal")
    words = [w for w in re.findall(r"[a-z0-9]{4,}", title.lower()) if w not in {"with", "from", "that", "this", "after", "before", "into", "over", "under", "news", "says", "said", "will", "have", "amid"}]
    if len(words) >= 5:
        return " ".join(words[:9])
    return re.sub(r"[^a-z0-9]+", "-", title.lower()).strip("-")[:96]


def _wm405_event_store(live_news: Any, country: str = "Global", limit: int = 300) -> list[dict[str, Any]]:
    raw = _wm38_flat_news(live_news)
    rows: list[dict[str, Any]] = []
    seen: set[str] = set()
    for idx, it in enumerate(raw):
        if not isinstance(it, dict):
            continue
        if not _wm405_country_match(it, country):
            # Country focus is a soft filter: skip if clearly unrelated, but Global keeps all.
            continue
        key = str(it.get("url") or it.get("link") or _wm405_canonical_key(it) or idx)
        if key in seen:
            continue
        seen.add(key)
        title = _text(it.get("title"), _text(it.get("name"), "Signal"))
        src = _wm404_source_name(it) if "_wm404_source_name" in globals() else _text(it.get("source"), "WorldMonitor")
        tier, reliability = _wm405_source_tier(src)
        topic = _wm404_classify_topic(it) if "_wm404_classify_topic" in globals() else "news"
        severity = _wm404_topic_score(it) if "_wm404_topic_score" in globals() else 50
        freshness = _wm405_freshness_score(it)
        fallback = _wm404_is_fallback_item(it) if "_wm404_is_fallback_item" in globals() else False
        cluster = _wm405_canonical_key(it)
        url = _text(it.get("url"), _text(it.get("link"), _text(it.get("source_url"), "")))
        ts = _wm405_item_time(it)
        rows.append({
            "idx": idx,
            "title": title,
            "source": src,
            "source_tier": tier,
            "reliability": reliability,
            "topic": topic,
            "severity": int(severity),
            "freshness": int(freshness),
            "fallback": bool(fallback),
            "cluster": cluster,
            "url": url,
            "time": ts.isoformat().replace("+00:00", "Z") if ts is not None else _text(it.get("published"), _text(it.get("date"), "")),
            "raw": it,
        })
        if len(rows) >= int(limit):
            break

    cluster_sources: dict[str, set[str]] = {}
    topic_sources: dict[str, set[str]] = {}
    for r in rows:
        cluster_sources.setdefault(r["cluster"], set()).add(str(r["source"]))
        topic_sources.setdefault(r["topic"], set()).add(str(r["source"]))
    for r in rows:
        corr = max(len(cluster_sources.get(r["cluster"], set())), min(4, len(topic_sources.get(r["topic"], set()))))
        corr_score = min(100, 38 + 14 * corr)
        fallback_penalty = 24 if r["fallback"] else 0
        confidence = 0.30 * r["severity"] + 0.25 * r["reliability"] + 0.20 * r["freshness"] + 0.25 * corr_score - fallback_penalty
        r["corroboration"] = int(corr)
        r["confidence"] = int(_wm405_clamp(confidence, 0, 98, 50))
        r["actionability"] = int(_wm405_clamp(0.45 * r["severity"] + 0.35 * r["confidence"] + 0.20 * r["freshness"], 0, 100, 50))
    rows.sort(key=lambda x: (x.get("actionability", 0), x.get("confidence", 0), x.get("freshness", 0)), reverse=True)
    return rows


def _wm405_topic_counts(store: list[dict[str, Any]]) -> dict[str, int]:
    out: dict[str, int] = {}
    for r in store or []:
        t = str(r.get("topic", "news"))
        out[t] = out.get(t, 0) + 1
    return out


def _wm405_topic_sources(store: list[dict[str, Any]]) -> dict[str, set[str]]:
    out: dict[str, set[str]] = {}
    for r in store or []:
        out.setdefault(str(r.get("topic", "news")), set()).add(str(r.get("source", "")))
    return out


def _wm405_evidence_rows(store: list[dict[str, Any]], limit: int = 5) -> list[dict[str, Any]]:
    rows = []
    for r in (store or [])[:int(limit)]:
        rows.append({
            "topic": str(r.get("topic", "news")).upper(),
            "score": int(r.get("actionability", r.get("confidence", 0))),
            "conf": int(r.get("confidence", 0)),
            "src": str(r.get("source", ""))[:24],
            "headline": str(r.get("title", ""))[:86],
        })
    return rows


def _wm405_provider_ladder(panel: str, providers: list[tuple[str, str, str]]) -> str:
    if not providers:
        return ""
    cards = []
    for name, state, fields in providers[:4]:
        cls = "live" if str(state).upper() in {"LIVE", "OK"} else ("provider" if "READY" in str(state).upper() else "cache")
        cards.append(
            '<div class="wm405-provider-card">'
            f'<b>{_wm38_panel_escape(name)}</b><span class="{cls}">{_wm38_panel_escape(state)}</span>'
            f'<small>{_wm38_panel_escape(fields)}</small>'
            '</div>'
        )
    return '<div class="wm405-provider-grid">' + ''.join(cards) + '</div>'


def _wm405_action_cards(store: list[dict[str, Any]], limit: int = 4) -> str:
    if not store:
        return '<div class="wm38-empty">Aucune alerte exploitable. Les flux provider-ready restent disponibles.</div>'
    cards = []
    for r in store[:int(limit)]:
        score = int(r.get("actionability", r.get("confidence", 0)))
        priority = "P0" if score >= 88 else ("P1" if score >= 74 else "P2")
        status = "CONFIRM" if int(r.get("corroboration", 1)) >= 3 else ("TRIAGE" if int(r.get("corroboration", 1)) >= 2 else "WATCH")
        horizon = "0-24h" if score >= 82 else "24-72h"
        cards.append(
            '<div class="wm405-action-card">'
            f'<div><span class="prio">{_wm38_panel_escape(priority)}</span><span>{_wm38_panel_escape(status)}</span><b>{score}</b></div>'
            f'<h4>{_wm38_panel_escape(r.get("title", "Signal"))}</h4>'
            f'<p>{_wm38_panel_escape(str(r.get("topic", "news")).upper())} · {int(r.get("corroboration", 1))} source bucket(s) · {horizon}</p>'
            '<small>Action: valider source primaire, mapper actifs/pays exposés, surveiller momentum 6h/24h.</small>'
            '</div>'
        )
    return '<div class="wm405-action-grid">' + ''.join(cards) + '</div>'


def _wm405_signal_formula() -> str:
    return (
        '<div class="wm405-formula">'
        '<b>Scoring formula</b>'
        '<span>30% severity · 25% source reliability · 20% freshness · 25% corroboration · fallback penalty</span>'
        '</div>'
    )


def _wm405_topic_waterfall(store: list[dict[str, Any]], title: str = "Institutional signal waterfall") -> str:
    counts = _wm405_topic_counts(store)
    weights = {"cyber": 24, "geo": 24, "energy": 18, "market": 16, "ai": 14, "supply": 14, "policy": 10, "disaster": 10, "news": 6}
    rows: list[tuple[str, int, str]] = []
    for topic in ["cyber", "geo", "energy", "market", "ai", "supply", "policy", "disaster"]:
        c = int(counts.get(topic, 0))
        if c or topic in {"cyber", "geo", "energy", "market", "ai"}:
            rows.append((topic.title(), min(weights.get(topic, 8), c * max(2, weights.get(topic, 8) // 6)), f"{c} routed items"))
    return _wm404_waterfall(rows, title) + _wm405_signal_formula()


def _wm405_source_quality_metrics(store: list[dict[str, Any]], source_registry: list[dict[str, Any]]) -> tuple[list[dict[str, Any]], list[dict[str, Any]], list[dict[str, Any]]]:
    n = len(store or [])
    sources: dict[str, int] = {}
    tiers: dict[str, int] = {}
    keys: set[str] = set()
    duplicate = 0
    ages = []
    for r in store or []:
        src = str(r.get("source", "WorldMonitor"))[:42]
        sources[src] = sources.get(src, 0) + 1
        tier = str(r.get("source_tier", "OPEN"))
        tiers[tier] = tiers.get(tier, 0) + 1
        key = str(r.get("cluster", r.get("title", "")))
        if key in keys:
            duplicate += 1
        keys.add(key)
        raw = r.get("raw", {})
        age = _wm405_age_hours(raw) if isinstance(raw, dict) else None
        if age is not None:
            ages.append(age)
    primary_ratio = int(round(100 * (tiers.get("PRIMARY", 0) + tiers.get("WIRE", 0)) / max(1, n)))
    diversity = int(round(100 * min(1.0, len(sources) / max(1, min(12, n)))))
    dup_rate = int(round(100 * duplicate / max(1, n)))
    median_age = sorted(ages)[len(ages)//2] if ages else None
    freshness = int(round(sum(int(r.get("freshness", 48)) for r in store) / max(1, n))) if n else 0
    quality = int(_wm405_clamp(0.30 * primary_ratio + 0.25 * diversity + 0.25 * freshness + 0.20 * (100 - dup_rate), 0, 100, 50)) if n else 38
    metrics = [
        {"label": "QUALITY", "value": f"{quality}/100", "delta": "HIGH" if quality >= 75 else ("WATCH" if quality >= 55 else "LOW")},
        {"label": "LIVE ITEMS", "value": n, "delta": "routed"},
        {"label": "SOURCE DIV", "value": f"{diversity}%", "delta": f"{len(sources)} src"},
        {"label": "DUP RATE", "value": f"{dup_rate}%", "delta": "dedupe"},
        {"label": "PRIMARY/WIRE", "value": f"{primary_ratio}%", "delta": "tier"},
        {"label": "AGE MED", "value": "n/a" if median_age is None else (f"{median_age:.1f}h" if median_age < 48 else f"{median_age/24:.1f}d"), "delta": "freshness"},
    ]
    source_rows = [{"source": k, "items": v, "share": f"{(v/max(1,n)*100):.0f}%"} for k, v in sorted(sources.items(), key=lambda x: x[1], reverse=True)[:8]]
    tier_rows = [{"tier": k, "items": v, "share": f"{(v/max(1,n)*100):.0f}%"} for k, v in sorted(tiers.items(), key=lambda x: x[1], reverse=True)]
    return metrics, source_rows, tier_rows


def _wm405_rows_from_store(store: list[dict[str, Any]], limit: int = 5) -> str:
    rows = _wm405_evidence_rows(store, limit)
    return _wm38_rows_table(rows, limit) if rows else '<div class="wm38-empty">Aucune source exploitable dans la fenêtre actuelle.</div>'


def _wm405_empty_guard(store: list[dict[str, Any]], panel_name: str) -> str:
    if store:
        return ""
    return _wm404_provider_note(panel_name, "Provider-ready", "connect source feed; no synthetic institutional data displayed")
# === WM211 INSTITUTIONAL PANEL UPGRADE V4.0.5 END ===



def _wm38_panel_body_v405_prev(panel_id: str, payload: dict[str, Any], live_news: Any, quote_rows: list[dict[str, Any]], ctx: dict[str, Any], source_registry: list[dict[str, Any]], display_style: str, country: str) -> str:
    pid = str(panel_id)
    # V4.0.4: institutional panel routing. Direct/live provider panels remain
    # rendered by the V4.0 direct helpers; analytic panels are upgraded below.
    try:
        if pid == "live_news" and "_wm40_render_direct_news" in globals():
            return _wm40_render_direct_news(live_news)
        if pid == "webcams" and "_wm40_render_webcams" in globals():
            return _wm40_render_webcams()
        if pid == "commodities" and "_wm40_render_commodities" in globals():
            return _wm40_render_commodities(quote_rows, payload) + _wm404_provider_note("Commodities provider", "market/commodities feed", "front-month, carry, volatility, timestamp")
        if pid == "github_trends" and "_wm40_render_github_trends" in globals():
            return _wm40_render_github_trends(payload, live_news) + _wm404_provider_note("GitHub provider", "GitHub Search/Trending", "stars 24h/7d, language, category, velocity")
        if pid == "force_posture" and "_wm40_render_force_posture" in globals():
            return _wm40_render_force_posture(live_news, ctx) + _wm404_next_watch(["add source count by theatre", "add air/naval/cyber delta", "link theatre click to map"])
        if pid == "escalation_monitor" and "_wm40_render_escalation_monitor" in globals():
            return _wm40_render_escalation_monitor(live_news, ctx) + _wm404_next_watch(["probability/impact matrix", "24h/7d/30d horizon", "counter-signal tracking"])
        if pid == "financial_stress" and "_wm40_render_financial_stress" in globals():
            return _wm40_render_financial_stress(ctx, quote_rows) + _wm404_provider_note("Stress provider", "FRED / spreads / VIX / rates", "Z-score, percentile, delta 1d/1w")
        if pid in {"fixed_income", "yield_curve"} and "_wm40_render_rates_panel" in globals():
            return _wm40_render_rates_panel(pid) + _wm404_provider_note("Rates provider", "Treasury/FRED", "3M, 2Y, 5Y, 10Y, 30Y, slope, real yields")
        if pid == "stablecoins" and "_wm40_render_stablecoins" in globals():
            return _wm40_render_stablecoins() + _wm404_provider_note("Stablecoin provider", "CoinGecko/DeFiLlama/exchange feeds", "supply, peg, flows, issuer concentration")
        if pid == "trade_policy" and "_wm40_render_trade_policy" in globals():
            return _wm40_render_trade_policy(live_news) + _wm404_provider_note("Trade policy provider", "official tariffs/export controls/sanctions feeds", "sector, country, affected tickers")
        if pid == "economic_warfare" and "_wm40_render_economic_warfare" in globals():
            return _wm40_render_economic_warfare(live_news) + _wm404_next_watch(["OFAC/EU/UK sanctions", "export controls", "insurance premia", "affected sectors"])
        if pid == "disaster_cascade" and "_wm40_render_disaster_cascade" in globals():
            return _wm40_render_disaster_cascade(live_news) + _wm404_provider_note("Disaster provider", "USGS / GDACS / EONET / FIRMS", "event, severity, infrastructure exposure, market linkage")
    except Exception as exc:
        return '<div class="wm38-empty">Panel direct indisponible: ' + _wm38_panel_escape(type(exc).__name__ + ': ' + str(exc)[:180]) + '</div>'

    if pid in {"daily_market_brief", "stock_analysis", "backtesting", "wm_analyst"}:
        return _wm38_locked_panel(pid)
    if pid == "country_intel":
        return _wm404_render_country_intel(payload, ctx, display_style, country)
    if pid == "alert_engine":
        return _wm404_render_actionable_alerts(payload, live_news)
    if pid == "signal_drivers":
        return _wm404_render_signal_waterfall(payload, live_news, ctx)
    if pid == "source_quality":
        return _wm404_render_source_quality(payload, live_news, source_registry)
    if pid == "ai_insights":
        return _wm404_render_ai_insights(payload, live_news)
    if pid == "live_intel":
        return _wm404_render_prioritized_intel(live_news, country)
    if pid == "intel_flow":
        return _wm404_news_panel("intel_flow", live_news, country, 6, "raw feed, deduped/diversified")
    if pid in {"world_news", "region_us", "region_europe", "region_mena", "region_africa", "region_latam", "region_apac", "energy_resources", "government", "think_tanks", "ai_ml", "technology"}:
        return _wm404_news_panel(pid, live_news, country, 5)
    if pid == "cybersecurity":
        return _wm404_render_cyber(live_news)
    if pid == "threat_timeline":
        return _wm38_render_timeline(live_news, ctx) + _wm404_next_watch(["replace static bars with 1h/24h/7d event timeline", "store previous refresh for true trend"])
    if pid == "ai_posture":
        return _wm38_render_ai_posture(ctx) + _wm404_next_watch(["add source count per theatre", "add air/naval/cyber readiness trend"])
    if pid == "ai_forecasts":
        return _wm404_render_forecasts(payload, live_news)
    if pid == "country_instability":
        return _wm38_render_instability() + _wm404_next_watch(["attach country drivers", "click country filters all panels", "add 24h/7d delta"])
    if pid == "strategic_risk":
        return _wm404_render_strategic_risk(ctx, live_news)
    if pid == "cross_source":
        return _wm404_render_cross_source(payload, live_news)
    if pid == "infra_cascade":
        return _wm404_render_infra_cascade(source_registry, live_news)
    if pid in {"markets", "finance", "crypto"}:
        return _wm404_render_markets(pid, quote_rows, payload)
    if pid == "economic":
        return _wm38_render_economic() + _wm404_provider_note("Macro provider", "FRED / ECB SDMX", "inflation, unemployment, curve, credit, central-bank surprises")
    if pid == "energy_complex":
        return _wm404_render_energy_complex(live_news)
    if pid == "supply_chain":
        return _wm404_render_supply_chain(live_news)
    if pid == "climate_anomalies":
        return _wm38_render_climate() + _wm404_provider_note("Climate provider", "NOAA / NASA EONET / ECMWF-style feed", "anomaly percentile, precipitation, grid/commodity impact")
    if pid == "flight_intel":
        return _wm38_render_flights() + _wm404_provider_note("Aviation provider", "OpenSky for ADS-B; separate provider for commercial delays", "states, altitude, route, airport stress")
    if pid == "central_bank_watch":
        return _wm404_render_central_bank_watch(live_news)

    if pid in {"policy_ai", "funding_vc", "tech_events", "tech_maturity", "vc_financing", "startups_vc", "service_status", "world_clock", "market_radar"}:
        pdata = ((payload.get("panels", {}) or {}).get(pid, {}) or {}) if isinstance(payload, dict) else {}
        if isinstance(pdata, dict):
            if pdata.get("rows"):
                return _wm38_rows_table(list(pdata.get("rows", []) or [])) + _wm404_provider_note("Panel data", "source catalog", "format, timestamp, source lineage")
            if pdata.get("cards"):
                return _wm38_metric_grid(list(pdata.get("cards", []) or [])) + _wm404_provider_note("Panel data", "source catalog", "format, timestamp, source lineage")
            if pdata.get("items"):
                items = _wm404_dedupe_diversify(list(pdata.get("items", []) or []), 5)
                return _wm38_news_cards(items, 5) + _wm404_drilldown(items, 4)
        return _wm404_news_panel(pid, live_news, country, 4)

    return _wm404_news_panel(pid, live_news, country, 4)

# === WM211 PANEL RATIONALIZATION & PROVIDER DISCIPLINE V4.0.6 START ===
# Final conservative panel layer.
# Scope:
# - keep the current WorldMonitor base, map, country focus, event window, layout and navigation;
# - keep V4.0.4/V4.0.5 panel runtime and fallback renderer;
# - specialize duplicated panels;
# - add provider discipline, source/timestamp/freshness, explainable scoring and canonicalization;
# - do not invent live data when a real provider is absent.

try:
    _dt
except NameError:  # pragma: no cover
    import datetime as _dt  # type: ignore


def _wm406_esc(value: Any) -> str:
    try:
        return _wm38_panel_escape(value)
    except Exception:
        try:
            return html.escape(str(value or ""), quote=True)
        except Exception:
            return str(value or "")


def _wm406_num(value: Any, default: float = 0.0) -> float:
    try:
        x = float(value)
        return x if math.isfinite(x) else float(default)
    except Exception:
        return float(default)


def _wm406_int(value: Any, default: int = 0) -> int:
    try:
        return int(round(_wm406_num(value, default)))
    except Exception:
        return int(default)


def _wm406_clip(value: Any, lo: float = 0.0, hi: float = 100.0, default: float = 0.0) -> float:
    return max(float(lo), min(float(hi), _wm406_num(value, default)))


def _wm406_text(value: Any, default: str = "") -> str:
    try:
        return _text(value, default)
    except Exception:
        s = str(value or "").strip()
        return s if s else default


def _wm406_now_utc() -> str:
    try:
        return _dt.datetime.now(_dt.timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    except Exception:
        return ""


def _wm406_panel_payload(payload: dict[str, Any], panel_id: str) -> dict[str, Any]:
    try:
        return ((payload or {}).get("panels", {}) or {}).get(str(panel_id), {}) or {}
    except Exception:
        return {}


def _wm406_flat_news(live_news: Any) -> list[dict[str, Any]]:
    try:
        rows = _wm38_flat_news(live_news)
    except Exception:
        rows = []
    return [x for x in (rows or []) if isinstance(x, dict)]


def _wm406_store(live_news: Any, country: str = "Global", limit: int = 320) -> list[dict[str, Any]]:
    try:
        store = _wm405_event_store(live_news, country, limit=limit)
        if isinstance(store, list):
            return [x for x in store if isinstance(x, dict)]
    except Exception:
        pass
    rows = []
    for idx, item in enumerate(_wm406_flat_news(live_news)[:limit]):
        title = _wm406_text(item.get("title"), _wm406_text(item.get("name"), "Signal"))
        source = _wm406_text(item.get("source"), _wm406_text(item.get("provider"), "WorldMonitor"))
        try:
            tier, reliability = _wm405_source_tier(source)
        except Exception:
            tier, reliability = ("OPEN", 60)
        try:
            topic = _wm404_classify_topic(item)
        except Exception:
            topic = _wm406_text(item.get("topic"), _wm406_text(item.get("tag"), "news")).lower()
        try:
            severity = int(_wm404_topic_score(item))
        except Exception:
            severity = 55
        try:
            freshness = int(_wm405_freshness_score(item))
        except Exception:
            freshness = 50
        try:
            fallback = bool(_wm404_is_fallback_item(item))
        except Exception:
            fallback = "fallback" in (source + " " + title).lower()
        corr = 1
        conf = int(_wm406_clip(0.32 * severity + 0.25 * reliability + 0.22 * freshness + 0.21 * (48 + 12 * corr) - (22 if fallback else 0), 0, 98, 50))
        rows.append({
            "idx": idx,
            "title": title,
            "source": source,
            "source_tier": tier,
            "reliability": int(reliability),
            "topic": topic,
            "severity": int(severity),
            "freshness": int(freshness),
            "fallback": fallback,
            "corroboration": corr,
            "confidence": conf,
            "actionability": int(_wm406_clip(0.42 * severity + 0.36 * conf + 0.22 * freshness, 0, 100, 50)),
            "time": _wm406_text(item.get("published"), _wm406_text(item.get("date"), "")),
            "url": _wm406_text(item.get("url"), _wm406_text(item.get("link"), "")),
            "raw": item,
        })
    rows.sort(key=lambda x: (x.get("actionability", 0), x.get("confidence", 0), x.get("freshness", 0)), reverse=True)
    return rows


def _wm406_unique_sources(store: list[dict[str, Any]]) -> set[str]:
    return {str(r.get("source", "")).strip() for r in (store or []) if str(r.get("source", "")).strip()}


def _wm406_topic_counts(store: list[dict[str, Any]]) -> dict[str, int]:
    try:
        return _wm405_topic_counts(store)
    except Exception:
        out: dict[str, int] = {}
        for r in store or []:
            t = str(r.get("topic", "news")).lower()
            out[t] = out.get(t, 0) + 1
        return out


def _wm406_topic_sources(store: list[dict[str, Any]]) -> dict[str, set[str]]:
    try:
        return _wm405_topic_sources(store)
    except Exception:
        out: dict[str, set[str]] = {}
        for r in store or []:
            out.setdefault(str(r.get("topic", "news")).lower(), set()).add(str(r.get("source", "")))
        return out


def _wm406_quality_metrics(store: list[dict[str, Any]], source_registry: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    store = store or []
    total = len(store)
    srcs = _wm406_unique_sources(store)
    fallback = sum(1 for r in store if bool(r.get("fallback")))
    primary = sum(1 for r in store if str(r.get("source_tier", "")).upper() == "PRIMARY")
    wire = sum(1 for r in store if str(r.get("source_tier", "")).upper() == "WIRE")
    specialist = sum(1 for r in store if str(r.get("source_tier", "")).upper() == "SPECIALIST")
    aggregated = sum(1 for r in store if str(r.get("source_tier", "")).upper() == "AGGREGATED")
    avg_conf = int(sum(_wm406_int(r.get("confidence"), 0) for r in store) / max(1, total))
    avg_fresh = int(sum(_wm406_int(r.get("freshness"), 0) for r in store) / max(1, total))
    dup_risk = max(0, total - len({str(r.get("url") or r.get("title"))[:130] for r in store}))
    diversity = min(100, int(28 + 9 * len(srcs) + 5 * len(_wm406_topic_counts(store))))
    real = max(0, total - fallback)
    official_ratio = int(100 * (primary + wire) / max(1, total))
    provider_rows = len(source_registry or [])
    score = int(_wm406_clip(
        0.23 * avg_conf + 0.18 * avg_fresh + 0.22 * diversity + 0.18 * official_ratio + 0.12 * min(100, real * 8) + 0.07 * min(100, provider_rows / 2),
        0, 100, 50,
    ))
    return {
        "score": score,
        "total": total,
        "real": real,
        "fallback": fallback,
        "sources": len(srcs),
        "primary": primary,
        "wire": wire,
        "specialist": specialist,
        "aggregated": aggregated,
        "avg_conf": avg_conf,
        "avg_fresh": avg_fresh,
        "dup_risk": dup_risk,
        "diversity": diversity,
        "official_ratio": official_ratio,
        "provider_rows": provider_rows,
    }


def _wm406_state_strip(label: str, store: list[dict[str, Any]], source_registry: list[dict[str, Any]] | None = None, provider_note: str = "") -> str:
    q = _wm406_quality_metrics(store, source_registry)
    state = "LIVE" if q["real"] > 0 else ("PROVIDER" if provider_note else "READY")
    if q["fallback"] > 0 and q["real"] > 0:
        state = "MIXED"
    elif q["fallback"] > 0 and q["real"] <= 0:
        state = "FALLBACK"
    note = provider_note or f'{q["real"]} real / {q["fallback"]} fallback · {q["sources"]} sources · freshness {q["avg_fresh"]}/100'
    return (
        '<div class="wm404-state-strip">'
        f'<b class="{ "provider" if state in {"PROVIDER","FALLBACK","MIXED"} else "" }">{_wm406_esc(state)}</b>'
        f'<span>{_wm406_esc(label)}</span>'
        f'<strong>{q["score"]}/100</strong>'
        f'<small>{_wm406_esc(note)}</small>'
        '</div>'
    )


def _wm406_provider_card(name: str, state: str, fields: str, detail: str = "") -> str:
    state_u = str(state or "").upper()
    cls = "live" if state_u in {"LIVE", "OK", "CONNECTED"} else ("provider" if any(x in state_u for x in ["READY", "PROVIDER", "TARGET"]) else "cache")
    return (
        '<div class="wm405-provider-card">'
        f'<b>{_wm406_esc(name)}</b><span class="{cls}">{_wm406_esc(state)}</span>'
        f'<small>{_wm406_esc(fields)}</small>'
        f'{f"<em>{_wm406_esc(detail)}</em>" if detail else ""}'
        '</div>'
    )


def _wm406_provider_grid(cards: list[tuple[str, str, str, str]]) -> str:
    return '<div class="wm405-provider-grid">' + ''.join(_wm406_provider_card(*c) for c in cards) + '</div>'


def _wm406_table(rows: list[dict[str, Any]], limit: int = 8, keys: list[str] | None = None) -> str:
    rows = [r for r in (rows or []) if isinstance(r, dict)][: int(limit)]
    if not rows:
        return '<div class="wm38-empty">Aucune donnée exploitable.</div>'
    if keys is None:
        keys = []
        for r in rows:
            for k in r.keys():
                if k not in keys and len(keys) < 5:
                    keys.append(str(k))
    try:
        head = ''.join(f'<th>{_wm406_esc(k)}</th>' for k in keys)
        body = ''.join('<tr>' + ''.join(f'<td>{_wm406_esc(r.get(k, ""))}</td>' for k in keys) + '</tr>' for r in rows)
        return f'<table class="wm38-table"><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table>'
    except Exception:
        try:
            return _wm38_rows_table(rows, limit)
        except Exception:
            return '<div class="wm38-empty">Erreur de rendu tableau.</div>'


def _wm406_provider_gate(panel_name: str, provider: str, expected: str, reason: str = "") -> str:
    return (
        '<div class="wm404-provider-note">'
        f'<b>{_wm406_esc(panel_name)}</b><span>PROVIDER CIBLE</span><em>{_wm406_esc(provider)}</em>'
        f'<small>{_wm406_esc(expected)}{(" · " + _wm406_esc(reason)) if reason else ""}</small>'
        '</div>'
    )


def _wm406_topic_waterfall(store: list[dict[str, Any]], title: str = "Institutional signal waterfall", limit: int = 7) -> str:
    counts = _wm406_topic_counts(store)
    q = _wm406_quality_metrics(store)
    if not counts:
        return '<div class="wm38-empty">Waterfall indisponible : aucun signal.</div>'
    rows = []
    max_count = max(counts.values()) or 1
    topic_sources = _wm406_topic_sources(store)
    for topic, cnt in sorted(counts.items(), key=lambda kv: kv[1], reverse=True)[:limit]:
        conf = int(sum(_wm406_int(r.get("confidence"), 0) for r in store if str(r.get("topic")) == topic) / max(1, cnt))
        width = int(min(100, max(5, 100 * cnt / max_count)))
        css = "crit" if conf >= 78 else ("warn" if conf >= 62 else "")
        rows.append(
            '<div class="wm404-wf-row">'
            f'<b>{_wm406_esc(topic.upper())}</b><i><u class="{css}" style="width:{width}%"></u></i><strong>{conf}</strong>'
            f'<small>{cnt} item(s) · {len(topic_sources.get(topic, set()))} source(s) · confidence-weighted contribution</small>'
            '</div>'
        )
    return (
        '<div class="wm404-waterfall">'
        f'<h4><span>{_wm406_esc(title)}</span><b>{q["score"]}/100</b></h4>'
        + ''.join(rows) +
        '</div>'
    )


def _wm406_evidence_table(store: list[dict[str, Any]], limit: int = 6) -> str:
    rows = []
    for r in (store or [])[: int(limit)]:
        rows.append({
            "TOPIC": str(r.get("topic", "news")).upper(),
            "SCORE": _wm406_int(r.get("actionability", r.get("confidence", 0))),
            "CONF": _wm406_int(r.get("confidence", 0)),
            "SRC": str(r.get("source", ""))[:24],
            "HEADLINE": str(r.get("title", ""))[:72],
        })
    return _wm406_table(rows, limit=limit, keys=["TOPIC", "SCORE", "CONF", "SRC", "HEADLINE"])


def _wm406_render_source_quality(store: list[dict[str, Any]], source_registry: list[dict[str, Any]]) -> str:
    q = _wm406_quality_metrics(store, source_registry)
    metrics = [
        {"label": "Quality", "value": f'{q["score"]}/100', "sub": "strict"},
        {"label": "Real / Fallback", "value": f'{q["real"]}/{q["fallback"]}', "sub": "provider discipline"},
        {"label": "Sources", "value": str(q["sources"]), "sub": "unique"},
        {"label": "Freshness", "value": f'{q["avg_fresh"]}/100', "sub": "median proxy"},
    ]
    top_sources: dict[str, int] = {}
    for r in store:
        s = str(r.get("source", "")).strip() or "Unknown"
        top_sources[s] = top_sources.get(s, 0) + 1
    src_rows = [{"SOURCE": k[:32], "ITEMS": v, "TIER": (_wm405_source_tier(k)[0] if "_wm405_source_tier" in globals() else "OPEN")} for k, v in sorted(top_sources.items(), key=lambda kv: kv[1], reverse=True)[:8]]
    return (
        _wm406_state_strip("source quality controller", store, source_registry)
        + '<div class="wm38-metric-grid">' + ''.join(
            f'<div class="wm38-metric"><span>{_wm406_esc(m["label"])}</span><b>{_wm406_esc(m["value"])}</b><small>{_wm406_esc(m["sub"])}</small></div>'
            for m in metrics
        ) + '</div>'
        + '<div class="wm404-next"><b>Institutional rule</b><span>Promote signals only when source diversity, freshness and corroboration are sufficient.</span><span>Downgrade Google/fallback-only clusters until a primary, wire or specialist source confirms.</span></div>'
        + _wm406_table(src_rows, limit=8, keys=["SOURCE", "ITEMS", "TIER"])
    )


def _wm406_render_cross_source(store: list[dict[str, Any]], source_registry: list[dict[str, Any]]) -> str:
    topic_counts = _wm406_topic_counts(store)
    topic_sources = _wm406_topic_sources(store)
    rows = []
    for topic, count in sorted(topic_counts.items(), key=lambda kv: kv[1], reverse=True)[:9]:
        items = [r for r in store if str(r.get("topic")) == topic]
        conf = int(sum(_wm406_int(r.get("confidence"), 0) for r in items) / max(1, len(items)))
        primary_flag = "YES" if any(str(r.get("source_tier")) in {"PRIMARY", "WIRE"} for r in items) else "NO"
        rows.append({
            "SIGNAL": topic.upper(),
            "ITEMS": count,
            "SOURCES": len(topic_sources.get(topic, set())),
            "CONF": conf,
            "PRIMARY": primary_flag,
        })
    return (
        _wm406_state_strip("independent-source corroboration", store, source_registry)
        + _wm406_table(rows, limit=9, keys=["SIGNAL", "ITEMS", "SOURCES", "CONF", "PRIMARY"])
        + '<div class="wm404-next"><b>Promotion rule</b><span>1 source = WATCH · 2 independent sources = MONITOR · 3+ or primary source = CONFIRMED · contradiction = DISPUTED.</span></div>'
        + _wm406_evidence_table(store, limit=5)
    )


def _wm406_render_signal_explanation(store: list[dict[str, Any]], source_registry: list[dict[str, Any]]) -> str:
    formula = (
        '<div class="wm405-formula">'
        '<b>Score formula</b>'
        '<span>severity 30% · source tier 25% · freshness 20% · corroboration 20% · fallback penalty 5-25 pts</span>'
        '<small>Displayed values are monitor signals, not trading recommendations.</small>'
        '</div>'
    )
    next_watch = (
        '<div class="wm404-next"><b>Next watch</b>'
        '<span>raise score only when independent sources corroborate and timestamp remains fresh.</span>'
        '<span>lower score when signal is duplicated, stale, fallback-only or contradicted.</span></div>'
    )
    return _wm406_state_strip("explainable scoring", store, source_registry) + formula + _wm406_topic_waterfall(store) + next_watch + _wm406_evidence_table(store, 5)


def _wm406_render_alert_engine(store: list[dict[str, Any]], source_registry: list[dict[str, Any]]) -> str:
    top = [r for r in store if _wm406_int(r.get("actionability"), 0) >= 68][:6]
    try:
        cards = _wm405_action_cards(top or store, 4)
    except Exception:
        cards = ''.join(
            '<div class="wm405-action-card">'
            f'<div><span class="prio">P1</span><span>TRIAGE</span><b>{_wm406_int(r.get("actionability"), 0)}</b></div>'
            f'<h4>{_wm406_esc(r.get("title"))}</h4><p>{_wm406_esc(str(r.get("topic", "news")).upper())} · {_wm406_int(r.get("corroboration"), 1)} source bucket(s)</p>'
            '<small>Action: confirm source, map exposures, monitor 6h/24h momentum.</small></div>'
            for r in (top or store)[:4]
        )
        cards = '<div class="wm405-action-grid">' + cards + '</div>'
    return _wm406_state_strip("action queue", top or store, source_registry) + cards + _wm406_evidence_table(top or store, 4)


def _wm406_render_country_intel(store: list[dict[str, Any]], country: str, source_registry: list[dict[str, Any]]) -> str:
    q = _wm406_quality_metrics(store, source_registry)
    topics = _wm406_topic_counts(store)
    geo = min(100, 42 + 5 * topics.get("geo", 0) + 4 * topics.get("conflict", 0) + 3 * topics.get("news", 0))
    cyber = min(100, 36 + 7 * topics.get("cyber", 0))
    energy = min(100, 34 + 7 * topics.get("energy", 0) + 4 * topics.get("supply", 0))
    market = min(100, 36 + 6 * topics.get("market", 0) + 4 * topics.get("ai", 0))
    score = int(_wm406_clip(0.30 * geo + 0.22 * cyber + 0.22 * energy + 0.16 * market + 0.10 * q["score"], 0, 100, 55))
    cards = [
        {"label": "Composite", "value": f"{score}/100", "sub": country or "Global"},
        {"label": "Geo", "value": f"{int(geo)}/100", "sub": "conflict/policy"},
        {"label": "Cyber", "value": f"{int(cyber)}/100", "sub": "infra threat"},
        {"label": "Energy", "value": f"{int(energy)}/100", "sub": "supply chokepoints"},
        {"label": "Market", "value": f"{int(market)}/100", "sub": "asset channel"},
        {"label": "Sources", "value": str(q["sources"]), "sub": "unique"},
    ]
    return (
        _wm406_state_strip(f"country focus · {country}", store, source_registry)
        + '<div class="wm38-metric-grid">' + ''.join(
            f'<div class="wm38-metric"><span>{_wm406_esc(c["label"])}</span><b>{_wm406_esc(c["value"])}</b><small>{_wm406_esc(c["sub"])}</small></div>'
            for c in cards
        ) + '</div>'
        + _wm406_topic_waterfall(store, "Country risk decomposition", 6)
    )


