def _wm406_render_tech_maturity(payload: dict[str, Any]) -> str:
    pdata = _wm406_panel_payload(payload, "tech_maturity")
    rows = list(pdata.get("rows", []) or []) if isinstance(pdata, dict) else []
    aliases = {
        "united states of america": "United States",
        "usa": "United States",
        "us": "United States",
        "u.s.": "United States",
        "korea, rep.": "South Korea",
        "korea": "South Korea",
        "japan": "Japan",
        "china": "China",
        "france": "France",
        "germany": "Germany",
        "india": "India",
    }
    acc: dict[str, dict[str, Any]] = {}
    for r in rows:
        if not isinstance(r, dict):
            continue
        raw = _wm406_text(r.get("country"), _wm406_text(r.get("COUNTRY"), "Unknown"))
        canon = aliases.get(raw.lower().strip(), raw)
        score = _wm406_clip(r.get("score", r.get("SCORE", 0)), 0, 100, 0)
        if canon not in acc or score > _wm406_num(acc[canon].get("SCORE"), 0):
            acc[canon] = {"COUNTRY": canon, "SCORE": round(score, 1), "LAYER": "cloud/AI/semis/datacenters"}
    out = sorted(acc.values(), key=lambda x: _wm406_num(x.get("SCORE"), 0), reverse=True)[:8]
    if not out:
        out = [{"COUNTRY": "United States", "SCORE": 98.0, "LAYER": "provider target"}, {"COUNTRY": "China", "SCORE": 91.0, "LAYER": "provider target"}]
    provider = _wm406_provider_grid([
        ("Source catalog", "READY", "cloud regions, AI labs, datacenters", "canonical countries"),
        ("Patent / talent", "TARGET", "research density", "future upgrade"),
        ("Semiconductor chain", "TARGET", "fabs, tooling, chokepoints", "future upgrade"),
    ])
    return provider + _wm406_table(out, 8, keys=["COUNTRY", "SCORE", "LAYER"])


