def _wm406_render_regional_news(pid: str, live_news: Any, country: str, source_registry: list[dict[str, Any]]) -> str:
    try:
        items = _wm38_news_for_panel(pid, live_news, country)
    except Exception:
        items = _wm406_flat_news(live_news)
    local_store = _wm406_store(items, "Global", 90)
    return _wm406_state_strip("regional event tape", local_store, source_registry) + _wm38_news_cards(items, 5) + _wm406_evidence_table(local_store, 4)


def _wm406_panel_body(panel_id: str, payload: dict[str, Any], live_news: Any, quote_rows: list[dict[str, Any]], ctx: dict[str, Any], source_registry: list[dict[str, Any]], display_style: str, country: str) -> str | None:
    pid = str(panel_id or "")
    store = _wm406_store(live_news, country or "Global")
    # Core intelligence panels.
    if pid == "source_quality":
        return _wm406_render_source_quality(store, source_registry or [])
    if pid == "cross_source":
        return _wm406_render_cross_source(store, source_registry or [])
    if pid == "signal_drivers":
        return _wm406_render_signal_explanation(store, source_registry or [])
    if pid == "alert_engine":
        return _wm406_render_alert_engine(store, source_registry or [])
    if pid == "country_intel":
        return _wm406_render_country_intel(store, country or "Global", source_registry or [])

    # Regional/news panels become event tapes with provider state.
    if pid in {"world_news", "region_us", "region_europe", "region_mena", "region_africa", "region_latam", "region_apac", "energy_resources", "government", "think_tanks", "renewable_energy"}:
        return _wm406_render_regional_news(pid, live_news, country, source_registry or [])

    # Markets/macro specialization. Keep markets/crypto visual base but add provider discipline. Finance is no longer an equity duplicate.
    if pid == "markets":
        return _wm406_render_markets("markets", quote_rows, payload)
    if pid == "finance":
        return _wm406_render_finance(live_news, quote_rows, payload)
    if pid == "crypto":
        return _wm406_render_crypto(quote_rows, payload)
    if pid == "commodities":
        return _wm406_render_commodities(live_news)
    if pid in {"fixed_income", "yield_curve"}:
        return _wm406_render_rates_panel(pid)
    if pid == "financial_stress":
        try:
            base = _wm404_render_financial_stress(live_news)
        except Exception:
            base = ""
        return _wm406_state_strip("financial stress composite", store, source_registry or [], "VIX/rates/credit/liquidity") + base + _wm406_provider_gate("Stress provider", "FRED / market data", "VIX, rates, credit spreads, liquidity proxies")
    if pid == "central_bank_watch":
        try:
            return _wm404_render_central_bank_watch(live_news) + _wm406_provider_gate("Central bank policy", "FRED / ECB / official calendars", "last meeting, next meeting, market-implied path, speech evidence")
        except Exception:
            return _wm406_provider_gate("Central bank policy", "FRED / ECB / official calendars", "last meeting, next meeting, market-implied path, speech evidence")

    # New tech/risk panels that need discipline or dedupe.
    if pid == "tech_maturity":
        return _wm406_render_tech_maturity(payload)
    if pid == "policy_ai":
        return _wm406_render_policy_ai(payload)
    if pid in {"funding_vc", "vc_financing"}:
        return _wm406_render_funding_vc(payload)
    if pid == "github_trends":
        return _wm406_render_github(payload)

    # Provider-ready energy/infrastructure placeholders: explicit no-fake-live guard.
    if pid in {"oil_inventory", "pipeline_status", "strategic_storage", "global_fuel_shortage"}:
        return _wm406_render_provider_ready_energy(pid)

    # High-risk provider panels: leave the original body, add state discipline and scoring context.
    if pid in {"force_posture", "escalation_monitor", "economic_warfare", "disaster_cascade", "trade_policy", "cybersecurity", "ai_forecasts", "threat_timeline", "strategic_risk", "live_intel", "intel_flow"}:
        try:
            base = _wm38_panel_body_v405_prev(panel_id, payload, live_news, quote_rows, ctx, source_registry, display_style, country)
        except Exception:
            base = ""
        return _wm406_state_strip("institutional discipline", store, source_registry or []) + base

    return None


def _wm38_panel_body(panel_id: str, payload: dict[str, Any], live_news: Any, quote_rows: list[dict[str, Any]], ctx: dict[str, Any], source_registry: list[dict[str, Any]], display_style: str, country: str) -> str:
    """V4.0.6 final wrapper: specialized institutional panels, fallback to the validated V4.0.5 body."""
    try:
        upgraded = _wm406_panel_body(panel_id, payload, live_news, quote_rows, ctx, source_registry, display_style, country)
        if isinstance(upgraded, str) and upgraded.strip():
            return upgraded
    except Exception as exc:
        try:
            base = _wm38_panel_body_v405_prev(panel_id, payload, live_news, quote_rows, ctx, source_registry, display_style, country)
            return base + f'<div class="wm404-provider-note"><b>V4.0.6 fallback</b><span>SAFE</span><em>renderer fallback</em><small>{_wm406_esc(type(exc).__name__)}: {_wm406_esc(str(exc)[:160])}</small></div>'
        except Exception:
            return f'<div class="wm38-empty">Panel renderer fallback: {_wm406_esc(type(exc).__name__)}.</div>'
    return _wm38_panel_body_v405_prev(panel_id, payload, live_news, quote_rows, ctx, source_registry, display_style, country)


# === WM211 PANEL RATIONALIZATION & PROVIDER DISCIPLINE V4.0.6 END ===

# === WM211 FINAL PANEL POLISH V4.0.7 START ===
# Final conservative polish layer.
# Scope:
# - keep V4.0.6 provider discipline;
# - no map/layout/navigation changes;
# - fix last institutional weaknesses visible after V4.0.6:
#   * action queue promotion too permissive;
#   * P1 CONFIRM shown without primary/official evidence;
#   * generic tech/news noise routed into exploitable alerts;
#   * cross-source panel did not clearly separate WATCH / MONITOR / CONFIRM.

_WM407_RUNTIME_LABEL = "V4.0.7 Final Panel Polish"


def _wm407_norm(value: Any) -> str:
    try:
        return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()
    except Exception:
        return str(value or "").lower().strip()


def _wm407_topic(row: dict[str, Any]) -> str:
    return _wm407_norm(row.get("topic", "news")).split(" ")[0] or "news"


def _wm407_title(row: dict[str, Any]) -> str:
    return str(row.get("title") or row.get("headline") or "").strip()


def _wm407_source(row: dict[str, Any]) -> str:
    return str(row.get("source") or row.get("provider") or "").strip()


def _wm407_source_tier(row: dict[str, Any]) -> str:
    return str(row.get("source_tier") or "OPEN").upper().strip()


def _wm407_allowed_alert_topic(topic: str) -> bool:
    t = _wm407_norm(topic)
    return t in {
        "geo", "geopolitical", "conflict", "war", "military", "cyber", "energy", "supply",
        "disaster", "policy", "sanctions", "market", "markets", "infra", "infrastructure",
        "aviation", "shipping", "rates", "macro"
    }


def _wm407_is_low_action_noise(row: dict[str, Any]) -> bool:
    blob = _wm407_norm(_wm407_title(row) + " " + _wm407_source(row) + " " + str(row.get("raw", "")))
    topic = _wm407_topic(row)
    hard_noise = [
        "browser wars", "best alternatives to chrome", "safari", "shopping", "celebrity",
        "review", "opinion", "explainer", "how to", "ranked", "best laptops", "rumor",
        "stock retail investors are watching", "product launch", "conference preview"
    ]
    if any(k in blob for k in hard_noise):
        return True
    # Generic AI/tech pieces are useful in feeds but should not be promoted as exploitable risk alerts.
    if topic in {"ai", "tech", "news"} and not any(k in blob for k in [
        "cisa", "exploit", "ransomware", "sanction", "export control", "datacenter outage",
        "critical infrastructure", "energy", "grid", "war", "strike", "earthquake", "storm",
        "hormuz", "taiwan", "ukraine", "iran", "red sea", "pipeline"
    ]):
        return True
    return False


def _wm407_independent_source_count_for_topic(store: list[dict[str, Any]], topic: str) -> int:
    t = _wm407_norm(topic)
    sources = set()
    for r in store or []:
        if _wm407_norm(r.get("topic")) == t:
            s = _wm407_source(r)
            if s:
                sources.add(s)
    return len(sources)


def _wm407_has_primary_or_wire(row: dict[str, Any]) -> bool:
    tier = _wm407_source_tier(row)
    source_blob = _wm407_norm(_wm407_source(row) + " " + _wm407_title(row))
    if tier in {"PRIMARY", "WIRE", "OFFICIAL"}:
        return True
    official_markers = [
        "cisa", "nvd", "nist", "usgs", "eia", "fred", "ecb", "ofac", "treasury",
        "state department", "pentagon", "white house", "european commission", "un", "reliefweb",
        "gdacs", "nasa", "noaa", "reuters", "ap news", "bloomberg", "financial times"
    ]
    return any(x in source_blob for x in official_markers)


def _wm407_promotion(row: dict[str, Any], store: list[dict[str, Any]]) -> tuple[str, str, int]:
    """Return (priority, status, adjusted_score)."""
    topic = _wm407_topic(row)
    sev = _wm406_int(row.get("severity"), 55)
    conf = _wm406_int(row.get("confidence"), 55)
    fresh = _wm406_int(row.get("freshness"), 50)
    action = _wm406_int(row.get("actionability"), 50)
    src_count = max(_wm407_independent_source_count_for_topic(store, topic), _wm406_int(row.get("corroboration"), 1))
    primary = _wm407_has_primary_or_wire(row)
    fallback = bool(row.get("fallback"))
    noise = _wm407_is_low_action_noise(row)
    allowed = _wm407_allowed_alert_topic(topic)

    score = int(_wm406_clip(0.34 * sev + 0.30 * conf + 0.18 * fresh + 0.18 * action, 0, 100, 50))
    if src_count >= 3:
        score += 5
    if primary:
        score += 7
    if fallback:
        score -= 18
    if not allowed:
        score -= 20
    if noise:
        score -= 28
    score = int(_wm406_clip(score, 0, 100, 0))

    if noise or not allowed or score < 58:
        return "P3", "WATCH", score
    if primary and src_count >= 3 and score >= 78:
        return "P1", "CONFIRM", score
    if src_count >= 2 and score >= 66:
        return "P2", "MONITOR", score
    return "P3", "WATCH", score


def _wm407_alert_card(row: dict[str, Any], store: list[dict[str, Any]]) -> str:
    prio, status, score = _wm407_promotion(row, store)
    topic = _wm407_topic(row).upper()
    title = _wm407_title(row)
    source = _wm407_source(row) or "source"
    src_count = max(_wm407_independent_source_count_for_topic(store, row.get("topic", "news")), _wm406_int(row.get("corroboration"), 1))
    primary = "PRIMARY" if _wm407_has_primary_or_wire(row) else "OPEN"
    window = "6-24h" if prio == "P1" else ("24-72h" if prio == "P2" else "watchlist")
    action = "valider source primaire, mapper actifs/pays exposés, surveiller momentum 6h/24h"
    if prio == "P3":
        action = "conserver en veille; ne pas promouvoir sans source primaire ou corroboration indépendante"
    return (
        '<div class="wm405-alert-card">'
        f'<div><span>{_wm406_esc(prio)}</span><b>{_wm406_esc(status)}</b><strong>{score}</strong></div>'
        f'<h4>{_wm406_esc(title)}</h4>'
        f'<p>{_wm406_esc(topic)} · {src_count} source bucket(s) · {primary} · {window}</p>'
        f'<small>Source: {_wm406_esc(source)}</small>'
        f'<em>Action: {_wm406_esc(action)}.</em>'
        '</div>'
    )


def _wm406_render_alert_engine(store: list[dict[str, Any]], source_registry: list[dict[str, Any]]) -> str:
    store = store or []
    q = _wm406_quality_metrics(store, source_registry or [])
    clean = []
    for r in store:
        if not isinstance(r, dict):
            continue
        prio, status, score = _wm407_promotion(r, store)
        rr = dict(r)
        rr["_wm407_prio"] = prio
        rr["_wm407_status"] = status
        rr["_wm407_score"] = score
        clean.append(rr)
    clean.sort(key=lambda r: ({"P1": 3, "P2": 2, "P3": 1}.get(str(r.get("_wm407_prio")), 0), r.get("_wm407_score", 0), r.get("confidence", 0)), reverse=True)
    # Keep the queue useful: first show P1/P2, then only a small watch tail.
    actionable = [r for r in clean if str(r.get("_wm407_prio")) in {"P1", "P2"}]
    watch_tail = [r for r in clean if str(r.get("_wm407_prio")) == "P3"][:2]
    selected = (actionable + watch_tail)[:6]
    header_note = f'action queue hardened · {q["real"]} real / {q["fallback"]} fallback · primary/wire {q.get("primary",0) + q.get("wire",0)} · no fake P1'
    body = _wm406_state_strip("actionability triage", store, source_registry or [], header_note)
    body += ''.join(_wm407_alert_card(r, store) for r in selected)
    body += _wm406_table([
        {"RULE": "P1 CONFIRM", "REQUIREMENT": "primary/wire + 3 independent buckets + score ≥78"},
        {"RULE": "P2 MONITOR", "REQUIREMENT": "2+ independent buckets + score ≥66"},
        {"RULE": "P3 WATCH", "REQUIREMENT": "open-source/noise/weak corroboration kept out of action queue"},
    ], 3, keys=["RULE", "REQUIREMENT"])
    return body


def _wm406_render_cross_source(store: list[dict[str, Any]], source_registry: list[dict[str, Any]]) -> str:
    store = store or []
    counts = _wm406_topic_counts(store)
    sources = _wm406_topic_sources(store)
    rows = []
    for topic, count in sorted(counts.items(), key=lambda kv: kv[1], reverse=True):
        tstore = [r for r in store if _wm407_norm(r.get("topic")) == _wm407_norm(topic)]
        if not tstore:
            continue
        src_count = len(sources.get(topic, set()))
        avg_conf = int(sum(_wm406_int(r.get("confidence"), 0) for r in tstore) / max(1, len(tstore)))
        primary = any(_wm407_has_primary_or_wire(r) for r in tstore)
        fallback = any(bool(r.get("fallback")) for r in tstore)
        if primary and src_count >= 3 and avg_conf >= 72 and not fallback:
            promotion = "CONFIRM"
        elif src_count >= 2 and avg_conf >= 62:
            promotion = "MONITOR"
        else:
            promotion = "WATCH"
        rows.append({
            "SIGNAL": str(topic).upper(),
            "ITEMS": count,
            "SOURCES": src_count,
            "CONF": avg_conf,
            "PRIMARY": "YES" if primary else "NO",
            "PROMOTION": promotion,
        })
    return (
        _wm406_state_strip("independent-source corroboration", store, source_registry or [])
        + _wm406_table(rows, 9, keys=["SIGNAL", "ITEMS", "SOURCES", "CONF", "PRIMARY", "PROMOTION"])
        + '<div class="wm404-provider-note"><b>PROMOTION RULE</b><span>STRICT</span><em>CONFIRM requires primary/wire + 3 independent buckets</em><small>open-source repetition alone remains MONITOR/WATCH</small></div>'
    )


def _wm406_render_source_quality(store: list[dict[str, Any]], source_registry: list[dict[str, Any]]) -> str:
    q = _wm406_quality_metrics(store or [], source_registry or [])
    mode = "PRODUCTION-READY" if q["score"] >= 78 and (q.get("primary", 0) + q.get("wire", 0)) >= 3 else "STRICT WATCH"
    rows = [
        {"METRIC": "Quality", "VALUE": f'{q["score"]}/100', "COMMENT": mode},
        {"METRIC": "Real / fallback", "VALUE": f'{q["real"]}/{q["fallback"]}', "COMMENT": "fallback cannot promote P1"},
        {"METRIC": "Unique sources", "VALUE": q["sources"], "COMMENT": "source diversity"},
        {"METRIC": "Primary + wire", "VALUE": q.get("primary", 0) + q.get("wire", 0), "COMMENT": "promotion gate"},
        {"METRIC": "Duplicate risk", "VALUE": q.get("dup_risk", 0), "COMMENT": "dedupe control"},
        {"METRIC": "Freshness", "VALUE": f'{q.get("avg_fresh", 0)}/100', "COMMENT": "timestamp discipline"},
    ]
    top_sources = []
    try:
        for source in sorted(_wm406_unique_sources(store))[:8]:
            sub = [r for r in store if _wm407_source(r) == source]
            top_sources.append({"SOURCE": source, "ITEMS": len(sub), "AVG_CONF": int(sum(_wm406_int(r.get("confidence"), 0) for r in sub) / max(1, len(sub)))})
    except Exception:
        top_sources = []
    return (
        _wm406_state_strip("source quality controller", store or [], source_registry or [], f'{q["real"]} real / {q["fallback"]} fallback · {q["sources"]} sources · primary/wire {q.get("primary",0)+q.get("wire",0)}')
        + _wm406_table(rows, 8, keys=["METRIC", "VALUE", "COMMENT"])
        + '<h4 class="wm404-section-title">TOP SOURCES</h4>'
        + _wm406_table(top_sources, 8, keys=["SOURCE", "ITEMS", "AVG_CONF"])
    )


def _wm407_final_status_banner() -> str:
    return '<div class="wm404-provider-note"><b>V4.0.7 FINAL</b><span>LOCKED</span><em>provider discipline + no fake P1 + source promotion gate</em><small>map/navigation/layout unchanged</small></div>'


# Override wrapper only to append a small final marker to the source-quality panel.
try:
    _wm38_panel_body_v406_prev
except NameError:
    try:
        _wm38_panel_body_v406_prev = _wm38_panel_body
    except Exception:
        _wm38_panel_body_v406_prev = None


def _wm38_panel_body(panel_id: str, payload: dict[str, Any], live_news: Any, quote_rows: list[dict[str, Any]], ctx: dict[str, Any], source_registry: list[dict[str, Any]], display_style: str, country: str) -> str:
    try:
        body = _wm406_panel_body(panel_id, payload, live_news, quote_rows, ctx, source_registry, display_style, country)
        if isinstance(body, str) and body.strip():
            if str(panel_id) == "source_quality":
                body += _wm407_final_status_banner()
            return body
    except Exception as exc:
        try:
            if _wm38_panel_body_v406_prev:
                return _wm38_panel_body_v406_prev(panel_id, payload, live_news, quote_rows, ctx, source_registry, display_style, country)
        except Exception:
            pass
        return f'<div class="wm38-empty">V4.0.7 safe fallback: {_wm406_esc(type(exc).__name__)}.</div>'
    try:
        if _wm38_panel_body_v406_prev:
            return _wm38_panel_body_v406_prev(panel_id, payload, live_news, quote_rows, ctx, source_registry, display_style, country)
    except Exception:
        pass
    return '<div class="wm38-empty">Panel renderer unavailable.</div>'

# === WM211 FINAL PANEL POLISH V4.0.7 END ===

def _wm38_rows_table(rows: list[dict[str, Any]], limit: int = 8) -> str:
    if not rows:
        return '<div class="wm38-empty">Aucune ligne exploitable.</div>'
    normalized = [r for r in rows if isinstance(r, dict)][: int(limit)]
    keys: list[str] = []
    for r in normalized:
        for k in r.keys():
            if k not in keys and len(keys) < 4:
                keys.append(str(k))
    if not keys:
        return '<div class="wm38-empty">Données présentes mais non tabulaires.</div>'
    head = "".join(f'<th>{_wm38_panel_escape(k)}</th>' for k in keys)
    body = "".join('<tr>' + "".join(f'<td>{_wm38_panel_escape(r.get(k, ""))}</td>' for k in keys) + '</tr>' for r in normalized)
    return f'<table class="wm38-table"><thead><tr>{head}</tr></thead><tbody>{body}</tbody></table>'


def _wm38_render_panel(meta: dict[str, Any], payload: dict[str, Any], live_news: Any, quote_rows: list[dict[str, Any]], ctx: dict[str, Any], source_registry: list[dict[str, Any]], display_style: str, country: str) -> str:
    pid = str(meta.get("id", "panel"))
    title = str(meta.get("title") or _wm38_panel_title(pid))
    family = str(meta.get("family") or _wm38_family(pid, str(meta.get("category", ""))))
    style = _wm38_family_style(family)
    status = str(meta.get("status", "READY") or "READY").upper()
    locked = bool(meta.get("locked"))
    size = str(meta.get("size", "medium") or "medium")
    count_hint = ""
    try:
        if pid in {"world_news", "region_us", "region_europe", "region_mena", "region_africa", "region_latam", "region_apac"}:
            count_hint = str(len(_wm38_news_for_panel(pid, live_news, country)))
        elif pid in {"markets", "finance", "crypto"}:
            count_hint = str(len(quote_rows or [])) if pid != "crypto" else "3"
        elif pid == "infra_cascade":
            count_hint = str(max(244, len(source_registry or [])))
    except Exception:
        count_hint = ""
    body = _wm38_locked_panel(title) if locked else _wm38_panel_body(pid, payload, live_news, quote_rows, ctx, source_registry, display_style, country)
    status_class = "pro" if locked or status == "PRO" else ("cache" if status in {"CACHE", "LOCAL", "PROVIDER"} else "live")
    default_open = "1" if bool(meta.get("default_open")) and not locked else "0"
    count_badge = f'<b class="wm38-count">{_wm38_panel_escape(count_hint)}</b>' if count_hint else ""
    return "".join([
        f'<section class="wm38-panel wm38-{_wm38_panel_escape(size)}" draggable="true" data-panel="{_wm38_panel_escape(pid)}" data-family="{_wm38_panel_escape(family)}" data-default-open="{default_open}" style="--accent:{_wm38_panel_escape(style["accent"])};--soft:{_wm38_panel_escape(style["soft"])};--mid:{_wm38_panel_escape(style["mid"])};">',
        '<div class="wm38-panel-head">',
        f'<div><h3>{_wm38_panel_escape(title)}</h3><small>{_wm38_panel_escape(family)}</small></div>',
        '<div class="wm38-actions">',
        f'<span class="wm38-badge {status_class}"><i></i>{_wm38_panel_escape("PRO" if locked else ("EN DIRECT" if status in {"READY", "LIVE"} else status))}</span>',
        count_badge,
        '<button data-refresh title="Refresh panel">↻</button><button data-min title="Minimize">−</button><button data-max title="Maximize">□</button><button data-close title="Close">×</button>',
        '</div></div>',
        f'<div class="wm38-panel-body">{body}</div>',
        '<div class="wm38-panel-foot"><span>⋯</span><em>drag · resize · double-click header</em></div>',
        '</section>',
    ])


