def _wm_v34_original_layer_color(layer_id: str, spec_color: str) -> str:
    style = _WM_V34_ORIGINAL_POINT_STYLE.get(str(layer_id))
    if style:
        return str(style.get("color", spec_color))
    return spec_color


def _wm_v34_original_point_size(layer_id: str, severity: float) -> float:
    style = _WM_V34_ORIGINAL_POINT_STYLE.get(str(layer_id), {})
    mn = float(style.get("min", 5))
    mx = float(style.get("max", 18))
    # Original feel: compact at world zoom; larger only for truly severe events.
    return max(mn, min(mx, mn + max(0.0, float(severity) - 35.0) / 12.0))


def _scatter_trace_for_points(layer_df: pd.DataFrame, spec: LayerSpec, visible: bool) -> go.Scattergeo:  # V3.4 original fidelity override
    layer_id = str(spec.layer_id)
    style = _WM_V34_ORIGINAL_POINT_STYLE.get(layer_id, {})
    hover: list[str] = []
    sizes: list[float] = []
    colors: list[str] = []
    line_colors: list[str] = []

    for _, r in layer_df.iterrows():
        sev = _safe_float(r.get("severity"), 55) or 55
        sizes.append(_wm_v34_original_point_size(layer_id, sev))
        colors.append(_wm_v34_original_layer_color(layer_id, spec.color))
        line_colors.append(str(style.get("line", "rgba(255,255,255,.34)")))
        hover.append(
            f"<b>{html.escape(_text(r.get('title'), ''))}</b><br>"
            f"Layer: {html.escape(spec.label)}<br>"
            f"Source: {html.escape(_text(r.get('source_file'), ''))}<br>"
            f"Severity: {sev:.0f}/100<br>"
            f"{html.escape(_text(r.get('metadata'), ''))[:700]}"
        )

    return go.Scattergeo(
        lon=pd.to_numeric(layer_df["lon"], errors="coerce"),
        lat=pd.to_numeric(layer_df["lat"], errors="coerce"),
        mode="markers",
        name=spec.label,
        visible=True if visible else "legendonly",
        marker=dict(
            size=sizes,
            color=colors,
            opacity=0.86,
            symbol=str(style.get("symbol", "circle")),
            line=dict(width=0.75, color=line_colors),
        ),
        hovertext=hover,
        hoverinfo="text",
        meta={"layer_id": spec.layer_id, "wm_v211": True, "kind": "point", "style": "original-fidelity"},
        showlegend=False,
    )


def _wm_v34_original_polygon_trace(layer_df: pd.DataFrame, spec: LayerSpec, visible: bool) -> go.Scattergeo | None:
    lons: list[float | None] = []
    lats: list[float | None] = []
    text: list[str] = []
    for _, r in layer_df.iterrows():
        try:
            pts = json.loads(_text(r.get("points_json"), "[]"))
        except Exception:
            pts = []
        if not isinstance(pts, list) or len(pts) < 3:
            continue
        local_lons: list[float] = []
        local_lats: list[float] = []
        for p in pts:
            try:
                lon, lat = float(p[0]), float(p[1])
            except Exception:
                continue
            local_lons.append(lon)
            local_lats.append(lat)
        if len(local_lons) < 3:
            continue
        # close polygon explicitly for Plotly fill.
        if local_lons[0] != local_lons[-1] or local_lats[0] != local_lats[-1]:
            local_lons.append(local_lons[0]); local_lats.append(local_lats[0])
        lons.extend(local_lons + [None])
        lats.extend(local_lats + [None])
        label = _text(r.get("title"), spec.label)
        text.extend([f"<b>{html.escape(label)}</b><br>Layer: {html.escape(spec.label)}"] * (len(local_lons) + 1))
    if not lons:
        return None
    # Original WorldMonitor conflict fill: red translucent, red stroke. No extra legend.
    return go.Scattergeo(
        lon=lons,
        lat=lats,
        mode="lines",
        name=spec.label,
        visible=True if visible else "legendonly",
        line=dict(width=1.7, color="rgba(255,0,0,.74)"),
        fill="toself",
        fillcolor="rgba(255,0,0,.27)",
        opacity=1.0,
        hovertext=text,
        hoverinfo="text",
        meta={"layer_id": spec.layer_id, "wm_v211": True, "kind": "polygon", "style": "original-conflict-zone"},
        showlegend=False,
    )


def _line_trace_for_layer(layer_df: pd.DataFrame, spec: LayerSpec, visible: bool) -> go.Scattergeo | None:  # V3.4 original fidelity override
    if str(spec.layer_id) == "conflicts":
        poly_df = layer_df[layer_df["kind"].astype(str).eq("polygon")].copy()
        tr = _wm_v34_original_polygon_trace(poly_df, spec, visible)
        if tr is not None:
            return tr

    lons: list[float | None] = []
    lats: list[float | None] = []
    text: list[str] = []
    for _, r in layer_df.iterrows():
        try:
            pts = json.loads(_text(r.get("points_json"), "[]"))
        except Exception:
            pts = []
        if not isinstance(pts, list) or len(pts) < 2:
            continue
        for p in pts:
            try:
                lon, lat = float(p[0]), float(p[1])
            except Exception:
                continue
            lons.append(lon); lats.append(lat)
            text.append(f"<b>{html.escape(_text(r.get('title'), ''))}</b><br>Layer: {html.escape(spec.label)}")
        lons.append(None); lats.append(None); text.append("")
    if not lons:
        return None

    style = _WM_V34_ORIGINAL_LINE_STYLE.get(str(spec.layer_id), {})
    return go.Scattergeo(
        lon=lons,
        lat=lats,
        mode="lines",
        name=spec.label,
        visible=True if visible else "legendonly",
        line=dict(width=float(style.get("width", 1.25)), color=str(style.get("color", spec.color))),
        opacity=0.72,
        hovertext=text,
        hoverinfo="text",
        meta={"layer_id": spec.layer_id, "wm_v211": True, "kind": "line", "style": "original-fidelity"},
        showlegend=False,
    )


def build_plotly_figure_v211(
    objects: pd.DataFrame,
    registry: pd.DataFrame,
    projection: str = "orthographic",
    region: str = "Global",
    max_points_per_layer: int = 1200,
    fig_height: int = 780,
    projection_scale: float | None = None,
) -> go.Figure:  # V3.4 original fidelity override
    fig = go.Figure()
    if objects is None or objects.empty:
        work = pd.DataFrame(columns=["layer_id", "kind", "lat", "lon", "points_json"])
    else:
        work = objects.copy()

    enabled_map = {str(r.layer_id): bool(r.enabled) for _, r in registry.iterrows()}

    # Original visual hierarchy: territorial conflict polygons / infrastructure routes first,
    # then point markers above. No synthetic halos or custom legend.
    for spec in LAYER_SPECS:
        sub = work[work["layer_id"] == spec.layer_id].copy() if not work.empty else pd.DataFrame()
        if sub.empty:
            continue
        visible = enabled_map.get(spec.layer_id, False)
        line_df = sub[sub["kind"].astype(str).isin(["line", "polygon"])].copy()
        if not line_df.empty:
            tr = _line_trace_for_layer(line_df, spec, visible)
            if tr is not None:
                fig.add_trace(tr)

    for spec in LAYER_SPECS:
        sub = work[work["layer_id"] == spec.layer_id].copy() if not work.empty else pd.DataFrame()
        if sub.empty:
            continue
        visible = enabled_map.get(spec.layer_id, False)
        point_df = sub[sub["kind"].astype(str).eq("point")].dropna(subset=["lat", "lon"]).copy()
        # Conflict zones in the original are zones, not normal event dots. Suppress generic conflict dots.
        if str(spec.layer_id) == "conflicts":
            continue
        if len(point_df) > int(max_points_per_layer):
            point_df = point_df.sort_values("severity", ascending=False).head(int(max_points_per_layer))
        if not point_df.empty:
            fig.add_trace(_scatter_trace_for_points(point_df, spec, visible))

    rotation_map = {
        "Global": dict(lon=15, lat=0, roll=0),
        "Americas": dict(lon=85, lat=-5, roll=0),
        "Europe": dict(lon=-10, lat=-8, roll=0),
        "MENA": dict(lon=-43, lat=-5, roll=0),
        "Asia": dict(lon=-105, lat=-5, roll=0),
        "Africa": dict(lon=-20, lat=0, roll=0),
        "Pacific": dict(lon=-165, lat=5, roll=0),
    }
    is_globe = projection == "3D globe"
    proj_type = "orthographic" if is_globe else "equirectangular"
    if projection_scale is None:
        projection_scale = 1.22 if is_globe else 1.0

    geo_kwargs = dict(
        projection_type=proj_type,
        projection_scale=float(projection_scale),
        showland=True,
        landcolor="rgba(15,23,42,0.98)",
        showocean=True,
        oceancolor="rgba(2,6,16,0.98)",
        showcountries=True,
        countrycolor="rgba(148,163,184,0.24)",
        showcoastlines=True,
        coastlinecolor="rgba(148,163,184,0.20)",
        showframe=False,
        bgcolor="rgba(0,0,0,0)",
        lataxis_showgrid=True,
        lonaxis_showgrid=True,
        lataxis_gridcolor="rgba(56,189,248,0.08)",
        lonaxis_gridcolor="rgba(56,189,248,0.08)",
        domain=dict(x=[0.0, 1.0], y=[0.0, 1.0]),
    )
    if is_globe:
        geo_kwargs["projection_rotation"] = rotation_map.get(region, rotation_map["Global"])
    else:
        geo_kwargs["center"] = dict(lon=0, lat=8)
        geo_kwargs["lonaxis_range"] = [-180, 180]
        geo_kwargs["lataxis_range"] = [-62, 84]
    fig.update_geos(**geo_kwargs)

    fig.update_layout(
        height=int(max(520, fig_height)),
        margin=dict(l=0, r=0, t=0, b=0),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color="#e5edf7"),
    )
    return fig


# Preserve the V3.3.2 HTML shell and only adjust labels. No semantic legend injection.
_WM_V332_MAP_COMPONENT_HTML = _map_component_html

def _map_component_html(fig: go.Figure, registry: pd.DataFrame, stage_height: int = 860, active_time: str = "24h", projection_mode: str = "2D") -> str:  # V3.4 original fidelity HTML label override
    try:
        html_payload = _WM_V332_MAP_COMPONENT_HTML(fig, registry, stage_height, active_time, projection_mode)
    except TypeError:
        html_payload = _WM_V332_MAP_COMPONENT_HTML(fig, registry, stage_height)
    html_payload = re.sub(r"V3\.3\.2", "V3.4", html_payload)
    html_payload = re.sub(r"source mix refined", "original map fidelity", html_payload)
    html_payload = re.sub(r"Source Mix", "Original Map Fidelity", html_payload)
    html_payload = re.sub(r"MAP LAYERS LIVE · V3\.4 · WORKSPACE", "MAP LAYERS LIVE · V3.4 · ORIGINAL", html_payload)
    # Guard against accidental semantic artifacts if this file is composed over a previous V3.4.
    html_payload = re.sub(r"<div class=\"wm34-semantic-legend\">.*?</div>", "", html_payload, flags=re.S)
    html_payload = html_payload.replace("SEMANTIC MAP", "")
    return html_payload


