def _wm35_layer_id(layer_id: Any) -> str:
    raw = str(layer_id or "").strip()
    return _WM35_LAYER_ALIASES.get(raw, raw)


def _wm35_rgb(color: str) -> tuple[int, int, int]:
    s = str(color or "").strip()
    if s.startswith("#"):
        s = s[1:]
        if len(s) == 3:
            s = "".join(ch * 2 for ch in s)
        if len(s) >= 6:
            try:
                return tuple(int(s[i:i + 2], 16) for i in (0, 2, 4))  # type: ignore[return-value]
            except Exception:
                pass
    m = re.match(r"rgba?\(([^)]+)\)", s)
    if m:
        vals = [x.strip() for x in m.group(1).split(",")]
        if len(vals) >= 3:
            try:
                return (int(float(vals[0])), int(float(vals[1])), int(float(vals[2])))
            except Exception:
                pass
    return (56, 189, 248)


def _wm35_rgba(color_or_rgb: Any, alpha: float) -> str:
    rgb = color_or_rgb if isinstance(color_or_rgb, tuple) else _wm35_rgb(str(color_or_rgb))
    r, g, b = [max(0, min(255, int(v))) for v in rgb]
    a = max(0.0, min(1.0, float(alpha)))
    return f"rgba({r},{g},{b},{a:.3f})"


def _wm35_mix(c1: Any, c2: Any, t: float) -> tuple[int, int, int]:
    a = _wm35_rgb(str(c1)) if not isinstance(c1, tuple) else c1
    b = _wm35_rgb(str(c2)) if not isinstance(c2, tuple) else c2
    u = max(0.0, min(1.0, float(t)))
    return tuple(int(round(x + (y - x) * u)) for x, y in zip(a, b))


def _wm35_meta(row: Any) -> dict[str, Any]:
    try:
        meta = row.get("metadata")
    except Exception:
        meta = None
    if isinstance(meta, dict):
        return dict(meta)
    s = _text(meta, "").strip()
    if not s:
        return {}
    try:
        obj = json.loads(s)
        return obj if isinstance(obj, dict) else {}
    except Exception:
        return {"raw": s}


def _wm35_score(row: Any) -> float:
    sev = _safe_float(row.get("severity") if hasattr(row, "get") else None, None)
    if sev is None:
        sev = 55.0
    meta = _wm35_meta(row)
    for k in ("severity", "intensity", "risk", "risk_score", "score", "confidence", "delay", "delay_min", "count", "cases", "magnitude"):
        v = _safe_float(meta.get(k), None)
        if v is None:
            continue
        if k == "magnitude":
            v = min(100.0, 30.0 + float(v) * 10.0)
        elif k in {"count", "cases"}:
            v = min(100.0, 18.0 + math.log1p(max(0.0, float(v))) * 15.0)
        elif k in {"delay", "delay_min"}:
            v = min(100.0, 35.0 + float(v) * 1.4)
        sev = max(float(sev), float(v))
    return float(max(0.0, min(100.0, sev)))


def _wm35_bucket(score: float) -> str:
    if score >= 78:
        return "high"
    if score >= 52:
        return "mid"
    return "low"


# Original-like visual grammar by layer. Marker types are constrained by Plotly Scattergeo.
