def _wm35_style(layer_id: str, spec: LayerSpec | None = None) -> dict[str, Any]:
    lid = _wm35_layer_id(layer_id)
    style = dict(_WM35_STYLE.get(lid, {}))
    if spec is not None:
        style.setdefault("low", spec.color)
        style.setdefault("mid", spec.color)
        style.setdefault("high", spec.color)
        style.setdefault("outline", "rgba(255,255,255,.32)")
        style.setdefault("min", 4.0)
        style.setdefault("max", 10.0)
        style.setdefault("alpha", .75)
    return style


def _wm35_color_for_row(style: dict[str, Any], row: Any, score: float, fallback: str) -> str:
    if style.get("palette"):
        palette = list(style.get("palette") or [fallback])
        key = _text(row.get("title") if hasattr(row, "get") else "", "") + "|" + json.dumps(_wm35_meta(row), ensure_ascii=False, default=str)
        bucket = int(hashlib.md5(key.encode("utf-8", "ignore")).hexdigest()[:8], 16) % max(1, len(palette))
        return _wm35_rgba(palette[bucket], float(style.get("alpha", .78)))
    low = style.get("low", fallback)
    mid = style.get("mid", fallback)
    high = style.get("high", fallback)
    rgb = _wm35_mix(low, mid, score / 50.0) if score <= 50 else _wm35_mix(mid, high, (score - 50.0) / 50.0)
    alpha = float(style.get("alpha", .78))
    if score >= 78:
        alpha = min(1.0, alpha + .10)
    return _wm35_rgba(rgb, alpha)


def _wm35_size(style: dict[str, Any], score: float) -> float:
    mn = float(style.get("min", 4.0))
    mx = float(style.get("max", 10.0))
    return mn + (mx - mn) * ((max(0.0, min(100.0, score)) / 100.0) ** .82)



def _wm35_hover(row: Any, spec: LayerSpec, score: float, kind_label: str = "Layer") -> str:
    """Compact hover for map objects. Source/ZIP/provider lineage stays in diagnostics."""
    meta = _wm35_meta(row)
    title = html.escape(_text(row.get("title") if hasattr(row, "get") else "", spec.label))
    bits: list[str] = []
    for key in ("country", "region", "status", "magnitude", "count", "delay", "severity"):
        val = meta.get(key)
        if val is not None and _text(val, "").strip():
            bits.append(f"<br><span style='color:#9ca3af'>{html.escape(key)}:</span> {html.escape(_text(val))}")
    return (
        f"<b>{title}</b>"
        f"<br><span style='color:#7dd3fc'>{html.escape(spec.label)}</span> · {html.escape(kind_label)}"
        f"<br>Intensity: <b>{score:.0f}/100</b>"
        + "".join(bits[:5])
    )
def _wm35_arc_points(points: list[Any], bend: float = 0.16) -> tuple[list[float | None], list[float | None]]:
    if len(points) < 2:
        return [], []
    out_lon: list[float | None] = []
    out_lat: list[float | None] = []
    usable: list[tuple[float, float]] = []
    for p in points:
        try:
            usable.append((float(p[0]), float(p[1])))
        except Exception:
            pass
    if len(usable) < 2:
        return [], []
    for (lon0, lat0), (lon1, lat1) in zip(usable[:-1], usable[1:]):
        # unwrap dateline for a cleaner equirectangular arc
        dlon = lon1 - lon0
        if dlon > 180:
            lon1 -= 360
        elif dlon < -180:
            lon1 += 360
        steps = 26
        dx = lon1 - lon0
        dy = lat1 - lat0
        amp = min(24.0, max(5.0, (abs(dx) + abs(dy)) * bend))
        for i in range(steps + 1):
            t = i / steps
            lon = lon0 + dx * t
            lat = lat0 + dy * t + math.sin(math.pi * t) * amp * (1 if dx >= 0 else -1) * .28
            if lon > 180:
                lon -= 360
            if lon < -180:
                lon += 360
            out_lon.append(lon)
            out_lat.append(lat)
        out_lon.append(None)
        out_lat.append(None)
    return out_lon, out_lat


def _wm35_point_trace(layer_df: pd.DataFrame, spec: LayerSpec, visible: bool) -> go.Scattergeo:
    lid = _wm35_layer_id(spec.layer_id)
    style = _wm35_style(lid, spec)
    sizes: list[float] = []
    colors: list[str] = []
    outlines: list[str] = []
    hover: list[str] = []
    for _, r in layer_df.iterrows():
        score = _wm35_score(r)
        colors.append(_wm35_color_for_row(style, r, score, spec.color))
        sizes.append(_wm35_size(style, score))
        outlines.append(str(style.get("outline", "rgba(255,255,255,.32)")))
        hover.append(_wm35_hover(r, spec, score, "point"))
    return go.Scattergeo(
        lon=pd.to_numeric(layer_df["lon"], errors="coerce"),
        lat=pd.to_numeric(layer_df["lat"], errors="coerce"),
        mode="markers",
        name=spec.label,
        visible=True if visible else "legendonly",
        marker=dict(
            size=sizes,
            color=colors,
            opacity=1.0,
            symbol="circle",
            line=dict(width=float(style.get("stroke_width", .75)), color=outlines),
        ),
        hovertext=hover,
        hoverinfo="text",
        meta={"layer_id": lid, "wm_v211": True, "kind": "point", "style": "v35-original-layer-design"},
        showlegend=False,
    )


def _wm35_zone_fallback_trace(point_df: pd.DataFrame, spec: LayerSpec, visible: bool) -> list[go.Scattergeo]:
    # If a zone layer has only points, draw small soft territorial cells instead of generic dots.
    lid = _wm35_layer_id(spec.layer_id)
    style = _wm35_style(lid, spec)
    traces: list[go.Scattergeo] = []
    for _, r in point_df.iterrows():
        try:
            lat = float(r.get("lat")); lon = float(r.get("lon"))
        except Exception:
            continue
        score = _wm35_score(r)
        bucket_color = style.get(_wm35_bucket(score), spec.color)
        radius_lon = 1.8 + score / 34.0
        radius_lat = 1.2 + score / 48.0
        lons: list[float] = []
        lats: list[float] = []
        for i in range(33):
            a = 2 * math.pi * i / 32
            lons.append(lon + math.cos(a) * radius_lon)
            lats.append(lat + math.sin(a) * radius_lat)
        traces.append(go.Scattergeo(
            lon=lons, lat=lats, mode="lines", name=spec.label,
            visible=True if visible else "legendonly",
            line=dict(width=float(style.get("width", 1.0)), color=_wm35_rgba(bucket_color, float(style.get("line", .55)))),
            fill="toself",
            fillcolor=_wm35_rgba(bucket_color, float(style.get("fill_low", .15)) + (float(style.get("fill_high", .30)) - float(style.get("fill_low", .15))) * score / 100.0),
            hovertext=[_wm35_hover(r, spec, score, "zone fallback")] * len(lons),
            hoverinfo="text",
            meta={"layer_id": lid, "wm_v211": True, "kind": "zone-fallback", "style": "v35-original-layer-design"},
            showlegend=False,
        ))
    return traces


def _wm35_polygon_traces(layer_df: pd.DataFrame, spec: LayerSpec, visible: bool) -> list[go.Scattergeo]:
    lid = _wm35_layer_id(spec.layer_id)
    style = _wm35_style(lid, spec)
    out: list[go.Scattergeo] = []
    for _, r in layer_df.iterrows():
        try:
            pts = json.loads(_text(r.get("points_json"), "[]"))
        except Exception:
            pts = []
        if not isinstance(pts, list) or len(pts) < 3:
            continue
        lons: list[float] = []
        lats: list[float] = []
        for p in pts:
            try:
                lon, lat = float(p[0]), float(p[1])
            except Exception:
                continue
            lons.append(lon); lats.append(lat)
        if len(lons) < 3:
            continue
        if lons[0] != lons[-1] or lats[0] != lats[-1]:
            lons.append(lons[0]); lats.append(lats[0])
        score = _wm35_score(r)
        color = style.get(_wm35_bucket(score), spec.color)
        fill_alpha = float(style.get("fill_low", .16)) + (float(style.get("fill_high", .32)) - float(style.get("fill_low", .16))) * score / 100.0
        out.append(go.Scattergeo(
            lon=lons, lat=lats, mode="lines", name=spec.label,
            visible=True if visible else "legendonly",
            line=dict(width=float(style.get("width", 1.15)), color=_wm35_rgba(color, float(style.get("line", .60)))),
            fill="toself", fillcolor=_wm35_rgba(color, fill_alpha), opacity=1.0,
            hovertext=[_wm35_hover(r, spec, score, "zone")] * len(lons), hoverinfo="text",
            meta={"layer_id": lid, "wm_v211": True, "kind": "polygon", "style": "v35-original-layer-design"},
            showlegend=False,
        ))
    return out


def _wm35_line_trace(layer_df: pd.DataFrame, spec: LayerSpec, visible: bool) -> go.Scattergeo | None:
    lid = _wm35_layer_id(spec.layer_id)
    style = _wm35_style(lid, spec)
    lons: list[float | None] = []
    lats: list[float | None] = []
    hover: list[str] = []
    curve = bool(style.get("curve", False))
    score_acc: list[float] = []
    for _, r in layer_df.iterrows():
        try:
            pts = json.loads(_text(r.get("points_json"), "[]"))
        except Exception:
            pts = []
        if not isinstance(pts, list) or len(pts) < 2:
            continue
        score = _wm35_score(r)
        score_acc.append(score)
        if curve:
            alon, alat = _wm35_arc_points(pts)
            lons.extend(alon); lats.extend(alat)
            hover.extend([_wm35_hover(r, spec, score, "route")] * len(alon))
        else:
            for p in pts:
                try:
                    lon, lat = float(p[0]), float(p[1])
                except Exception:
                    continue
                lons.append(lon); lats.append(lat); hover.append(_wm35_hover(r, spec, score, "route"))
            lons.append(None); lats.append(None); hover.append("")
    if not lons:
        return None
    score = float(np.nanmean(score_acc)) if score_acc else 60.0
    color = _wm35_color_for_row(style, pd.Series({"title": spec.label, "metadata": {}}), score, spec.color)
    return go.Scattergeo(
        lon=lons, lat=lats, mode="lines", name=spec.label,
        visible=True if visible else "legendonly",
        line=dict(width=float(style.get("width", 1.2)), color=color),
        opacity=float(style.get("alpha", .62)),
        hovertext=hover, hoverinfo="text",
        meta={"layer_id": lid, "wm_v211": True, "kind": "line", "style": "v35-original-layer-design"},
        showlegend=False,
    )


def _wm35_daynight_trace(visible: bool) -> go.Scattergeo:
    # Streamlit/Plotly approximation of the original terminator overlay.
    now = _dt.datetime.utcnow()
    utc_hour = now.hour + now.minute / 60.0
    night_center_lon = ((utc_hour - 0.0) * 15.0 + 180.0) % 360.0 - 180.0
    lons: list[float] = []
    lats: list[float] = []
    for a in np.linspace(-95, 95, 80):
        lons.append(float(night_center_lon + a))
        lats.append(86.0)
    for a in np.linspace(95, -95, 80):
        lons.append(float(night_center_lon + a))
        lats.append(-86.0)
    lons = [((x + 180.0) % 360.0) - 180.0 for x in lons]
    return go.Scattergeo(
        lon=lons, lat=lats, mode="lines", name="Jour/Nuit",
        visible=True if visible else "legendonly",
        line=dict(width=.6, color="rgba(148,163,184,.24)"),
        fill="toself", fillcolor="rgba(15,23,42,.34)", opacity=1.0,
        hoverinfo="skip", showlegend=False,
        meta={"layer_id": "dayNight", "wm_v211": True, "kind": "terminator", "style": "v35-original-layer-design"},
    )


def build_plotly_figure_v211(
    objects: pd.DataFrame,
    registry: pd.DataFrame,
    projection: str = "orthographic",
    region: str = "Global",
    max_points_per_layer: int = 2200,
    fig_height: int = 780,
    projection_scale: float | None = None,
) -> go.Figure:  # V3.5 override
    fig = go.Figure()
    work = objects.copy() if isinstance(objects, pd.DataFrame) and not objects.empty else pd.DataFrame(columns=["layer_id", "kind", "lat", "lon", "points_json"])
    if not work.empty and "layer_id" in work.columns:
        work["layer_id"] = work["layer_id"].astype(str).map(_wm35_layer_id)

    reg = registry.copy() if isinstance(registry, pd.DataFrame) else pd.DataFrame(columns=["layer_id", "enabled"])
    if not reg.empty and "layer_id" in reg.columns:
        reg["layer_id"] = reg["layer_id"].astype(str).map(_wm35_layer_id)
        reg = reg.drop_duplicates(subset=["layer_id"], keep="last")
    enabled_map = {str(r.layer_id): bool(r.enabled) for _, r in reg.iterrows()} if not reg.empty else {}

    # Ensure canonical specs are used once, but preserve the original drawer order.
    specs: list[LayerSpec] = []
    seen: set[str] = set()
    for spec in LAYER_SPECS:
        lid = _wm35_layer_id(spec.layer_id)
        if lid in seen:
            continue
        seen.add(lid)
        specs.append(LayerSpec(lid, spec.label, spec.group, spec.renderer, spec.default, spec.color, spec.icon, spec.source_class, spec.note))

    # Day/night is a synthetic utility overlay only when selected.
    if enabled_map.get("dayNight", False):
        fig.add_trace(_wm35_daynight_trace(True))

    # 1) zones below everything else
    zone_layers = {"conflicts", "ciiInstability", "sanctions"}
    for spec in specs:
        lid = _wm35_layer_id(spec.layer_id)
        if lid not in zone_layers or work.empty:
            continue
        sub = work[work["layer_id"] == lid].copy()
        if sub.empty:
            continue
        visible = enabled_map.get(lid, False)
        poly_df = sub[sub["kind"].astype(str).eq("polygon")].copy()
        for tr in _wm35_polygon_traces(poly_df, spec, visible):
            fig.add_trace(tr)
        # point fallback as soft local zones, not plain dots
        point_df = sub[sub["kind"].astype(str).eq("point")].dropna(subset=["lat", "lon"]).copy()
        for tr in _wm35_zone_fallback_trace(point_df, spec, visible):
            fig.add_trace(tr)

    # 2) infrastructure routes / flows
    for spec in specs:
        lid = _wm35_layer_id(spec.layer_id)
        if lid in zone_layers or work.empty:
            continue
        sub = work[work["layer_id"] == lid].copy()
        if sub.empty:
            continue
        line_df = sub[sub["kind"].astype(str).isin(["line", "polygon"])].copy()
        if line_df.empty:
            continue
        visible = enabled_map.get(lid, False)
        if lid == "orbitalSurveillance":
            # Render both line and polygon swaths as translucent blue route traces.
            line_df = sub[sub["kind"].astype(str).isin(["line", "polygon"])].copy()
        tr = _wm35_line_trace(line_df, spec, visible)
        if tr is not None:
            fig.add_trace(tr)

    # 3) dense points above routes. Conflict/CII/sanctions point fallback already handled as zones.
    for spec in specs:
        lid = _wm35_layer_id(spec.layer_id)
        if lid in zone_layers or work.empty:
            continue
        sub = work[work["layer_id"] == lid].copy()
        if sub.empty:
            continue
        point_df = sub[sub["kind"].astype(str).eq("point")].dropna(subset=["lat", "lon"]).copy()
        if point_df.empty:
            continue
        # retain dense original-like layers, cap only pathological cases
        layer_cap = 4500 if lid in {"fires", "weather", "gpsJamming", "maritimeTraffic", "ucdpEvents"} else int(max_points_per_layer)
        if len(point_df) > layer_cap:
            point_df = point_df.sort_values("severity", ascending=False).head(layer_cap)
        visible = enabled_map.get(lid, False)
        fig.add_trace(_wm35_point_trace(point_df, spec, visible))

    rotation_map = {
        "Global": dict(lon=15, lat=0, roll=0),
        "Americas": dict(lon=85, lat=-5, roll=0),
        "Europe": dict(lon=-10, lat=-8, roll=0),
        "MENA": dict(lon=-43, lat=-5, roll=0),
        "Asia": dict(lon=-105, lat=-5, roll=0),
        "Africa": dict(lon=-20, lat=0, roll=0),
        "Pacific": dict(lon=-165, lat=5, roll=0),
    }
    is_globe = projection == "3D globe"
    proj_type = "orthographic" if is_globe else "equirectangular"
    if projection_scale is None:
        projection_scale = 1.18 if is_globe else 1.0

    geo_kwargs = dict(
        projection_type=proj_type,
        projection_scale=float(projection_scale),
        showland=True,
        landcolor="rgba(45,45,45,0.98)",
        showocean=True,
        oceancolor="rgba(18,18,18,0.99)",
        showcountries=True,
        countrycolor="rgba(190,198,208,0.30)",
        showcoastlines=True,
        coastlinecolor="rgba(190,198,208,0.22)",
        showlakes=True,
        lakecolor="rgba(20,20,20,0.95)",
        showframe=False,
        bgcolor="rgba(0,0,0,0)",
        lataxis_showgrid=True,
        lonaxis_showgrid=True,
        lataxis_gridcolor="rgba(255,255,255,0.045)",
        lonaxis_gridcolor="rgba(255,255,255,0.045)",
        domain=dict(x=[0.0, 1.0], y=[0.0, 1.0]),
    )
    if is_globe:
        geo_kwargs["projection_rotation"] = rotation_map.get(region, rotation_map["Global"])
    else:
        geo_kwargs["center"] = dict(lon=0, lat=10)
        geo_kwargs["lonaxis_range"] = [-180, 180]
        geo_kwargs["lataxis_range"] = [-62, 84]
    fig.update_geos(**geo_kwargs)
    fig.update_layout(
        height=int(max(560, fig_height)),
        margin=dict(l=0, r=0, t=0, b=0),
        paper_bgcolor="rgba(0,0,0,0)",
        plot_bgcolor="rgba(0,0,0,0)",
        font=dict(color="#e5edf7", family="Inter, ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace"),
    )
    return fig


# Keep shell, but inject original-like map CSS and relabel runtime.
_WM35_PREV_MAP_COMPONENT_HTML = _map_component_html

def _map_component_html(fig: go.Figure, registry: pd.DataFrame, stage_height: int = 860, active_time: str = "24h", projection_mode: str = "2D") -> str:  # V3.5 shell override
    try:
        html_payload = _WM35_PREV_MAP_COMPONENT_HTML(fig, registry, stage_height=stage_height, active_time=active_time, projection_mode=projection_mode)
    except TypeError:
        html_payload = _WM35_PREV_MAP_COMPONENT_HTML(fig, registry, stage_height)
    html_payload = re.sub(r"V3\.4", "V3.5", html_payload)
    html_payload = re.sub(r"original map fidelity", "original layer design", html_payload)
    html_payload = re.sub(r"MAP LAYERS LIVE · V3\.5 · ORIGINAL", "MAP LAYERS LIVE · V3.5 · ORIGINAL-LIKE", html_payload)
    extra_css = """
<style id="wm35-original-layer-design-css">
  .wm-map-shell,.wm-map-stage,.wm-map-plot,.plot-container,.svg-container{width:100%!important;max-width:none!important;}
  .wm-map-shell{background:#05070b!important;}
  .wm-map-stage{min-height:720px!important;border-color:rgba(56,189,248,.16)!important;box-shadow:inset 0 0 90px rgba(10,25,45,.42)!important;}
  .wm-map-drawer{backdrop-filter:blur(7px);background:rgba(0,0,0,.82)!important;border-color:rgba(56,189,248,.20)!important;}
  .wm-timebar button,.wm-proj button{background:#060606!important;border-color:rgba(255,255,255,.14)!important;}
  .wm-timebar button.active,.wm-proj button.active{background:#39ff88!important;color:#020202!important;border-color:#39ff88!important;}
</style>
"""
    if "wm35-original-layer-design-css" not in html_payload:
        html_payload = html_payload.replace("</head>", extra_css + "</head>") if "</head>" in html_payload else extra_css + html_payload
    return html_payload


