def _wm360_iso_from_text(blob: Any) -> str | None:
    s = str(blob or "").lower()
    if not s:
        return None

    # Direct ISO-3 tokens first.
    for token in re.findall(r"\b[A-Z]{3}\b", str(blob or "")):
        if token in {v for v in _WM360_COUNTRY_KEYWORDS.values()}:
            return token

    for key, iso in sorted(_WM360_COUNTRY_KEYWORDS.items(), key=lambda kv: len(kv[0]), reverse=True):
        if re.search(r"(?<![a-z0-9])" + re.escape(key.lower()) + r"(?![a-z0-9])", s):
            return iso
    return None


def _wm360_iso_from_latlon(lat: Any, lon: Any) -> str | None:
    la = _safe_float(lat)
    lo = _safe_float(lon)
    if la is None or lo is None:
        return None
    for iso, lat_min, lat_max, lon_min, lon_max in _WM360_BOUNDS:
        if lat_min <= la <= lat_max and lon_min <= lo <= lon_max:
            return iso
    return None


def _wm360_row_blob(row: Any) -> str:
    bits: list[str] = []
    for col in ("title", "layer_label", "group", "source_file", "collection", "metadata", "country", "region"):
        try:
            value = row.get(col)
        except Exception:
            value = None
        if value is not None:
            bits.append(_text(value, ""))
    meta = None
    try:
        raw = row.get("metadata")
        if isinstance(raw, str) and raw.strip().startswith("{"):
            meta = json.loads(raw)
    except Exception:
        meta = None
    if isinstance(meta, dict):
        for k in ("country", "iso3", "iso", "location", "region", "name", "target", "description", "status"):
            if meta.get(k) is not None:
                bits.append(_text(meta.get(k), ""))
    return " | ".join([b for b in bits if b])


def _wm360_score(row: Any, default: float = 65.0) -> float:
    try:
        return float(_wm35_score(row))
    except Exception:
        pass
    for k in ("severity", "criticality", "score", "value", "z"):
        try:
            value = row.get(k)
        except Exception:
            value = None
        x = _safe_float(value)
        if x is not None:
            return max(0.0, min(100.0, float(x)))
    return default


def _wm360_zone_fallback(layer_id: str) -> list[tuple[str, float, str]]:
    if layer_id == "sanctions":
        return list(_WM360_SANCTIONS_FALLBACK)
    if layer_id == "conflicts":
        return list(_WM360_CONFLICT_FALLBACK)
    if layer_id == "ciiInstability":
        return list(_WM360_CII_FALLBACK)
    return []


def _wm360_zone_records(objects: pd.DataFrame, layer_id: str) -> list[dict[str, Any]]:
    lid = _wm360_layer_id(layer_id)
    bucket: dict[str, dict[str, Any]] = {}

    if isinstance(objects, pd.DataFrame) and not objects.empty and "layer_id" in objects.columns:
        work = objects.copy()
        work["_wm360_lid"] = work["layer_id"].astype(str).map(_wm360_layer_id)
        sub = work[work["_wm360_lid"].eq(lid)].copy()
    else:
        sub = pd.DataFrame()

    if not sub.empty:
        for _, r in sub.iterrows():
            blob = _wm360_row_blob(r)
            iso = _wm360_iso_from_text(blob)
            if iso is None:
                iso = _wm360_iso_from_latlon(r.get("lat"), r.get("lon"))
            if iso is None and _text(r.get("points_json"), ""):
                # Try polygon centroid if legacy geometry was present.
                try:
                    pts = json.loads(_text(r.get("points_json"), "[]"))
                    xs = [float(p[0]) for p in pts if isinstance(p, (list, tuple)) and len(p) >= 2]
                    ys = [float(p[1]) for p in pts if isinstance(p, (list, tuple)) and len(p) >= 2]
                    if xs and ys:
                        iso = _wm360_iso_from_latlon(sum(ys) / len(ys), sum(xs) / len(xs))
                except Exception:
                    iso = None
            if iso is None:
                continue

            score = _wm360_score(r, 72.0 if lid == "conflicts" else 62.0)
            title = _text(r.get("title"), f"{lid} · {iso}")
            if iso not in bucket or score >= float(bucket[iso]["score"]):
                bucket[iso] = {"iso": iso, "score": score, "title": title, "source": _text(r.get("source_file"), ""), "from_object": True}

    # If extraction is weak, use curated country-level defaults instead of drawing
    # unsafe Plotly polygons or empty squares.
    min_needed = 4 if lid in {"sanctions", "conflicts"} else 8
    if len(bucket) < min_needed:
        for iso, score, title in _wm360_zone_fallback(lid):
            bucket.setdefault(iso, {"iso": iso, "score": float(score), "title": title, "source": "V3.6 curated fallback", "from_object": False})

    return sorted(bucket.values(), key=lambda x: (-float(x.get("score", 0)), str(x.get("iso", ""))))


def _wm360_zone_colorscale(layer_id: str) -> list[list[Any]]:
    lid = _wm360_layer_id(layer_id)
    if lid == "ciiInstability":
        return [
            [0.00, "rgba(34,197,94,0.18)"],
            [0.35, "rgba(234,179,8,0.22)"],
            [0.65, "rgba(249,115,22,0.30)"],
            [1.00, "rgba(239,68,68,0.42)"],
        ]
    if lid == "sanctions":
        return [
            [0.00, "rgba(250,204,21,0.16)"],
            [0.45, "rgba(249,115,22,0.25)"],
            [1.00, "rgba(239,68,68,0.40)"],
        ]
    return [
        [0.00, "rgba(248,113,113,0.12)"],
        [0.50, "rgba(239,68,68,0.26)"],
        [1.00, "rgba(185,28,28,0.46)"],
    ]


def _wm360_zone_line(layer_id: str) -> tuple[str, float]:
    lid = _wm360_layer_id(layer_id)
    if lid == "sanctions":
        return "rgba(255,140,80,0.78)", 0.95
    if lid == "ciiInstability":
        return "rgba(255,220,120,0.48)", 0.70
    return "rgba(255,80,80,0.90)", 1.15


def _wm360_choropleth_trace(records: list[dict[str, Any]], spec: LayerSpec, visible: bool) -> go.Choropleth | None:
    lid = _wm360_layer_id(spec.layer_id)
    if not records:
        return None

    locations = [r["iso"] for r in records]
    zvals = [float(r.get("score", 0)) for r in records]
    hover = [
        (
            f"<b>{html.escape(_text(r.get('title'), spec.label))}</b>"
            f"<br><span style='color:#7dd3fc'>{html.escape(spec.label)}</span>"
            f"<br>ISO-3: <b>{html.escape(_text(r.get('iso')))}</b>"
            f"<br>Intensity: <b>{float(r.get('score', 0)):.0f}/100</b>"
            + (f"<br>Source: {html.escape(_text(r.get('source')))}" if _text(r.get("source"), "") else "")
        )
        for r in records
    ]
    line_color, line_width = _wm360_zone_line(lid)
    return go.Choropleth(
        locations=locations,
        z=zvals,
        locationmode="ISO-3",
        zmin=0,
        zmax=100,
        colorscale=_wm360_zone_colorscale(lid),
        marker=dict(line=dict(color=line_color, width=line_width)),
        showscale=False,
        name=spec.label,
        text=hover,
        hoverinfo="text",
        visible=True if visible else "legendonly",
        meta={"layer_id": lid, "wm_v211": True, "kind": "country-choropleth", "style": "v360-country-zone-renderer"},
        showlegend=False,
    )


def _wm360_filtered_objects_for_legacy_renderer(objects: pd.DataFrame) -> pd.DataFrame:
    if not isinstance(objects, pd.DataFrame) or objects.empty or "layer_id" not in objects.columns:
        return objects
    out = objects.copy()
    lids = out["layer_id"].astype(str).map(_wm360_layer_id)
    # Remove all zone layers from the old V3.5/V3.5.x renderer. They will be
    # re-added as choropleths below, so legacy polygons cannot leak through.
    return out[~lids.isin(_WM360_ZONE_LAYERS)].copy()


def _wm360_build_zone_traces(objects: pd.DataFrame, registry: pd.DataFrame) -> list[Any]:
    reg = registry.copy() if isinstance(registry, pd.DataFrame) else pd.DataFrame(columns=["layer_id", "enabled"])
    if not reg.empty and "layer_id" in reg.columns:
        reg["_wm360_lid"] = reg["layer_id"].astype(str).map(_wm360_layer_id)
        reg = reg.drop_duplicates(subset=["_wm360_lid"], keep="last")
    enabled_map = {str(r._wm360_lid): bool(r.enabled) for _, r in reg.iterrows()} if not reg.empty else {}

    traces: list[Any] = []
    spec_by_lid = {_wm360_layer_id(s.layer_id): s for s in LAYER_SPECS}
    for lid in ("ciiInstability", "sanctions", "conflicts"):
        spec = spec_by_lid.get(lid, LayerSpec(lid, lid, "Security", "polygon", False, "#ef4444", "×", "derived", "Country choropleth."))
        records = _wm360_zone_records(objects, lid)
        tr = _wm360_choropleth_trace(records, spec, enabled_map.get(lid, False))
        if tr is not None:
            traces.append(tr)
    return traces


def _wm360_remove_unsafe_legacy_traces(fig: go.Figure) -> go.Figure:
    """Final safety pass: no old full-map filled Scattergeo trace can survive."""
    safe_data = []
    for tr in list(getattr(fig, "data", []) or []):
        meta = getattr(tr, "meta", None) or {}
        lid = ""
        kind = ""
        if isinstance(meta, dict):
            lid = _wm360_layer_id(meta.get("layer_id", ""))
            kind = str(meta.get("kind", ""))
        fill = str(getattr(tr, "fill", "") or "").lower()
        trace_type = str(getattr(tr, "type", "") or "").lower()

        # Keep our new choropleths.
        if trace_type == "choropleth" and lid in _WM360_ZONE_LAYERS:
            safe_data.append(tr)
            continue

        # Remove all legacy filled Scattergeo traces for zone/utility layers.
        if lid in _WM360_NO_SCATTER_FILL_LAYERS and fill not in {"", "none"}:
            continue
        if kind in {"polygon", "zone-fallback", "terminator"} and lid in _WM360_NO_SCATTER_FILL_LAYERS:
            continue

        # Metadata-independent large red/orange/yellow fill guard.
        if trace_type == "scattergeo" and fill not in {"", "none"}:
            try:
                xs = [float(x) for x in list(getattr(tr, "lon", []) or []) if x is not None]
                ys = [float(y) for y in list(getattr(tr, "lat", []) or []) if y is not None]
                span_lon = max(xs) - min(xs) if xs else 0
                span_lat = max(ys) - min(ys) if ys else 0
                fillcolor = str(getattr(tr, "fillcolor", "") or "").lower()
                hot_fill = any(token in fillcolor for token in ["239,68,68", "249,115,22", "255,", "#ef4444", "#f97316", "red", "orange"])
                if hot_fill and (span_lon >= 60 or span_lat >= 35 or span_lon * span_lat >= 1500):
                    continue
            except Exception:
                pass

        safe_data.append(tr)

    fig.data = tuple(safe_data)
    return fig


def build_plotly_figure_v211(
    objects: pd.DataFrame,
    registry: pd.DataFrame,
    projection: str = "orthographic",
    region: str = "Global",
    max_points_per_layer: int = 2200,
    fig_height: int = 780,
    projection_scale: float | None = None,
) -> go.Figure:  # V3.6.0 final country-zone renderer
    if _WM360_PREV_BUILD_PLOTLY is None:
        base = go.Figure()
    else:
        clean_objects = _wm360_filtered_objects_for_legacy_renderer(objects)
        base = _WM360_PREV_BUILD_PLOTLY(
            clean_objects,
            registry,
            projection=projection,
            region=region,
            max_points_per_layer=max_points_per_layer,
            fig_height=fig_height,
            projection_scale=projection_scale,
        )

    zone_traces = _wm360_build_zone_traces(objects, registry)

    fig = go.Figure()
    for tr in zone_traces:
        fig.add_trace(tr)
    for tr in list(getattr(base, "data", []) or []):
        fig.add_trace(tr)

    try:
        fig.update_layout(base.layout)
    except Exception:
        pass

    # Keep the institutional dark map background even when only choropleths are active.
    try:
        fig.update_geos(
            showland=True,
            landcolor="rgba(45,45,45,0.98)",
            showocean=True,
            oceancolor="rgba(18,18,18,0.99)",
            showcountries=True,
            countrycolor="rgba(190,198,208,0.32)",
            showcoastlines=True,
            coastlinecolor="rgba(190,198,208,0.24)",
            showframe=False,
            bgcolor="rgba(0,0,0,0)",
        )
    except Exception:
        pass

    return _wm360_remove_unsafe_legacy_traces(fig)


def _map_component_html(fig: go.Figure, registry: pd.DataFrame, stage_height: int = 860, *args: Any, **kwargs: Any) -> str:  # V3.6.0 HTML guard
    if _WM360_PREV_MAP_COMPONENT_HTML is None:
        html_payload = pio.to_html(fig, include_plotlyjs="cdn", full_html=True, config={"displayModeBar": False, "responsive": True})
    else:
        try:
            html_payload = _WM360_PREV_MAP_COMPONENT_HTML(fig, registry, stage_height=stage_height, *args, **kwargs)
        except TypeError:
            try:
                html_payload = _WM360_PREV_MAP_COMPONENT_HTML(fig, registry, stage_height)
            except TypeError:
                html_payload = _WM360_PREV_MAP_COMPONENT_HTML(fig, registry)

    # Remove old append-only guards that were blocking zones or fighting the new renderer.
    html_payload = re.sub(r"<script[^>]*id=[\"']wm35[1-4][^\"']*[\"'][\s\S]*?</script>", "", html_payload, flags=re.I)
    html_payload = re.sub(r"<script[^>]*id=[\"']wm35[1-4]-[^\"']*[\"'][\s\S]*?</script>", "", html_payload, flags=re.I)
    html_payload = re.sub(r"V3\.5(?:\.[1-4])?", "V3.6.0", html_payload)
    html_payload = html_payload.replace("ORIGINAL-LIKE", "COUNTRY-ZONE SAFE").replace("ZONE SAFE", "COUNTRY-ZONE SAFE")

    # Make TOUT ON safe again: zones can be activated, day/night remains excluded.
    guard_script = """
<script id="wm360-country-zone-layer-guard">
(function(){
  const UTILITY = new Set(['dayNight','daynight','dayNightTerminator']);
  function layerId(trace){
    try{return String((trace.meta||{}).layer_id||'');}catch(e){return '';}
  }
  function rootOf(node){return (node && node.closest && node.closest('.wm-map-shell,.wm-stage')) || document;}
  function restyle(root){
    const gd = root.querySelector('.plotly-graph-div');
    if(!gd || !window.Plotly || !gd.data) return;
    const checked = new Set(Array.from(root.querySelectorAll('.wm-check,input[type="checkbox"][data-layer-id]'))
      .filter(x=>x.checked&&!x.disabled)
      .map(x=>String(x.dataset.layerId||'')));
    const vis = gd.data.map(tr => checked.has(layerId(tr)) ? true : 'legendonly');
    try{window.Plotly.restyle(gd,{visible:vis});}
    catch(e){try{vis.forEach((v,i)=>window.Plotly.restyle(gd,{visible:v},[i]));}catch(_){}}
  }
  function install(){
    const roots = Array.from(document.querySelectorAll('.wm-map-shell,.wm-stage'));
    if(!roots.length) roots.push(document);
    roots.forEach(function(root){
      const buttons = Array.from(root.querySelectorAll('[data-all-on],button')).filter(function(b){
        return String(b.textContent||'').toUpperCase().includes('TOUT ON') || b.hasAttribute('data-all-on');
      });
      buttons.forEach(function(btn){
        if(btn.dataset && btn.dataset.wm360Guarded==='1') return;
        if(btn.dataset) btn.dataset.wm360Guarded='1';
        btn.addEventListener('click',function(e){
          e.preventDefault();
          e.stopImmediatePropagation();
          const r = rootOf(btn);
          r.querySelectorAll('.wm-check:not(:disabled),input[type="checkbox"][data-layer-id]:not(:disabled)').forEach(function(x){
            const lid = String(x.dataset.layerId||'');
            x.checked = !UTILITY.has(lid);
          });
          restyle(r);
        }, true);
      });
    });
  }
  install();
  setTimeout(install,250); setTimeout(install,1000); setTimeout(install,2500);
})();
</script>
"""
    if "wm360-country-zone-layer-guard" not in html_payload:
        html_payload += guard_script
    return html_payload


def _wm360_snapshot_for_tests() -> dict[str, Any]:
    return {
        "module_version": MODULE_VERSION,
        "renderer": "ISO-3 choropleth",
        "zone_layers": sorted(_WM360_ZONE_LAYERS),
        "legacy_zone_fill_removed": True,
        "sanctions_country_fill": True,
        "conflicts_country_fill": True,
        "cii_country_fill": True,
        "tout_on_excludes_only_utility": sorted(_WM360_UTILITY_LAYERS),
    }


