def _wm361_lid(value):
    try:
        return _wm360_layer_id(value)
    except Exception:
        return str(value or "").strip()


def _wm361_canonical_for_layer(layer_id):
    lid = _wm361_lid(layer_id)
    if lid == "sanctions":
        return list(_WM361_SANCTIONS_CANONICAL)
    if lid == "conflicts":
        return list(_WM361_CONFLICT_CANONICAL)
    if lid == "ciiInstability":
        return list(_WM361_CII_CANONICAL)
    return []


def _wm361_to_records(items, layer_id):
    out = []
    for iso, score, label in items:
        out.append({
            "iso3": str(iso).upper(),
            "score": float(score),
            "label": str(label),
            "layer_id": _wm361_lid(layer_id),
            "source": "canonical-original-coverage",
        })
    return out


def _wm361_merge_country_records(base_records, canonical_records):
    """
    Merge live/static detected country records with canonical original-like coverage.
    Existing detected records win when they have higher severity.
    """
    merged = {}

    def add(rec, priority):
        iso = str(rec.get("iso3", "") or "").upper().strip()
        if len(iso) != 3:
            return
        try:
            score = float(rec.get("score", 0) or 0)
        except Exception:
            score = 0.0
        label = str(rec.get("label", "") or iso)
        prev = merged.get(iso)
        if prev is None or score > prev["score"] or priority > prev.get("_priority", 0):
            nr = dict(rec)
            nr["iso3"] = iso
            nr["score"] = max(0.0, min(100.0, score))
            nr["label"] = label
            nr["_priority"] = priority
            merged[iso] = nr

    for rec in canonical_records:
        add(rec, priority=1)
    for rec in base_records or []:
        add(rec, priority=2)

    out = []
    for rec in merged.values():
        rec.pop("_priority", None)
        out.append(rec)
    out.sort(key=lambda r: float(r.get("score", 0) or 0), reverse=True)
    return out


def _wm360_zone_records(objects, layer_id):  # override V3.6.0 records
    lid = _wm361_lid(layer_id)

    if _WM361_PREV_ZONE_RECORDS is not None:
        try:
            base = _WM361_PREV_ZONE_RECORDS(objects, lid)
        except Exception:
            base = []
    else:
        base = []

    canonical = _wm361_to_records(_wm361_canonical_for_layer(lid), lid)

    if lid in {"sanctions", "conflicts", "ciiInstability"}:
        return _wm361_merge_country_records(base, canonical)

    return base


def _wm361_expected_count(layer_id):
    return len(_wm361_canonical_for_layer(layer_id))


def build_layer_registry_v211(objects):  # override registry counts so drawer is coherent
    if _WM361_PREV_BUILD_REGISTRY is None:
        reg = pd.DataFrame()
    else:
        reg = _WM361_PREV_BUILD_REGISTRY(objects)

    try:
        if isinstance(reg, pd.DataFrame) and not reg.empty and "layer_id" in reg.columns:
            out = reg.copy()
            for lid in ("sanctions", "conflicts", "ciiInstability"):
                mask = out["layer_id"].astype(str).map(_wm361_lid).eq(lid)
                if mask.any() and "count" in out.columns:
                    out.loc[mask, "count"] = out.loc[mask, "count"].apply(
                        lambda x: max(int(x or 0), _wm361_expected_count(lid))
                    )
                    if "disabled" in out.columns:
                        out.loc[mask, "disabled"] = False
            return out
    except Exception:
        pass
    return reg


def _wm361_original_zone_opacity(layer_id):
    lid = _wm361_lid(layer_id)
    if lid == "sanctions":
        return 0.42
    if lid == "conflicts":
        return 0.50
    if lid == "ciiInstability":
        return 0.38
    return 0.42


def _wm360_choropleth_trace(records, spec, visible):  # override trace style from V3.6.0
    try:
        lid = _wm361_lid(getattr(spec, "layer_id", ""))
    except Exception:
        lid = "unknown"

    if not records:
        return None

    locs = []
    z = []
    hover = []
    seen = set()

    for rec in records:
        iso = str(rec.get("iso3", "") or "").upper().strip()
        if len(iso) != 3 or iso in seen:
            continue
        seen.add(iso)
        score = float(rec.get("score", 0) or 0)
        locs.append(iso)
        z.append(score)
        hover.append(
            "<b>%s</b><br>%s<br>Score: %.0f/100"
            % (iso, str(rec.get("label", iso)), score)
        )

    if not locs:
        return None

    try:
        colorscale = _wm360_zone_colorscale(lid)
    except Exception:
        if lid == "conflicts":
            colorscale = [[0, "rgba(127,29,29,0.20)"], [1, "rgba(239,68,68,0.62)"]]
        elif lid == "ciiInstability":
            colorscale = [[0, "rgba(34,197,94,0.18)"], [0.5, "rgba(245,158,11,0.36)"], [1, "rgba(239,68,68,0.56)"]]
        else:
            colorscale = [[0, "rgba(245,158,11,0.20)"], [1, "rgba(249,115,22,0.56)"]]

    if lid == "sanctions":
        line_color = "rgba(251,146,60,0.95)"
        line_width = 1.25
    elif lid == "conflicts":
        line_color = "rgba(248,113,113,0.96)"
        line_width = 1.35
    else:
        line_color = "rgba(226,232,240,0.62)"
        line_width = 0.75

    return go.Choropleth(
        locations=locs,
        z=z,
        locationmode="ISO-3",
        zmin=0,
        zmax=100,
        colorscale=colorscale,
        marker=dict(line=dict(color=line_color, width=line_width)),
        showscale=False,
        name=getattr(spec, "label", lid),
        text=hover,
        hoverinfo="text",
        visible=True if visible else "legendonly",
        opacity=_wm361_original_zone_opacity(lid),
        meta={
            "layer_id": lid,
            "wm_v211": True,
            "kind": "country-choropleth",
            "style": "v361-country-coverage-fidelity",
        },
        showlegend=False,
    )


def _map_component_html(fig, registry, stage_height=860, *args, **kwargs):  # V3.6.1 header guard
    if _WM361_PREV_MAP_COMPONENT_HTML is None:
        html_payload = pio.to_html(fig, include_plotlyjs="cdn", full_html=False, config={"displayModeBar": False, "responsive": True})
    else:
        try:
            html_payload = _WM361_PREV_MAP_COMPONENT_HTML(fig, registry, stage_height=stage_height, *args, **kwargs)
        except TypeError:
            try:
                html_payload = _WM361_PREV_MAP_COMPONENT_HTML(fig, registry, stage_height)
            except TypeError:
                html_payload = _WM361_PREV_MAP_COMPONENT_HTML(fig, registry)

    try:
        html_payload = re.sub(r"V3\.6\.0", "V3.6.1", html_payload)
        html_payload = re.sub(r"LIVE\s*·\s*V3\.5(?:\.[0-9])?", "LIVE · V3.6.1", html_payload)
        html_payload = html_payload.replace("COUNTRY-ZONE SAFE", "COUNTRY COVERAGE")
    except Exception:
        pass
    return html_payload


