def _wm21121_rerun() -> None:
    try:
        st.rerun()
    except Exception:
        try:
            st.experimental_rerun()
        except Exception:
            pass


def _wm21121_query_dict() -> dict[str, str]:
    out: dict[str, str] = {}
    try:
        qp = getattr(st, "query_params", None)
        if qp is not None:
            for k in qp.keys():
                v = qp.get(k)
                out[str(k)] = str(v[0] if isinstance(v, (list, tuple)) and v else v if v is not None else "")
            return out
    except Exception:
        pass
    try:
        qp = st.experimental_get_query_params()
        if isinstance(qp, dict):
            for k, v in qp.items():
                out[str(k)] = str(v[0] if isinstance(v, list) and v else v)
    except Exception:
        pass
    return out


def _wm21121_bool(value: object, default: bool = True) -> bool:
    if isinstance(value, bool):
        return value
    raw = str(value).strip().lower()
    if raw in {"1", "true", "yes", "y", "on", "live", "en direct"}:
        return True
    if raw in {"0", "false", "no", "n", "off", "static"}:
        return False
    return bool(default)


def _wm21121_style_label(value: object) -> str:
    raw = str(value or "Tech").strip()
    if raw in _WM21121_STYLE_LABELS:
        return raw
    return _WM21121_VALUE_TO_STYLE_LABEL.get(raw, "💻 TECH")


def _wm21121_country_value(value: object) -> str:
    raw = str(value or "Global").strip()
    return raw if raw in _WM21121_COUNTRIES else "Global"


def _wm21121_time_value(value: object) -> str:
    raw = str(value or "24h").strip()
    return raw if raw in _WM21121_TIME_OPTIONS else "24h"


def _wm21121_time_to_hours(value: object) -> int:
    try:
        if "_wm21116_time_to_hours" in globals() and callable(globals().get("_wm21116_time_to_hours")):
            return int(globals()["_wm21116_time_to_hours"](str(value)))
    except Exception:
        pass
    try:
        if "_wm_final_hours_from_window" in globals() and callable(globals().get("_wm_final_hours_from_window")):
            return int(globals()["_wm_final_hours_from_window"](str(value)))
    except Exception:
        pass
    return {"1h": 1, "6h": 6, "24h": 24, "48h": 48, "7d": 168, "Tout": 24 * 365 * 5}.get(str(value), 24)


def _wm21121_country_cfg(country: str) -> dict:
    return dict(_WM21121_COUNTRY_CONTEXT.get(str(country or "Global"), _WM21121_COUNTRY_CONTEXT["Global"]))


# Override the older country helper used by previous V2.11 layers.
def _wm_country_cfg_v211(country: str) -> dict:  # type: ignore[override]
    return _wm21121_country_cfg(str(country or "Global"))


def _wm21121_seed_state_once() -> None:
    q = _wm21121_query_dict()
    try:
        display_style, country, live_enabled, _effective_style = _wm_v33_context_from_query()
    except Exception:
        display_style = q.get("wm_style", "Tech")
        country = q.get("wm_country", "Global")
        live_enabled = _wm21121_bool(q.get("wm_live", "1"), True)

    if "wm21121_style_label" not in st.session_state:
        # Preserve V2.11.20 state if it already exists.
        st.session_state["wm21121_style_label"] = _wm21121_style_label(st.session_state.get("wm21120_style_label", display_style))
    if "wm21121_country" not in st.session_state:
        st.session_state["wm21121_country"] = _wm21121_country_value(st.session_state.get("wm21120_country", country))
    if "wm21121_live" not in st.session_state:
        st.session_state["wm21121_live"] = bool(st.session_state.get("wm21120_live", live_enabled))
    if "wm21121_time" not in st.session_state:
        try:
            initial_time = st.session_state.get("wm21120_time", _wm21116_current_time_window())
        except Exception:
            initial_time = st.session_state.get("wm21120_time", q.get("wm_time", "24h"))
        st.session_state["wm21121_time"] = _wm21121_time_value(initial_time)
    if "wm21121_projection" not in st.session_state:
        st.session_state["wm21121_projection"] = "3D" if str(st.session_state.get("wm21120_projection", q.get("wm_projection", "2D"))).upper() == "3D" else "2D"


def _wm21121_safe_button(label: str, key: str, active: bool, use_container_width: bool = True) -> bool:
    # Native Streamlit button, but never blue visually.
    # Active buttons use type="primary" only as a DOM hook; V2.11.22 CSS forces
    # the WorldMonitor dark/green skin over both old and new Streamlit button DOMs.
    try:
        return bool(st.button(label, key=key, type="primary" if active else "secondary", use_container_width=use_container_width))
    except TypeError:
        return bool(st.button(label, key=key, use_container_width=use_container_width))

def _wm21121_slug(value: str) -> str:
    return re.sub(r"[^a-zA-Z0-9_]+", "_", str(value)).strip("_")[:40] or "x"



def _wm21121_button_rows(
    options: list[str],
    key: str,
    row_sizes: list[int] | None = None,
    active_prefix: str = "",
    idle_prefix: str = "",
) -> str:
    """Compact native segmented control.

    Important:
    - no href / no target / no browser navigation;
    - labels are intentionally short and mono-line;
    - active state is carried by Streamlit primary button type, then skinned by CSS.
    """
    current = str(st.session_state.get(key, options[0] if options else ""))
    if not options:
        return current
    if current not in options:
        current = options[0]
        st.session_state[key] = current

    if not row_sizes:
        row_sizes = [len(options)]

    pos = 0
    for raw_size in row_sizes:
        row_size = max(1, int(raw_size))
        row = options[pos:pos + row_size]
        pos += row_size
        if not row:
            continue
        try:
            cols = st.columns([1.0] * len(row), gap="small")
        except TypeError:
            cols = st.columns([1.0] * len(row))
        for col, opt in zip(cols, row):
            active = (opt == current)
            prefix = active_prefix if active else idle_prefix
            label = f"{prefix} {str(opt)}".strip()
            with col:
                if _wm21121_safe_button(label, f"{key}_btn_{_wm21121_slug(opt)}", active=active, use_container_width=True):
                    if st.session_state.get(key) != opt:
                        st.session_state[key] = opt
                        _wm21121_rerun()

    if pos < len(options):
        rest = options[pos:]
        try:
            cols = st.columns([1.0] * len(rest), gap="small")
        except TypeError:
            cols = st.columns([1.0] * len(rest))
        for col, opt in zip(cols, rest):
            active = (opt == current)
            prefix = active_prefix if active else idle_prefix
            label = f"{prefix} {str(opt)}".strip()
            with col:
                if _wm21121_safe_button(label, f"{key}_btn_{_wm21121_slug(opt)}", active=active, use_container_width=True):
                    if st.session_state.get(key) != opt:
                        st.session_state[key] = opt
                        _wm21121_rerun()

    return str(st.session_state.get(key, current))



