def _wm21121_render_topbar() -> tuple[str, str, bool, str]:
    _wm21121_seed_state_once()

    style_options = [
        "MONDE",
        "TECH",
        "FINANCE",
        "COMMO",
        "ÉNERGIE",
        "GOOD",
        "RISK",
        "OPS",
    ]
    style_to_value = {
        "MONDE": "Global",
        "TECH": "Tech",
        "FINANCE": "Finance",
        "COMMO": "Commodities",
        "ÉNERGIE": "Energy",
        "ENERGIE": "Energy",
        "GOOD": "Good News",
        "RISK": "Risk",
        "OPS": "Ops",
    }

    previous_label = str(st.session_state.get("wm21121_style_label", "TECH")).strip()
    legacy_to_new = {
        " MONDE": "MONDE",
        "MONDE": "MONDE",
        " TECH": "TECH",
        "TECH": "TECH",
        " FINANCE": "FINANCE",
        "FINANCE": "FINANCE",
        " MATIÈRE PREMIÈRE": "COMMO",
        "MATIÈRE PREMIÈRE": "COMMO",
        "MATIERE PREMIERE": "COMMO",
        "COMMOD.": "COMMO",
        "COMMOD": "COMMO",
        "COMMO": "COMMO",
        " ÉNERGIE": "ÉNERGIE",
        "ÉNERGIE": "ÉNERGIE",
        "ENERGIE": "ÉNERGIE",
        " GOOD NEWS": "GOOD",
        "GOOD NEWS": "GOOD",
        "GOOD": "GOOD",
        " RISK": "RISK",
        "RISK": "RISK",
        " OPS": "OPS",
        "OPS": "OPS",
    }
    if previous_label not in style_options:
        st.session_state["wm21121_style_label"] = legacy_to_new.get(previous_label, "TECH")

    # V2.11.25: no open HTML wrapper around Streamlit widgets.
    # The previous shell wrapper rendered as an empty green rectangle and pushed
    # the controls into overlapping positions. Closed rails preserve the style
    # without breaking Streamlit's DOM.
    st.markdown('<div class="wm21121-native-top-rail" data-wm-runtime="native-v21125-no-wrapper"></div>', unsafe_allow_html=True)

    try:
        brand_col, style_col, country_col, live_col = st.columns([0.95, 3.55, 5.55, 1.00], gap="medium")
    except TypeError:
        brand_col, style_col, country_col, live_col = st.columns([0.95, 3.55, 5.55, 1.00])

    with brand_col:
        st.markdown('<div class="wm21121-brand">MONITOR</div><div class="wm21121-ver">V3.3.8</div>', unsafe_allow_html=True)

    with style_col:
        st.markdown('<div class="wm21121-label">WORKSPACE</div>', unsafe_allow_html=True)
        style_label = _wm21121_button_rows(style_options, "wm21121_style_label", [4, 4])

    with country_col:
        st.markdown('<div class="wm21121-label">COUNTRY / THEATRE</div>', unsafe_allow_html=True)
        country = _wm21121_button_rows(_WM21121_COUNTRIES, "wm21121_country", [5, 4])

    with live_col:
        st.markdown('<div class="wm21121-label-spacer"></div>', unsafe_allow_html=True)
        live_enabled = bool(st.session_state.get("wm21121_live", True))
        live_label = "EN DIRECT" if live_enabled else "LIVE OFF"
        if _wm21121_safe_button(live_label, "wm21121_live_toggle", active=live_enabled, use_container_width=True):
            st.session_state["wm21121_live"] = not live_enabled
            _wm21121_rerun()
        live_enabled = bool(st.session_state.get("wm21121_live", True))

    st.markdown('<div class="wm21121-native-bottom-rail"></div>', unsafe_allow_html=True)

    display_style = style_to_value.get(str(style_label).strip(), "Tech")
    effective_style = display_style
    if display_style == "Commodities":
        effective_style = "Finance"
    elif display_style in {"Energy", "Good News", "Risk", "Ops", "Global", "Tech", "Finance"}:
        effective_style = display_style

    st.session_state["wm21120_style_label"] = str(style_label)
    st.session_state["wm21120_country"] = str(country)
    st.session_state["wm21120_live"] = bool(live_enabled)
    st.session_state["wm_style"] = str(display_style)
    st.session_state["wm_country"] = str(country)
    st.session_state["wm_live"] = bool(live_enabled)
    return str(display_style), str(country), bool(live_enabled), str(effective_style)

def _wm21121_render_eventbar(live_enabled: bool = True) -> str:
    # V2.11.25: no open eventbar wrapper. The old wrapper became an empty
    # blue/green box above the buttons in Streamlit's DOM.
    st.markdown('<div class="wm21121-event-rail" data-wm-runtime="event-v21125-no-wrapper"></div>', unsafe_allow_html=True)

    try:
        title_col, buttons_col, note_col = st.columns([1.05, 4.75, 4.20], gap="medium")
    except TypeError:
        title_col, buttons_col, note_col = st.columns([1.05, 4.75, 4.20])

    with title_col:
        st.markdown('<div class="wm21121-event-title">EVENT WINDOW</div>', unsafe_allow_html=True)

    with buttons_col:
        time_window = _wm21121_button_rows(_WM21121_TIME_OPTIONS, "wm21121_time", [6])

    hours = _wm21121_time_to_hours(time_window)
    live_txt = "live ON" if bool(live_enabled) else "static"
    country_txt = str(st.session_state.get("wm21121_country", "Global"))

    with note_col:
        st.markdown(
            f'<div class="wm21121-event-note"><span>●</span> {html.escape(str(time_window))} · serveur lookback {int(hours)}h · pays: <b>{html.escape(country_txt)}</b> · couches statiques inchangées · {html.escape(live_txt)}</div>',
            unsafe_allow_html=True,
        )

    st.markdown('<div class="wm21121-event-bottom-rail"></div>', unsafe_allow_html=True)
    st.session_state["wm21120_time"] = str(time_window)
    st.session_state["wm_time"] = str(time_window)
    return str(time_window)

def _wm21121_metadata_blob(row: pd.Series) -> str:
    vals = []
    for col in ["title", "metadata", "source_file", "collection", "layer_id", "country", "region", "object_id"]:
        try:
            vals.append(str(row.get(col, "") or ""))
        except Exception:
            pass
    return " " + " ".join(vals).lower() + " "


def _wm21121_point_in_box(lon: object, lat: object, cfg: dict) -> bool:
    try:
        lo = float(lon)
        la = float(lat)
        lon_min, lon_max = cfg.get("lon_range", [-180, 180])
        lat_min, lat_max = cfg.get("lat_range", [-62, 84])
        return float(lon_min) <= lo <= float(lon_max) and float(lat_min) <= la <= float(lat_max)
    except Exception:
        return False


def _wm21121_points_json_hits(points_json: object, cfg: dict) -> bool:
    try:
        pts = json.loads(str(points_json or "[]"))
        if not isinstance(pts, list):
            return False
        for p in pts[:120]:
            if isinstance(p, (list, tuple)) and len(p) >= 2 and _wm21121_point_in_box(p[0], p[1], cfg):
                return True
            if isinstance(p, dict):
                lon = p.get("lon", p.get("lng", p.get("longitude")))
                lat = p.get("lat", p.get("latitude"))
                if _wm21121_point_in_box(lon, lat, cfg):
                    return True
    except Exception:
        return False
    return False


def _wm21121_filter_objects_for_country(objects: pd.DataFrame, country: str) -> pd.DataFrame:
    if not isinstance(objects, pd.DataFrame) or objects.empty or str(country or "Global") == "Global":
        return objects
    cfg = _wm21121_country_cfg(country)
    kws = [str(x).lower() for x in cfg.get("keywords", []) if str(x).strip()]
    if not kws:
        return objects

    mask = []
    for _, row in objects.iterrows():
        hit = False
        try:
            if _wm21121_point_in_box(row.get("lon"), row.get("lat"), cfg):
                hit = True
            elif _wm21121_points_json_hits(row.get("points_json"), cfg):
                hit = True
            else:
                blob = _wm21121_metadata_blob(row)
                hit = any(k in blob for k in kws)
        except Exception:
            hit = False
        mask.append(bool(hit))
    try:
        filtered = objects.loc[mask].copy().reset_index(drop=True)
    except Exception:
        return objects
    # Avoid a blank map if the local source has no country-specific rows.
    return filtered if not filtered.empty else objects


def _wm21121_add_country_focus_registry(registry: pd.DataFrame, country: str) -> pd.DataFrame:
    if str(country or "Global") == "Global" or not isinstance(registry, pd.DataFrame):
        return registry
    row = {
        "layer_id": "countryFocus",
        "label": "Country focus",
        "group": "Focus",
        "renderer": "focus",
        "source_class": "derived",
        "count": 1,
        "enabled": True,
        "disabled": False,
        "color": "#33ff88",
        "icon": "⌖",
        "note": f"Active country focus: {country}",
        "order": 9999,
        "preset": "country",
    }
    try:
        if "layer_id" in registry.columns and (registry["layer_id"].astype(str) == "countryFocus").any():
            return registry
        return pd.concat([registry, pd.DataFrame([row])], ignore_index=True, sort=False)
    except Exception:
        return registry


def _wm_focus_figure_on_country_v211(fig: go.Figure, country: str, projection_mode: str) -> None:  # type: ignore[override]
    cfg = _wm21121_country_cfg(str(country or "Global"))
    try:
        if str(country or "Global") != "Global":
            lon = float(cfg.get("lon", 0.0))
            lat = float(cfg.get("lat", 0.0))
            lon_min, lon_max = cfg.get("lon_range", [-180, 180])
            lat_min, lat_max = cfg.get("lat_range", [-62, 84])
            fig.add_trace(go.Scattergeo(
                lon=[lon], lat=[lat], mode="markers+text", text=[str(country)], textposition="top center",
                marker=dict(size=18, color="#33ff88", opacity=0.96, line=dict(width=2, color="rgba(255,255,255,.75)")),
                hovertext=[f"Country focus · {country}"], hoverinfo="text", showlegend=False,
                name="Country focus", meta={"layer_id": "countryFocus", "wm_v211": True, "wm_keep_visible": True},
            ))
            # A subtle envelope makes the country/theatre change visually obvious.
            fig.add_trace(go.Scattergeo(
                lon=[float(lon_min), float(lon_max), float(lon_max), float(lon_min), float(lon_min)],
                lat=[float(lat_min), float(lat_min), float(lat_max), float(lat_max), float(lat_min)],
                mode="lines", line=dict(width=1.5, color="#33ff88", dash="dot"), opacity=0.72,
                hoverinfo="skip", showlegend=False, name="Country envelope",
                meta={"layer_id": "countryFocus", "wm_v211": True, "wm_keep_visible": True},
            ))
    except Exception:
        pass
    try:
        if str(projection_mode).upper() == "3D":
            fig.update_geos(projection_rotation=dict(lon=-float(cfg.get("lon", 15.0)), lat=float(cfg.get("lat", 0.0)) / 3, roll=0))
        else:
            fig.update_geos(
                center=dict(lon=float(cfg.get("lon", 0.0)), lat=float(cfg.get("lat", 8.0))),
                lonaxis_range=cfg.get("lon_range", [-180, 180]),
                lataxis_range=cfg.get("lat_range", [-62, 84]),
            )
    except Exception:
        pass


def _render_worldmonitor_map_clean_v211(  # type: ignore[override]
    live_enabled: bool = False,
    time_window: str = "24h",
    style: str = "Global",
    projection_mode: str = "2D",
    country: str = "Global",
    **_kwargs,
) -> None:
    static_objects, _static_status = load_worldmonitor_static_objects_v211("")
    live_objects = pd.DataFrame()
    if bool(live_enabled):
        hours_back = _wm21121_time_to_hours(str(time_window))
        live_objects, _live_status = load_live_event_objects_v211(
            hours_back=int(hours_back),
            min_magnitude=0.0,
            cache_nonce=int(hours_back),
            provider_profile="Fast natural",
        )
    frames = [df for df in [static_objects, live_objects] if isinstance(df, pd.DataFrame) and not df.empty]
    objects = pd.concat(frames, ignore_index=True) if frames else pd.DataFrame(columns=static_objects.columns if isinstance(static_objects, pd.DataFrame) else [])
    if not objects.empty:
        objects = objects.drop_duplicates(subset=["object_id", "kind", "points_json"], keep="first").reset_index(drop=True)
        objects = _wm21121_filter_objects_for_country(objects, str(country or "Global"))

    preset = "Balanced institutional"
    try:
        preset = _WM_STYLE_TO_MAP_PRESET.get(str(style), preset)
    except Exception:
        pass
    registry = build_layer_registry_v211(objects, preset=preset)
    registry = _wm21121_add_country_focus_registry(registry, str(country or "Global"))

    projection = "3D globe" if str(projection_mode).upper() == "3D" else "Flat world"
    try:
        if "_wm_final_projection_name" in globals() and callable(globals().get("_wm_final_projection_name")):
            projection = str(globals()["_wm_final_projection_name"](str(projection_mode)))
    except Exception:
        pass
    projection_scale = 1.16 if projection == "3D globe" else 1.0

    fig = build_plotly_figure_v211(
        objects,
        registry,
        projection=projection,
        region=_wm21121_country_cfg(str(country or "Global")).get("region", "Global"),
        fig_height=606,
        projection_scale=projection_scale,
    )
    _wm_focus_figure_on_country_v211(fig, str(country or "Global"), str(projection_mode))
    html_payload = _map_component_html(
        fig,
        registry,
        stage_height=660,
        active_time=str(time_window or "24h"),
        projection_mode=str(projection_mode),
        country=str(country or "Global"),
    )
    html_payload = f"<!-- WM21121 country={html.escape(str(country or 'Global'))} time={html.escape(str(time_window or '24h'))} style={html.escape(str(style))} -->\n" + str(html_payload)
    if components is not None:
        components.html(html_payload, height=660, scrolling=False)
    else:
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": True, "responsive": True})


def _map_component_html(fig, registry, stage_height: int = 860, *args, **kwargs):  # type: ignore[override]
    """Wrap older map HTML and suppress legacy clickable controls.

    The drawer may still restyle Plotly traces by layer_id. V2.11.21 adds a
    countryFocus layer to the registry, so focus traces remain visible.
    """
    if callable(_WM21121_PREV_MAP_COMPONENT_HTML):
        try:
            html_payload = _WM21121_PREV_MAP_COMPONENT_HTML(fig, registry, stage_height=stage_height, *args, **kwargs)
        except TypeError:
            try:
                html_payload = _WM21121_PREV_MAP_COMPONENT_HTML(fig, registry, stage_height)
            except Exception:
                html_payload = ""
    else:
        html_payload = ""
    if not isinstance(html_payload, str):
        return ""
    guard_css = """
      /* V2.11.21: native top/event bars are the only active controls. */
      .wm-timebar,.wm21117-eventbar,.wm33-runtime-top{display:none!important;pointer-events:none!important;}
    """
    if "</style>" in html_payload:
        html_payload = html_payload.replace("</style>", guard_css + "\n</style>", 1)
    else:
        html_payload += "<style>" + guard_css + "</style>"
    return html_payload


def render_worldmonitor_bridge_v211() -> None:  # type: ignore[override]
    """V2.11.23 public entrypoint: native no-reload nav + final institutional skin."""
    try:
        _wm_inject_clean_css_v211()
    except Exception:
        pass
    _wm21121_inject_css()

    display_style, country, live_enabled, effective_style = _wm21121_render_topbar()

    st.markdown(
        f'<div class="wm21121-sub"><b>WORLD MONITOR V2.11 · ORIGINAL WORKSPACE RUNTIME</b> · {html.escape(str(display_style))} / {html.escape(str(country))} <span class="wm21121-focus-note">country focus active</span> · navigation native même session · aucun reload URL · source manager conservé.</div>',
        unsafe_allow_html=True,
    )

    time_window = _wm21121_render_eventbar(live_enabled=bool(live_enabled))
    projection_mode = str(st.session_state.get("wm21121_projection", "2D"))
    if projection_mode not in {"2D", "3D"}:
        projection_mode = "2D"
    st.session_state["wm21120_projection"] = projection_mode

    _render_worldmonitor_map_clean_v211(
        live_enabled=bool(live_enabled),
        time_window=str(time_window),
        style=str(effective_style),
        projection_mode=str(projection_mode),
        country=str(country),
    )

    try:
        _render_worldmonitor_panels_runtime_v33(
            display_style=str(display_style),
            effective_style=str(effective_style),
            country=str(country),
            live_enabled=bool(live_enabled),
        )
    except Exception as exc:
        try:
            st.error(f"WorldMonitor panels runtime error: {type(exc).__name__}: {str(exc)[:180]}")
        except Exception:
            pass


