def _wm211_geoexp_classify_event_layer_v41(row: pd.Series) -> str:
    text_blob = " ".join(
        _text(row.get(c), "")
        for c in ["event_type", "subtype", "title", "description", "source", "market_channel", "_domain_v294", "category"]
        if c in row.index
    ).lower()
    source = _text(row.get("source"), "").lower()

    # Social / political first: more precise than generic news.
    if any(k in text_blob for k in ["internet shutdown", "network shutdown", "netblocks", "ioda", "cloudflare radar", "communications blackout"]):
        return "internetShutdowns"
    if any(k in text_blob for k in ["strike", "walkout", "labor action", "labour action", "blockade", "port strike", "rail strike", "refinery strike"]):
        return "strikeActions"
    if any(k in text_blob for k in ["riot", "civil unrest", "violent protest", "looting", "clashes with police"]):
        return "riotUnrest"
    if any(k in text_blob for k in ["protest", "demonstration", "march", "rally", "sit-in", "civil disobedience"]):
        return "protestEvents"
    if any(k in text_blob for k in ["curfew", "state of emergency", "crackdown", "arrested protesters", "repression", "police fired"]):
        return "stateRepression"
    if any(k in text_blob for k in ["coup", "mutiny", "junta", "military takeover"]):
        return "coupRisk"
    if any(k in text_blob for k in ["election", "ballot", "vote count", "contested vote", "polling station"]):
        return "electionRisk"
    if any(k in text_blob for k in ["government collaps", "no-confidence", "confidence vote", "prime minister resign", "cabinet resign", "snap election"]):
        return "governmentInstability"

    # Cyber / information / navigation.
    if any(k in text_blob for k in ["disinformation", "influence operation", "information operation", "propaganda network"]):
        return "informationOps"
    if any(k in text_blob for k in ["gnss", "gps jamming", "gps spoofing", "jamming", "spoofing"]):
        return "gnssJamming"
    if any(k in text_blob for k in ["cyber", "cisa", "kev", "nvd", "malware", "ransomware", "data breach", "zero-day", "exploit"]):
        return "cyberThreats"

    # Energy / supply chain.
    if any(k in text_blob for k in ["lng", "liquefaction", "regasification"]):
        return "lngTerminals"
    if any(k in text_blob for k in ["refinery", "diesel", "gasoline", "jet fuel", "petrochemical"]):
        return "refineries"
    if any(k in text_blob for k in ["rig count", "drilling rig", "active rig"]):
        return "activeRigs"
    if any(k in text_blob for k in ["drilling permit", "exploration permit", "offshore license", "licence award"]):
        return "drillingPermits"
    if any(k in text_blob for k in ["fuel shortage", "fuel rationing", "gasoline shortage", "diesel shortage"]):
        return "fuelShortages"
    if any(k in text_blob for k in ["power outage", "blackout", "grid emergency", "reserve margin", "brownout"]):
        return "gridStress"
    if any(k in text_blob for k in ["port congestion", "port delay", "port closure", "terminal closure"]):
        return "portCongestion"
    if any(k in text_blob for k in ["port disruption", "shipping disruption", "container disruption"]):
        return "portDisruptions"
    if any(k in text_blob for k in ["war risk premium", "marine insurance", "shipping insurance"]):
        return "warRiskInsurance"
    if any(k in text_blob for k in ["tariff", "anti-dumping", "import duty", "trade remedy"]):
        return "tariffMeasures"
    if any(k in text_blob for k in ["export control", "dual-use", "semiconductor restriction", "chip export", "advanced lithography"]):
        return "exportControls"
    if any(k in text_blob for k in ["secondary sanction", "sanctions evasion", "circumvention"]):
        return "secondarySanctionsRisk"

    # Industry / commodities / food.
    if any(k in text_blob for k in ["semiconductor fab", "wafer fab", "foundry", "lithography", "advanced node"]):
        return "semiconductorFabs"
    if any(k in text_blob for k in ["rare earth", "lithium", "cobalt", "nickel", "graphite", "critical mineral"]):
        return "transitionMineralMines"
    if any(k in text_blob for k in ["fertilizer", "ammonia", "urea", "phosphate", "potash"]):
        return "fertilizerPlants"
    if any(k in text_blob for k in ["food price", "food inflation", "bread price", "grain price", "wheat price"]):
        return "foodPriceStress"
    if any(k in text_blob for k in ["crop stress", "yield risk", "drought", "heatwave"]):
        return "cropStress"

    # Preserve existing stable classification for natural/security/news.
    if any(k in text_blob for k in ["earthquake", "usgs", "magnitude", "seismic"]):
        return "earthquakes"
    if any(k in text_blob for k in ["gdacs", "flood", "storm", "cyclone", "volcano", "tsunami", "disaster", "eonet"]):
        return "natural"
    if any(k in text_blob for k in ["fire", "firms", "wildfire"]):
        return "fires"
    if any(k in text_blob for k in ["vessel", "ais", "ship", "tanker", "coast guard", "maritime"]):
        return "maritimeSecurityIncidents" if any(k in text_blob for k in ["attack", "seized", "missile", "drone", "mine"]) else "ais"
    if any(k in text_blob for k in ["aircraft", "opensky", "flight", "airport"]):
        return "flights"
    if any(k in text_blob for k in ["sanction", "ofac", "treasury", "restriction", "embargo"]):
        return "sanctions"
    if any(k in text_blob for k in ["refugee", "displaced", "humanitarian", "reliefweb", "ocha", "unicef"]):
        return "displacement"
    if any(k in text_blob for k in ["war", "conflict", "missile", "drone", "attack", "military", "defense", "ucdp"]):
        return "ucdpEvents" if "ucdp" in source else "conflicts"
    return "newsLocations"


