def _wm211_v44_projection_name_for_fit(projection: str) -> str:
    """Normalize projection labels without depending on the older wrapper chain."""
    try:
        p = str(projection or "").strip().lower()
    except Exception:
        p = ""
    if p in {"3d", "3d globe", "orthographic", "globe"}:
        return "3D globe"
    return "Flat world"


def build_plotly_figure_v211(  # type: ignore[override]
    objects: pd.DataFrame,
    registry: pd.DataFrame,
    projection: str = "orthographic",
    region: str = "Global",
    max_points_per_layer: int = 1200,
    fig_height: int = 780,
    projection_scale: float | None = None,
) -> go.Figure:
    """Final viewport-fit wrapper around the validated Plotly builder.

    The previous logic stays authoritative. This wrapper only changes the visual
    projection scale/autosize defaults so the map is not left-compressed inside
    the Streamlit component.
    """
    normalized_projection = _wm211_v44_projection_name_for_fit(projection)

    # The old renderer often passed projection_scale=1.0 for 2D. That is safe
    # but leaves too much empty black space on wide screens. Keep 3D conservative.
    if projection_scale is None:
        safe_scale = 1.24 if normalized_projection == "Flat world" else 1.18
    else:
        try:
            raw_scale = float(projection_scale)
        except Exception:
            raw_scale = 1.0
        if normalized_projection == "Flat world":
            safe_scale = max(1.18, min(raw_scale if raw_scale > 0 else 1.0, 1.42))
        else:
            safe_scale = max(1.08, min(raw_scale if raw_scale > 0 else 1.0, 1.28))

    if callable(_WM211_V44_PREV_BUILD_PLOTLY_FIGURE):
        fig = _WM211_V44_PREV_BUILD_PLOTLY_FIGURE(
            objects,
            registry,
            projection=normalized_projection,
            region=region,
            max_points_per_layer=max_points_per_layer,
            fig_height=fig_height,
            projection_scale=safe_scale,
        )
    else:
        fig = go.Figure()

    try:
        fig.update_layout(
            autosize=True,
            height=int(max(560, fig_height)),
            margin=dict(l=0, r=0, t=0, b=0),
            paper_bgcolor="rgba(0,0,0,0)",
            plot_bgcolor="rgba(0,0,0,0)",
        )
    except Exception:
        pass

    try:
        if normalized_projection == "Flat world":
            fig.update_geos(
                projection_type="equirectangular",
                projection_scale=float(safe_scale),
                center=dict(lon=0, lat=10),
                lonaxis_range=[-180, 180],
                lataxis_range=[-58, 83],
                domain=dict(x=[0.0, 1.0], y=[0.0, 1.0]),
            )
        else:
            fig.update_geos(
                projection_type="orthographic",
                projection_scale=float(safe_scale),
                domain=dict(x=[0.0, 1.0], y=[0.0, 1.0]),
            )
    except Exception:
        pass

    return fig


