def _wm211_final_install_layer_specs_v45() -> None:
    global LAYER_SPECS, LAYER_BY_ID, DEFAULT_TRUE_LAYER_IDS
    try:
        existing = {str(getattr(s, "layer_id", "")) for s in LAYER_SPECS}
        additions = [s for s in _WM211_FINAL_NEW_LAYER_SPECS_V45 if s.layer_id not in existing]
        if additions:
            LAYER_SPECS = list(LAYER_SPECS) + additions

        upgraded = []
        for spec in LAYER_SPECS:
            sid = str(getattr(spec, "layer_id", ""))
            if sid in _WM211_FINAL_LIVE_BACKED_LAYERS_V45:
                src = str(getattr(spec, "source_class", ""))
                if "live" not in src:
                    src = "live/provider-ready" if "provider" in src else "static/live"
                note = str(getattr(spec, "note", ""))
                if "V4.5" not in note:
                    note = (note + " V4.5 no-key live mesh ready.").strip()
                try:
                    spec = _wm211_dataclasses.replace(spec, source_class=src, note=note)
                except Exception:
                    pass
            upgraded.append(spec)
        LAYER_SPECS = upgraded
        LAYER_BY_ID = {s.layer_id: s for s in LAYER_SPECS}
        DEFAULT_TRUE_LAYER_IDS = {s.layer_id for s in LAYER_SPECS if bool(getattr(s, "default", False))}
    except Exception:
        pass

_wm211_final_install_layer_specs_v45()

