def _wm211_geo_match_v45(text_blob: str) -> dict[str, Any] | None:
    blob = " " + re.sub(r"[^a-z0-9]+", " ", str(text_blob or "").lower()) + " "
    best = None
    best_len = 0
    for item in _WM211_GAZETTEER_V45:
        for alias in item.get("aliases", []):
            a = " " + re.sub(r"[^a-z0-9]+", " ", str(alias).lower()).strip() + " "
            if a.strip() and a in blob and len(a) > best_len:
                best = item
                best_len = len(a)
    return dict(best) if best else None

