def _wm211_classify_layer_v45(title: str, description: str = "", default: str = "newsLocations") -> str:
    blob = " " + re.sub(r"[^a-z0-9]+", " ", (str(title or "") + " " + str(description or "")).lower()) + " "
    for layer_id, keys in _WM211_LAYER_KEYWORDS_V45:
        for key in keys:
            k = " " + re.sub(r"[^a-z0-9]+", " ", key.lower()).strip() + " "
            if k in blob and layer_id in LAYER_BY_ID:
                return layer_id
    return default if default in LAYER_BY_ID else "newsLocations"

try:
    _WM211_PREV_EVENT_LAYER_ID_V45 = _event_layer_id
except Exception:
    _WM211_PREV_EVENT_LAYER_ID_V45 = None

def _event_layer_id(row: pd.Series) -> str:  # type: ignore[override]
    try:
        explicit = _text(row.get("layer_id"), "")
        if explicit in LAYER_BY_ID:
            return explicit
    except Exception:
        pass
    try:
        title = _text(row.get("title"), "")
        desc = " ".join(_text(row.get(c), "") for c in ["description", "subtype", "event_type", "market_channel", "source"] if c in row.index)
        layer = _wm211_classify_layer_v45(title, desc, default="")
        if layer:
            return layer
    except Exception:
        pass
    if callable(_WM211_PREV_EVENT_LAYER_ID_V45):
        return _WM211_PREV_EVENT_LAYER_ID_V45(row)
    return "newsLocations"

def _wm211_source_tier_v45(source: str, url: str = "") -> tuple[str, int]:
    blob = (str(source or "") + " " + str(url or "")).lower()
    if any(x in blob for x in ["usgs", "gdacs", "nasa", "eonet", "cisa", "nvd", "eia.gov", "who.int", "treasury.gov", "ofac", "imf.org", "worldbank.org", "wto.org"]):
        return "PRIMARY", 92
    if any(x in blob for x in ["reuters", "ap news", "associated press", "bloomberg", "cnbc", "financial times", "ft.com", "wsj", "bbc", "al jazeera", "dw.com", "france 24"]):
        return "WIRE/MEDIA", 82
    if any(x in blob for x in ["gdelt", "google news"]):
        return "AGGREGATED", 64
    return "OPEN", 56

def _wm211_severity_v45(layer_id: str, title: str, desc: str = "") -> int:
    blob = (str(title or "") + " " + str(desc or "")).lower()
    score = 54
    if layer_id in {"conflicts", "coupRisk", "civilianViolence", "maritimeSecurityIncidents", "missileRanges"}:
        score = 78
    elif layer_id in {"protestEvents", "riotUnrest", "strikeActions", "governmentInstability", "internetShutdowns"}:
        score = 68
    elif layer_id in {"activeRigs", "drillingPermits", "refineries", "lngTerminals", "gridStress", "portCongestion", "exportControls", "sanctions"}:
        score = 65
    elif layer_id in {"earthquakes", "activeFires", "floodEvents", "stormTracks", "volcanoEvents", "healthOutbreaks"}:
        score = 70
    if any(k in blob for k in ["dead", "killed", "fatal", "casualties", "severe", "critical", "emergency", "default", "war", "missile", "strike shuts", "closure"]):
        score += 12
    if any(k in blob for k in ["watch", "may", "could", "warns", "warning", "risk"]):
        score += 4
    return int(max(35, min(96, score)))

# ------------------------------------------------------------------
# 5) No-key fetchers
# ------------------------------------------------------------------

def _wm211_http_text_v45(url: str, timeout: int = 8) -> str:
    req = _wm211_urlrequest.Request(
        url,
        headers={
            "User-Agent": "QuantTerminal-WorldMonitor/4.5 (+no-key public feed reader)",
            "Accept": "application/rss+xml, application/json, text/xml, text/plain, */*",
        },
    )
    with _wm211_urlrequest.urlopen(req, timeout=timeout) as resp:
        raw = resp.read(2_500_000)
    return raw.decode("utf-8", errors="ignore")

def _wm211_parse_dt_v45(value: Any) -> _wm211_dt.datetime:
    if isinstance(value, _wm211_dt.datetime):
        dt = value
    else:
        txt = str(value or "").strip()
        if not txt:
            return _wm211_dt.datetime.utcnow().replace(tzinfo=_wm211_dt.timezone.utc)
        try:
            dt = _wm211_dt.datetime.fromisoformat(txt.replace("Z", "+00:00"))
        except Exception:
            try:
                dt = _wm211_email_utils.parsedate_to_datetime(txt)
            except Exception:
                dt = _wm211_dt.datetime.utcnow().replace(tzinfo=_wm211_dt.timezone.utc)
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=_wm211_dt.timezone.utc)
    return dt.astimezone(_wm211_dt.timezone.utc)

def _wm211_event_row_v45(layer_id: str, title: str, source: str, url: str, published: Any, description: str = "", provider: str = "public-feed") -> dict[str, Any] | None:
    title = _text(title, "")
    if not title:
        return None
    desc = _text(description, "")
    geo = _wm211_geo_match_v45(" ".join([title, desc, source, url]))
    if not geo:
        return None
    if layer_id not in LAYER_BY_ID:
        layer_id = _wm211_classify_layer_v45(title, desc, default="newsLocations")
    tier, base_conf = _wm211_source_tier_v45(source, url)
    pub_dt = _wm211_parse_dt_v45(published)
    age_h = max(0.0, (_wm211_dt.datetime.now(_wm211_dt.timezone.utc) - pub_dt).total_seconds() / 3600.0)
    freshness_bonus = 12 if age_h <= 6 else (6 if age_h <= 24 else 0)
    confidence = int(max(42, min(96, base_conf + freshness_bonus - (10 if tier == "AGGREGATED" else 0))))
    oid = _id_hash(layer_id, title, str(geo.get("name")), url)
    return {
        "event_id": f"wm211final:{oid}",
        "layer_id": layer_id,
        "title": title[:260],
        "description": desc[:700],
        "event_type": "no_key_live",
        "subtype": layer_id,
        "source": source[:160] or provider,
        "source_url": url[:800],
        "timestamp_utc": pub_dt.strftime("%Y-%m-%dT%H:%M:%SZ"),
        "country": str(geo.get("country", "")),
        "lat": float(geo["lat"]),
        "lon": float(geo["lon"]),
        "severity": _wm211_severity_v45(layer_id, title, desc),
        "confidence": confidence,
        "provider": provider,
        "source_tier": tier,
        "geo_name": str(geo.get("name", "")),
    }

def _wm211_google_news_rss_url_v45(query: str) -> str:
    # Google News RSS is intentionally used as a fallback aggregator for sources
    # that do not publish stable public RSS endpoints. It is not treated as a
    # primary source; provider confidence is lower unless the item source is a wire.
    q = _wm211_urlparse.quote_plus(str(query).strip())
    return f"https://news.google.com/rss/search?q={q}&hl=en-US&gl=US&ceid=US:en"

def _wm211_parse_rss_items_v45(xml_text: str) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    try:
        root = _wm211_ET.fromstring(xml_text.encode("utf-8", errors="ignore"))
    except Exception:
        return out
    for item in root.findall(".//item"):
        def _find_text(tag: str) -> str:
            node = item.find(tag)
            return node.text.strip() if node is not None and node.text else ""
        title = _find_text("title")
        link = _find_text("link")
        pub = _find_text("pubDate") or _find_text("published") or _find_text("updated")
        desc = _find_text("description")
        source = ""
        src_node = item.find("source")
        if src_node is not None and src_node.text:
            source = src_node.text.strip()
        out.append({"title": title, "url": link, "published": pub, "description": desc, "source": source})
    # Atom fallback
    ns = {"a": "http://www.w3.org/2005/Atom"}
    for item in root.findall(".//a:entry", ns):
        title_node = item.find("a:title", ns)
        link_node = item.find("a:link", ns)
        pub_node = item.find("a:published", ns) or item.find("a:updated", ns)
        out.append({
            "title": title_node.text if title_node is not None and title_node.text else "",
            "url": link_node.attrib.get("href", "") if link_node is not None else "",
            "published": pub_node.text if pub_node is not None and pub_node.text else "",
            "description": "",
            "source": "",
        })
    return out

