def _wm211_fetch_google_news_events_v45(hours_back: int, max_queries: int, per_query: int) -> tuple[pd.DataFrame, pd.DataFrame]:
    rows: list[dict[str, Any]] = []
    statuses: list[dict[str, Any]] = []
    now = _wm211_dt.datetime.now(_wm211_dt.timezone.utc)
    for layer_id, query in _WM211_FINAL_QUERY_BANK_V45[:max(1, int(max_queries))]:
        url = _wm211_google_news_rss_url_v45(query)
        before = len(rows)
        try:
            xml = _wm211_http_text_v45(url, timeout=8)
            items = _wm211_parse_rss_items_v45(xml)[:max(1, int(per_query))]
            for it in items:
                pub_dt = _wm211_parse_dt_v45(it.get("published"))
                if (now - pub_dt).total_seconds() > max(1, int(hours_back)) * 3600 * 1.25:
                    # Some Google News items do not carry fresh pubDate; keep only time-window aligned ones.
                    continue
                source = _text(it.get("source"), "Google News")
                ev = _wm211_event_row_v45(
                    layer_id=layer_id,
                    title=it.get("title", ""),
                    source=source if source else "Google News",
                    url=it.get("url", ""),
                    published=pub_dt,
                    description=it.get("description", ""),
                    provider="Google News RSS / no-key source mesh",
                )
                if ev:
                    rows.append(ev)
            statuses.append({"provider": f"GoogleNews:{layer_id}", "status": "OK", "rows": len(rows) - before, "detail": query[:140]})
        except Exception as exc:
            statuses.append({"provider": f"GoogleNews:{layer_id}", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:160]}"})
    return pd.DataFrame(rows), pd.DataFrame(statuses)

def _wm211_fetch_gdelt_doc_events_v45(hours_back: int, max_queries: int, per_query: int) -> tuple[pd.DataFrame, pd.DataFrame]:
    rows: list[dict[str, Any]] = []
    statuses: list[dict[str, Any]] = []
    # Use fewer GDELT queries than Google News to avoid slow startup.
    query_subset = _WM211_FINAL_QUERY_BANK_V45[:max(1, min(int(max_queries), 14))]
    timespan = f"{max(1, min(int(hours_back), 168))}h"
    for layer_id, query in query_subset:
        # Remove Google News operators not meaningful to GDELT.
        q = re.sub(r"\bwhen:\d+[hd]\b", "", query, flags=re.I).strip()
        q = q.replace('"', "%22")
        url = (
            "https://api.gdeltproject.org/api/v2/doc/doc?"
            f"query={_wm211_urlparse.quote(q)}&mode=artlist&format=json&maxrecords={max(1, int(per_query))}&timespan={_wm211_urlparse.quote(timespan)}"
        )
        before = len(rows)
        try:
            txt = _wm211_http_text_v45(url, timeout=9)
            payload = json.loads(txt)
            for art in (payload.get("articles") or [])[:max(1, int(per_query))]:
                title = art.get("title") or ""
                src = art.get("sourceCommonName") or art.get("domain") or "GDELT"
                link = art.get("url") or ""
                pub = art.get("seendate") or art.get("socialimage") or ""
                ev = _wm211_event_row_v45(
                    layer_id=layer_id,
                    title=title,
                    source=str(src),
                    url=str(link),
                    published=pub,
                    description=str(art.get("language", "")),
                    provider="GDELT DOC 2.0 / no-key",
                )
                if ev:
                    rows.append(ev)
            statuses.append({"provider": f"GDELT:{layer_id}", "status": "OK", "rows": len(rows) - before, "detail": q[:140]})
        except Exception as exc:
            statuses.append({"provider": f"GDELT:{layer_id}", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:160]}"})
    return pd.DataFrame(rows), pd.DataFrame(statuses)

def _wm211_fetch_usgs_final_v45(hours_back: int = 24) -> tuple[pd.DataFrame, pd.DataFrame]:
    rows: list[dict[str, Any]] = []
    url = "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_day.geojson" if int(hours_back) <= 24 else "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_week.geojson"
    try:
        payload = json.loads(_wm211_http_text_v45(url, timeout=8))
        for feat in payload.get("features", [])[:450]:
            props = feat.get("properties") or {}
            geom = feat.get("geometry") or {}
            coords = geom.get("coordinates") or []
            if not isinstance(coords, list) or len(coords) < 2:
                continue
            lon, lat = float(coords[0]), float(coords[1])
            mag = props.get("mag")
            place = props.get("place") or "Earthquake"
            ts_ms = props.get("time")
            pub = _wm211_dt.datetime.fromtimestamp(float(ts_ms or 0) / 1000.0, tz=_wm211_dt.timezone.utc) if ts_ms else _wm211_dt.datetime.now(_wm211_dt.timezone.utc)
            rows.append({
                "event_id": f"usgs:{props.get('code') or _id_hash(place, lat, lon, ts_ms)}",
                "layer_id": "earthquakes",
                "title": f"M{mag or '?'} earthquake · {place}",
                "description": str(props.get("title") or ""),
                "event_type": "earthquake",
                "subtype": "USGS",
                "source": "USGS",
                "source_url": str(props.get("url") or url),
                "timestamp_utc": pub.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "country": str(place),
                "lat": lat,
                "lon": lon,
                "severity": int(max(35, min(98, 38 + float(mag or 2.5) * 9))),
                "confidence": 94,
                "provider": "USGS GeoJSON",
                "source_tier": "PRIMARY",
                "geo_name": place,
            })
        return pd.DataFrame(rows), pd.DataFrame([{"provider": "USGS final", "status": "OK", "rows": len(rows), "detail": "GeoJSON no-key"}])
    except Exception as exc:
        return pd.DataFrame(rows), pd.DataFrame([{"provider": "USGS final", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:160]}"}])

def _wm211_fetch_eonet_final_v45(hours_back: int = 168) -> tuple[pd.DataFrame, pd.DataFrame]:
    rows: list[dict[str, Any]] = []
    url = f"https://eonet.gsfc.nasa.gov/api/v3/events?days={max(1, min(int(hours_back/24)+1, 30))}&status=open"
    try:
        payload = json.loads(_wm211_http_text_v45(url, timeout=8))
        for ev0 in payload.get("events", [])[:280]:
            cats = ev0.get("categories") or []
            cat_title = " ".join(str(c.get("title", "")) for c in cats if isinstance(c, dict))
            layer = "natural"
            if re.search("wildfire|fire", cat_title, re.I):
                layer = "activeFires" if "activeFires" in LAYER_BY_ID else "fires"
            elif re.search("flood", cat_title, re.I):
                layer = "floodEvents" if "floodEvents" in LAYER_BY_ID else "natural"
            elif re.search("storm|cyclone|severe", cat_title, re.I):
                layer = "stormTracks" if "stormTracks" in LAYER_BY_ID else "weather"
            elif re.search("volcano", cat_title, re.I):
                layer = "volcanoEvents" if "volcanoEvents" in LAYER_BY_ID else "natural"
            geoms = ev0.get("geometry") or []
            for geom in geoms[:1]:
                coords = geom.get("coordinates") if isinstance(geom, dict) else None
                if not isinstance(coords, list) or len(coords) < 2:
                    continue
                lon, lat = float(coords[0]), float(coords[1])
                pub = geom.get("date") or ev0.get("closed") or _wm211_dt.datetime.now(_wm211_dt.timezone.utc).isoformat()
                rows.append({
                    "event_id": f"eonet:{ev0.get('id') or _id_hash(ev0.get('title'), lat, lon)}",
                    "layer_id": layer,
                    "title": str(ev0.get("title") or "NASA EONET event"),
                    "description": cat_title,
                    "event_type": "natural_event",
                    "subtype": cat_title,
                    "source": "NASA EONET",
                    "source_url": str(ev0.get("link") or url),
                    "timestamp_utc": _wm211_parse_dt_v45(pub).strftime("%Y-%m-%dT%H:%M:%SZ"),
                    "country": "",
                    "lat": lat,
                    "lon": lon,
                    "severity": 70,
                    "confidence": 90,
                    "provider": "NASA EONET",
                    "source_tier": "PRIMARY",
                    "geo_name": str(ev0.get("title") or ""),
                })
        return pd.DataFrame(rows), pd.DataFrame([{"provider": "NASA EONET final", "status": "OK", "rows": len(rows), "detail": "EONET v3 no-key"}])
    except Exception as exc:
        return pd.DataFrame(rows), pd.DataFrame([{"provider": "NASA EONET final", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:160]}"}])

def _wm211_fetch_gdacs_final_v45() -> tuple[pd.DataFrame, pd.DataFrame]:
    url = "https://www.gdacs.org/xml/rss.xml"
    rows: list[dict[str, Any]] = []
    try:
        xml = _wm211_http_text_v45(url, timeout=8)
        for it in _wm211_parse_rss_items_v45(xml)[:80]:
            title = str(it.get("title") or "")
            layer = _wm211_classify_layer_v45(title, str(it.get("description") or ""), default="natural")
            if layer == "newsLocations":
                layer = "natural"
            ev = _wm211_event_row_v45(layer, title, "GDACS", str(it.get("url") or ""), it.get("published"), it.get("description", ""), "GDACS RSS")
            if ev:
                ev["confidence"] = max(int(ev.get("confidence", 80)), 90)
                ev["source_tier"] = "PRIMARY"
                rows.append(ev)
        return pd.DataFrame(rows), pd.DataFrame([{"provider": "GDACS final", "status": "OK", "rows": len(rows), "detail": "RSS no-key"}])
    except Exception as exc:
        return pd.DataFrame(rows), pd.DataFrame([{"provider": "GDACS final", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:160]}"}])

def _wm211_fetch_x_status_v45() -> tuple[pd.DataFrame, pd.DataFrame]:
    # Do not scrape X. This is deliberately locked unless a compliant API token is supplied later.
    token = os.getenv("X_BEARER_TOKEN", "").strip()
    if not token:
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "X / Twitter",
            "status": "LOCKED",
            "rows": 0,
            "detail": "No scraping. Set X_BEARER_TOKEN only for a compliant future API adapter.",
        }])
    return pd.DataFrame(), pd.DataFrame([{
        "provider": "X / Twitter",
        "status": "READY",
        "rows": 0,
        "detail": "Token detected, but V4.5 intentionally does not implement X ingestion without an explicit approved API adapter.",
    }])

def _wm211_fetch_final_live_events_v45(hours_back: int = 24, cache_nonce: int = 0, provider_profile: str = "Fast natural") -> tuple[pd.DataFrame, pd.DataFrame]:
    max_queries = int(os.getenv("WORLDMONITOR_LIVE_QUERY_BUDGET", "12"))
    per_query = int(os.getenv("WORLDMONITOR_LIVE_RESULTS_PER_QUERY", "4"))
    profile = str(provider_profile or "Fast natural")
    if profile == "Fast natural":
        # In the current native entrypoint this is the profile used by the validated map.
        # Keep it broad but capped: enough live coverage without freezing Streamlit.
        max_queries = min(max_queries, 12)
        per_query = min(per_query, 4)
    frames: list[pd.DataFrame] = []
    statuses: list[pd.DataFrame] = []

    # Primary/open event feeds first.
    for fn in [
        lambda: _wm211_fetch_usgs_final_v45(hours_back),
        lambda: _wm211_fetch_gdacs_final_v45(),
        lambda: _wm211_fetch_eonet_final_v45(hours_back),
        lambda: _wm211_fetch_google_news_events_v45(hours_back, max_queries=max_queries, per_query=per_query),
        lambda: _wm211_fetch_gdelt_doc_events_v45(hours_back, max_queries=max_queries // 2, per_query=max(2, per_query // 2)),
        _wm211_fetch_x_status_v45,
    ]:
        try:
            df, st_df = fn()
            if isinstance(df, pd.DataFrame) and not df.empty:
                frames.append(df)
            if isinstance(st_df, pd.DataFrame) and not st_df.empty:
                statuses.append(st_df)
        except Exception as exc:
            statuses.append(pd.DataFrame([{"provider": "WM211 final live", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:160]}"}]))

    events = pd.concat(frames, ignore_index=True, sort=False) if frames else pd.DataFrame()
    if not events.empty:
        events["_dedupe"] = events.apply(lambda r: _id_hash(r.get("layer_id"), r.get("title"), r.get("lat"), r.get("lon"), r.get("source_url")), axis=1)
        events = events.drop_duplicates("_dedupe", keep="first").drop(columns=["_dedupe"], errors="ignore").reset_index(drop=True)
        events["severity"] = pd.to_numeric(events.get("severity"), errors="coerce").fillna(55).clip(0, 100)
        events["confidence"] = pd.to_numeric(events.get("confidence"), errors="coerce").fillna(60).clip(0, 100)
    status = pd.concat(statuses, ignore_index=True, sort=False) if statuses else pd.DataFrame()
    if not status.empty:
        status = pd.concat([pd.DataFrame([{"provider": "WM211 FINAL LIVE V4.5", "status": "OK" if not events.empty else "EMPTY", "rows": len(events), "detail": f"no-key live mesh; profile={profile}; queries={max_queries}; cache_nonce={cache_nonce}"}]), status], ignore_index=True)
    return events, status

# ------------------------------------------------------------------
# 6) Override live loader safely: old loader remains fallback.
# ------------------------------------------------------------------

try:
    _WM211_PREV_LOAD_LIVE_EVENT_OBJECTS_V45 = load_live_event_objects_v211
except Exception:
    _WM211_PREV_LOAD_LIVE_EVENT_OBJECTS_V45 = None

@st.cache_data(ttl=300, show_spinner=False)
def load_live_event_objects_v211(  # type: ignore[override]
    hours_back: int = 168,
    min_magnitude: float = 2.5,
    cache_nonce: int = 0,
    provider_profile: str = "Fast natural",
) -> tuple[pd.DataFrame, pd.DataFrame]:
    object_frames: list[pd.DataFrame] = []
    status_frames: list[pd.DataFrame] = []

    # Existing validated providers first.
    if callable(_WM211_PREV_LOAD_LIVE_EVENT_OBJECTS_V45):
        try:
            old_objects, old_status = _WM211_PREV_LOAD_LIVE_EVENT_OBJECTS_V45(
                hours_back=hours_back,
                min_magnitude=min_magnitude,
                cache_nonce=cache_nonce,
                provider_profile=provider_profile,
            )
            if isinstance(old_objects, pd.DataFrame) and not old_objects.empty:
                object_frames.append(old_objects)
            if isinstance(old_status, pd.DataFrame) and not old_status.empty:
                status_frames.append(old_status)
        except Exception as exc:
            status_frames.append(pd.DataFrame([{"provider": "previous live loader", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:160]}"}]))

    # Final no-key live layer mesh.
    try:
        final_events, final_status = _wm211_fetch_final_live_events_v45(
            hours_back=int(hours_back or 24),
            cache_nonce=int(cache_nonce or 0),
            provider_profile=str(provider_profile or "Fast natural"),
        )
        if isinstance(final_status, pd.DataFrame) and not final_status.empty:
            status_frames.append(final_status)
        if isinstance(final_events, pd.DataFrame) and not final_events.empty:
            final_objects = _events_to_objects(final_events, source_name="WM211 FINAL LIVE V4.5")
            if isinstance(final_objects, pd.DataFrame) and not final_objects.empty:
                object_frames.append(final_objects)
    except Exception as exc:
        status_frames.append(pd.DataFrame([{"provider": "WM211 FINAL LIVE V4.5", "status": "ERROR", "rows": 0, "detail": f"{type(exc).__name__}: {str(exc)[:160]}"}]))

    objects = pd.concat(object_frames, ignore_index=True, sort=False) if object_frames else pd.DataFrame()
    if not objects.empty:
        objects = objects.drop_duplicates(subset=["object_id", "kind", "points_json"], keep="first").reset_index(drop=True)
        if "severity" in objects.columns:
            objects["severity"] = pd.to_numeric(objects["severity"], errors="coerce").fillna(55).clip(0, 100)
        if "confidence" in objects.columns:
            objects["confidence"] = pd.to_numeric(objects["confidence"], errors="coerce").fillna(60).clip(0, 100)
    status = pd.concat(status_frames, ignore_index=True, sort=False) if status_frames else pd.DataFrame([{"provider": "live", "status": "EMPTY", "rows": 0, "detail": "No live provider rows"}])
    return objects, status

