def _wmci_text_v50(value, default="") -> str:
    try:
        if value is None:
            return str(default)
        try:
            if pd.isna(value):
                return str(default)
        except Exception:
            pass
        out = str(value).strip()
        return out if out else str(default)
    except Exception:
        return str(default)


def _wmci_esc_v50(value) -> str:
    try:
        return html.escape(_wmci_text_v50(value), quote=True)
    except Exception:
        return str(value)


def _wmci_num_v50(value, default=0.0) -> float:
    try:
        x = float(value)
        if math.isfinite(x):
            return x
    except Exception:
        pass
    return float(default)


def _wmci_clip_v50(value, lo=0, hi=100) -> int:
    try:
        return int(max(lo, min(hi, round(float(value)))))
    except Exception:
        return int(lo)


def _wmci_stable_v50(label: str, lo: float, hi: float) -> float:
    try:
        raw = int(hashlib.sha1(str(label).encode("utf-8", "ignore")).hexdigest()[:8], 16)
        return float(lo) + (raw % 10000) / 10000.0 * (float(hi) - float(lo))
    except Exception:
        return float(lo)


def _wmci_country_options_v50() -> list[str]:
    base = [
        "Global", "France", "United States", "China", "Taiwan", "Israel", "Ukraine", "Germany", "Japan",
        "Poland", "United Kingdom", "India", "Russia", "Saudi Arabia", "United Arab Emirates", "Singapore", "South Korea",
        "Turkey", "Brazil", "Mexico", "Egypt", "South Africa", "Nigeria", "Indonesia", "Australia", "Canada",
    ]
    try:
        existing = list(globals().get("_WM21121_COUNTRIES", [])) + list(globals().get("_WM_COUNTRIES", []))
    except Exception:
        existing = []
    out = []
    for item in existing + base:
        item = _wmci_text_v50(item)
        if item and item not in out:
            out.append(item)
    return out or base


