def _wmci_country_meta_v50(country: str) -> dict:
    name = _wmci_text_v50(country, "Global")
    if name in _WMCI_COUNTRY_META_V50:
        meta = dict(_WMCI_COUNTRY_META_V50[name])
    else:
        try:
            cfg = dict(globals().get("_WM21121_COUNTRY_CONTEXT", {}).get(name, {}))
        except Exception:
            cfg = {}
        meta = {
            "iso2": cfg.get("iso2", ""),
            "iso3": cfg.get("iso3", ""),
            "flag": "🌐",
            "region": cfg.get("region", "Global"),
            "lon": cfg.get("lon", 15.0),
            "lat": cfg.get("lat", 8.0),
            "bbox": [*(cfg.get("lon_range", [-180, 180])), *(cfg.get("lat_range", [-62, 84]))],
            "keywords": list(cfg.get("keywords", [])),
        }
    meta["name"] = name
    if "bbox" not in meta:
        meta["bbox"] = [-180, 180, -62, 84]
    meta["keywords"] = list(dict.fromkeys([name.lower()] + [str(x).lower() for x in meta.get("keywords", []) if x]))
    return meta


