def _wmci_profile_energy_v50(country: str) -> dict:
    return dict(_WMCI_ENERGY_PROFILES_V50.get(country, _WMCI_ENERGY_PROFILES_V50.get("Global", {})))


def _wmci_profile_macro_v50(country: str) -> dict:
    base = dict(_WMCI_MACRO_PROFILES_V50.get(country, _WMCI_MACRO_PROFILES_V50.get("Global", {})))
    if country not in _WMCI_MACRO_PROFILES_V50 and country != "Global":
        base["instability"] = _wmci_clip_v50(_wmci_stable_v50(country + "instability", 18, 58))
        base["gdp"] = round(_wmci_stable_v50(country + "gdp", 0.5, 5.5), 1)
        base["cpi"] = round(_wmci_stable_v50(country + "cpi", 1.5, 8.0), 1)
        base["unemployment"] = round(_wmci_stable_v50(country + "unemp", 2.0, 11.0), 1)
        base["primary_balance"] = round(_wmci_stable_v50(country + "bal", -8.0, 2.0), 1)
        base["gdp_capita"] = int(_wmci_stable_v50(country + "gdppc", 5000, 65000))
        base["debt"] = int(_wmci_stable_v50(country + "debt", 28, 130))
        base["fx"] = "local FX"
        base["source"] = "derived atlas fallback"
    return base


def _wmci_profile_infra_v50(country: str) -> dict:
    if country in _WMCI_INFRA_PROFILES_V50:
        return dict(_WMCI_INFRA_PROFILES_V50[country])
    return dict(_WMCI_INFRA_PROFILES_V50.get("Global", {}))


def _wmci_history_for_country_v50(country: str, limit: int = 8) -> list[dict]:
    rows = [r for r in _WMCI_HISTORY_LEDGER_V50 if r.get("country") in {country, "Global"}]
    rows = sorted(rows, key=lambda r: int(r.get("year", 0)), reverse=True)
    return rows[:int(limit)]


def _wmci_object_blob_v50(row) -> str:
    vals = []
    for col in ["title", "metadata", "source_file", "collection", "layer_id", "country", "region", "object_id", "layer_label", "group"]:
        try:
            vals.append(str(row.get(col, "") or ""))
        except Exception:
            pass
    return " " + " ".join(vals).lower() + " "


def _wmci_point_in_bbox_v50(row, meta: dict) -> bool:
    try:
        bbox = meta.get("bbox", [-180, 180, -62, 84])
        lon_min, lon_max, lat_min, lat_max = float(bbox[0]), float(bbox[1]), float(bbox[2]), float(bbox[3])
        lon = float(row.get("lon"))
        lat = float(row.get("lat"))
        return lon_min <= lon <= lon_max and lat_min <= lat <= lat_max
    except Exception:
        return False


def _wmci_filter_country_objects_v50(objects, country: str):
    if not isinstance(objects, pd.DataFrame) or objects.empty:
        return pd.DataFrame()
    if str(country or "Global") == "Global":
        return objects.copy()
    meta = _wmci_country_meta_v50(country)
    keywords = [str(k).lower() for k in meta.get("keywords", []) if k]
    rows = []
    try:
        for idx, row in objects.iterrows():
            blob = _wmci_object_blob_v50(row)
            has_kw = any((" " + kw + " ") in blob or kw in blob for kw in keywords if len(kw) >= 3)
            has_box = _wmci_point_in_bbox_v50(row, meta)
            if has_kw or has_box:
                rows.append(idx)
    except Exception:
        return pd.DataFrame()
    if not rows:
        return pd.DataFrame()
    return objects.loc[rows].copy().reset_index(drop=True)


def _wmci_load_objects_v50(country: str, live_enabled: bool, time_window: str):
    static_objects = pd.DataFrame()
    live_objects = pd.DataFrame()
    try:
        static_objects, _ = load_worldmonitor_static_objects_v211("")
    except Exception:
        static_objects = pd.DataFrame()
    if bool(live_enabled):
        try:
            hours = int(globals().get("_wm21121_time_to_hours", lambda x: 24)(str(time_window or "24h")))
        except Exception:
            hours = 24
        try:
            live_objects, _ = load_live_event_objects_v211(
                hours_back=max(1, min(int(hours), 24 * 365 * 5)),
                min_magnitude=0.0,
                cache_nonce=int(hours),
                provider_profile="All configured" if int(hours) >= 168 else "Fast natural",
            )
        except Exception:
            live_objects = pd.DataFrame()
    frames = [df for df in [static_objects, live_objects] if isinstance(df, pd.DataFrame) and not df.empty]
    objects = pd.concat(frames, ignore_index=True, sort=False) if frames else pd.DataFrame()
    if not objects.empty:
        try:
            objects = objects.drop_duplicates(subset=[c for c in ["object_id", "kind", "points_json"] if c in objects.columns], keep="first").reset_index(drop=True)
        except Exception:
            objects = objects.drop_duplicates().reset_index(drop=True)
    country_objects = _wmci_filter_country_objects_v50(objects, country)
    return objects, country_objects


def _wmci_theme_counts_v50(country_objects) -> dict[str, int]:
    counts: dict[str, int] = {}
    if not isinstance(country_objects, pd.DataFrame) or country_objects.empty or "layer_id" not in country_objects.columns:
        return counts
    try:
        for layer_id, n in country_objects["layer_id"].astype(str).value_counts().items():
            theme = _WMCI_LAYER_THEME_MAP_V50.get(str(layer_id), str(layer_id))
            counts[theme] = int(counts.get(theme, 0) + int(n))
    except Exception:
        pass
    return counts


def _wmci_live_rows_v50(country_objects, limit: int = 8) -> list[dict]:
    if not isinstance(country_objects, pd.DataFrame) or country_objects.empty:
        return []
    df = country_objects.copy()
    try:
        if "source_class" in df.columns:
            live = df[df["source_class"].astype(str).str.contains("live", case=False, na=False)].copy()
            if not live.empty:
                df = live
        if "severity" in df.columns:
            df["_sev"] = pd.to_numeric(df["severity"], errors="coerce").fillna(50)
            df = df.sort_values("_sev", ascending=False)
    except Exception:
        pass
    rows = []
    for _, r in df.head(int(limit)).iterrows():
        layer = _wmci_text_v50(r.get("layer_id"), "signal")
        sev = _wmci_clip_v50(r.get("severity", 50))
        rows.append({
            "title": _wmci_text_v50(r.get("title"), "Country signal"),
            "layer": layer,
            "theme": _WMCI_LAYER_THEME_MAP_V50.get(layer, layer),
            "source": _wmci_text_v50(r.get("source_file"), "source"),
            "severity": sev,
            "confidence": _wmci_clip_v50(r.get("confidence", 60)),
        })
    return rows


def _wmci_instability_v50(country: str, theme_counts: dict, live_rows: list[dict]) -> dict:
    macro = _wmci_profile_macro_v50(country)
    base = _wmci_num_v50(macro.get("instability", 25), 25)
    live_boost = min(18.0, sum(max(0, r.get("severity", 0) - 60) for r in live_rows[:5]) / 12.0)
    social_boost = min(12.0, (theme_counts.get("social", 0) + theme_counts.get("political", 0)) * 0.8)
    military_boost = min(16.0, theme_counts.get("military", 0) * 0.7)
    score = _wmci_clip_v50(base + live_boost + social_boost + military_boost)
    if score >= 75:
        regime, color = "Critical", "#ff4d5c"
    elif score >= 50:
        regime, color = "Elevated", "#f59e0b"
    elif score >= 25:
        regime, color = "Watch", "#fbbf24"
    else:
        regime, color = "Stable", "#33ff88"
    return {"score": score, "regime": regime, "color": color, "base": _wmci_clip_v50(base), "live_boost": round(live_boost, 1)}


def _wmci_energy_exposure_score_v50(country: str, scenario: str) -> int:
    energy = _wmci_profile_energy_v50(country)
    dep = _wmci_text_v50(energy.get("import"), "").lower()
    storage = _wmci_num_v50(energy.get("storage", 60), 60)
    score = 38
    if "very high" in dep or "near total" in dep:
        score += 26
    elif "high" in dep or "net importer" in dep:
        score += 17
    elif "exporter" in dep:
        score -= 10
    if "hormuz" in scenario.lower() or "suez" in scenario.lower():
        if any(k in _wmci_text_v50(energy.get("exposure"), "").lower() for k in ["hormuz", "malacca", "shipping", "lng", "red sea"]):
            score += 14
    if storage < 45:
        score += 12
    elif storage > 90:
        score -= 8
    return _wmci_clip_v50(score)


def _wmci_scenario_result_v50(country: str, scenario: str, intensity: str, transmission: str, theme_counts: dict) -> dict:
    tmpl = dict(_WMCI_SCENARIO_TEMPLATES_V50.get(scenario, _WMCI_SCENARIO_TEMPLATES_V50["Sanctions escalation"]))
    try:
        mult = {"Low": 0.65, "Base": 1.0, "High": 1.35, "Severe": 1.75}.get(str(intensity), 1.0)
    except Exception:
        mult = 1.0
    energy_score = _wmci_energy_exposure_score_v50(country, scenario)
    macro = _wmci_profile_macro_v50(country)
    debt = _wmci_num_v50(macro.get("debt", 60), 60)
    import_add = max(0, energy_score - 50) / 6
    signal_add = min(15, sum(theme_counts.values()) / 18)
    impact = _wmci_clip_v50((tmpl.get("base", 30) + energy_score * 0.35 + debt * 0.08 + import_add + signal_add) * mult)
    bridge_days = max(7, int(_wmci_num_v50(_wmci_profile_energy_v50(country).get("storage", 60), 60) * 5.8 / max(0.55, mult)))
    return {
        "impact": impact,
        "energy": energy_score,
        "bridge_days": bridge_days,
        "inflation": round((tmpl.get("inflation", 10) * mult + max(0, energy_score - 50) / 10), 1),
        "trade": _wmci_clip_v50(tmpl.get("trade", 12) * mult + theme_counts.get("trade", 0) * 0.8),
        "finance": _wmci_clip_v50(tmpl.get("finance", 10) * mult + debt / 8),
        "transmission": transmission,
        "assumption": "Public/atlas model. Use as directional stress-test, not as a priced forecast.",
    }


def _wmci_mix_html_v50(mix: dict, title: str) -> str:
    if not isinstance(mix, dict) or not mix:
        return ""
    rows = []
    for k, v in sorted(mix.items(), key=lambda kv: -_wmci_num_v50(kv[1], 0)):
        pct = _wmci_clip_v50(v)
        rows.append(f'<div class="wmci-mix-row"><span>{_wmci_esc_v50(k)}</span><div class="wmci-bar"><i style="width:{pct}%"></i></div><b>{pct}%</b></div>')
    return f'<div class="wmci-card"><h4>{_wmci_esc_v50(title)}</h4>{"".join(rows)}</div>'


def _wmci_badge_v50(label: str, value, color: str = "#38bdf8") -> str:
    return f'<span class="wmci-badge" style="border-color:{color};color:{color};">{_wmci_esc_v50(label)} <b>{_wmci_esc_v50(value)}</b></span>'


def _wmci_html_v50(country: str, live_enabled: bool, time_window: str, scenario: str, intensity: str, transmission: str) -> str:
    meta = _wmci_country_meta_v50(country)
    _objects, country_objects = _wmci_load_objects_v50(country, live_enabled, time_window)
    theme_counts = _wmci_theme_counts_v50(country_objects)
    live_rows = _wmci_live_rows_v50(country_objects, limit=8)
    macro = _wmci_profile_macro_v50(country)
    energy = _wmci_profile_energy_v50(country)
    infra = _wmci_profile_infra_v50(country)
    history = _wmci_history_for_country_v50(country, 8)
    instability = _wmci_instability_v50(country, theme_counts, live_rows)
    scenario_res = _wmci_scenario_result_v50(country, scenario, intensity, transmission, theme_counts)

    source_quality = _wmci_clip_v50(58 + min(18, len(live_rows) * 3) + min(14, len(country_objects) / 18 if hasattr(country_objects, "__len__") else 0))
    active_total = len(live_rows)
    critical = sum(1 for r in live_rows if r.get("severity", 0) >= 80)
    high = sum(1 for r in live_rows if 65 <= r.get("severity", 0) < 80)
    moderate = sum(1 for r in live_rows if 45 <= r.get("severity", 0) < 65)
    layer_total = int(len(country_objects)) if isinstance(country_objects, pd.DataFrame) else 0

    brief_bits = []
    if instability["score"] >= 50:
        brief_bits.append(f"instability {instability['score']}/100 {instability['regime']}")
    else:
        brief_bits.append(f"instability {instability['score']}/100 {instability['regime']}")
    if active_total:
        brief_bits.append(f"{active_total} live/country signals")
    if energy.get("import"):
        brief_bits.append(str(energy.get("import")))
    if history:
        brief_bits.append(f"{len(history)} historical shocks indexed")
    brief = " · ".join(brief_bits)

    signals_html = ""
    if live_rows:
        for r in live_rows[:6]:
            sev = int(r.get("severity", 0))
            c = "#ff4d5c" if sev >= 80 else "#f59e0b" if sev >= 65 else "#38bdf8"
            signals_html += f"""
            <div class="wmci-signal">
                <div><b>{_wmci_esc_v50(r.get('title'))}</b><small>{_wmci_esc_v50(r.get('source'))} · {_wmci_esc_v50(r.get('theme'))}</small></div>
                <span style="color:{c};border-color:{c};">{sev}</span>
            </div>"""
    else:
        signals_html = '<div class="wmci-empty">No recent country-specific live signal in selected event window. Static/atlas context remains active.</div>'

    history_html = ""
    for h in history:
        themes = " ".join([f'<span>{_wmci_esc_v50(t)}</span>' for t in h.get("themes", [])[:5]])
        pcol = "#33ff88" if h.get("persistence") == "low" else "#fbbf24" if h.get("persistence") == "medium" else "#ff4d5c"
        history_html += f"""
        <div class="wmci-history">
            <div class="wmci-year">{_wmci_esc_v50(h.get('year'))}</div>
            <div><b>{_wmci_esc_v50(h.get('title'))}</b><p>{_wmci_esc_v50(h.get('impact'))}</p><div class="wmci-tags">{themes}</div></div>
            <em style="color:{pcol};">{_wmci_esc_v50(h.get('persistence'))}</em>
        </div>"""

    theme_html = ""
    theme_order = ["military", "social", "political", "energy", "trade", "finance", "cyber", "technology", "commodities", "natural", "food", "water", "health"]
    for t in theme_order:
        n = int(theme_counts.get(t, 0))
        width = min(100, 8 + n * 9)
        theme_html += f'<div class="wmci-theme"><span>{_wmci_esc_v50(t)}</span><div class="wmci-bar"><i style="width:{width}%"></i></div><b>{n}</b></div>'

    infra_html = ""
    for label, vals in [("Ports", infra.get("ports", [])), ("Pipelines", infra.get("pipelines", [])), ("Storage", infra.get("storage", [])), ("Critical nodes", infra.get("nodes", []))]:
        vals = vals or []
        infra_html += f'<div class="wmci-list"><b>{_wmci_esc_v50(label)}</b><p>{_wmci_esc_v50(" · ".join(vals[:5]) if vals else "No atlas node yet")}</p></div>'

    macro_html = ""
    macro_rows = [
        ("Real GDP growth", f"{_wmci_num_v50(macro.get('gdp'), 0):+.1f}%", "macro"),
        ("CPI inflation", f"{_wmci_num_v50(macro.get('cpi'), 0):.1f}%", "prices"),
        ("Unemployment", f"{_wmci_num_v50(macro.get('unemployment'), 0):.1f}%", "labor"),
        ("Primary balance", f"{_wmci_num_v50(macro.get('primary_balance'), 0):+.1f}% GDP", "fiscal"),
        ("Debt", f"{_wmci_num_v50(macro.get('debt'), 0):.0f}% GDP", "sovereign"),
        ("GDP / capita", f"${_wmci_num_v50(macro.get('gdp_capita'), 0):,.0f}", "income"),
    ]
    for label, value, sub in macro_rows:
        macro_html += f'<div class="wmci-kpi"><small>{_wmci_esc_v50(label)}</small><strong>{_wmci_esc_v50(value)}</strong><span>{_wmci_esc_v50(sub)}</span></div>'

    shock_color = "#ff4d5c" if scenario_res["impact"] >= 75 else "#f59e0b" if scenario_res["impact"] >= 50 else "#33ff88"

    html_payload = f"""
    <style>
    .wmci-wrap{{border:1px solid rgba(56,189,248,.22);background:linear-gradient(180deg,rgba(12,14,18,.98),rgba(5,6,9,.98));margin:10px 0 12px 0;color:#f3f4f6;font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;box-shadow:inset 0 0 36px rgba(56,189,248,.05);}}
    .wmci-head{{display:grid;grid-template-columns:1.1fr .9fr .9fr .9fr .9fr;gap:1px;background:rgba(148,163,184,.16);border-bottom:1px solid rgba(148,163,184,.25);}}
    .wmci-title{{background:#121212;padding:18px 20px;}}
    .wmci-title h2{{margin:0;color:#f8fafc;font-size:24px;letter-spacing:.10em;text-transform:uppercase;}}
    .wmci-title small{{color:#8b949e;font-weight:900;letter-spacing:.08em;}}
    .wmci-head-kpi{{background:#121212;padding:16px 18px;}}
    .wmci-head-kpi small{{display:block;color:#8b949e;text-transform:uppercase;font-weight:900;font-size:11px;}}
    .wmci-head-kpi strong{{display:block;font-size:25px;margin-top:5px;}}
    .wmci-badge{{display:inline-block;border:1px solid rgba(56,189,248,.38);border-radius:999px;padding:4px 8px;margin:5px 5px 0 0;font-size:11px;font-weight:900;}}
    .wmci-body{{display:grid;grid-template-columns:1.10fr 1.05fr 1.15fr;gap:6px;padding:6px;}}
    .wmci-panel{{border:1px solid rgba(148,163,184,.20);background:linear-gradient(180deg,#171717,#0c0c0d);min-height:220px;overflow:hidden;}}
    .wmci-panel h3{{margin:0;padding:13px 15px;border-bottom:1px solid rgba(148,163,184,.18);font-size:16px;letter-spacing:.12em;text-transform:uppercase;color:#e5e7eb;background:rgba(255,255,255,.025);}}
    .wmci-panel h4{{margin:0 0 12px 0;color:#8b949e;text-transform:uppercase;letter-spacing:.08em;font-size:12px;}}
    .wmci-card{{padding:15px;border-bottom:1px solid rgba(148,163,184,.13);}}
    .wmci-brief{{padding:16px 18px;background:linear-gradient(90deg,rgba(56,189,248,.13),rgba(255,255,255,.02));border-left:4px solid #38bdf8;margin:14px;font-size:15px;line-height:1.45;}}
    .wmci-grid2{{display:grid;grid-template-columns:1fr 1fr;gap:8px;padding:12px;}}
    .wmci-kpi{{border:1px solid rgba(148,163,184,.18);background:#101010;padding:12px;min-height:78px;}}
    .wmci-kpi small{{display:block;color:#8b949e;text-transform:uppercase;font-size:10px;font-weight:900;}}
    .wmci-kpi strong{{display:block;font-size:21px;margin:5px 0;color:#fff;}}
    .wmci-kpi span{{color:#8b949e;font-size:11px;}}
    .wmci-mix-row,.wmci-theme{{display:grid;grid-template-columns:115px 1fr 44px;gap:8px;align-items:center;margin:8px 0;font-size:12px;}}
    .wmci-bar{{height:8px;background:#1f2937;border-radius:999px;overflow:hidden;}}
    .wmci-bar i{{display:block;height:100%;background:linear-gradient(90deg,#33ff88,#38bdf8);}}
    .wmci-signal{{display:grid;grid-template-columns:1fr 48px;gap:8px;align-items:center;padding:12px 14px;border-bottom:1px solid rgba(148,163,184,.14);}}
    .wmci-signal b{{display:block;font-size:14px;line-height:1.25;}}
    .wmci-signal small{{display:block;color:#8b949e;margin-top:5px;font-size:10px;text-transform:uppercase;}}
    .wmci-signal span{{border:1px solid;border-radius:999px;text-align:center;font-weight:950;padding:5px 0;}}
    .wmci-history{{display:grid;grid-template-columns:58px 1fr 62px;gap:10px;padding:12px 14px;border-bottom:1px solid rgba(148,163,184,.13);}}
    .wmci-year{{color:#38bdf8;font-weight:950;}}
    .wmci-history b{{font-size:14px;}}
    .wmci-history p{{margin:6px 0;color:#cbd5e1;font-size:12px;line-height:1.35;}}
    .wmci-history em{{font-style:normal;text-transform:uppercase;font-size:10px;font-weight:950;text-align:right;}}
    .wmci-tags span{{display:inline-block;border:1px solid rgba(56,189,248,.28);color:#7dd3fc;border-radius:999px;padding:2px 6px;font-size:10px;margin:2px 3px 0 0;}}
    .wmci-list{{padding:12px 15px;border-bottom:1px solid rgba(148,163,184,.13);}}
    .wmci-list b{{color:#f8fafc;}}
    .wmci-list p{{margin:6px 0 0;color:#cbd5e1;line-height:1.35;font-size:13px;}}
    .wmci-scenario{{margin:14px;border:1px solid rgba(148,163,184,.20);background:#111;padding:14px;}}
    .wmci-scenario-score{{display:flex;align-items:end;gap:16px;margin-bottom:12px;}}
    .wmci-scenario-score strong{{font-size:42px;color:{shock_color};line-height:1;}}
    .wmci-scenario-score span{{color:#8b949e;text-transform:uppercase;font-size:12px;}}
    .wmci-empty{{padding:16px;color:#8b949e;font-style:italic;}}
    .wmci-footer{{border-top:1px solid rgba(148,163,184,.20);padding:10px 14px;color:#8b949e;font-size:11px;}}
    @media(max-width:1200px){{.wmci-head{{grid-template-columns:1fr 1fr;}}.wmci-body{{grid-template-columns:1fr;}}}}
    </style>
    <div class="wmci-wrap">
      <div class="wmci-head">
        <div class="wmci-title"><h2>{_wmci_esc_v50(meta.get('flag'))} {_wmci_esc_v50(country)}</h2><small>{_wmci_esc_v50(meta.get('iso3'))} · Country Intelligence · {_wmci_esc_v50(meta.get('region'))}</small></div>
        <div class="wmci-head-kpi"><small>Instability</small><strong style="color:{instability['color']};">{instability['score']}/100</strong>{_wmci_badge_v50(instability['regime'], 'regime', instability['color'])}</div>
        <div class="wmci-head-kpi"><small>Live Signals</small><strong>{active_total}</strong>{_wmci_badge_v50('critical', critical, '#ff4d5c')}{_wmci_badge_v50('high', high, '#f59e0b')}</div>
        <div class="wmci-head-kpi"><small>Source quality</small><strong>{source_quality}/100</strong>{_wmci_badge_v50('objects', layer_total, '#38bdf8')}</div>
        <div class="wmci-head-kpi"><small>Window</small><strong>{_wmci_esc_v50(time_window)}</strong>{_wmci_badge_v50('live', 'ON' if live_enabled else 'OFF', '#33ff88' if live_enabled else '#8b949e')}</div>
      </div>
      <div class="wmci-brief"><b>Brief renseignement.</b> {_wmci_esc_v50(brief)}. Transmission model links historical shocks, layer objects, live signals and structural exposure.</div>
      <div class="wmci-body">
        <section class="wmci-panel"><h3>Energy / infrastructure</h3>{_wmci_mix_html_v50(energy.get('mix', {}), 'Primary energy mix')}{_wmci_mix_html_v50(energy.get('electricity', {}), 'Electricity mix')}<div class="wmci-card">{_wmci_badge_v50('dependency', energy.get('import', 'n/a'), '#33ff88')}{_wmci_badge_v50('storage cover', str(energy.get('storage', 'n/a')) + 'd', '#fbbf24')}<p style="color:#cbd5e1;line-height:1.4;">{_wmci_esc_v50(energy.get('exposure', ''))}</p></div>{infra_html}</section>
        <section class="wmci-panel"><h3>Macro / transmission</h3><div class="wmci-grid2">{macro_html}</div><div class="wmci-card"><h4>Layer transmission matrix</h4>{theme_html}</div><div class="wmci-card"><h4>Live country signals</h4>{signals_html}</div></section>
        <section class="wmci-panel"><h3>Historical geopolitical ledger</h3>{history_html}</section>
      </div>
      <div class="wmci-body" style="grid-template-columns:1fr 1fr;">
        <section class="wmci-panel"><h3>Scenario lab</h3><div class="wmci-scenario"><div class="wmci-scenario-score"><strong>{scenario_res['impact']}/100</strong><span>{_wmci_esc_v50(scenario)} · {_wmci_esc_v50(intensity)} · {_wmci_esc_v50(transmission)}</span></div>{_wmci_badge_v50('energy exposure', scenario_res['energy'], '#f59e0b')}{_wmci_badge_v50('trade shock', scenario_res['trade'], '#38bdf8')}{_wmci_badge_v50('finance shock', scenario_res['finance'], '#a78bfa')}{_wmci_badge_v50('inflation impulse', str(scenario_res['inflation']) + ' pts', '#ff4d5c')}<p style="color:#cbd5e1;line-height:1.45;">Bridgeability estimate: <b>{scenario_res['bridge_days']} days</b>. {_wmci_esc_v50(scenario_res['assumption'])}</p></div></section>
        <section class="wmci-panel"><h3>Operational reading</h3><div class="wmci-card"><h4>What matters now</h4><p style="color:#cbd5e1;line-height:1.5;">Monitor source corroboration, layer density, live signal severity, energy import dependency, fiscal room, ports/pipelines/storage, and historical persistence. The center is deliberately no-key/public-data ready and avoids locked “PRO” placeholders.</p></div><div class="wmci-card">{_wmci_badge_v50('model', 'atlas + live objects', '#38bdf8')}{_wmci_badge_v50('data mode', 'no fake live', '#33ff88')}{_wmci_badge_v50('macro source', macro.get('source', 'atlas'), '#8b5cf6')}</div></section>
      </div>
      <div class="wmci-footer">{_wmci_esc_v50(_WMCI_VERSION_V50)} · public/no-key analytical center · historical ledger is curated and should be enriched country-by-country over time.</div>
    </div>
    """
    return html_payload


def _wmci_render_center_v50(country: str, live_enabled: bool, time_window: str, display_style: str = "Global") -> None:
    try:
        st.markdown(
            """
            <style>
            .wmci-native-controls{border:1px solid rgba(56,189,248,.18);background:linear-gradient(90deg,rgba(2,6,23,.94),rgba(2,6,23,.60));padding:8px 10px;margin:8px 0 6px 0;}
            .wmci-control-title{font-family:ui-monospace,SFMono-Regular,Menlo,Monaco,Consolas,monospace;color:#38bdf8;font-size:11px;font-weight:950;letter-spacing:.18em;text-transform:uppercase;margin-bottom:6px;}
            .wmci-native-controls label{font-size:10px!important;letter-spacing:.08em!important;color:#9aa4b2!important;}
            </style>
            <div class="wmci-native-controls"><div class="wmci-control-title">COUNTRY INTELLIGENCE CENTER</div></div>
            """,
            unsafe_allow_html=True,
        )
    except Exception:
        pass

    options = _wmci_country_options_v50()
    default_country = str(country or "Global") if str(country or "Global") in options else "Global"
    if "wmci_country_select_v50" not in st.session_state:
        st.session_state["wmci_country_select_v50"] = default_country
    # Keep the intelligence center synchronized with topbar unless user manually changed this selector.
    if str(country or "Global") != "Global" and st.session_state.get("wmci_last_topbar_country_v50") != str(country):
        st.session_state["wmci_country_select_v50"] = str(country) if str(country) in options else default_country
        st.session_state["wmci_last_topbar_country_v50"] = str(country)

    c1, c2, c3, c4 = st.columns([1.25, 1.15, 1.00, 3.10], gap="small")
    with c1:
        selected_country = st.selectbox("Country analyzed", options, index=options.index(st.session_state.get("wmci_country_select_v50", default_country)) if st.session_state.get("wmci_country_select_v50", default_country) in options else options.index(default_country), key="wmci_country_select_v50")
    with c2:
        scenario = st.selectbox("Scenario", list(_WMCI_SCENARIO_TEMPLATES_V50.keys()), index=0, key="wmci_scenario_v50")
    with c3:
        intensity = st.selectbox("Intensity", ["Low", "Base", "High", "Severe"], index=1, key="wmci_intensity_v50")
    with c4:
        transmission = st.selectbox("Transmission focus", ["All channels", "Energy", "Trade / ports", "Sanctions / finance", "Cyber / infrastructure", "Social / regime", "Technology / supply chain"], index=0, key="wmci_transmission_v50")

    try:
        st.markdown(_wmci_html_v50(str(selected_country), bool(live_enabled), str(time_window or "24h"), str(scenario), str(intensity), str(transmission)), unsafe_allow_html=True)
    except Exception as exc:
        try:
            st.error(f"Country Intelligence Center error: {type(exc).__name__}: {str(exc)[:240]}")
        except Exception:
            pass


# Preserve the current public entrypoint once, then override it with the same flow plus CIC.
try:
    _WMCI_PREV_RENDER_WORLD_MONITOR_V50 = render_worldmonitor_bridge_v211
except Exception:
    _WMCI_PREV_RENDER_WORLD_MONITOR_V50 = None


def render_worldmonitor_bridge_v211() -> None:  # type: ignore[override]
    """V5.0 public entrypoint: validated map/nav/panels + Country Intelligence Center."""
    try:
        _wm_inject_clean_css_v211()
    except Exception:
        pass
    try:
        _wm21121_inject_css()
    except Exception:
        pass

    try:
        display_style, country, live_enabled, effective_style = _wm21121_render_topbar()
    except Exception:
        display_style, country, live_enabled, effective_style = "Global", "Global", True, "Global"

    try:
        st.markdown(
            f'<div class="wm21121-sub"><b>WORLDMONITOR · JARVIS INTELLIGENCE ENGINE</b> · {html.escape(str(display_style))} / {html.escape(str(country))} <span class="wm21121-focus-note">quant + country intelligence active</span> · map, layers, causal transmission and historical country center.</div>',
            unsafe_allow_html=True,
        )
    except Exception:
        pass

    try:
        time_window = _wm21121_render_eventbar(live_enabled=bool(live_enabled))
    except Exception:
        time_window = str(st.session_state.get("wm21121_time", "24h"))

    projection_mode = str(st.session_state.get("wm21121_projection", "2D"))
    if projection_mode not in {"2D", "3D"}:
        projection_mode = "2D"
    st.session_state["wm21120_projection"] = projection_mode

    try:
        _render_worldmonitor_map_clean_v211(
            live_enabled=bool(live_enabled),
            time_window=str(time_window),
            style=str(effective_style),
            projection_mode=str(projection_mode),
            country=str(country),
        )
    except Exception as exc:
        try:
            st.error(f"WorldMonitor map runtime error: {type(exc).__name__}: {str(exc)[:180]}")
        except Exception:
            pass

    _wmci_render_center_v50(
        country=str(country),
        live_enabled=bool(live_enabled),
        time_window=str(time_window),
        display_style=str(display_style),
    )

    try:
        _render_worldmonitor_panels_runtime_v33(
            display_style=str(display_style),
            effective_style=str(effective_style),
            country=str(country),
            live_enabled=bool(live_enabled),
        )
    except Exception as exc:
        try:
            st.error(f"WorldMonitor panels runtime error: {type(exc).__name__}: {str(exc)[:180]}")
        except Exception:
            pass


