def _map_component_html(*args, **kwargs):  # type: ignore[override]
    """Compatibility wrapper: original map HTML + original-style click-to-open country drawer."""
    if _WMCI_PREV_MAP_COMPONENT_HTML_V51 is None:
        return ""
    base = _WMCI_PREV_MAP_COMPONENT_HTML_V51(*args, **kwargs)
    try:
        if not isinstance(base, str):
            return base
        if "wmci-country-drawer-v51-js" in base:
            return base
        active_time = str(kwargs.get("active_time") or kwargs.get("time_window") or kwargs.get("event_window") or "24h")
        live_enabled = bool(kwargs.get("live_enabled", True))
        inj = _wmci_drawer_injection_v51(active_time=active_time, live_enabled=live_enabled)
        if "</body>" in base:
            return base.replace("</body>", inj + "\n</body>")
        return base + "\n" + inj
    except Exception:
        return base


