def _wmci_clip_v52(x, lo: int = 0, hi: int = 100) -> int:
    try:
        return int(max(lo, min(hi, round(float(x)))))
    except Exception:
        return lo


def _wmci_safe_list_v52(x, limit: int = 8) -> list[str]:
    try:
        if isinstance(x, (list, tuple)):
            return [str(v) for v in x if str(v).strip()][:limit]
        if isinstance(x, str) and x.strip():
            return [x.strip()]
    except Exception:
        pass
    return []


def _wmci_area_v52(bbox) -> float:
    try:
        if not isinstance(bbox, (list, tuple)) or len(bbox) != 4:
            return 10_000_000.0
        return abs(float(bbox[1]) - float(bbox[0])) * abs(float(bbox[3]) - float(bbox[2]))
    except Exception:
        return 10_000_000.0


