def _wmci_profile_seed_rows_v55() -> list[dict]:
    """Rows from the existing Country Intelligence profile engine."""
    rows: list[dict] = []
    try:
        countries = list(_wmci_country_options_v52())  # type: ignore[name-defined]
    except Exception:
        try:
            countries = list(_wmci_country_options_v50())  # type: ignore[name-defined]
        except Exception:
            countries = []
    for country in countries:
        c = str(country or "").strip()
        if not c or c == "Global":
            continue
        try:
            meta = dict(_WMCI_COUNTRY_META_V52.get(c, {}))  # type: ignore[name-defined]
        except Exception:
            try:
                meta = dict(_wmci_country_meta_v50(c))  # type: ignore[name-defined]
            except Exception:
                meta = {}
        iso3 = str(meta.get("iso3") or "").upper().strip()
        if len(iso3) != 3 or iso3 in {"GLB", "N/A", "NON"}:
            continue
        try:
            profile = _wmci_rich_profile_v52(c, active_time="24h", live_enabled=False)  # type: ignore[name-defined]
            inst = dict(profile.get("instability") or {})
            score = int(inst.get("score") or 0)
            regime = str(inst.get("regime") or "Stable")
        except Exception:
            try:
                macro = _wmci_profile_macro_v50(c)  # type: ignore[name-defined]
                score = int(float(macro.get("instability", 25)))
            except Exception:
                score = int(abs(hash(c)) % 42 + 12)
            regime = "High" if score >= 70 else "Watch" if score >= 40 else "Stable"
        bbox = meta.get("bbox") if isinstance(meta.get("bbox"), (list, tuple)) and len(meta.get("bbox")) == 4 else None
        lon = meta.get("lon")
        lat = meta.get("lat")
        if (lon is None or lat is None) and bbox:
            try:
                lon = (float(bbox[0]) + float(bbox[1])) / 2.0
                lat = (float(bbox[2]) + float(bbox[3])) / 2.0
            except Exception:
                lon, lat = None, None
        rows.append({
            "country": c,
            "iso3": iso3,
            "iso2": str(meta.get("iso2") or ""),
            "flag": str(meta.get("flag") or ""),
            "region": str(meta.get("region") or ""),
            "lon": lon,
            "lat": lat,
            "bbox": list(bbox) if bbox else None,
            "score": max(0, min(100, int(score))),
            "regime": regime,
            "source": "country-intelligence",
        })
    return rows


def _wmci_countryinfo_rows_v55() -> list[dict]:
    """All-country atlas using countryinfo when available."""
    rows: list[dict] = []
    try:
        from countryinfo import CountryInfo as _WMCI_CountryInfo  # type: ignore
        data = _WMCI_CountryInfo().all()
    except Exception:
        data = {}
    if isinstance(data, dict) and data:
        for _key, info in data.items():
            if not isinstance(info, dict):
                continue
            iso = info.get("ISO") or {}
            iso3 = str((iso or {}).get("alpha3") or "").upper().strip()
            iso2 = str((iso or {}).get("alpha2") or "").upper().strip()
            if len(iso3) != 3:
                continue
            name = str(info.get("name") or _key or iso3).strip()
            ll = info.get("latlng") or []
            lat = lon = None
            try:
                if isinstance(ll, (list, tuple)) and len(ll) >= 2:
                    lat = float(ll[0]); lon = float(ll[1])
            except Exception:
                lat = lon = None
            if lat is None or lon is None:
                continue
            rows.append({
                "country": name,
                "iso3": iso3,
                "iso2": iso2,
                "flag": "",
                "region": str(info.get("region") or info.get("subregion") or ""),
                "lon": lon,
                "lat": lat,
                "bbox": None,
                "score": 0,
                "regime": "Atlas",
                "source": "countryinfo",
            })
    if not rows:
        for iso3, name, iso2, region, lon, lat in _WMCI_FALLBACK_COUNTRIES_V55:
            rows.append({
                "country": name, "iso3": iso3, "iso2": iso2, "flag": "", "region": region,
                "lon": float(lon), "lat": float(lat), "bbox": None, "score": 0, "regime": "Atlas", "source": "fallback",
            })
    return rows


def _wmci_all_country_rows_v55() -> list[dict]:
    """Merge all-country atlas with richer existing Country Intelligence rows."""
    merged: dict[str, dict] = {}
    for r in _wmci_countryinfo_rows_v55():
        iso3 = str(r.get("iso3") or "").upper()
        if len(iso3) == 3:
            merged[iso3] = dict(r)
    for r in _wmci_profile_seed_rows_v55():
        iso3 = str(r.get("iso3") or "").upper()
        if len(iso3) != 3:
            continue
        base = dict(merged.get(iso3, {}))
        base.update({k: v for k, v in r.items() if v not in (None, "", [])})
        merged[iso3] = base
    rows = [r for r in merged.values() if len(str(r.get("iso3") or "")) == 3]
    rows.sort(key=lambda x: str(x.get("country") or x.get("iso3")))
    return rows


def _wmci_capital_rows_v55() -> list[dict]:
    rows: list[dict] = []
    try:
        from countryinfo import CountryInfo as _WMCI_CountryInfo  # type: ignore
        data = _WMCI_CountryInfo().all()
    except Exception:
        data = {}
    if isinstance(data, dict):
        for _key, info in data.items():
            if not isinstance(info, dict):
                continue
            iso = info.get("ISO") or {}
            iso3 = str((iso or {}).get("alpha3") or "").upper().strip()
            cap = str(info.get("capital") or "").strip()
            ll = info.get("capital_latlng") or []
            try:
                if len(iso3) == 3 and cap and isinstance(ll, (list, tuple)) and len(ll) >= 2:
                    rows.append({"city": cap, "iso3": iso3, "country": str(info.get("name") or ""), "lat": float(ll[0]), "lon": float(ll[1])})
            except Exception:
                pass
    # De-duplicate and avoid overloading the map with tiny island labels.
    out: list[dict] = []
    seen: set[tuple[str, str]] = set()
    for r in rows:
        key = (str(r.get("city") or "").lower(), str(r.get("iso3") or ""))
        if key in seen:
            continue
        seen.add(key)
        out.append(r)
    return out[:185]


def _wmci_city_rows_v55() -> list[dict]:
    rows: list[dict] = []
    for city, iso3, lon, lat in _WMCI_MAJOR_CITY_LABELS_V55:
        rows.append({"city": city, "iso3": iso3, "lon": float(lon), "lat": float(lat), "major": True})
    return rows


def _wmci_color_for_score_v55(score: int) -> str:
    try:
        s = int(score)
    except Exception:
        s = 0
    if s >= 70:
        return "#ff4d5c"
    if s >= 40:
        return "#f59e0b"
    if s > 0:
        return "#33ff88"
    return "#94a3b8"


def _wmci_add_country_foundation_traces_v55(fig):
    """Add all-country polygons, labels, city labels and focus overlay."""
    try:
        import plotly.graph_objects as _go
    except Exception:
        return fig
    try:
        for tr in list(getattr(fig, "data", []) or []):
            meta = getattr(tr, "meta", None)
            if isinstance(meta, dict) and meta.get("wmci_country_atlas_v55"):
                return fig
    except Exception:
        pass

    rows = _wmci_all_country_rows_v55()
    if not rows:
        return fig

    locations = [str(r.get("iso3") or "") for r in rows]
    zvals = [int(r.get("score") or 0) for r in rows]
    names = [str(r.get("country") or r.get("iso3") or "") for r in rows]
    custom = [[
        r.get("country", ""), r.get("iso3", ""), r.get("iso2", ""), r.get("region", ""),
        r.get("bbox") or [], r.get("lon"), r.get("lat"), r.get("score"), r.get("regime", ""), r.get("flag", ""),
    ] for r in rows]

    try:
        fig.add_trace(_go.Choropleth(
            locations=locations,
            z=zvals,
            text=names,
            customdata=custom,
            locationmode="ISO-3",
            name="World Country Atlas",
            colorscale=[
                [0.00, "rgba(148,163,184,0.030)"],
                [0.30, "rgba(51,255,136,0.050)"],
                [0.55, "rgba(56,189,248,0.060)"],
                [0.75, "rgba(245,158,11,0.120)"],
                [1.00, "rgba(239,68,68,0.190)"],
            ],
            zmin=0,
            zmax=100,
            marker={"line": {"color": "rgba(148,163,184,0.52)", "width": 0.46}},
            showscale=False,
            hovertemplate="<b>%{text}</b><br>Instability %{z}/100<br>%{customdata[3]}<extra></extra>",
            showlegend=False,
            meta={"layer_id": "countryIntelligence", "wm_v211": True, "wmci_country_atlas": True, "wmci_country_atlas_v55": True, "wmci_kind": "country_base"},
        ))
    except Exception:
        pass

    try:
        fig.add_trace(_go.Choropleth(
            locations=[],
            z=[],
            text=[],
            customdata=[],
            locationmode="ISO-3",
            name="Selected Country Focus",
            colorscale=[[0.0, "rgba(59,130,246,0.18)"], [1.0, "rgba(59,130,246,0.18)"]],
            zmin=0,
            zmax=100,
            marker={"line": {"color": "rgba(96,165,250,1.00)", "width": 3.2}},
            showscale=False,
            hovertemplate="<b>%{text}</b><br>Selected country<extra></extra>",
            showlegend=False,
            meta={"layer_id": "countryIntelligenceFocus", "wm_v211": True, "wmci_country_focus": True, "wmci_kind": "country_focus"},
        ))
    except Exception:
        pass

    label_rows = []
    for r in rows:
        try:
            lon = float(r.get("lon")); lat = float(r.get("lat"))
            if -180 <= lon <= 180 and -90 <= lat <= 90:
                label_rows.append(r)
        except Exception:
            continue
    if label_rows:
        try:
            fig.add_trace(_go.Scattergeo(
                lon=[float(r["lon"]) for r in label_rows],
                lat=[float(r["lat"]) for r in label_rows],
                text=[str(r.get("country") or r.get("iso3") or "").upper() for r in label_rows],
                customdata=[[r.get("country", ""), r.get("iso3", ""), r.get("iso2", ""), r.get("region", ""), r.get("bbox") or [], r.get("lon"), r.get("lat"), r.get("score"), r.get("regime", ""), r.get("flag", "")] for r in label_rows],
                mode="text",
                name="Country labels",
                visible=False,
                textfont={"size": 8, "color": "rgba(226,232,240,0.42)", "family": "Arial Black, ui-monospace, monospace"},
                hoverinfo="skip",
                showlegend=False,
                meta={"layer_id": "countryIntelligenceLabels", "wm_v211": True, "wmci_country_labels": True, "wmci_kind": "country_labels"},
            ))
        except Exception:
            pass

    cities = _wmci_city_rows_v55()
    if cities:
        try:
            fig.add_trace(_go.Scattergeo(
                lon=[float(r["lon"]) for r in cities],
                lat=[float(r["lat"]) for r in cities],
                text=[str(r.get("city") or "") for r in cities],
                customdata=[[r.get("city", ""), r.get("iso3", "")] for r in cities],
                mode="text",
                name="Major city labels",
                visible=False,
                textfont={"size": 9, "color": "rgba(226,232,240,0.58)", "family": "Arial, ui-monospace, monospace"},
                hoverinfo="skip",
                showlegend=False,
                meta={"layer_id": "countryIntelligenceCities", "wm_v211": True, "wmci_city_labels": True, "wmci_kind": "country_city_labels"},
            ))
        except Exception:
            pass

    capitals = _wmci_capital_rows_v55()
    if capitals:
        try:
            fig.add_trace(_go.Scattergeo(
                lon=[float(r["lon"]) for r in capitals],
                lat=[float(r["lat"]) for r in capitals],
                text=[str(r.get("city") or "") for r in capitals],
                customdata=[[r.get("country", ""), r.get("iso3", ""), r.get("city", "")] for r in capitals],
                mode="text",
                name="Capital labels",
                visible=False,
                opacity=0.72,
                textfont={"size": 7, "color": "rgba(203,213,225,0.28)", "family": "Arial, ui-monospace, monospace"},
                hoverinfo="skip",
                showlegend=False,
                meta={"layer_id": "countryIntelligenceCapitals", "wm_v211": True, "wmci_capital_labels": True, "wmci_kind": "country_capital_labels"},
            ))
        except Exception:
            pass

    try:
        fig.update_geos(
            showcountries=True,
            showsubunits=True,
            subunitcolor="rgba(148,163,184,0.20)",
            subunitwidth=0.45,
            countrycolor="rgba(148,163,184,0.34)",
            showlakes=True,
            lakecolor="rgba(15,23,42,0.92)",
            showrivers=True,
            rivercolor="rgba(56,189,248,0.13)",
            riverwidth=0.35,
        )
    except Exception:
        pass
    return fig


try:
    _WMCI_V55_PREV_BUILD_PLOTLY_FIGURE = build_plotly_figure_v211  # type: ignore[name-defined]
except Exception:
    _WMCI_V55_PREV_BUILD_PLOTLY_FIGURE = None


def build_plotly_figure_v211(*args, **kwargs):  # type: ignore[override]
    if _WMCI_V55_PREV_BUILD_PLOTLY_FIGURE is None:
        try:
            return go.Figure()  # type: ignore[name-defined]
        except Exception:
            return None
    fig = _WMCI_V55_PREV_BUILD_PLOTLY_FIGURE(*args, **kwargs)
    try:
        return _wmci_add_country_foundation_traces_v55(fig)
    except Exception:
        return fig


