def _wmci_parse_country_atlas_v59() -> list[dict]:
    rows: list[dict] = []
    for raw in str(_WMCI_COUNTRY_ATLAS_V59).splitlines():
        raw = raw.strip()
        if not raw or raw.startswith("#"):
            continue
        parts = raw.split("|")
        if len(parts) < 9:
            continue
        iso3, country, iso2, region, lon, lat, capital, cap_lon, cap_lat = parts[:9]
        try:
            lon_f = float(lon); lat_f = float(lat); cap_lon_f = float(cap_lon); cap_lat_f = float(cap_lat)
        except Exception:
            continue
        rows.append({
            "country": country.strip(),
            "iso3": iso3.strip().upper(),
            "iso2": iso2.strip().upper(),
            "flag": "",
            "region": region.strip(),
            "lon": lon_f,
            "lat": lat_f,
            "bbox": None,
            "score": 0,
            "regime": "Atlas",
            "source": "embedded-full-atlas-v59",
            "capital": capital.strip(),
            "capital_lon": cap_lon_f,
            "capital_lat": cap_lat_f,
        })
    return rows

try:
    _WMCI_PREV_COUNTRYINFO_ROWS_V59 = _wmci_countryinfo_rows_v55  # type: ignore[name-defined]
except Exception:
    _WMCI_PREV_COUNTRYINFO_ROWS_V59 = None


def _wmci_countryinfo_rows_v55() -> list[dict]:  # type: ignore[override]
    """Full embedded country atlas. Uses previous/countryinfo rows only as enrichment."""
    merged: dict[str, dict] = {}
    for r in _wmci_parse_country_atlas_v59():
        iso = str(r.get("iso3") or "").upper()
        if len(iso) == 3:
            merged[iso] = dict(r)
    if callable(_WMCI_PREV_COUNTRYINFO_ROWS_V59):
        try:
            for r in _WMCI_PREV_COUNTRYINFO_ROWS_V59() or []:
                if not isinstance(r, dict):
                    continue
                iso = str(r.get("iso3") or "").upper()
                if len(iso) != 3:
                    continue
                base = dict(merged.get(iso, {}))
                # keep the embedded capital fields, but allow previous richer source/score/bbox/name fields
                capital_keep = {k: base.get(k) for k in ["capital", "capital_lon", "capital_lat"] if k in base}
                base.update({k: v for k, v in dict(r).items() if v not in (None, "", [])})
                for k, v in capital_keep.items():
                    if base.get(k) in (None, "", []):
                        base[k] = v
                merged[iso] = base
        except Exception:
            pass
    out = [r for r in merged.values() if len(str(r.get("iso3") or "")) == 3]
    out.sort(key=lambda x: str(x.get("country") or x.get("iso3")))
    return out

try:
    _WMCI_PREV_CAPITAL_ROWS_V59 = _wmci_capital_rows_v55  # type: ignore[name-defined]
except Exception:
    _WMCI_PREV_CAPITAL_ROWS_V59 = None


def _wmci_capital_rows_v55() -> list[dict]:  # type: ignore[override]
    """Capital label rows from previous source + embedded atlas."""
    out: list[dict] = []
    seen: set[tuple[str, str]] = set()
    if callable(_WMCI_PREV_CAPITAL_ROWS_V59):
        try:
            for r in _WMCI_PREV_CAPITAL_ROWS_V59() or []:
                if not isinstance(r, dict):
                    continue
                key = (str(r.get("city") or "").lower(), str(r.get("iso3") or "").upper())
                if key[0] and key not in seen:
                    seen.add(key); out.append(dict(r))
        except Exception:
            pass
    for r in _wmci_parse_country_atlas_v59():
        cap = str(r.get("capital") or "").strip()
        iso = str(r.get("iso3") or "").upper()
        key = (cap.lower(), iso)
        if not cap or key in seen:
            continue
        seen.add(key)
        out.append({
            "city": cap,
            "iso3": iso,
            "country": str(r.get("country") or ""),
            "lon": float(r.get("capital_lon")),
            "lat": float(r.get("capital_lat")),
        })
    return out[:230]

try:
    _WMCI_PREV_COUNTRY_PAYLOAD_V59 = _wmci_country_payload_v51  # type: ignore[name-defined]
except Exception:
    _WMCI_PREV_COUNTRY_PAYLOAD_V59 = None


def _wmci_lite_profile_v59(row: dict, active_time: str = "24h") -> dict:
    country = str(row.get("country") or row.get("iso3") or "Country")
    score = int(float(row.get("score") or 0)) if str(row.get("score") or "").strip() else 0
    regime = str(row.get("regime") or ("Watch" if score >= 40 else "Atlas"))
    color = "#ff4d5c" if score >= 70 else "#f59e0b" if score >= 40 else "#33ff88" if score > 0 else "#94a3b8"
    return {
        "country": country,
        "meta": {
            "iso3": str(row.get("iso3") or ""),
            "iso2": str(row.get("iso2") or ""),
            "flag": str(row.get("flag") or ""),
            "region": str(row.get("region") or ""),
            "bbox": row.get("bbox") or [],
            "lon": row.get("lon"),
            "lat": row.get("lat"),
            "capital": str(row.get("capital") or ""),
        },
        "instability": {"score": score, "regime": regime, "color": color},
        "source_quality": 42 if score == 0 else 58,
        "live": [],
        "energy": {"import": "atlas profile pending", "storage": "n/a", "exposure": "No dedicated energy profile yet."},
        "macro": {"source": "embedded atlas / public-source slot pending"},
        "infra": {"ports": [], "pipelines": [], "storage": [], "nodes": []},
        "themes": {},
        "risk_channels": [],
        "watchlist": [],
        "history": [],
        "scenario": {"impact": 0, "energy": 0, "trade": 0, "finance": 0, "inflation": 0, "bridge_days": "n/a"},
        "operational": "Atlas country profile. Detailed live/historical rows are shown when a provider or internal profile exists.",
    }


def _wmci_country_payload_v51(active_time: str = "24h", live_enabled: bool = True) -> str:  # type: ignore[override]
    """Drawer payload for all countries, not only countries with rich profiles."""
    import json as _json
    profiles: list[dict] = []
    seen_country: set[str] = set()
    seen_iso: set[str] = set()

    # Keep existing rich profiles first.
    if callable(_WMCI_PREV_COUNTRY_PAYLOAD_V59):
        try:
            old = _json.loads(str(_WMCI_PREV_COUNTRY_PAYLOAD_V59(active_time=active_time, live_enabled=live_enabled) or "{}"))
            for p in old.get("profiles", []) if isinstance(old, dict) else []:
                if not isinstance(p, dict):
                    continue
                c = str(p.get("country") or "").strip()
                iso = str((p.get("meta") or {}).get("iso3") or "").upper()
                # Enrich old/rich profile with embedded atlas canonical ISO3/ISO2/center.
                try:
                    atlas_rows = _wmci_parse_country_atlas_v59()
                    atlas_by_country = {str(r.get('country') or '').lower(): r for r in atlas_rows}
                    atlas_by_iso2 = {str(r.get('iso2') or '').upper(): r for r in atlas_rows}
                    ar = atlas_by_country.get(c.lower()) or atlas_by_iso2.get(iso)
                    if isinstance(ar, dict):
                        meta = dict(p.get('meta') or {})
                        for k in ['iso3', 'iso2', 'region', 'lon', 'lat', 'capital', 'capital_lon', 'capital_lat']:
                            if ar.get(k) not in (None, '', []):
                                meta[k] = ar.get(k)
                        p['meta'] = meta
                        iso = str(meta.get('iso3') or iso).upper()
                except Exception:
                    pass
                if c:
                    seen_country.add(c.lower())
                if iso:
                    seen_iso.add(iso)
                profiles.append(p)
        except Exception:
            pass

    # Add every country row, preserving rich country profiles where present and using lite profiles otherwise.
    for row in _wmci_countryinfo_rows_v55():
        if not isinstance(row, dict):
            continue
        c = str(row.get("country") or row.get("iso3") or "").strip()
        iso = str(row.get("iso3") or "").upper()
        if not c or (c.lower() in seen_country) or (iso and iso in seen_iso):
            continue
        p = None
        # Try the rich builder only for countries already known by the original profile registry.
        try:
            opts = set(str(x) for x in (_wmci_country_options_v52() if callable(globals().get("_wmci_country_options_v52")) else []))  # type: ignore[name-defined]
        except Exception:
            try:
                opts = set(str(x) for x in _wmci_country_options_v50())  # type: ignore[name-defined]
            except Exception:
                opts = set()
        if c in opts:
            try:
                p = _wmci_safe_profile_v51(c, active_time=active_time, live_enabled=live_enabled)  # type: ignore[name-defined]
            except Exception:
                p = None
        if not isinstance(p, dict):
            p = _wmci_lite_profile_v59(row, active_time=active_time)
        meta = dict(p.get("meta") or {})
        for k in ["iso3", "iso2", "flag", "region", "lon", "lat", "bbox", "capital"]:
            if k in row and row.get(k) not in (None, "", []):
                meta[k] = row.get(k)
        p["country"] = c
        p["meta"] = meta
        p.setdefault("source_quality", 42)
        p.setdefault("live", [])
        p.setdefault("energy", {"import": "atlas profile pending"})
        p.setdefault("macro", {"source": "atlas"})
        p.setdefault("infra", {"ports": [], "pipelines": [], "storage": [], "nodes": []})
        p.setdefault("themes", {})
        p.setdefault("risk_channels", [])
        p.setdefault("history", [])
        p.setdefault("scenario", {"impact": 0, "energy": 0, "trade": 0, "finance": 0, "inflation": 0, "bridge_days": "n/a"})
        profiles.append(p)
        seen_country.add(c.lower())
        if iso:
            seen_iso.add(iso)

    payload = {"version": _WMCI_VERSION_V59, "active_time": str(active_time or "24h"), "profiles": profiles}
    try:
        return _json.dumps(payload, ensure_ascii=False)
    except Exception:
        return '{"profiles":[]}'

try:
    _WMCI_PREV_DRAWER_INJECTION_V59 = _wmci_drawer_injection_v51  # type: ignore[name-defined]
except Exception:
    _WMCI_PREV_DRAWER_INJECTION_V59 = None

_WMCI_DOM_CLICK_V59_JS = r"""
 

function profileFromLonLatV59(gd, lon, lat){
  lon = Number(lon); lat = Number(lat);
  if(!Number.isFinite(lon) || !Number.isFinite(lat)) return null;
  let bboxHit = null, bboxScore = -Infinity;
  let nearest = null, nearestD = Infinity;
  const r = (typeof _wmciCurrentRangesV56 === 'function') ? _wmciCurrentRangesV56(gd) : {lonSpan:360, latSpan:146};
  const zoomPenalty = Math.max(0.14, Math.min(1.0, Math.max(r.lonSpan || 360, r.latSpan || 146) / 160));

  for(const p of profiles){
    if(!p || String(p.country || '').toLowerCase() === 'global') continue;
    const m = (p && p.meta) ? p.meta : {};
    const bbox = (typeof _wmciProfileBBoxV56 === 'function') ? _wmciProfileBBoxV56(p) : (Array.isArray(m.bbox) ? m.bbox.map(Number) : null);
    if(Array.isArray(bbox) && bbox.length >= 4 && bbox.every(Number.isFinite)){
      let west=bbox[0], east=bbox[1], south=bbox[2], north=bbox[3];
      if(east < west){ const t=east; east=west; west=t; }
      if(north < south){ const t=north; north=south; south=t; }
      const rawArea = Math.max(0.01, (east-west)*(north-south));
      const padLon=Math.max(0.04, Math.min(0.50, (east-west)*0.012*zoomPenalty));
      const padLat=Math.max(0.03, Math.min(0.35, (north-south)*0.015*zoomPenalty));
      if(lon >= west-padLon && lon <= east+padLon && lat >= south-padLat && lat <= north+padLat){
        const cx = (west+east)/2, cy = (south+north)/2;
        const centerD = Math.pow((lon-cx)*Math.cos((lat+cy)*Math.PI/360),2) + Math.pow(lat-cy,2);
        // Prefer precise/small bboxes only when the click is truly inside them;
        // otherwise a large country bbox no longer gets stolen by a nearby micro-state.
        const score = -Math.log(rawArea + 1) * 4.0 - centerD * 0.16;
        if(score > bboxScore){ bboxScore = score; bboxHit = p; }
      }
    }
    const mlon=Number(m.lon), mlat=Number(m.lat);
    if(Number.isFinite(mlon) && Number.isFinite(mlat)){
      const d = Math.pow((lon-mlon)*Math.cos((lat+mlat)*Math.PI/360),2) + Math.pow(lat-mlat,2);
      if(d < nearestD){ nearestD=d; nearest=p; }
    }
  }
  if(bboxHit) return bboxHit;
  const threshold = Math.pow(Math.max(0.75, Math.min(5.2, Math.max(r.lonSpan || 360, r.latSpan || 146) * 0.018)), 2);
  return nearestD <= threshold ? nearest : null;
}
 
function lonLatFromClientV59(gd, evt){
  // Prefer Plotly's own projection inverse. The previous linear gd-rectangle
  // approximation was the root of India->Bhutan / wrong-country switches when
  // the geo canvas did not occupy the full component rectangle.
  try{
    const svg = gd.querySelector('svg.main-svg') || gd.querySelector('svg');
    const rect = svg ? svg.getBoundingClientRect() : gd.getBoundingClientRect();
    const subplot = gd._fullLayout && gd._fullLayout.geo && gd._fullLayout.geo._subplot;
    const proj = subplot && subplot.projection;
    if(proj && typeof proj.invert === 'function'){
      const inv = proj.invert([evt.clientX - rect.left, evt.clientY - rect.top]);
      if(inv && inv.length >= 2 && Number.isFinite(Number(inv[0])) && Number.isFinite(Number(inv[1]))){
        return {lon:Number(inv[0]), lat:Number(inv[1]), method:'plotly-projection'};
      }
    }
  }catch(e){}
  const rect = gd.getBoundingClientRect();
  const x = Math.max(0, Math.min(1, (evt.clientX - rect.left) / Math.max(1, rect.width)));
  const y = Math.max(0, Math.min(1, (evt.clientY - rect.top) / Math.max(1, rect.height)));
  const r = _wmciCurrentRangesV56(gd);
  return {lon: Number(r.lon[0]) + x * (Number(r.lon[1])-Number(r.lon[0])), lat: Number(r.lat[1]) - y * (Number(r.lat[1])-Number(r.lat[0])), method:'linear-fallback'};
}
 
function bindDomClickV59(gd){
  if(!gd || gd.dataset.wmciDomClickV59 === '1') return;
  gd.dataset.wmciDomClickV59 = '1';
  gd.addEventListener('click', function(evt){
   try{
    if(evt.target && evt.target.closest && evt.target.closest('#wmci-country-drawer-v51,.wm-window,.wm-tools,.wm21121-topbar,.wm21121-eventbar')) return;
    setTimeout(function(){
     const lastPlotly = Number(gd.dataset.wmciLastPlotlyClickV59 || 0);
     // Plotly country/point click is authoritative. The DOM fallback must never
     // reopen another country immediately after the correct Plotly event.
     if(Date.now() - lastPlotly < 720) return;
     const ll = lonLatFromClientV59(gd, evt);
     const p = profileFromLonLatV59(gd, ll.lon, ll.lat);
     if(p){
       gd.dataset.wmciLastDomCountryClickV62 = String(Date.now());
       render(p); focusCountry(gd, p);
     }
    }, 115);
   }catch(e){}
  }, false);
}
"""


def _wmci_drawer_injection_v51(active_time: str = "24h", live_enabled: bool = True) -> str:  # type: ignore[override]
    if not callable(_WMCI_PREV_DRAWER_INJECTION_V59):
        return ""
    try:
        base = str(_WMCI_PREV_DRAWER_INJECTION_V59(active_time=active_time, live_enabled=live_enabled))
    except Exception:
        return ""
    # Rebind on top of V5.5/V5.8 caches.
    base = base.replace('id="wmci-country-drawer-v55-js"', 'id="wmci-country-drawer-v59-js"')
    base = base.replace('data-version="v57-fixed-map-frame"', 'data-version="v62-click-routing-zoom-lock"')
    base = base.replace("drawer.dataset.bound === 'v55'", "drawer.dataset.bound === 'v59'")
    base = base.replace("drawer.dataset.bound = 'v55';", "drawer.dataset.bound = 'v59';")
    base = base.replace("gd.dataset.wmciBoundV55 === '1'", "gd.dataset.wmciBoundV59 === '1'")
    base = base.replace(
        "gd.dataset.wmciBoundV55 = '1'; gd.dataset.wmciBoundV54 = '1'; gd.dataset.wmciBoundV53 = '1';",
        "gd.dataset.wmciBoundV59 = '1'; gd.dataset.wmciBoundV55 = '1'; gd.dataset.wmciBoundV54 = '1'; gd.dataset.wmciBoundV53 = '1'; bindDomClickV59(gd);"
    )
    if "function profileFromLonLatV59" not in base:
        base = base.replace("function findTrace(gd, predicate){", _WMCI_DOM_CLICK_V59_JS + "\n function findTrace(gd, predicate){")
    base = base.replace(
        "gd.on('plotly_click', function(ev){ const pt = ev && ev.points && ev.points.length ? ev.points[0] : null; const p = profileFromPoint(pt); if(p){ render(p); focusCountry(gd, p); } });",
        "gd.on('plotly_click', function(ev){ const pt = ev && ev.points && ev.points.length ? ev.points[0] : null; const p = profileFromPoint(pt); if(p){ try{ gd.dataset.wmciLastPlotlyClickV59 = String(Date.now()); }catch(_){} render(p); focusCountry(gd, p); } });"
    )
    return base

try:
    _WMCI_PREV_SCATTER_TRACE_V59 = _scatter_trace_for_points  # type: ignore[name-defined]
except Exception:
    _WMCI_PREV_SCATTER_TRACE_V59 = None


def _scatter_trace_for_points(layer_df, spec, visible):  # type: ignore[override]
    """Compact map hovers. Source/ZIP lineage stays in diagnostics, not in huge map bubbles."""
    import html as _html
    import pandas as _pd
    import plotly.graph_objects as _go
    hover = []
    sizes = []
    for _, r in layer_df.iterrows():
        try:
            sev = float(r.get("severity", 55) or 55)
        except Exception:
            sev = 55.0
        sizes.append(max(6, min(22, 5 + sev / 7)))
        title = _html.escape(str(r.get("title") or "Signal"))[:180]
        layer = _html.escape(str(getattr(spec, "label", "Layer") or "Layer"))[:80]
        collection = _html.escape(str(r.get("collection") or "")[:90])
        country = ""
        try:
            meta_txt = str(r.get("metadata") or "")
            m = re.search(r'"country"\s*:\s*"([^"]+)"', meta_txt)
            country = _html.escape(m.group(1)) if m else ""
        except Exception:
            country = ""
        line2 = f"<br>{country}" if country else ""
        line3 = f"<br>{collection}" if collection else ""
        hover.append(f"<b>{title}</b>{line2}<br>{layer}{line3}<br>Intensity: {sev:.0f}/100")
    return _go.Scattergeo(
        lon=_pd.to_numeric(layer_df["lon"], errors="coerce"),
        lat=_pd.to_numeric(layer_df["lat"], errors="coerce"),
        mode="markers",
        name=getattr(spec, "label", "Layer"),
        visible=True if visible else "legendonly",
        marker=dict(size=sizes, color=getattr(spec, "color", "#38bdf8"), opacity=0.82, line=dict(width=0.65, color="rgba(255,255,255,.34)")),
        hovertext=hover,
        hoverinfo="text",
        meta={"layer_id": getattr(spec, "layer_id", ""), "wm_v211": True, "kind": "point"},
        showlegend=False,
    )


