def _wmj_secret_v7(*names: str) -> str:
    """Read a server-side credential without ever exposing it to component HTML."""
    for name in names:
        try:
            value = str(st.secrets.get(name, "") or "").strip()
        except Exception:
            value = ""
        if value:
            return value
        value = str(os.getenv(name, "") or "").strip()
        if value:
            return value
    return ""


def _wmj_fetch_acled_v7(hours_back: int) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Load recent ACLED observations using current OAuth or a legacy key."""
    email = _wmj_secret_v7("ACLED_EMAIL")
    password = _wmj_secret_v7("ACLED_PASSWORD")
    access_token = _wmj_secret_v7("ACLED_ACCESS_TOKEN")
    legacy_key = _wmj_secret_v7("ACLED_KEY")
    if not email or not (password or access_token or legacy_key):
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "ACLED",
            "status": "LOCKED",
            "rows": 0,
            "detail": "Configure ACLED_EMAIL + ACLED_PASSWORD (preferred OAuth) or ACLED_ACCESS_TOKEN.",
        }])
    now = _wm211_dt.datetime.now(_wm211_dt.timezone.utc)
    start = (now - _wm211_dt.timedelta(hours=max(24, min(int(hours_back), 168)))).strftime("%Y-%m-%d")
    end = now.strftime("%Y-%m-%d")
    params = {
        "event_date": f"{start}|{end}",
        "event_date_where": "BETWEEN",
        "limit": "500",
    }
    headers = {"Accept": "application/json", "User-Agent": "QuantTerminal-WorldMonitor/7"}
    auth_mode = "OAuth"
    try:
        if not access_token and password:
            token_body = _wm211_urlparse.urlencode({
                "username": email,
                "password": password,
                "grant_type": "password",
                "client_id": "acled",
                "scope": "authenticated",
            }).encode("utf-8")
            token_request = _wm211_urlrequest.Request(
                "https://acleddata.com/oauth/token",
                data=token_body,
                headers={"Content-Type": "application/x-www-form-urlencoded", "Accept": "application/json"},
                method="POST",
            )
            with _wm211_urlrequest.urlopen(token_request, timeout=6) as response:
                access_token = str(json.loads(response.read(500_000).decode("utf-8", errors="ignore")).get("access_token") or "")
            if not access_token:
                raise RuntimeError("ACLED OAuth response did not contain an access token")
        if access_token:
            headers["Authorization"] = f"Bearer {access_token}"
        else:
            auth_mode = "legacy-key"
            params.update({"key": legacy_key, "email": email})
    except Exception as exc:
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "ACLED",
            "status": "ERROR",
            "rows": 0,
            "detail": f"OAuth: {type(exc).__name__}: {str(exc)[:150]}",
        }])
    url = "https://acleddata.com/api/acled/read?" + _wm211_urlparse.urlencode(params)
    rows: list[dict[str, Any]] = []
    layer_map = {
        "protests": "protestEvents",
        "riots": "riotUnrest",
        "violence against civilians": "civilianViolence",
        "strategic developments": "governmentInstability",
    }
    try:
        request = _wm211_urlrequest.Request(url, headers=headers)
        with _wm211_urlrequest.urlopen(request, timeout=6) as response:
            payload = json.loads(response.read(3_000_000).decode("utf-8", errors="ignore"))
        for item in (payload.get("data") or [])[:500]:
            if not isinstance(item, dict):
                continue
            try:
                lat, lon = float(item.get("latitude")), float(item.get("longitude"))
            except Exception:
                continue
            event_type = str(item.get("event_type") or "").strip()
            layer_id = layer_map.get(event_type.lower(), "conflicts")
            fatalities = max(0, int(float(item.get("fatalities") or 0)))
            title = " · ".join(filter(None, [
                event_type or "ACLED event",
                str(item.get("sub_event_type") or "").strip(),
                str(item.get("location") or "").strip(),
            ]))
            published = _wm211_parse_dt_v45(item.get("event_date"))
            rows.append({
                "event_id": f"acled:{item.get('event_id_cnty') or _id_hash(title, lat, lon, published)}",
                "layer_id": layer_id,
                "title": title[:260],
                "description": str(item.get("notes") or "")[:700],
                "event_type": "conflict_event",
                "subtype": str(item.get("sub_event_type") or event_type),
                "source": "ACLED",
                "source_url": "https://acleddata.com/",
                "timestamp_utc": published.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "country": str(item.get("country") or ""),
                "lat": lat,
                "lon": lon,
                "severity": int(max(50, min(98, 62 + fatalities * 4))),
                "confidence": 92,
                "provider": "ACLED API",
                "source_tier": "PRIMARY",
                "geo_name": str(item.get("location") or item.get("admin1") or ""),
            })
        return pd.DataFrame(rows), pd.DataFrame([{
            "provider": "ACLED",
            "status": "OK",
            "rows": len(rows),
            "detail": f"authoritative observations; auth={auth_mode}; window={start}..{end}",
        }])
    except Exception as exc:
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "ACLED",
            "status": "ERROR",
            "rows": 0,
            "detail": f"{type(exc).__name__}: {str(exc)[:160]}",
        }])


def _wmj_fetch_firms_v7(hours_back: int) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Load bounded global MODIS fire detections using either deployed key alias."""
    map_key = _wmj_secret_v7("NASA_FIRMS_MAP_KEY", "NASA_FIRMS_API_KEY")
    if not map_key:
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "NASA FIRMS",
            "status": "LOCKED",
            "rows": 0,
            "detail": "Configure NASA_FIRMS_MAP_KEY (NASA_FIRMS_API_KEY is also accepted).",
        }])
    import csv as _wmj_csv
    import io as _wmj_io

    days = max(1, min(5, int(math.ceil(max(1, int(hours_back)) / 24))))
    url = f"https://firms.modaps.eosdis.nasa.gov/api/area/csv/{_wm211_urlparse.quote(map_key)}/MODIS_NRT/world/{days}"
    rows: list[dict[str, Any]] = []
    try:
        raw = _wm211_http_text_v45(url, timeout=7)
        for item in list(_wmj_csv.DictReader(_wmj_io.StringIO(raw)))[:2500]:
            try:
                lat, lon = float(item.get("latitude")), float(item.get("longitude"))
            except Exception:
                continue
            date = str(item.get("acq_date") or "")
            hhmm = str(item.get("acq_time") or "0000").zfill(4)
            published = _wm211_parse_dt_v45(f"{date}T{hhmm[:2]}:{hhmm[2:]}:00Z")
            frp = max(0.0, float(_safe_float(item.get("frp"), 0.0) or 0.0))
            confidence_raw = str(item.get("confidence") or "nominal").lower()
            confidence = 92 if confidence_raw in {"h", "high"} else (78 if confidence_raw in {"n", "nominal"} else 64)
            label = f"Satellite fire · {item.get('satellite') or 'MODIS'} · FRP {frp:.1f} MW"
            rows.append({
                "event_id": f"firms:{_id_hash(lat, lon, date, hhmm, item.get('satellite'))}",
                "layer_id": "activeFires" if "activeFires" in LAYER_BY_ID else "fires",
                "title": label,
                "description": f"NASA FIRMS {item.get('instrument') or 'MODIS'} · confidence {confidence_raw}",
                "event_type": "satellite_fire",
                "subtype": "NASA FIRMS MODIS NRT",
                "source": "NASA FIRMS",
                "source_url": "https://firms.modaps.eosdis.nasa.gov/",
                "timestamp_utc": published.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "country": "",
                "lat": lat,
                "lon": lon,
                "severity": int(max(45, min(96, 48 + math.log1p(frp) * 10))),
                "confidence": confidence,
                "provider": "NASA FIRMS Area API",
                "source_tier": "PRIMARY",
                "geo_name": "Satellite detection",
            })
        # A world query can contain tens of thousands of pixels.  Keep the
        # strongest observation per half-degree cell, then cap the browser
        # payload.  This preserves global coverage and operational hotspots
        # without turning the interactive Plotly component into a fire dump.
        selected: list[dict[str, Any]] = []
        occupied: set[tuple[int, int]] = set()
        for row in sorted(rows, key=lambda value: (int(value.get("severity", 0)), int(value.get("confidence", 0))), reverse=True):
            cell = (round(float(row.get("lat", 0.0)) * 2), round(float(row.get("lon", 0.0)) * 2))
            if cell in occupied:
                continue
            occupied.add(cell)
            selected.append(row)
            if len(selected) >= 280:
                break
        return pd.DataFrame(selected), pd.DataFrame([{
            "provider": "NASA FIRMS",
            "status": "OK",
            "rows": len(selected),
            "detail": f"MODIS NRT; strongest global cells; raw={len(rows)}; selected={len(selected)}; days={days}",
        }])
    except Exception as exc:
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "NASA FIRMS",
            "status": "ERROR",
            "rows": 0,
            "detail": f"{type(exc).__name__}: {str(exc)[:160]}",
        }])


def _wmj_fetch_newsapi_v7(hours_back: int) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Add direct NewsAPI observations; geolocation and confidence stay explicit."""
    api_key = _wmj_secret_v7("NEWSAPI_KEY")
    if not api_key:
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "NewsAPI",
            "status": "LOCKED",
            "rows": 0,
            "detail": "Configure NEWSAPI_KEY for the direct publisher mesh.",
        }])
    from_date = (_wm211_dt.datetime.now(_wm211_dt.timezone.utc) - _wm211_dt.timedelta(hours=max(1, min(int(hours_back), 720)))).strftime("%Y-%m-%d")
    params = _wm211_urlparse.urlencode({
        "q": "geopolitics OR conflict OR sanctions OR energy OR supply chain OR cyber",
        "from": from_date,
        "language": "en",
        "sortBy": "publishedAt",
        "pageSize": "60",
    })
    req = _wm211_urlrequest.Request(
        "https://newsapi.org/v2/everything?" + params,
        headers={"X-Api-Key": api_key, "User-Agent": "QuantTerminal-WorldMonitor/7"},
    )
    rows: list[dict[str, Any]] = []
    try:
        with _wm211_urlrequest.urlopen(req, timeout=6) as response:
            payload = json.loads(response.read(1_500_000).decode("utf-8", errors="ignore"))
        for item in (payload.get("articles") or [])[:60]:
            source = str((item.get("source") or {}).get("name") or "NewsAPI")
            event = _wm211_event_row_v45(
                _wm211_classify_layer_v45(item.get("title") or "", item.get("description") or ""),
                item.get("title") or "",
                source,
                item.get("url") or "",
                item.get("publishedAt") or "",
                item.get("description") or "",
                "NewsAPI direct publisher mesh",
            )
            if event:
                rows.append(event)
        return pd.DataFrame(rows), pd.DataFrame([{
            "provider": "NewsAPI",
            "status": "OK",
            "rows": len(rows),
            "detail": "direct publisher discovery; server-side API key",
        }])
    except Exception as exc:
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "NewsAPI",
            "status": "ERROR",
            "rows": 0,
            "detail": f"{type(exc).__name__}: {str(exc)[:160]}",
        }])


def _wmj_fetch_opensky_v7() -> tuple[pd.DataFrame, pd.DataFrame]:
    """Load a bounded, spatially diverse sample of authenticated live ADS-B states."""
    client_id = _wmj_secret_v7("OPENSKY_CLIENT_ID")
    client_secret = _wmj_secret_v7("OPENSKY_CLIENT_SECRET")
    if not client_id or not client_secret:
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "OpenSky",
            "status": "LOCKED",
            "rows": 0,
            "detail": "Configure OPENSKY_CLIENT_ID + OPENSKY_CLIENT_SECRET; username/password REST auth is obsolete.",
        }])
    try:
        body = _wm211_urlparse.urlencode({
            "grant_type": "client_credentials",
            "client_id": client_id,
            "client_secret": client_secret,
        }).encode("utf-8")
        token_request = _wm211_urlrequest.Request(
            "https://auth.opensky-network.org/auth/realms/opensky-network/protocol/openid-connect/token",
            data=body,
            headers={"Content-Type": "application/x-www-form-urlencoded", "Accept": "application/json"},
            method="POST",
        )
        with _wm211_urlrequest.urlopen(token_request, timeout=6) as response:
            token = str(json.loads(response.read(500_000).decode("utf-8", errors="ignore")).get("access_token") or "")
        if not token:
            raise RuntimeError("OpenSky OAuth response did not contain an access token")
        state_request = _wm211_urlrequest.Request(
            "https://opensky-network.org/api/states/all?extended=1",
            headers={"Authorization": f"Bearer {token}", "Accept": "application/json", "User-Agent": "QuantTerminal-WorldMonitor/7"},
        )
        with _wm211_urlrequest.urlopen(state_request, timeout=7) as response:
            payload = json.loads(response.read(10_000_000).decode("utf-8", errors="ignore"))
        candidates: list[dict[str, Any]] = []
        for state in (payload.get("states") or [])[:35000]:
            if not isinstance(state, list) or len(state) < 17:
                continue
            try:
                lon, lat = float(state[5]), float(state[6])
            except Exception:
                continue
            if bool(state[8]):
                continue
            callsign = str(state[1] or "").strip() or str(state[0] or "ADS-B").upper()
            altitude = _safe_float(state[13], _safe_float(state[7], 0.0)) or 0.0
            velocity = _safe_float(state[9], 0.0) or 0.0
            timestamp = _wm211_dt.datetime.fromtimestamp(float(state[4] or payload.get("time") or 0), tz=_wm211_dt.timezone.utc)
            candidates.append({
                "event_id": f"opensky:{state[0] or _id_hash(callsign, lat, lon)}",
                "layer_id": "flights",
                "title": f"{callsign} · {str(state[2] or 'Unknown origin')}",
                "description": f"Public ADS-B state · altitude {altitude:.0f} m · velocity {velocity:.0f} m/s",
                "event_type": "aircraft_state",
                "subtype": "OpenSky ADS-B",
                "source": "OpenSky Network",
                "source_url": "https://opensky-network.org/",
                "timestamp_utc": timestamp.strftime("%Y-%m-%dT%H:%M:%SZ"),
                "country": str(state[2] or ""),
                "lat": lat,
                "lon": lon,
                "severity": 42,
                "confidence": 86 if int(state[16] or 0) == 0 else 78,
                "provider": "OpenSky REST OAuth",
                "source_tier": "PRIMARY",
                "geo_name": callsign,
                "altitude_m": altitude,
                "velocity_mps": velocity,
            })
        selected: list[dict[str, Any]] = []
        occupied: set[tuple[int, int]] = set()
        for row in sorted(candidates, key=lambda value: float(value.get("altitude_m", 0.0)), reverse=True):
            cell = (round(float(row.get("lat", 0.0))), round(float(row.get("lon", 0.0))))
            if cell in occupied:
                continue
            occupied.add(cell)
            selected.append(row)
            if len(selected) >= 260:
                break
        return pd.DataFrame(selected), pd.DataFrame([{
            "provider": "OpenSky",
            "status": "OK",
            "rows": len(selected),
            "detail": f"OAuth ADS-B live states; raw={len(candidates)}; selected={len(selected)}",
        }])
    except Exception as exc:
        return pd.DataFrame(), pd.DataFrame([{
            "provider": "OpenSky",
            "status": "ERROR",
            "rows": 0,
            "detail": f"{type(exc).__name__}: {str(exc)[:160]}",
        }])


@st.cache_data(ttl=180, show_spinner=False)
def load_live_event_objects_v211(  # type: ignore[override]
    hours_back: int = 168,
    min_magnitude: float = 2.5,
    cache_nonce: int = 0,
    provider_profile: str = "Fast natural",
) -> tuple[pd.DataFrame, pd.DataFrame]:
    """Bounded parallel live mesh used by the JARVIS map-first runtime.

    The historical loader chain performed multiple generations of the same
    provider scans.  JARVIS calls each authoritative/open family once and in
    parallel, which keeps the initial cockpit render bounded by the slowest
    provider instead of the sum of all provider timeouts.
    """

    hours = max(1, min(int(hours_back or 24), 168))
    query_budget = max(1, min(12, int(os.getenv("WORLDMONITOR_LIVE_QUERY_BUDGET", "12"))))
    gdelt_budget = max(1, min(6, int(os.getenv("WORLDMONITOR_GDELT_QUERY_BUDGET", "6"))))
    jobs = [
        ("USGS", lambda: _wm211_fetch_usgs_final_v45(hours)),
        ("GDACS", _wm211_fetch_gdacs_final_v45),
        ("NASA EONET", lambda: _wm211_fetch_eonet_final_v45(hours)),
        ("Google News", lambda: _wm211_fetch_google_news_events_v45(hours, query_budget, 4)),
        ("GDELT", lambda: _wm211_fetch_gdelt_doc_events_v45(hours, gdelt_budget, 3)),
        ("ACLED", lambda: _wmj_fetch_acled_v7(hours)),
        ("NASA FIRMS", lambda: _wmj_fetch_firms_v7(hours)),
        ("NewsAPI", lambda: _wmj_fetch_newsapi_v7(hours)),
        ("OpenSky", _wmj_fetch_opensky_v7),
    ]

    def run(job: tuple[str, Any]) -> tuple[pd.DataFrame, pd.DataFrame]:
        name, function = job
        try:
            return function()
        except Exception as exc:
            return pd.DataFrame(), pd.DataFrame([{
                "provider": name,
                "status": "ERROR",
                "rows": 0,
                "detail": f"{type(exc).__name__}: {str(exc)[:160]}",
            }])

    with _WMJThreadPoolExecutor(max_workers=len(jobs), thread_name_prefix="wmj-provider") as pool:
        results = list(pool.map(run, jobs))

    event_frames = [events for events, _status in results if isinstance(events, pd.DataFrame) and not events.empty]
    status_frames = [status for _events, status in results if isinstance(status, pd.DataFrame) and not status.empty]
    x_events, x_status = _wm211_fetch_x_status_v45()
    if isinstance(x_events, pd.DataFrame) and not x_events.empty:
        event_frames.append(x_events)
    if isinstance(x_status, pd.DataFrame) and not x_status.empty:
        status_frames.append(x_status)

    events = pd.concat(event_frames, ignore_index=True, sort=False) if event_frames else pd.DataFrame()
    if not events.empty:
        events["_dedupe"] = events.apply(
            lambda row: _id_hash(row.get("layer_id"), row.get("title"), row.get("lat"), row.get("lon"), row.get("source_url")),
            axis=1,
        )
        events = events.drop_duplicates("_dedupe", keep="first").drop(columns=["_dedupe"], errors="ignore")
        events["severity"] = pd.to_numeric(events.get("severity"), errors="coerce").fillna(55).clip(0, 100)
        events["confidence"] = pd.to_numeric(events.get("confidence"), errors="coerce").fillna(60).clip(0, 100)
        objects = _events_to_objects(events.reset_index(drop=True), source_name="WorldMonitor JARVIS live mesh")
    else:
        objects = pd.DataFrame()

    if isinstance(objects, pd.DataFrame) and not objects.empty:
        objects = objects.drop_duplicates(subset=["object_id", "kind", "points_json"], keep="first").reset_index(drop=True)
    status = pd.concat(status_frames, ignore_index=True, sort=False) if status_frames else pd.DataFrame()
    summary = pd.DataFrame([{
        "provider": "WORLDMONITOR JARVIS V7",
        "status": "OK" if isinstance(objects, pd.DataFrame) and not objects.empty else "EMPTY",
        "rows": len(objects) if isinstance(objects, pd.DataFrame) else 0,
        "detail": f"parallel bounded mesh; profile={provider_profile}; hours={hours}; nonce={cache_nonce}",
    }])
    return objects, pd.concat([summary, status], ignore_index=True, sort=False)


def _wmj_rss_query_v7(task: tuple[str, str, str, int]) -> list[dict[str, Any]]:
    """Fetch one filtered panel-news query without sharing mutable state."""
    source, tag, region, per_feed = task
    query = source
    return _wm_v321_fetch_google_rss(
        f"Google News {tag}",
        tag,
        region,
        query,
        per_feed,
        set(),
    )


@st.cache_data(ttl=300, show_spinner=False)
def _wm_fetch_rss_items_v211(  # type: ignore[override]
    style: str = "Global",
    country: str = "Global",
    max_items: int = 128,
) -> list[dict[str, Any]]:
    """Parallel, bounded news router for the panel cockpit.

    Earlier generations walked topic, region and direct-feed lists serially,
    which made a cold WorldMonitor render wait for the sum of several network
    timeouts.  The JARVIS runtime keeps the same freshness/relevance filters
    while bounding latency by the slowest query.
    """

    style_name = str(style or "Global")
    country_name = str(country or "Global")
    per_feed = 4 if int(max_items or 0) <= 80 else 5
    query_rows: list[tuple[str, str, str, int]] = []

    for tag, query in list(_WM_V321_TOPIC_QUERIES.get(style_name, _WM_V321_TOPIC_QUERIES["Global"])):
        scoped = f"{query} {country_name}" if country_name != "Global" else query
        query_rows.append((scoped, str(tag), country_name, per_feed))
    for region, regional_queries in _WM_V321_REGION_QUERIES.items():
        for tag, query in list(regional_queries)[:2]:
            query_rows.append((query, str(tag), str(region), 3))

    budget = max(4, min(len(query_rows), int(os.getenv("WORLDMONITOR_PANEL_QUERY_BUDGET", "12"))))
    tasks = query_rows[:budget]
    workers = max(2, min(budget, int(os.getenv("WORLDMONITOR_PANEL_WORKERS", "10"))))
    with _WMJThreadPoolExecutor(max_workers=workers, thread_name_prefix="wmj-panels") as pool:
        batches = list(pool.map(_wmj_rss_query_v7, tasks))

    items: list[dict[str, Any]] = []
    seen: set[str] = set()
    for batch in batches:
        for item in batch:
            key = _wm_normalize_news_key_v211(item)
            if not key or key in seen:
                continue
            seen.add(key)
            items.append(item)
            if len(items) >= int(max_items):
                return items
    return items


@st.cache_data(ttl=180, show_spinner=False)
def _wmci_country_payload_v51(  # type: ignore[override]
    active_time: str = "24h",
    live_enabled: bool = True,
) -> str:
    """Build the full click-through country atlas in one bounded pass.

    The legacy V5.9 builder recursively rebuilt and filtered the entire object
    frame for nearly every country.  This version loads the frame once, keeps
    detailed intelligence for the curated profiles, and emits lightweight but
    valid profiles for the rest of the 195-country atlas.
    """

    atlas_rows = list(_wmci_countryinfo_rows_v55() or [])
    # Structural context already lives in the atlas profiles.  Only the cached
    # live frame is needed here for per-country signal counts; filtering the
    # 2k+ static object frame for every curated country added several seconds.
    objects = pd.DataFrame()
    if bool(live_enabled):
        try:
            hours = int(_wm21121_time_to_hours(str(active_time or "24h")))
            objects, _ = load_live_event_objects_v211(
                hours_back=max(1, min(hours, 168)),
                min_magnitude=0.0,
                cache_nonce=int(hours),
                provider_profile="Fast natural",
            )
        except Exception:
            objects = pd.DataFrame()

    rich_names: set[str] = set()
    for registry_name in (
        "_WMCI_COUNTRY_META_V50",
        "_WMCI_ENERGY_PROFILES_V50",
        "_WMCI_MACRO_PROFILES_V50",
        "_WMCI_INFRA_PROFILES_V50",
    ):
        registry = globals().get(registry_name, {})
        if isinstance(registry, dict):
            rich_names.update(str(name) for name in registry)

    profiles: list[dict[str, Any]] = []
    for row in atlas_rows:
        if not isinstance(row, dict):
            continue
        country_name = str(row.get("country") or row.get("iso3") or "Country")
        profile = _wmci_lite_profile_v59(row, active_time=str(active_time or "24h"))
        if country_name in rich_names:
            try:
                country_objects = _wmci_filter_country_objects_v50(objects, country_name) if not objects.empty else pd.DataFrame()
                themes = _wmci_theme_counts_v50(country_objects)
                live_rows = _wmci_live_rows_v50(country_objects, limit=6)
                instability = _wmci_instability_v50(country_name, themes, live_rows)
                profile.update({
                    "energy": _wmci_profile_energy_v50(country_name),
                    "macro": _wmci_profile_macro_v50(country_name),
                    "infra": _wmci_profile_infra_v50(country_name),
                    "history": _wmci_history_for_country_v50(country_name, 6),
                    "themes": themes,
                    "live": live_rows,
                    "instability": instability,
                    "scenario": _wmci_scenario_result_v50(
                        country_name,
                        "Hormuz disruption",
                        "Base",
                        "All channels",
                        themes,
                    ),
                    "source_quality": _wmci_clip_v50(58 + min(18, len(live_rows) * 3)),
                    "operational": "Curated structural profile fused with the current live object mesh.",
                })
            except Exception:
                pass

        canonical_meta = dict(profile.get("meta") or {})
        for key in ("iso3", "iso2", "flag", "region", "lon", "lat", "bbox", "capital"):
            if row.get(key) not in (None, "", []):
                canonical_meta[key] = row.get(key)
        profile["country"] = country_name
        profile["meta"] = canonical_meta
        profiles.append(profile)

    return json.dumps(
        {
            "version": _WMJ_VERSION_V7,
            "active_time": str(active_time or "24h"),
            "profiles": profiles,
        },
        ensure_ascii=False,
        default=str,
        separators=(",", ":"),
    )


def _render_worldmonitor_map_clean_v211(  # type: ignore[override]
    live_enabled: bool = False,
    time_window: str = "24h",
    style: str = "Global",
    projection_mode: str = "2D",
    country: str = "Global",
    **_kwargs: Any,
) -> None:
    """Map-first renderer with static and live data loaded concurrently."""

    hours_back = _wm21121_time_to_hours(str(time_window))

    def load_static() -> tuple[pd.DataFrame, pd.DataFrame]:
        return load_worldmonitor_static_objects_v211("")

    def load_live() -> tuple[pd.DataFrame, pd.DataFrame]:
        if not bool(live_enabled):
            return pd.DataFrame(), pd.DataFrame()
        return load_live_event_objects_v211(
            hours_back=int(hours_back),
            min_magnitude=0.0,
            cache_nonce=int(hours_back),
            provider_profile="Fast natural",
        )

    with _WMJThreadPoolExecutor(max_workers=2, thread_name_prefix="wmj-map") as pool:
        static_future = pool.submit(load_static)
        live_future = pool.submit(load_live)
        try:
            static_objects, _static_status = static_future.result()
        except Exception:
            static_objects = pd.DataFrame()
        try:
            live_objects, _live_status = live_future.result()
        except Exception:
            live_objects = pd.DataFrame()

    frames = [frame for frame in (static_objects, live_objects) if isinstance(frame, pd.DataFrame) and not frame.empty]
    objects = pd.concat(frames, ignore_index=True, sort=False) if frames else pd.DataFrame()
    if not objects.empty:
        objects = objects.drop_duplicates(subset=[c for c in ("object_id", "kind", "points_json") if c in objects.columns], keep="first").reset_index(drop=True)
        objects = _wm21121_filter_objects_for_country(objects, str(country or "Global"))

    preset = _WM_STYLE_TO_MAP_PRESET.get(str(style), "Balanced institutional")
    registry = build_layer_registry_v211(objects, preset=preset)
    registry = _wm21121_add_country_focus_registry(registry, str(country or "Global"))
    projection = "3D globe" if str(projection_mode).upper() == "3D" else "Flat world"
    projection_scale = 1.16 if projection == "3D globe" else 1.0
    fig = build_plotly_figure_v211(
        objects,
        registry,
        projection=projection,
        region=_wm21121_country_cfg(str(country or "Global")).get("region", "Global"),
        fig_height=606,
        projection_scale=projection_scale,
    )
    _wm_focus_figure_on_country_v211(fig, str(country or "Global"), str(projection_mode))
    html_payload = _map_component_html(
        fig,
        registry,
        stage_height=660,
        active_time=str(time_window or "24h"),
        projection_mode=str(projection_mode),
        country=str(country or "Global"),
        live_enabled=bool(live_enabled),
    )
    html_payload = (
        f"<!-- WMJ-V7 country={html.escape(str(country or 'Global'))} "
        f"time={html.escape(str(time_window or '24h'))} style={html.escape(str(style))} -->\n"
        + str(html_payload)
    )
    if components is not None:
        components.html(html_payload, height=660, scrolling=False)
    else:
        st.plotly_chart(fig, use_container_width=True, config={"displayModeBar": True, "responsive": True})


